/**
 * @module HandTrackingManager
 * @description
 * Adds WebXR hand-tracking support on top of Three.js hand helpers, including
 * pinch events, pointer rays, optional hand-flight gestures, and triangle or
 * single-hand pinch-aim teleport gestures.
 */
import * as THREE from 'three';
import { XRHandModelFactory } from 'three/addons/webxr/XRHandModelFactory.js';
import { OculusHandPointerModel } from 'three/addons/webxr/OculusHandPointerModel.js';

import { EventsDispatcher } from '../utils/EventsDispatcher.js';

export const TRIANGLE_TELEPORT_START_DISTANCE = 0.15;
/** Seconds to wait before emitting hand-teleport preview updates. */
export const HAND_TELEPORT_PREVIEW_DELAY = 0.5;

/**
 * Event type constants dispatched by {@link HandTrackingManager}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when a tracked hand connects. */
	ON_HAND_CONNECTED: 'onHandConnected',
	/** Fired when a tracked hand disconnects. */
	ON_HAND_DISCONNECTED: 'onHandDisconnected',
	/** Fired when a pinch gesture begins. */
	ON_PINCH_START: 'onPinchStart',
	/** Fired when a pinch gesture ends. */
	ON_PINCH_END: 'onPinchEnd',
	/** Fired after a pinch is held longer than `pinchHoldDelay`. */
	ON_PINCH_HOLD: 'onPinchHold',
	/** Fired when the hand pointer ray updates. */
	ON_POINTER_RAY_UPDATED: 'onPointerRayUpdated',
	/** Fired when the triangle teleport gesture begins. */
	ON_TRIANGLE_TELEPORT_STARTED: 'onTriangleTeleportStarted',
	/** Fired while the triangle teleport gesture updates. */
	ON_TRIANGLE_TELEPORT_UPDATED: 'onTriangleTeleportUpdated',
	/** Fired when triangle teleport is confirmed. */
	ON_TRIANGLE_TELEPORT_CONFIRMED: 'onTriangleTeleportConfirmed',
	/** Fired when triangle teleport ends or is cancelled. */
	ON_TRIANGLE_TELEPORT_ENDED: 'onTriangleTeleportEnded',
	/** Fired when a single-hand pinch-aim teleport begins. */
	ON_PINCH_AIM_TELEPORT_STARTED: 'onPinchAimTeleportStarted',
	/** Fired while a single-hand pinch-aim teleport updates. */
	ON_PINCH_AIM_TELEPORT_UPDATED: 'onPinchAimTeleportUpdated',
	/** Fired when a single-hand pinch-aim teleport is confirmed. */
	ON_PINCH_AIM_TELEPORT_CONFIRMED: 'onPinchAimTeleportConfirmed',
	/** Fired when a single-hand pinch-aim teleport ends or is cancelled. */
	ON_PINCH_AIM_TELEPORT_ENDED: 'onPinchAimTeleportEnded',
	/** Fired when optional hand-flight starts. */
	ON_HAND_FLIGHT_STARTED: 'onHandFlightStarted',
	/** Fired while optional hand-flight updates. */
	ON_HAND_FLIGHT_UPDATED: 'onHandFlightUpdated',
	/** Fired when optional hand-flight ends. */
	ON_HAND_FLIGHT_ENDED: 'onHandFlightEnded',
};

export const defaultOptions = {
	handModelProfile: 'spheres',
	pinchHoldDelay: 0.65,
	handBones: {
		color: 0xd8e3ee,
		jointColor: 0x8fd7ff,
		thickness: 0.0054,
		jointSize: 0.0168,
	},
	handGrip: {
		positionMode: 'pinch-midpoint',
		positionSmoothing: 0,
		rotationSmoothing: 0,
		lostTrackingGraceFrames: 2,
	},
	pinchGestures: {
		primaryFinger: 'index',
		alternateFinger: 'middle',
		startDistance: 0.035,
		endDistance: 0.055,
		rejectWhenPalmFacesHead: true,
		palmFacingHeadMaxDot: 0.55,
	},
	flightGesture: {
		enabled: false,
		hand: 'right',
		minFistStrength: 0.72,
		speed: 1,
	},
	triangleTeleport: {
		enabled: false,
		thumbTouchDistance: TRIANGLE_TELEPORT_START_DISTANCE,
		indexTouchDistance: TRIANGLE_TELEPORT_START_DISTANCE,
		minTriangleHeight: 0.08,
		closePinchDistance: 0.045,
		frontMinDot: 0.2,
		confirmFrames: 2,
		previewDelay: HAND_TELEPORT_PREVIEW_DELAY,
	},
	pinchAimTeleport: {
		enabled: false,
		// Pinch Aim is intentionally assigned to one hand at a time.
		hand: 'right',
		aimStartDistance: 0.06,
		pinchDistance: 0.035,
		frontMinDot: 0.1,
		previewDelay: HAND_TELEPORT_PREVIEW_DELAY,
	},
};

const BONE_SEGMENTS = [
	['wrist', 'thumb-metacarpal'],
	['thumb-metacarpal', 'thumb-phalanx-proximal'],
	['thumb-phalanx-proximal', 'thumb-phalanx-distal'],
	['thumb-phalanx-distal', 'thumb-tip'],
	['wrist', 'index-finger-metacarpal'],
	['index-finger-metacarpal', 'index-finger-phalanx-proximal'],
	['index-finger-phalanx-proximal', 'index-finger-phalanx-intermediate'],
	['index-finger-phalanx-intermediate', 'index-finger-phalanx-distal'],
	['index-finger-phalanx-distal', 'index-finger-tip'],
	['wrist', 'middle-finger-metacarpal'],
	['middle-finger-metacarpal', 'middle-finger-phalanx-proximal'],
	['middle-finger-phalanx-proximal', 'middle-finger-phalanx-intermediate'],
	['middle-finger-phalanx-intermediate', 'middle-finger-phalanx-distal'],
	['middle-finger-phalanx-distal', 'middle-finger-tip'],
	['wrist', 'ring-finger-metacarpal'],
	['ring-finger-metacarpal', 'ring-finger-phalanx-proximal'],
	['ring-finger-phalanx-proximal', 'ring-finger-phalanx-intermediate'],
	['ring-finger-phalanx-intermediate', 'ring-finger-phalanx-distal'],
	['ring-finger-phalanx-distal', 'ring-finger-tip'],
	['wrist', 'pinky-finger-metacarpal'],
	['pinky-finger-metacarpal', 'pinky-finger-phalanx-proximal'],
	['pinky-finger-phalanx-proximal', 'pinky-finger-phalanx-intermediate'],
	['pinky-finger-phalanx-intermediate', 'pinky-finger-phalanx-distal'],
	['pinky-finger-phalanx-distal', 'pinky-finger-tip'],
	['index-finger-metacarpal', 'middle-finger-metacarpal'],
	['middle-finger-metacarpal', 'ring-finger-metacarpal'],
	['ring-finger-metacarpal', 'pinky-finger-metacarpal'],
];

const BONE_JOINTS = [...new Set(BONE_SEGMENTS.flat())];
const FINGER_JOINT_PREFIX = {
	index: 'index-finger',
	middle: 'middle-finger',
	ring: 'ring-finger',
	pinky: 'pinky-finger',
};

/**
 * Wraps Three.js WebXR hand tracking helpers and exposes hand events through
 * the same object shape used by GrabbableVRObject controller interactions.
 *
 * Three.js owns the low-level joint tracking and pinch detection. This class
 * adds a project-level event surface and a stable holding point positioned at
 * the thumb/index midpoint.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const handTracking = controllers.enableHandTracking({
 *   pinchGestures: { startDistance: 0.035, endDistance: 0.055 },
 * });
 *
 * handTracking.addEventListener(EventTypes.ON_PINCH_START, ({ hand }) => {
 *   console.log('pinch from', hand.handedness);
 * });
 */
export class HandTrackingManager extends EventsDispatcher {
	/** @type {THREE.WebXRManager} */
	xr;
	/** @type {THREE.Object3D} */
	parentContainer;
	/** @type {object} */
	options;
	/** @type {TrackedHand} */
	hand0;
	/** @type {TrackedHand} */
	hand1;

	/**
	 * @param {THREE.WebXRManager} xr - The WebXR manager from `renderer.xr`.
	 * @param {THREE.Object3D} parentContainer - Scene node that receives hand models and pointer helpers.
	 * @param {object} [options] - Hand tracking, gesture, and visualization options.
	 */
	constructor(xr, parentContainer, options = {}) {
		super();
		this.xr = xr;
		this.parentContainer = parentContainer;
		this.options = mergeOptions(defaultOptions, options);

		this.hand0 = new TrackedHand(this.xr, this.parentContainer, 0, this.options);
		this.hand1 = new TrackedHand(this.xr, this.parentContainer, 1, this.options);
		this._triangleTeleportActive = false;
		this._triangleTeleportConfirmed = false;
		this._triangleTeleportConfirmFrames = 0;
		this._triangleTeleportPreviewElapsed = 0;
		this._pinchAimTeleportActive = false;
		this._pinchAimTeleportConfirmed = false;
		this._pinchAimTeleportHand = null;
		this._pinchAimTeleportPreviewElapsed = 0;
		this._pinchAimTeleportAwaitingRelease = new Set();
		this._flightActive = false;

		this._setupEventListeners();
	}

	/**
	 * Both tracked hand wrappers, regardless of handedness assignment.
	 * @type {Array<TrackedHand>}
	 */
	get hands() {
		return [this.hand0, this.hand1];
	}

	/**
	 * The left tracked hand, or `null` before it connects.
	 * @type {TrackedHand|null}
	 */
	get left() {
		return this.hands.find((hand) => hand.handedness === 'left') || null;
	}

	/**
	 * The right tracked hand, or `null` before it connects.
	 * @type {TrackedHand|null}
	 */
	get right() {
		return this.hands.find((hand) => hand.handedness === 'right') || null;
	}

	/**
	 * Returns a tracked hand by handedness.
	 * @param {'left'|'right'} handedness - Hand to return.
	 * @returns {TrackedHand|null}
	 */
	getHand(handedness) {
		if (handedness === 'left') return this.left;
		if (handedness === 'right') return this.right;
		return null;
	}

	/**
	 * Updates hand poses and gesture state. Call once per XR animation frame.
	 * @param {number} time - Elapsed time in seconds.
	 * @param {number} [deltaTime=0] - Time in seconds since the previous frame.
	 * @returns {void}
	 */
	update(time, deltaTime = 0) {
		for (const hand of this.hands) {
			hand.update(time, deltaTime);
		}
		this._updateTriangleTeleportGesture(deltaTime);
		this._updatePinchAimTeleportGesture(deltaTime);
		this._updateFlightGesture(deltaTime);
	}

	dispose() {
		for (const hand of this.hands) {
			hand.dispose();
		}
	}

	_setupEventListeners() {
		for (const hand of this.hands) {
			this._exportEvent(hand, EventTypes.ON_HAND_CONNECTED);
			this._exportEvent(hand, EventTypes.ON_HAND_DISCONNECTED);
			this._exportEvent(hand, EventTypes.ON_PINCH_START);
			this._exportEvent(hand, EventTypes.ON_PINCH_END);
			this._exportEvent(hand, EventTypes.ON_PINCH_HOLD);
			this._exportEvent(hand, EventTypes.ON_POINTER_RAY_UPDATED);
			this._exportEvent(hand, EventTypes.ON_HAND_FLIGHT_STARTED);
			this._exportEvent(hand, EventTypes.ON_HAND_FLIGHT_UPDATED);
			this._exportEvent(hand, EventTypes.ON_HAND_FLIGHT_ENDED);
		}
	}

	_exportEvent(origin, type) {
		origin.addEventListener(type, (event) => {
			this.dispatchEvent({ ...event });
		});
	}

	get triangleTeleportIsActive() {
		return this._triangleTeleportActive;
	}

	get flightIsActive() {
		return this._flightActive;
	}

	/** Whether either teleport gesture is currently active. */
	get teleportIsActive() {
		return this._triangleTeleportActive || this._pinchAimTeleportActive;
	}

	/**
	 * Selects the teleport gesture while preserving all configured thresholds.
	 * @param {'triangle'|'pinch-aim'} mode
	 */
	setTeleportGestureMode(mode) {
		if (mode !== 'triangle' && mode !== 'pinch-aim') {
			throw new Error(`HandTrackingManager: unsupported teleport gesture mode "${mode}"`);
		}
		if (this._triangleTeleportActive) this._endTriangleTeleportGesture('mode-changed');
		if (this._pinchAimTeleportActive) this._endPinchAimTeleportGesture('mode-changed');
		this.options.triangleTeleport.enabled = mode === 'triangle';
		this.options.pinchAimTeleport.enabled = mode === 'pinch-aim';
	}

	/**
	 * Selects one mutually exclusive hand locomotion mode.
	 * @param {'triangle'|'pinch-aim'|'hand-flight'} mode
	 */
	setLocomotionMode(mode) {
		if (!['triangle', 'pinch-aim', 'hand-flight'].includes(mode)) {
			throw new Error(`HandTrackingManager: unsupported locomotion mode "${mode}"`);
		}
		if (this._triangleTeleportActive) this._endTriangleTeleportGesture('mode-changed');
		if (this._pinchAimTeleportActive) this._endPinchAimTeleportGesture('mode-changed');
		if (this._flightActive) this._endFlightGesture('mode-changed');

		this.options.triangleTeleport.enabled = mode === 'triangle';
		this.options.pinchAimTeleport.enabled = mode === 'pinch-aim';
		this.options.flightGesture.enabled = mode === 'hand-flight';
	}

	_updateTriangleTeleportGesture(deltaTime = 0) {
		const options = this.options.triangleTeleport;
		if (!options.enabled) return;

		const sample = this._sampleTriangleTeleportGesture(this.left, this.right);
		if (!sample) {
			if (this._triangleTeleportActive) this._endTriangleTeleportGesture('lost-tracking');
			return;
		}

		const canStart =
			sample.thumbDistance <= options.thumbTouchDistance &&
			sample.indexDistance <= options.indexTouchDistance &&
			sample.triangleHeight >= options.minTriangleHeight &&
			sample.frontDot >= options.frontMinDot;
		const canContinue =
			sample.thumbDistance <= options.thumbTouchDistance &&
			sample.indexDistance <= options.indexTouchDistance &&
			sample.frontDot >= options.frontMinDot;

		if (!this._triangleTeleportActive) {
			if (!canStart) return;
			this._startTriangleTeleportGesture(sample);
		} else if (!canContinue) {
			this._endTriangleTeleportGesture('shape-lost');
			return;
		}

		this._setTeleportPinchSuppression(true);
		this._triangleTeleportPreviewElapsed += Math.max(0, deltaTime);
		if (this._triangleTeleportPreviewElapsed >= options.previewDelay) {
			this.dispatchEvent(this._buildTriangleTeleportEvent(EventTypes.ON_TRIANGLE_TELEPORT_UPDATED, sample));
		}

		if (
			sample.leftPinchDistance <= options.closePinchDistance &&
			sample.rightPinchDistance <= options.closePinchDistance
		) {
			this._triangleTeleportConfirmFrames += 1;
		} else {
			this._triangleTeleportConfirmFrames = 0;
		}

		if (this._triangleTeleportConfirmFrames >= options.confirmFrames) {
			this._triangleTeleportConfirmed = true;
			this.dispatchEvent(this._buildTriangleTeleportEvent(EventTypes.ON_TRIANGLE_TELEPORT_CONFIRMED, sample));
			this._endTriangleTeleportGesture('confirmed');
		}
	}

	_updatePinchAimTeleportGesture(deltaTime = 0) {
		const options = this.options.pinchAimTeleport;
		if (!options.enabled) {
			if (this._pinchAimTeleportActive) this._endPinchAimTeleportGesture('disabled');
			return;
		}

		for (const hand of this.hands) {
			if (!this._isPinchAimPinching(hand)) this._pinchAimTeleportAwaitingRelease.delete(hand);
		}

		if (this._pinchAimTeleportActive) {
			const sample = this._samplePinchAimTeleportGesture(this._pinchAimTeleportHand);
			if (!sample || sample.frontDot < options.frontMinDot || sample.hand.grabbedObject || sample.hand.attachedObject) {
				this._endPinchAimTeleportGesture(sample ? 'aim-lost' : 'lost-tracking');
				return;
			}
			this._pinchAimTeleportPreviewElapsed += Math.max(0, deltaTime);
			if (this._pinchAimTeleportPreviewElapsed >= options.previewDelay) {
				this.dispatchEvent(this._buildPinchAimTeleportEvent(EventTypes.ON_PINCH_AIM_TELEPORT_UPDATED, sample));
			}
			if (sample.isPinching) {
				this._pinchAimTeleportConfirmed = true;
				this._pinchAimTeleportAwaitingRelease.add(sample.hand);
				this.dispatchEvent(this._buildPinchAimTeleportEvent(EventTypes.ON_PINCH_AIM_TELEPORT_CONFIRMED, sample));
				this._endPinchAimTeleportGesture('confirmed');
			}
			return;
		}

		const hand = this._getPinchAimTeleportHand(options.hand);
		if (!hand || this._pinchAimTeleportAwaitingRelease.has(hand)) return;
		const sample = this._samplePinchAimTeleportGesture(hand);
		if (!sample || !sample.isAimReady || sample.frontDot < options.frontMinDot) return;

		this._pinchAimTeleportActive = true;
		this._pinchAimTeleportConfirmed = false;
		this._pinchAimTeleportHand = hand;
		this._setTeleportPinchSuppression(true);
		this.dispatchEvent(this._buildPinchAimTeleportEvent(EventTypes.ON_PINCH_AIM_TELEPORT_STARTED, sample));
	}

	_updateFlightGesture(deltaTime = 0) {
		const options = this.options.flightGesture;
		if (!options.enabled) {
			if (this._flightActive) this._endFlightGesture('disabled');
			return;
		}

		if (this.teleportIsActive) {
			if (this._flightActive) this._endFlightGesture('triangle-teleport');
			return;
		}

		const hand = this.getHand(options.hand);
		if (!hand?.connected) {
			if (this._flightActive) this._endFlightGesture('lost-tracking');
			return;
		}

		if (hand.grabbedObject || hand.attachedObject || hand.isPinching) {
			if (this._flightActive) this._endFlightGesture('hand-busy');
			return;
		}

		const fistStrength = hand.getFistStrength();
		if (fistStrength < options.minFistStrength) {
			if (this._flightActive) this._endFlightGesture('fist-opened');
			return;
		}

		const strength = THREE.MathUtils.clamp(
			(fistStrength - options.minFistStrength) / Math.max(1 - options.minFistStrength, 0.0001),
			0,
			1
		);
		const event = {
			source: 'hand-tracking',
			controller: hand,
			hand,
			handedness: hand.handedness,
			ray: hand.ray.clone(),
			fistStrength,
			strength: strength * options.speed,
			deltaTime,
		};

		if (!this._flightActive) {
			this._flightActive = true;
			this.dispatchEvent({ ...event, type: EventTypes.ON_HAND_FLIGHT_STARTED });
		}

		this.dispatchEvent({ ...event, type: EventTypes.ON_HAND_FLIGHT_UPDATED });
	}

	_endFlightGesture(reason) {
		this._flightActive = false;
		this.dispatchEvent({
			type: EventTypes.ON_HAND_FLIGHT_ENDED,
			source: 'hand-tracking',
			reason,
		});
	}

	_sampleTriangleTeleportGesture(left, right) {
		if (!left?.connected || !right?.connected) return null;

		const leftThumb = left.getJointWorldPosition('thumb-tip');
		const rightThumb = right.getJointWorldPosition('thumb-tip');
		const leftIndex = left.getJointWorldPosition('index-finger-tip');
		const rightIndex = right.getJointWorldPosition('index-finger-tip');
		if (!leftThumb || !rightThumb || !leftIndex || !rightIndex) return null;

		const head = this._getHeadsetTransform();
		if (!head) return null;

		const thumbBaseCenter = new THREE.Vector3().addVectors(leftThumb, rightThumb).multiplyScalar(0.5);
		const indexApex = new THREE.Vector3().addVectors(leftIndex, rightIndex).multiplyScalar(0.5);
		const triangleCenter = new THREE.Vector3()
			.add(leftThumb)
			.add(rightThumb)
			.add(indexApex)
			.multiplyScalar(1 / 3);
		const direction = triangleCenter.clone().sub(head.position);
		if (direction.lengthSq() === 0) return null;
		direction.normalize();

		return {
			ray: new THREE.Ray(head.position, direction),
			triangleCenter,
			thumbBaseCenter,
			indexApex,
			thumbDistance: leftThumb.distanceTo(rightThumb),
			indexDistance: leftIndex.distanceTo(rightIndex),
			leftPinchDistance: leftThumb.distanceTo(leftIndex),
			rightPinchDistance: rightThumb.distanceTo(rightIndex),
			triangleHeight: thumbBaseCenter.distanceTo(indexApex),
			frontDot: direction.dot(head.viewDirection),
		};
	}

	_getPinchAimTeleportHand(handedness) {
		if (handedness !== 'left' && handedness !== 'right') return null;
		const hand = this.getHand(handedness);
		return hand?.connected && !hand.grabbedObject && !hand.attachedObject && this._isPinchAimReady(hand)
			? hand
			: null;
	}

	_isPinchAimReady(hand) {
		const distance = hand?.getFingerThumbDistance('index');
		return distance != null && distance >= this.options.pinchAimTeleport.aimStartDistance;
	}

	_isPinchAimPinching(hand) {
		const distance = hand?.getFingerThumbDistance('index');
		return distance != null && distance <= this.options.pinchAimTeleport.pinchDistance;
	}

	_samplePinchAimTeleportGesture(hand) {
		if (!hand?.connected) return null;
		const wrist = hand.getJointWorldPosition('wrist');
		const index = hand.getJointWorldPosition('index-finger-tip');
		const thumb = hand.getJointWorldPosition('thumb-tip');
		const head = this._getHeadsetTransform();
		if (!wrist || !index || !thumb || !head) return null;

		const direction = index.clone().sub(wrist);
		if (direction.lengthSq() === 0) return null;
		direction.normalize();
		const pinchCenter = index.clone().add(thumb).multiplyScalar(0.5);
		return {
			hand,
			handedness: hand.handedness,
			ray: new THREE.Ray(pinchCenter, direction),
			pinchCenter,
			pinchDistance: thumb.distanceTo(index),
			isAimReady: this._isPinchAimReady(hand),
			isPinching: this._isPinchAimPinching(hand),
			frontDot: direction.dot(head.viewDirection),
		};
	}

	_getHeadsetTransform() {
		const xrCamera = this.xr.getCamera();
		if (!xrCamera) return null;
		xrCamera.updateMatrixWorld(true);

		const position = new THREE.Vector3().setFromMatrixPosition(xrCamera.matrixWorld);
		const viewDirection = new THREE.Vector3();
		xrCamera.getWorldDirection(viewDirection);
		viewDirection.normalize();

		return { position, viewDirection };
	}

	_startTriangleTeleportGesture(sample) {
		this._triangleTeleportActive = true;
		this._triangleTeleportConfirmed = false;
		this._triangleTeleportConfirmFrames = 0;
		this._triangleTeleportPreviewElapsed = 0;
		this._setTeleportPinchSuppression(true);
		this.dispatchEvent(this._buildTriangleTeleportEvent(EventTypes.ON_TRIANGLE_TELEPORT_STARTED, sample));
	}

	_endTriangleTeleportGesture(reason) {
		const confirmed = this._triangleTeleportConfirmed;
		this._triangleTeleportActive = false;
		this._triangleTeleportConfirmed = false;
		this._triangleTeleportConfirmFrames = 0;
		this._triangleTeleportPreviewElapsed = 0;
		this._setTeleportPinchSuppression(false);
		this.dispatchEvent({
			type: EventTypes.ON_TRIANGLE_TELEPORT_ENDED,
			source: 'hand-tracking',
			reason,
			confirmed,
		});
	}

	_endPinchAimTeleportGesture(reason) {
		const confirmed = this._pinchAimTeleportConfirmed;
		this._pinchAimTeleportActive = false;
		this._pinchAimTeleportConfirmed = false;
		this._pinchAimTeleportHand = null;
		this._pinchAimTeleportPreviewElapsed = 0;
		this._setTeleportPinchSuppression(false);
		this.dispatchEvent({
			type: EventTypes.ON_PINCH_AIM_TELEPORT_ENDED,
			source: 'hand-tracking',
			reason,
			confirmed,
		});
	}

	_setTeleportPinchSuppression(suppressed) {
		for (const hand of this.hands) {
			hand.suppressPinchEvents = suppressed;
		}
	}

	_buildTriangleTeleportEvent(type, sample) {
		return {
			type,
			source: 'hand-tracking',
			ray: sample.ray.clone(),
			triangleCenter: sample.triangleCenter.clone(),
			thumbBaseCenter: sample.thumbBaseCenter.clone(),
			indexApex: sample.indexApex.clone(),
			thumbDistance: sample.thumbDistance,
			indexDistance: sample.indexDistance,
			leftPinchDistance: sample.leftPinchDistance,
			rightPinchDistance: sample.rightPinchDistance,
			triangleHeight: sample.triangleHeight,
			frontDot: sample.frontDot,
			diagnostics: {
				thumbDistance: sample.thumbDistance,
				indexDistance: sample.indexDistance,
				leftPinchDistance: sample.leftPinchDistance,
				rightPinchDistance: sample.rightPinchDistance,
				triangleHeight: sample.triangleHeight,
				frontDot: sample.frontDot,
				confirmFrames: this._triangleTeleportConfirmFrames,
			},
		};
	}

	_buildPinchAimTeleportEvent(type, sample) {
		return {
			type,
			source: 'hand-tracking',
			hand: sample.hand,
			handedness: sample.handedness,
			ray: sample.ray.clone(),
			pinchCenter: sample.pinchCenter.clone(),
			pinchDistance: sample.pinchDistance,
			frontDot: sample.frontDot,
			diagnostics: {
				pinchDistance: sample.pinchDistance,
				frontDot: sample.frontDot,
			},
		};
	}
}

class XRHandBoneModel extends THREE.Group {
	constructor(controller, options = {}) {
		super();
		this.controller = controller;
		this.options = options;

		this.segmentMeshes = BONE_SEGMENTS.map(([start, end]) => this._createSegment(start, end));
		this.jointMeshes = BONE_JOINTS.map((jointName) => this._createJoint(jointName));
	}

	dispose() {
		this.traverse((child) => {
			if (child.geometry) child.geometry.dispose();
			if (child.material) child.material.dispose();
		});
	}

	updateMatrixWorld(force) {
		this._updateSegments();
		this._updateJoints();
		super.updateMatrixWorld(force);
	}

	_createSegment(start, end) {
		const mesh = new THREE.Mesh(
			new THREE.CylinderGeometry(1, 1, 1, 8),
			new THREE.MeshStandardMaterial({
				color: this.options.color,
				roughness: 0.45,
				metalness: 0.05,
			})
		);
		mesh.name = `handBone:${start}:${end}`;
		mesh.userData.startJoint = start;
		mesh.userData.endJoint = end;
		mesh.frustumCulled = false;
		this.add(mesh);
		return mesh;
	}

	_createJoint(jointName) {
		const mesh = new THREE.Mesh(
			new THREE.SphereGeometry(1, 8, 6),
			new THREE.MeshStandardMaterial({
				color: this.options.jointColor,
				roughness: 0.45,
				metalness: 0.05,
			})
		);
		mesh.name = `handJoint:${jointName}`;
		mesh.userData.jointName = jointName;
		mesh.frustumCulled = false;
		this.add(mesh);
		return mesh;
	}

	_updateSegments() {
		const yAxis = new THREE.Vector3(0, 1, 0);

		for (const mesh of this.segmentMeshes) {
			const start = this.controller.joints?.[mesh.userData.startJoint];
			const end = this.controller.joints?.[mesh.userData.endJoint];
			if (!start?.visible || !end?.visible) {
				mesh.visible = false;
				continue;
			}

			const from = start.position;
			const to = end.position;
			const direction = new THREE.Vector3().subVectors(to, from);
			const length = direction.length();
			if (length <= 0.0001) {
				mesh.visible = false;
				continue;
			}

			mesh.visible = true;
			mesh.position.copy(from).add(to).multiplyScalar(0.5);
			mesh.quaternion.setFromUnitVectors(yAxis, direction.normalize());
			mesh.scale.set(this.options.thickness, length, this.options.thickness);
		}
	}

	_updateJoints() {
		for (const mesh of this.jointMeshes) {
			const joint = this.controller.joints?.[mesh.userData.jointName];
			if (!joint?.visible) {
				mesh.visible = false;
				continue;
			}

			const radius = Math.max((joint.jointRadius || 0.008) * 0.42, this.options.jointSize * 0.3);
			mesh.visible = true;
			mesh.position.copy(joint.position);
			mesh.quaternion.copy(joint.quaternion);
			mesh.scale.setScalar(radius);
		}
	}
}

function mergeOptions(defaults, options = {}) {
	const result = { ...defaults, ...options };
	result.handBones = { ...defaults.handBones, ...options.handBones };
	result.handGrip = { ...defaults.handGrip, ...options.handGrip };
	result.pinchGestures = { ...defaults.pinchGestures, ...options.pinchGestures };
	result.flightGesture = { ...defaults.flightGesture, ...options.flightGesture };
	result.triangleTeleport = { ...defaults.triangleTeleport, ...options.triangleTeleport };
	result.pinchAimTeleport = { ...defaults.pinchAimTeleport, ...options.pinchAimTeleport };
	return result;
}

class TrackedHand extends EventsDispatcher {
	source = 'hand-tracking';
	connected = false;
	handedness = undefined;
	isSqueezing = false;
	isPinching = false;
	suppressPinchEvents = false;
	ray = new THREE.Ray(new THREE.Vector3(), new THREE.Vector3(0, 0, -1));
	lastRay = null;
	attachedObject = null;
	attachedObjectParent = null;

	constructor(xr, parentContainer, index, options) {
		super();
		this.xr = xr;
		this.parentContainer = parentContainer;
		this.index = index;
		this.options = options;

		this.hand = this.xr.getHand(index);
		this.controller = this.xr.getController(index);
		this.holdingPoint = new THREE.Object3D();
		this.holdingPoint.name = `handTrackingHoldingPoint${index}`;

		this._pinchElapsed = 0;
		this._pinchHoldFired = false;
		this._pinchEventSuppressed = false;
		this._activePinchGesture = null;
		this._nativePinchActive = false;
		this._hasHoldingPointPose = false;
		this._holdingPointLostFrames = 0;
		this._lastHoldingPointPosition = new THREE.Vector3();
		this._lastHoldingPointQuaternion = new THREE.Quaternion();

		this._onConnected = this._onConnected.bind(this);
		this._onDisconnected = this._onDisconnected.bind(this);
		this._onPinchStart = this._onPinchStart.bind(this);
		this._onPinchEnd = this._onPinchEnd.bind(this);

		this._setup();
	}

	getGrip() {
		return this.holdingPoint;
	}

	getJoint(jointName) {
		return this.hand?.joints?.[jointName] || null;
	}

	getJointWorldPosition(jointName, target = new THREE.Vector3()) {
		const joint = this.getJoint(jointName);
		if (!joint || !joint.visible) return null;
		return joint.getWorldPosition(target);
	}

	attachObject(object) {
		this.attachedObject = object;
		this.attachedObjectParent = object.parent;
		this.holdingPoint.attach(object);
	}

	detachObject() {
		if (this.attachedObject && this.attachedObjectParent) {
			this.attachedObjectParent.attach(this.attachedObject);
		}
		this.attachedObject = null;
		this.attachedObjectParent = null;
	}

	pulse() {
		// Hand tracking input has no haptic actuator.
	}

	update(time, deltaTime = 0) {
		this._updateHoldingPoint();
		this._updatePointerRay();
		this._updatePinchGesture();
		this._updatePinchHold(deltaTime);

		if (this.connected) {
			this.dispatchEvent(this._buildEvent(EventTypes.ON_POINTER_RAY_UPDATED));
		}
	}

	dispose() {
		this.detachObject();
		this.hand.removeEventListener('connected', this._onConnected);
		this.hand.removeEventListener('disconnected', this._onDisconnected);
		this.hand.removeEventListener('pinchstart', this._onPinchStart);
		this.hand.removeEventListener('pinchend', this._onPinchEnd);
		if (this.handModel?.dispose) this.handModel.dispose();
		if (this.pointerModel?.dispose) this.pointerModel.dispose();
		if (this.hand.parent) this.hand.parent.remove(this.hand);
		if (this.holdingPoint.parent) this.holdingPoint.parent.remove(this.holdingPoint);
	}

	_setup() {
		this.hand.name = `trackedHand${this.index}`;
		this.hand.addEventListener('connected', this._onConnected);
		this.hand.addEventListener('disconnected', this._onDisconnected);
		this.hand.addEventListener('pinchstart', this._onPinchStart);
		this.hand.addEventListener('pinchend', this._onPinchEnd);

		if (this.options.handModelProfile === 'bones') {
			this.handModel = new XRHandBoneModel(this.hand, this.options.handBones);
		} else {
			const handModelFactory = new XRHandModelFactory();
			this.handModel = handModelFactory.createHandModel(this.hand, this.options.handModelProfile);
		}
		this.hand.add(this.handModel);

		this.pointerModel = new OculusHandPointerModel(this.hand, this.controller);
		this.hand.add(this.pointerModel);

		this.parentContainer.add(this.hand);
		if (!this.controller.parent) {
			this.parentContainer.add(this.controller);
		}
		this.parentContainer.add(this.holdingPoint);
	}

	_onConnected(event) {
		const inputSource = event.data;
		if (!inputSource?.hand) return;

		this.connected = true;
		this.handedness = inputSource.handedness;
		this.dispatchEvent(this._buildEvent(EventTypes.ON_HAND_CONNECTED, { originalEvent: event }));
	}

	_onDisconnected(event) {
		this.connected = false;
		this.isSqueezing = false;
		this.isPinching = false;
		this._pinchElapsed = 0;
		this._pinchHoldFired = false;
		this._pinchEventSuppressed = false;
		this._activePinchGesture = null;
		this._nativePinchActive = false;
		this._hasHoldingPointPose = false;
		this._holdingPointLostFrames = 0;
		this.detachObject();
		this.dispatchEvent(this._buildEvent(EventTypes.ON_HAND_DISCONNECTED, { originalEvent: event }));
	}

	_onPinchStart(event) {
		if (!this.connected) return;
		this._updateHoldingPoint();
		this._updatePointerRay();
		this._nativePinchActive = true;

		const gesture = this._getPinchGestureCandidate('index', this.options.pinchGestures.startDistance);
		this._pinchEventSuppressed = this.suppressPinchEvents || !gesture;
		if (this._pinchEventSuppressed) return;
		this._startPinchGesture(gesture, { originalEvent: event, inputSource: 'native' });
	}

	_onPinchEnd(event) {
		if (!this.connected) return;
		this._updateHoldingPoint();
		this._updatePointerRay();
		this._nativePinchActive = false;
		if (this._pinchEventSuppressed) {
			this._pinchEventSuppressed = false;
			return;
		}
		if (this._activePinchGesture?.inputSource === 'native') {
			this._endPinchGesture({ originalEvent: event, reason: 'native-pinch-end' });
		}
	}

	_updatePinchGesture() {
		const options = this.options.pinchGestures;

		if (this.suppressPinchEvents) {
			if (this.isPinching) this._endPinchGesture({ reason: 'suppressed' });
			return;
		}

		if (this.isPinching) {
			const active = this._activePinchGesture;
			const gesture = active
				? this._getPinchGestureCandidate(active.gestureFinger, options.endDistance, active.inputSource)
				: null;
			if (!gesture) {
				this._endPinchGesture({ reason: 'gesture-lost' });
			} else {
				this._activePinchGesture = gesture;
			}
			return;
		}

		const gesture =
			this._getPinchGestureCandidate(options.primaryFinger, options.startDistance, 'custom') ||
			this._getPinchGestureCandidate(options.alternateFinger, options.startDistance, 'custom');
		if (gesture) {
			this._startPinchGesture(gesture);
		}
	}

	_startPinchGesture(gesture, data = {}) {
		if (this.isPinching) return;

		this.isSqueezing = true;
		this.isPinching = true;
		this._pinchElapsed = 0;
		this._pinchHoldFired = false;
		this._activePinchGesture = { ...gesture, ...data };
		this.dispatchEvent(this._buildEvent(EventTypes.ON_PINCH_START, this._activePinchGesture));
	}

	_endPinchGesture(data = {}) {
		if (!this.isPinching) return;

		const gesture = this._activePinchGesture || {};
		this.isSqueezing = false;
		this.isPinching = false;
		this._pinchElapsed = 0;
		this._pinchHoldFired = false;
		this._activePinchGesture = null;
		this.dispatchEvent(this._buildEvent(EventTypes.ON_PINCH_END, { ...gesture, ...data }));
	}

	_getPinchGestureCandidate(fingerName, threshold, inputSource = 'custom') {
		const options = this.options.pinchGestures;
		if (!fingerName || !FINGER_JOINT_PREFIX[fingerName]) return null;

		const distance = this.getFingerThumbDistance(fingerName);
		if (distance == null || distance > threshold) return null;

		const palmFacingHead = this.isPalmFacingHead();
		if (
			options.rejectWhenPalmFacesHead &&
			fingerName === options.primaryFinger &&
			palmFacingHead
		) {
			return null;
		}

		return {
			inputSource,
			gestureFinger: fingerName,
			pinchDistance: distance,
			palmFacingHead,
		};
	}

	getFingerThumbDistance(fingerName) {
		const fingerPrefix = FINGER_JOINT_PREFIX[fingerName];
		if (!fingerPrefix) return null;

		const thumb = this.getJointWorldPosition('thumb-tip');
		const finger = this.getJointWorldPosition(`${fingerPrefix}-tip`);
		if (!thumb || !finger) return null;
		return thumb.distanceTo(finger);
	}

	isThumbFingerPinch(fingerName) {
		const distance = this.getFingerThumbDistance(fingerName);
		return distance != null && distance <= this.options.pinchGestures.startDistance;
	}

	isPalmFacingHead() {
		const palmNormal = this._getPalmNormalWorld();
		const palmCenter = this._getPalmCenterWorld();
		const head = this._getHeadsetPosition();
		if (!palmNormal || !palmCenter || !head) return false;

		const toHead = head.sub(palmCenter);
		if (toHead.lengthSq() === 0) return false;
		toHead.normalize();

		return palmNormal.dot(toHead) >= this.options.pinchGestures.palmFacingHeadMaxDot;
	}

	getFistStrength() {
		const palmCenter = this._getPalmCenterWorld();
		if (!palmCenter) return 0;

		const closedDistance = 0.045;
		const openDistance = 0.12;
		let total = 0;
		let count = 0;

		for (const fingerName of ['index', 'middle', 'ring', 'pinky']) {
			const fingerPrefix = FINGER_JOINT_PREFIX[fingerName];
			const tip = this.getJointWorldPosition(`${fingerPrefix}-tip`);
			if (!tip) continue;

			const distance = tip.distanceTo(palmCenter);
			const strength = 1 - THREE.MathUtils.clamp((distance - closedDistance) / (openDistance - closedDistance), 0, 1);
			total += strength;
			count += 1;
		}

		return count > 0 ? total / count : 0;
	}

	_getPalmCenterWorld() {
		const joints = [
			this.getJointWorldPosition('wrist'),
			this.getJointWorldPosition('index-finger-metacarpal'),
			this.getJointWorldPosition('middle-finger-metacarpal'),
			this.getJointWorldPosition('ring-finger-metacarpal'),
			this.getJointWorldPosition('pinky-finger-metacarpal'),
		].filter(Boolean);

		if (!joints.length) return null;
		const center = new THREE.Vector3();
		for (const joint of joints) center.add(joint);
		return center.multiplyScalar(1 / joints.length);
	}

	_getPalmNormalWorld() {
		const wrist = this.getJointWorldPosition('wrist');
		const index = this.getJointWorldPosition('index-finger-metacarpal');
		const pinky = this.getJointWorldPosition('pinky-finger-metacarpal');
		if (!wrist || !index || !pinky) return null;

		const wristToIndex = index.sub(wrist);
		const wristToPinky = pinky.sub(wrist);
		const normal = new THREE.Vector3().crossVectors(wristToPinky, wristToIndex);
		if (this.handedness === 'left') normal.negate();
		if (normal.lengthSq() === 0) return null;
		return normal.normalize();
	}

	_getHeadsetPosition() {
		const xrCamera = this.xr.getCamera();
		if (!xrCamera) return null;
		xrCamera.updateMatrixWorld(true);
		return new THREE.Vector3().setFromMatrixPosition(xrCamera.matrixWorld);
	}

	_updatePinchHold(deltaTime) {
		if (!this.isPinching || this._pinchHoldFired) return;
		this._pinchElapsed += deltaTime || 0;
		if (this._pinchElapsed < this.options.pinchHoldDelay) return;
		if (this.suppressPinchEvents || this._pinchEventSuppressed) return;

		this._pinchHoldFired = true;
		this.dispatchEvent(this._buildEvent(EventTypes.ON_PINCH_HOLD, { holdTime: this._pinchElapsed }));
	}

	_updateHoldingPoint() {
		this.hand.updateMatrixWorld(true);
		const pose = this._sampleHoldingPointPose();
		if (!pose) {
			this._holdingPointLostFrames += 1;
			if (
				this._hasHoldingPointPose &&
				this._holdingPointLostFrames <= this.options.handGrip.lostTrackingGraceFrames
			) {
				this._applyHoldingPointPose(this._lastHoldingPointPosition, this._lastHoldingPointQuaternion);
			}
			return;
		}

		this._holdingPointLostFrames = 0;
		this._applyHoldingPointPose(pose.position, pose.quaternion);
		this._hasHoldingPointPose = true;
	}

	_sampleHoldingPointPose() {
		const gripOptions = this.options.handGrip;
		if (gripOptions.positionMode !== 'pinch-midpoint') return null;

		const thumbTip = this.getJoint('thumb-tip');
		const indexTip = this.getJoint('index-finger-tip');
		if (!thumbTip?.visible || !indexTip?.visible) return null;

		const thumbWorld = thumbTip.getWorldPosition(new THREE.Vector3());
		const indexWorld = indexTip.getWorldPosition(new THREE.Vector3());
		const position = thumbWorld.add(indexWorld).multiplyScalar(0.5);
		const quaternion = this.controller.getWorldQuaternion(new THREE.Quaternion());

		return { position, quaternion };
	}

	_applyHoldingPointPose(position, quaternion) {
		const gripOptions = this.options.handGrip;
		const positionSmoothing = THREE.MathUtils.clamp(gripOptions.positionSmoothing || 0, 0, 1);
		const rotationSmoothing = THREE.MathUtils.clamp(gripOptions.rotationSmoothing || 0, 0, 1);

		if (positionSmoothing > 0 && this._hasHoldingPointPose) {
			this.holdingPoint.position.lerp(position, 1 - positionSmoothing);
		} else {
			this.holdingPoint.position.copy(position);
		}

		if (rotationSmoothing > 0 && this._hasHoldingPointPose) {
			this.holdingPoint.quaternion.slerp(quaternion, 1 - rotationSmoothing);
		} else {
			this.holdingPoint.quaternion.copy(quaternion);
		}

		this._lastHoldingPointPosition.copy(this.holdingPoint.position);
		this._lastHoldingPointQuaternion.copy(this.holdingPoint.quaternion);
		this.holdingPoint.updateMatrixWorld(true);
	}

	_updatePointerRay() {
		this.lastRay = this.ray.clone();
		this.controller.updateMatrixWorld(true);
		this.pointerModel?.updateMatrixWorld(true);

		if (this.pointerModel?.raycaster) {
			this.ray.copy(this.pointerModel.raycaster.ray);
			return;
		}

		const mat = new THREE.Matrix4().identity().extractRotation(this.controller.matrixWorld);
		const origin = new THREE.Vector3().setFromMatrixPosition(this.controller.matrixWorld);
		const direction = new THREE.Vector3(0, 0, -1).applyMatrix4(mat);
		this.ray.set(origin, direction);
	}

	_buildEvent(type, data = {}) {
		return {
			type,
			source: this.source,
			controller: this,
			hand: this,
			handedness: this.handedness,
			ray: this.ray.clone(),
			...data,
		};
	}
}
