const METHODS = ['log', 'info', 'warn', 'error', 'debug', 'trace', 'clear'];

const subscribers = new Set();
const originals = new Map();
const wrappers = new Map();
let runtimeListenersInstalled = false;

function notify(type, args, source = 'console', metadata = {}) {
	for (const subscriber of [...subscribers]) {
		if (source === 'runtime' && !subscriber.captureRuntimeErrors) continue;
		try {
			subscriber.capture(type, args, source, metadata);
		} catch (_) {
			// A debug surface must never break the application it is observing.
		}
	}
}

function installConsoleWrappers() {
	if (wrappers.size > 0) return;

	for (const method of METHODS) {
		const original = console[method];
		if (typeof original !== 'function') continue;
		originals.set(method, original);

		const wrapper = function (...args) {
			const metadata = method === 'trace' ? { stack: new Error().stack } : {};
			const result = original.apply(console, args);
			notify(method, args, 'console', metadata);
			return result;
		};
		wrappers.set(method, wrapper);
		console[method] = wrapper;
	}
}

function uninstallConsoleWrappers() {
	for (const [method, wrapper] of wrappers) {
		// Do not overwrite a wrapper installed by somebody else after VRConsole.
		if (console[method] === wrapper) console[method] = originals.get(method);
	}
	originals.clear();
	wrappers.clear();
}

function onWindowError(event) {
	const value = event.error || `${event.message || 'Uncaught error'}${event.filename ? ` (${event.filename}:${event.lineno || 0}:${event.colno || 0})` : ''}`;
	notify('error', ['[uncaught]', value], 'runtime');
}

function onUnhandledRejection(event) {
	notify('error', ['[unhandledrejection]', event.reason], 'runtime');
}

function syncRuntimeListeners() {
	if (typeof window === 'undefined') return;
	const needed = [...subscribers].some((subscriber) => subscriber.captureRuntimeErrors);
	if (needed === runtimeListenersInstalled) return;

	if (needed) {
		window.addEventListener('error', onWindowError);
		window.addEventListener('unhandledrejection', onUnhandledRejection);
	} else {
		window.removeEventListener('error', onWindowError);
		window.removeEventListener('unhandledrejection', onUnhandledRejection);
	}
	runtimeListenersInstalled = needed;
}

/**
 * Subscribes a sink to the process-wide console mirror.
 * @param {{capture: Function, captureRuntimeErrors?: boolean}} subscriber
 * @returns {Function} unsubscribe callback
 */
export function subscribeToConsole(subscriber) {
	if (!subscriber || typeof subscriber.capture !== 'function') {
		throw new TypeError('VRConsole interceptor subscriber requires capture(type, args, source)');
	}
	subscribers.add(subscriber);
	installConsoleWrappers();
	syncRuntimeListeners();

	let active = true;
	return () => {
		if (!active) return;
		active = false;
		subscribers.delete(subscriber);
		syncRuntimeListeners();
		if (subscribers.size === 0) uninstallConsoleWrappers();
	};
}
