import * as THREE from 'three';
import { snapshotDebugValue } from './DebugValueSnapshot.js';

export const defaultWatcherRendererOptions = {
	width: 600,
	height: 360,
	precision: 2,
	refreshIntervalMs: 0,
	maxDepth: 4,
	maxProperties: 50,
	maxStringLength: 2_000,
	changeHighlightMs: 350,
	historyLength: 120,
	density: 'normal',
	columns: 1,
};

const COLORS = {
	background: '#15191e',
	header: '#242a31',
	headerBorder: '#46505c',
	row: '#1b2026',
	rowAlt: '#20262d',
	text: '#e7edf3',
	muted: '#98a5b3',
	accent: '#68b5ff',
	changed: '#284b38',
	warn: '#5a431d',
	critical: '#5b2929',
	error: '#ff8b8b',
	scrollTrack: '#2c333c',
	scrollThumb: '#778594',
};

function nowMs() {
	return typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();
}

function safeInstance(value, constructor) {
	try { return value instanceof constructor; } catch (_) { return false; }
}

function formatNumber(value, precision) {
	if (!Number.isFinite(value)) return String(value);
	return value.toFixed(Math.max(0, Math.min(20, precision)));
}

function isCompactThreeValue(value) {
	return safeInstance(value, THREE.Vector2) || safeInstance(value, THREE.Vector3) ||
		safeInstance(value, THREE.Vector4) || safeInstance(value, THREE.Euler) ||
		safeInstance(value, THREE.Quaternion) || safeInstance(value, THREE.Color) ||
		safeInstance(value, THREE.Matrix3) || safeInstance(value, THREE.Matrix4);
}

function formatCompactValue(value, precision, maxStringLength) {
	const n = (number) => formatNumber(number, precision);
	if (safeInstance(value, THREE.Vector2)) return `x:${n(value.x)} y:${n(value.y)}`;
	if (safeInstance(value, THREE.Vector3)) return `x:${n(value.x)} y:${n(value.y)} z:${n(value.z)}`;
	if (safeInstance(value, THREE.Vector4) || safeInstance(value, THREE.Quaternion)) {
		return `x:${n(value.x)} y:${n(value.y)} z:${n(value.z)} w:${n(value.w)}`;
	}
	if (safeInstance(value, THREE.Euler)) return `x:${n(value.x)} y:${n(value.y)} z:${n(value.z)} ${value.order}`;
	if (safeInstance(value, THREE.Color)) return `#${value.getHexString()}`;
	if (safeInstance(value, THREE.Matrix3) || safeInstance(value, THREE.Matrix4)) {
		return `[${value.elements.map((item) => n(item)).join(', ')}]`;
	}
	if (value === null) return 'null';
	if (value === undefined) return 'undefined';
	if (typeof value === 'number') return n(value);
	if (typeof value === 'bigint') return `${value}n`;
	if (typeof value === 'string') {
		return value.length <= maxStringLength ? value : `${value.slice(0, maxStringLength)}…`;
	}
	if (typeof value === 'function') return `ƒ ${value.name || '(anonymous)'}()`;
	if (typeof value === 'symbol') return String(value);
	return String(value);
}

function snapshotText(node) {
	if (!node) return 'undefined';
	if ('text' in node) return node.text;
	if (node.type === 'array' || node.type === 'typedarray' || node.type === 'map' || node.type === 'set') return node.label;
	if (node.type === 'date' || node.type === 'regexp' || node.type === 'error') return node.label;
	return `${node.label || 'Object'} ${node.properties?.length ? '{…}' : '{}'}`;
}

function hasChildren(node) {
	return Boolean(node && (node.properties?.length || node.truncated));
}

function pathSegment(key) {
	return encodeURIComponent(String(key)).replaceAll('.', '%2E');
}

function fitText(context, text, maxWidth) {
	if (maxWidth <= 0) return '';
	const value = String(text);
	if (context.measureText(value).width <= maxWidth) return value;
	const suffix = '…';
	let low = 0;
	let high = value.length;
	while (low < high) {
		const middle = Math.ceil((low + high) / 2);
		if (context.measureText(value.slice(0, middle) + suffix).width <= maxWidth) low = middle;
		else high = middle - 1;
	}
	return value.slice(0, low) + suffix;
}

/** Canvas renderer and interaction model for live watched values. */
export class VRVarsWatcherRenderer {
	constructor(options = {}) {
		this.options = { ...defaultWatcherRendererOptions, ...options };
		this.width = this.options.width;
		this.height = this.options.height;
		this.canvas = this.options.canvas || document.createElement('canvas');
		this.canvas.width = this.width;
		this.canvas.height = this.height;
		this.context = this.canvas.getContext('2d');
		this.entries = [];
		this.activeTab = 'General';
		this.tabOffset = 0;
		this.scrollByTab = new Map();
		this.expanded = new Set();
		this.hitZones = [];
		this.pointer = null;
		this.filter = '';
		this.paused = false;
		this.lastEvaluationAt = -Infinity;
		this.onRender = null;
		this.renderCount = 0;
		this.contentHeight = 0;
		this.metrics = {
			evaluationMs: 0,
			renderMs: 0,
			getterMs: 0,
			evaluatedEntries: 0,
			renderCount: 0,
		};
		this.render();
	}

	get tabs() {
		const tabs = ['General'];
		for (const entry of this.entries) {
			if (!tabs.includes(entry.tab)) tabs.push(entry.tab);
		}
		if (this.entries.some((entry) => entry.pinned)) tabs.push('Pinned');
		return tabs;
	}

	get headerHeight() {
		return 38;
	}

	get lineHeight() {
		return this.options.density === 'compact' ? 19 : 25;
	}

	get viewportHeight() {
		return this.height - this.headerHeight;
	}

	get scrollTop() {
		return this.scrollByTab.get(this.activeTab) || 0;
	}

	set scrollTop(value) {
		this.scrollByTab.set(this.activeTab, Math.max(0, Math.min(value, this.maxScroll)));
	}

	get maxScroll() {
		return Math.max(0, this.contentHeight - this.viewportHeight);
	}

	add(entry) {
		this.entries.push(entry);
		this.render();
	}

	remove(id) {
		const index = this.entries.findIndex((entry) => entry.id === id);
		if (index < 0) return false;
		this.entries.splice(index, 1);
		for (const key of [...this.expanded]) if (key.startsWith(`${id}:`)) this.expanded.delete(key);
		this._repairActiveTab();
		this.render();
		return true;
	}

	clear(tab) {
		const removedIds = new Set();
		this.entries = this.entries.filter((entry) => {
			const remove = tab === undefined || entry.tab === tab || (tab === 'Pinned' && entry.pinned);
			if (remove) removedIds.add(entry.id);
			return !remove;
		});
		for (const key of [...this.expanded]) {
			if (removedIds.has(Number(key.slice(0, key.indexOf(':'))))) this.expanded.delete(key);
		}
		this._repairActiveTab();
		this.render();
		return removedIds;
	}

	_repairActiveTab() {
		if (!this.tabs.includes(this.activeTab)) this.activeTab = 'General';
		this.scrollTop = this.scrollTop;
	}

	setActiveTab(tab) {
		if (!this.tabs.includes(tab)) throw new RangeError(`Unknown VRVarsWatcher tab: ${tab}`);
		if (this.activeTab === tab) return;
		this.activeTab = tab;
		const isAlreadyVisible = this.hitZones.some((zone) => zone.action.type === 'tab' && zone.action.tab === tab);
		if (!isAlreadyVisible) this.tabOffset = this.tabs.indexOf(tab);
		if (this.paused) this.render();
		else this.evaluate(nowMs(), true);
	}

	setPaused(paused) {
		const next = Boolean(paused);
		if (this.paused === next) return;
		this.paused = next;
		if (this.paused) this.render();
		else this.evaluate(nowMs(), true);
	}

	setFilter(filter) {
		this.filter = String(filter || '').trim().toLowerCase();
		this.scrollTop = 0;
		this.render();
	}

	setDensity(density) {
		if (!['normal', 'compact'].includes(density)) throw new RangeError("density must be 'normal' or 'compact'");
		this.options.density = density;
		this.scrollTop = 0;
		this.render();
	}

	setColumns(columns) {
		if (columns !== 1 && columns !== 2) throw new RangeError('columns must be 1 or 2');
		this.options.columns = columns;
		this.scrollTop = 0;
		this.render();
	}

	setPinned(id, pinned) {
		const entry = this.entries.find((candidate) => candidate.id === id);
		if (!entry) return false;
		entry.pinned = Boolean(pinned);
		this._repairActiveTab();
		this.render();
		return true;
	}

	_visibleEntries() {
		return this.entries.filter((entry) => {
			const inTab = this.activeTab === 'Pinned' ? entry.pinned : entry.tab === this.activeTab;
			return inTab && (!this.filter || entry.name.toLowerCase().includes(this.filter));
		});
	}

	_statusFor(entry, value) {
		const options = entry.options;
		if (typeof options.threshold === 'function') {
			try {
				const status = options.threshold(value);
				if (status === 'warn' || status === 'critical') return status;
			} catch (_) { /* a display hint must not break evaluation */ }
		}
		if (typeof value !== 'number') return null;
		if ((Number.isFinite(options.criticalAbove) && value > options.criticalAbove) ||
			(Number.isFinite(options.criticalBelow) && value < options.criticalBelow)) return 'critical';
		if ((Number.isFinite(options.warnAbove) && value > options.warnAbove) ||
			(Number.isFinite(options.warnBelow) && value < options.warnBelow)) return 'warn';
		return null;
	}

	_evaluateEntry(entry, timestamp) {
		const started = nowMs();
		let value;
		let text;
		let snapshot = null;
		let error = null;
		try {
			value = entry.getter();
			const precision = entry.options.precision ?? this.options.precision;
			if (typeof entry.options.formatter === 'function') text = String(entry.options.formatter(value));
			else text = formatCompactValue(value, precision, this.options.maxStringLength);
			if (value !== null && (typeof value === 'object' || typeof value === 'function')) {
				const compactThreeValue = isCompactThreeValue(value);
				const expandable = entry.options.expandable !== false &&
					(!compactThreeValue || entry.options.expandable === true);
				if (expandable) {
					snapshot = snapshotDebugValue(value, {
						maxDepth: entry.options.maxDepth ?? this.options.maxDepth,
						maxProperties: entry.options.maxProperties ?? this.options.maxProperties,
						maxStringLength: entry.options.maxStringLength ?? this.options.maxStringLength,
					});
					if (typeof entry.options.formatter !== 'function' && !compactThreeValue) text = snapshotText(snapshot);
				}
			}
			if (entry.options.unit) text += ` ${entry.options.unit}`;
		} catch (caught) {
			error = caught;
			text = `⚠ Error: ${caught?.message || String(caught)}`;
		}

		const signature = error ? `error:${text}` : `${text}|${snapshot ? JSON.stringify(snapshot) : ''}`;
		const firstValue = !entry.model;
		const changed = !firstValue && entry.model.signature !== signature;
		const history = entry.model?.history || [];
		if (!error && entry.options.history && typeof value === 'number' && Number.isFinite(value)) {
			history.push({ time: timestamp, value });
			const limit = Math.max(2, entry.options.historyLength || this.options.historyLength);
			if (history.length > limit) history.splice(0, history.length - limit);
		}
		entry.model = {
			value,
			text,
			snapshot,
			error,
			signature,
			changedAt: changed ? timestamp : entry.model?.changedAt || -Infinity,
			history,
			status: error ? 'critical' : this._statusFor(entry, value),
			lastEvaluationMs: nowMs() - started,
		};
		return changed || firstValue || Boolean(entry.options.history);
	}

	evaluate(timestamp = nowMs(), force = false) {
		if (this.paused && !force) return false;
		const interval = Math.max(0, this.options.refreshIntervalMs || 0);
		if (!force && interval && timestamp - this.lastEvaluationAt < interval) return false;
		this.lastEvaluationAt = timestamp;
		const started = nowMs();
		let getterMs = 0;
		let changed = false;
		const visible = this._visibleEntries();
		for (const entry of visible) {
			changed = this._evaluateEntry(entry, timestamp) || changed;
			getterMs += entry.model.lastEvaluationMs;
		}
		this.metrics.evaluationMs = nowMs() - started;
		this.metrics.getterMs = getterMs;
		this.metrics.evaluatedEntries = visible.length;
		const highlighting = visible.some((entry) => timestamp - (entry.model?.changedAt || -Infinity) < this.options.changeHighlightMs);
		if (changed || highlighting || force) this.render(timestamp);
		return changed;
	}

	_rootKey(entry) {
		return `${entry.id}:root`;
	}

	_appendNodeRows(rows, entry, node, path, depth) {
		const expandKey = `${entry.id}:${path}`;
		if (!this.expanded.has(expandKey)) return;
		for (const property of node.properties || []) {
			const childPath = `${path}.${pathSegment(property.key)}`;
			rows.push({
				entry,
				kind: 'property',
				name: property.key,
				text: snapshotText(property.value),
				depth,
				expandKey: hasChildren(property.value) ? `${entry.id}:${childPath}` : null,
			});
			this._appendNodeRows(rows, entry, property.value, childPath, depth + 1);
		}
		if (node.truncated) rows.push({ entry, kind: 'property', name: '', text: '… truncated', depth, expandKey: null });
	}

	_buildRows() {
		const rows = [];
		for (const entry of this._visibleEntries()) {
			const model = entry.model;
			const rootExpandable = Boolean(model && (hasChildren(model.snapshot) || model.history.length));
			rows.push({
				entry,
				kind: 'entry',
				name: entry.name,
				text: model?.text || '—',
				depth: 0,
				expandKey: rootExpandable ? this._rootKey(entry) : null,
			});
			if (model?.snapshot) this._appendNodeRows(rows, entry, model.snapshot, 'root', 1);
			if (model?.history.length && this.expanded.has(this._rootKey(entry))) {
				const values = model.history.map((sample) => sample.value);
				const min = Math.min(...values);
				const max = Math.max(...values);
				const average = values.reduce((sum, value) => sum + value, 0) / values.length;
				const precision = entry.options.precision ?? this.options.precision;
				rows.push({
					entry,
					kind: 'history',
					name: 'history',
					text: `min ${formatNumber(min, precision)}  avg ${formatNumber(average, precision)}  max ${formatNumber(max, precision)}`,
					depth: 1,
					expandKey: null,
				});
			}
		}
		return rows;
	}

	_layoutRows(rows) {
		const columnCount = this.options.columns === 2 ? 2 : 1;
		if (columnCount === 1) {
			return {
				items: rows.map((row, rowIndex) => ({ row, column: 0, rowIndex })),
				rowCount: rows.length,
				columnCount,
			};
		}

		const blocks = [];
		let block = null;
		for (const row of rows) {
			if (row.kind === 'entry' || !block) {
				block = [];
				blocks.push(block);
			}
			block.push(row);
		}
		const targetRows = Math.ceil(rows.length / 2);
		const columns = [[], []];
		for (const candidate of blocks) {
			const useSecond = columns[0].length > 0 && columns[0].length + candidate.length > targetRows;
			columns[useSecond ? 1 : 0].push(...candidate);
		}
		return {
			items: columns.flatMap((columnRows, column) =>
				columnRows.map((row, rowIndex) => ({ row, column, rowIndex }))),
			rowCount: Math.max(columns[0].length, columns[1].length),
			columnCount,
		};
	}

	_renderTabs(context) {
		context.fillStyle = COLORS.header;
		context.fillRect(0, 0, this.width, this.headerHeight);
		context.strokeStyle = COLORS.headerBorder;
		context.beginPath();
		context.moveTo(0, this.headerHeight - 0.5);
		context.lineTo(this.width, this.headerHeight - 0.5);
		context.stroke();
		context.textBaseline = 'middle';
		context.font = 'bold 13px monospace';
		context.fillStyle = COLORS.text;
		context.fillText('VRVarsWatcher', 10, 19);
		const titleEnd = 10 + context.measureText('VRVarsWatcher').width;
		const dividerX = Math.ceil(titleEnd + 9) + 0.5;
		context.strokeStyle = COLORS.headerBorder;
		context.beginPath();
		context.moveTo(dividerX, 7);
		context.lineTo(dividerX, 31);
		context.stroke();
		const tabsStart = dividerX + 9;

		const pauseWidth = 62;
		const pauseX = this.width - pauseWidth - 5;
		context.fillStyle = this.paused ? '#684d20' : '#303842';
		context.fillRect(pauseX, 6, pauseWidth, 26);
		context.strokeStyle = COLORS.headerBorder;
		context.strokeRect(pauseX + 0.5, 6.5, pauseWidth - 1, 25);
		context.fillStyle = COLORS.text;
		context.fillText(this.paused ? 'RESUME' : 'PAUSE', pauseX + 8, 19);
		this.hitZones.push({ x: pauseX, y: 6, w: pauseWidth, h: 26, action: { type: 'pause' } });

		const tabs = this.tabs;
		const availableRight = pauseX - 5;
		if (tabs.length === 1) return;
		context.font = 'bold 11px monospace';
		const widths = tabs.map((tab) => Math.max(60, Math.min(140, context.measureText(tab).width + 20)));
		const totalWidth = widths.reduce((sum, width) => sum + width + 4, 0);
		const overflowing = totalWidth > availableRight - tabsStart;
		if (!overflowing) this.tabOffset = 0;
		let x = tabsStart;
		let rightLimit = availableRight;
		if (overflowing) {
			const arrowWidth = 25;
			context.fillStyle = '#303842';
			context.fillRect(x, 6, arrowWidth, 26);
			context.fillStyle = this.tabOffset > 0 ? COLORS.text : COLORS.muted;
			context.fillText('‹', x + 8, 19);
			this.hitZones.push({ x, y: 6, w: arrowWidth, h: 26, action: { type: 'tabPage', delta: -1 } });
			x += arrowWidth + 4;
			rightLimit -= arrowWidth + 4;
		}

		let hasMore = false;
		for (let index = this.tabOffset; index < tabs.length; index++) {
			const width = widths[index];
			if (x + width > rightLimit) {
				hasMore = true;
				break;
			}
			const tab = tabs[index];
			const active = tab === this.activeTab;
			context.fillStyle = active ? '#385875' : '#303842';
			context.fillRect(x, 6, width, 26);
			context.strokeStyle = active ? COLORS.accent : COLORS.headerBorder;
			context.strokeRect(x + 0.5, 6.5, width - 1, 25);
			context.fillStyle = active ? '#ffffff' : COLORS.text;
			context.fillText(fitText(context, tab, width - 14), x + 7, 19);
			this.hitZones.push({ x, y: 6, w: width, h: 26, action: { type: 'tab', tab } });
			x += width + 4;
		}
		if (overflowing) {
			const arrowX = availableRight - 25;
			context.fillStyle = '#303842';
			context.fillRect(arrowX, 6, 25, 26);
			context.fillStyle = hasMore ? COLORS.text : COLORS.muted;
			context.fillText('›', arrowX + 8, 19);
			this.hitZones.push({ x: arrowX, y: 6, w: 25, h: 26, action: { type: 'tabPage', delta: 1 } });
		}
	}

	_drawSparkline(context, history, x, y, width, height) {
		if (!history || history.length < 2 || width < 10) return;
		const values = history.map((sample) => sample.value);
		const min = Math.min(...values);
		const max = Math.max(...values);
		const span = max - min || 1;
		context.strokeStyle = COLORS.accent;
		context.beginPath();
		for (let index = 0; index < values.length; index++) {
			const px = x + (index / (values.length - 1)) * width;
			const py = y + height - ((values[index] - min) / span) * height;
			if (index === 0) context.moveTo(px, py);
			else context.lineTo(px, py);
		}
		context.stroke();
	}

	_renderScrollbar(context) {
		if (this.contentHeight <= this.viewportHeight) return;
		const x = this.width - 10;
		const y = this.headerHeight + 2;
		const height = this.viewportHeight - 4;
		const thumbHeight = Math.max(24, height * (this.viewportHeight / this.contentHeight));
		const travel = height - thumbHeight;
		const thumbY = y + (this.maxScroll ? (this.scrollTop / this.maxScroll) * travel : 0);
		context.fillStyle = COLORS.scrollTrack;
		context.fillRect(x, y, 7, height);
		context.fillStyle = COLORS.scrollThumb;
		context.fillRect(x, thumbY, 7, thumbHeight);
		this.hitZones.push({
			x, y, w: 7, h: height,
			action: { type: 'scrollTrack', thumbY, thumbHeight, trackY: y, trackHeight: height },
		});
	}

	render(timestamp = nowMs()) {
		const started = nowMs();
		const context = this.context;
		this.hitZones = [];
		const rows = this._buildRows();
		const layout = this._layoutRows(rows);
		this.contentHeight = layout.rowCount * this.lineHeight + 8;
		this.scrollTop = this.scrollTop;
		context.clearRect(0, 0, this.width, this.height);
		context.fillStyle = COLORS.background;
		context.fillRect(0, 0, this.width, this.height);
		this._renderTabs(context);
		context.save();
		context.beginPath();
		context.rect(0, this.headerHeight, this.width, this.viewportHeight);
		context.clip();
		context.font = this.options.density === 'compact' ? '11px monospace' : '13px monospace';
		context.textBaseline = 'middle';

		const contentWidth = this.width - 11;
		const columnWidth = contentWidth / layout.columnCount;
		if (layout.columnCount === 2) {
			context.strokeStyle = COLORS.headerBorder;
			context.beginPath();
			context.moveTo(columnWidth + 0.5, this.headerHeight);
			context.lineTo(columnWidth + 0.5, this.height);
			context.stroke();
		}
		for (const item of layout.items) {
			const { row, column, rowIndex } = item;
			const xOffset = column * columnWidth;
			const labelWidth = Math.max(96, Math.floor(columnWidth * 0.38));
			const y = this.headerHeight + 4 + rowIndex * this.lineHeight - this.scrollTop;
			if (y + this.lineHeight < this.headerHeight || y > this.height) continue;
			const model = row.entry.model;
			let background = rowIndex % 2 ? COLORS.rowAlt : COLORS.row;
			if (model?.status === 'warn') background = COLORS.warn;
			if (model?.status === 'critical') background = COLORS.critical;
			if (timestamp - (model?.changedAt || -Infinity) < this.options.changeHighlightMs) background = COLORS.changed;
			context.fillStyle = background;
			context.fillRect(xOffset, y, columnWidth - 1, this.lineHeight - 1);

			const indent = row.depth * 16;
			const marker = row.expandKey ? (this.expanded.has(row.expandKey) ? '▼ ' : '▶ ') : '  ';
			context.fillStyle = row.kind === 'entry' ? COLORS.text : COLORS.muted;
			const nameX = xOffset + 7 + indent;
			const nameWidth = Math.max(20, xOffset + labelWidth - nameX - 5);
			context.fillText(fitText(context, marker + row.name, nameWidth), nameX, y + this.lineHeight / 2);

			const pinWidth = row.kind === 'entry' ? 22 : 0;
			const sparkWidth = row.kind === 'entry' && model?.history.length > 1 ? Math.min(86, columnWidth * 0.2) : 0;
			const valueX = xOffset + labelWidth + 7;
			const valueRight = xOffset + columnWidth - 5 - pinWidth - (sparkWidth ? sparkWidth + 8 : 0);
			let displayText = row.text;
			if (row.kind === 'entry' && model?.history.length > 1) {
				const previous = model.history.at(-2).value;
				const current = model.history.at(-1).value;
				displayText = `${current > previous ? '↑' : current < previous ? '↓' : '→'} ${displayText}`;
			}
			context.fillStyle = model?.error ? COLORS.error : row.entry.options.color || COLORS.text;
			context.fillText(fitText(context, displayText, Math.max(10, valueRight - valueX)), valueX, y + this.lineHeight / 2);
			if (sparkWidth) this._drawSparkline(context, model.history, valueRight + 4, y + 5, sparkWidth, this.lineHeight - 10);

			if (row.kind === 'entry') {
				const pinX = xOffset + columnWidth - 24;
				context.fillStyle = row.entry.pinned ? '#ffd166' : COLORS.muted;
				context.fillText(row.entry.pinned ? '★' : '☆', pinX, y + this.lineHeight / 2);
				this.hitZones.push({ x: pinX - 5, y, w: 24, h: this.lineHeight, action: { type: 'pin', id: row.entry.id } });
			}
			if (row.expandKey) {
				this.hitZones.push({ x: xOffset, y, w: labelWidth, h: this.lineHeight, action: { type: 'toggle', key: row.expandKey } });
			}
		}
		context.restore();
		this._renderScrollbar(context);
		this.renderCount++;
		this.metrics.renderCount = this.renderCount;
		this.metrics.renderMs = nowMs() - started;
		if (this.onRender) this.onRender(this.canvas);
	}

	_hitTest(x, y) {
		for (let index = this.hitZones.length - 1; index >= 0; index--) {
			const zone = this.hitZones[index];
			if (x >= zone.x && x <= zone.x + zone.w && y >= zone.y && y <= zone.y + zone.h) return zone;
		}
		return null;
	}

	_actionId(action) {
		if (!action) return null;
		if (action.type === 'tab') return `tab:${action.tab}`;
		if (action.type === 'tabPage') return `tabPage:${action.delta}`;
		if (action.type === 'toggle') return `toggle:${action.key}`;
		if (action.type === 'pin') return `pin:${action.id}`;
		return action.type;
	}

	pointerDown(x, y) {
		const zone = this._hitTest(x, y);
		this.pointer = {
			x,
			y,
			startScroll: this.scrollTop,
			zone,
			actionId: this._actionId(zone?.action),
			moved: false,
		};
	}

	pointerMove(x, y) {
		if (!this.pointer) return;
		if (Math.hypot(x - this.pointer.x, y - this.pointer.y) > 4) this.pointer.moved = true;
		if (!this.pointer.moved) return;
		const action = this.pointer.zone?.action;
		let scrolled = false;
		if (action?.type === 'scrollTrack') {
			const travel = action.trackHeight - action.thumbHeight;
			if (travel > 0) {
				this.scrollTop = this.pointer.startScroll + ((y - this.pointer.y) / travel) * this.maxScroll;
				scrolled = true;
			}
		} else if (this.pointer.y >= this.headerHeight) {
			this.scrollTop = this.pointer.startScroll - (y - this.pointer.y);
			scrolled = this.maxScroll > 0;
		}
		if (scrolled) this.render();
	}

	pointerUp(x, y) {
		if (!this.pointer) return;
		const pointer = this.pointer;
		this.pointer = null;
		if (pointer.moved) return;
		const zone = this._hitTest(x, y);
		if (!zone || this._actionId(zone.action) !== pointer.actionId) return;
		const action = zone.action;
		if (action.type === 'tab') this.setActiveTab(action.tab);
		else if (action.type === 'tabPage') {
			this.tabOffset = Math.max(0, Math.min(this.tabs.length - 1, this.tabOffset + action.delta));
			this.render();
		} else if (action.type === 'pause') this.setPaused(!this.paused);
		else if (action.type === 'toggle') {
			if (this.expanded.has(action.key)) this.expanded.delete(action.key);
			else this.expanded.add(action.key);
			this.render();
		} else if (action.type === 'pin') this.setPinned(action.id, !this.entries.find((entry) => entry.id === action.id)?.pinned);
		else if (action.type === 'scrollTrack') {
			const travel = action.trackHeight - action.thumbHeight;
			const position = travel > 0 ? (y - action.trackY - action.thumbHeight / 2) / travel : 0;
			this.scrollTop = Math.max(0, Math.min(1, position)) * this.maxScroll;
			this.render();
		}
	}

	pointerCancel() {
		this.pointer = null;
	}

	dispose() {
		this.pointer = null;
		this.onRender = null;
		this.hitZones.length = 0;
		this.entries.length = 0;
		this.expanded.clear();
		this.scrollByTab.clear();
	}
}
