/**
 * @module XRControllerLabelHelper
 * @description
 * Builds floating text labels and leader lines for WebXR controller model
 * components such as triggers, grips, thumbsticks, and face buttons.
 */
import * as THREE from 'three';

/**
 * Default labels for common WebXR input profile component ids.
 * Override these per application through the `labels` constructor option.
 * @type {Object<string, string>}
 */
export const DEFAULT_CONTROLLER_LABELS = {
	'xr-standard-trigger': 'Trigger',
	'xr-standard-squeeze': 'Grip',
	'xr-standard-thumbstick': 'Joystick',
	'a-button': 'A',
	'b-button': 'B',
	'x-button': 'X',
	'y-button': 'Y',
	menu: 'Menu',
	thumbrest: 'Thumbrest',
};

/**
 * Initial Quest Touch Plus offsets in controller local coordinates.
 * Values are in meters and can be calibrated per application.
 * @type {Object<string, Object<string, Object<string, THREE.Vector3>>>}
 */
export const DEFAULT_CONTROLLER_LABEL_OFFSETS = {
	'meta-quest-touch-plus': {
		right: {
			'a-button': new THREE.Vector3(0.055, 0.04, -0.015),
			'b-button': new THREE.Vector3(0.06, 0.055, -0.02),
			'xr-standard-thumbstick': new THREE.Vector3(0.05, 0.035, 0),
			'xr-standard-trigger': new THREE.Vector3(0.035, -0.025, -0.02),
			'xr-standard-squeeze': new THREE.Vector3(0.045, -0.015, 0.02),
			thumbrest: new THREE.Vector3(0.055, 0.025, 0),
		},
		left: {
			'x-button': new THREE.Vector3(-0.055, 0.04, -0.015),
			'y-button': new THREE.Vector3(-0.06, 0.055, -0.02),
			menu: new THREE.Vector3(-0.055, 0.025, -0.005),
			'xr-standard-thumbstick': new THREE.Vector3(-0.05, 0.035, 0),
			'xr-standard-trigger': new THREE.Vector3(-0.035, -0.025, -0.02),
			'xr-standard-squeeze': new THREE.Vector3(-0.045, -0.015, 0.02),
			thumbrest: new THREE.Vector3(-0.055, 0.025, 0),
		},
	},
};

/**
 * Identifier and version for portable manual controller-label layout documents.
 */
export const CONTROLLER_LABEL_LAYOUT_SCHEMA = 'three-xr-toolkit/controller-label-layout';
export const CONTROLLER_LABEL_LAYOUT_VERSION = 1;

const DEFAULT_STYLE = {
	backgroundColor: 'rgba(20, 24, 28, 0.85)',
	borderColor: 'rgba(255, 255, 255, 0.55)',
	textColor: '#ffffff',
	fontFamily: 'sans-serif',
	fontSize: 38,
	minFontSize: 20,
	canvasWidth: 512,
	canvasHeight: 128,
	padding: 22,
	cornerRadius: 24,
	labelWidth: 0.115,
	labelHeight: 0.032,
	labelWidthMode: 'uniform',
	labelHorizontalPadding: 0.012,
	lineColor: 0xffffff,
	lineOpacity: 1,
	lineDepthTest: true,
	lineDepthWrite: true,
	labelOpacity: 1,
	labelAlphaTest: 0.01,
	labelDepthTest: true,
	labelDepthWrite: true,
	depthTest: true,
};

const DEFAULT_LAYOUT = {
	mode: 'split',
	axis: 'y',
	minGap: 0.008,
	sideDistance: 0.095,
	minHorizontalMargin: 0,
	planarity: 0,
	minDistance: 0.095,
	angularSpacing: 1,
	lockSideAxis: true,
	lockDepthAxis: false,
	screenSpace: true,
	sideByComponent: null,
	manualLayout: null,
};

const LAYOUT_EPSILON = 1e-6;

const DEFAULT_LAYOUT_SIDE_BY_COMPONENT = {
	'xr-standard-trigger': 'left',
	'xr-standard-squeeze': 'left',
	menu: 'left',
	thumbrest: 'left',
	'xr-standard-thumbstick': 'right',
	'a-button': 'right',
	'b-button': 'right',
	'x-button': 'right',
	'y-button': 'right',
};

/**
 * Creates text sprites and leader lines anchored to WebXR controller model
 * components such as trigger, grip, thumbstick, A/B/X/Y buttons, and menu.
 *
 * @example
 * const labels = await new XRControllerLabelHelper({
 *   handController: controllers.right,
 *   labels: {
 *     ...DEFAULT_CONTROLLER_LABELS,
 *     'a-button': 'Jump',
 *   },
 * }).init();
 *
 * labels.setVisible(true);
 */
export class XRControllerLabelHelper {
	/**
	 * @param {object} options
	 * @param {THREE.Group} [options.controllerGrip] - Grip group returned by `renderer.xr.getControllerGrip(index)`.
	 * @param {THREE.Object3D} [options.controllerModel] - Controller model created by `XRControllerModelFactory`.
	 * @param {HandController} [options.handController] - Convenience source for grip/model.
	 * @param {Object<string, string|object|Function>} [options.labels=DEFAULT_CONTROLLER_LABELS] - Component label definitions.
	 * @param {Object<string, Object<string, Object<string, THREE.Vector3>>>} [options.profileOffsets=DEFAULT_CONTROLLER_LABEL_OFFSETS]
	 * @param {boolean} [options.includeUnknownLabels=false] - Render generic labels for components not present in `labels`.
	 * @param {boolean} [options.visible=true] - Initial labels visibility.
	 * @param {boolean} [options.debug=false] - Dump anchors to the console after build.
	 * @param {object} [options.style] - Canvas/sprite/line styling overrides.
	 * @param {'uniform'|'content'} [options.style.labelWidthMode='uniform'] - Use the widest label for all widths, or fit each label to its text.
	 * @param {number} [options.style.labelHorizontalPadding=0.012] - Horizontal padding on each side of fitted label text, in meters.
	 * @param {object|false} [options.layout] - Label layout options. Use `false` for raw anchor-relative offsets.
	 * @param {'split'|'radial'|'hybrid'|'manual'} [options.layout.mode='split'] - Distribution strategy.
	 * @param {object} [options.layout.manualLayout] - Versioned manual layout document for `mode: 'manual'`.
	 * @param {number} [options.layout.minGap=0.008] - Minimum gap between labels in meters.
	 * @param {number} [options.layout.sideDistance=0.095] - Absolute local X distance used by the split layout.
	 * @param {number} [options.layout.minHorizontalMargin=0] - Minimum split-layout gap between the projected controller edge and labels, in meters.
	 * @param {number} [options.layout.planarity=0] - Radial direction blend toward the controller-local XZ plane, clamped to 0..1.
	 * @param {number} [options.layout.minDistance=0.095] - Minimum radial distance from each component anchor to its label center.
	 * @param {number} [options.layout.angularSpacing=1] - Radial angular equalization strength (0 preserves original rays, 1 uses uniform sectors).
	 * @param {boolean} [options.layout.lockDepthAxis=false] - Align labels on the same local Z plane.
	 * @param {boolean} [options.layout.screenSpace=true] - Keep split-layout rows separated in screen space as the camera moves.
	 * @param {Object<string, 'left'|'right'>} [options.layout.sideByComponent] - Per-component side override for split layout.
	 * @param {number} [options.waitTimeout=30000] - Max milliseconds to wait for usable component anchors.
	 */
	constructor({
		controllerGrip = null,
		controllerModel = null,
		handController = null,
		labels = DEFAULT_CONTROLLER_LABELS,
		profileOffsets = DEFAULT_CONTROLLER_LABEL_OFFSETS,
		includeUnknownLabels = false,
		visible = true,
		debug = false,
		style = {},
		layout = {},
		waitTimeout = 30000,
	} = {}) {
		this.handController = handController;
		this.controllerGrip = controllerGrip ?? handController?.getGrip?.() ?? null;
		this.controllerModel =
			controllerModel ?? handController?.getControllerModel?.() ?? handController?.controllerModel ?? null;
		this.labels = labels;
		this.profileOffsets = profileOffsets;
		this.includeUnknownLabels = includeUnknownLabels;
		this.debug = debug;
		this.style = { ...DEFAULT_STYLE, ...style };
		this.layout = layout === false ? { mode: 'offset' } : { ...DEFAULT_LAYOUT, ...layout };
		this.waitTimeout = waitTimeout;
		this._disposed = false;
		this._isReady = false;
		this._splitScreenItems = null;
		this._hybridScreenItems = null;
		this._layoutItems = null;
		this._splitScreenFrame = -1;

		this.group = new THREE.Group();
		this.group.name = 'XRControllerLabels';
		this.group.visible = visible;

		if (this.controllerGrip) {
			this.controllerGrip.add(this.group);
		}
	}

	/**
	 * Waits for the model profile data and builds the labels.
	 * @returns {Promise<XRControllerLabelHelper>}
	 */
	async init() {
		this._assertRequiredObjects();
		await this.waitForModel();

		if (this._disposed) return this;

		this.build();
		this._isReady = true;

		if (this.debug) {
			this.dumpAnchors();
		}

		return this;
	}

	/**
	 * Rebuilds the label group using current profile/component anchors.
	 */
	refresh() {
		this._assertRequiredObjects();
		this.build();
		return this;
	}

	/**
	 * Replaces the label definitions.
	 * @param {Object<string, string|object|Function>} labels
	 * @param {object} [options]
	 * @param {boolean} [options.rebuild=true]
	 */
	setLabels(labels, { rebuild = true } = {}) {
		this.labels = labels;

		if (rebuild && this._isReady) {
			this.build();
		}

		return this;
	}

	/**
	 * Returns the controller identity used to scope manual layout documents.
	 * @returns {{profileId: string|null, handedness: string|null}}
	 */
	getLayoutTarget() {
		const motionController = this.controllerModel?.motionController;
		return {
			profileId:
				motionController?.id ??
				motionController?.profileId ??
				motionController?.xrInputSource?.profiles?.[0] ??
				null,
			handedness: motionController?.xrInputSource?.handedness ?? null,
		};
	}

	/**
	 * Validates a manual layout document and its compatibility with the loaded controller.
	 * Missing components are allowed and keep their normal offsets.
	 *
	 * @param {object} document
	 * @param {object} [options]
	 * @param {boolean} [options.checkTarget=true]
	 * @returns {{
	 *   valid: boolean,
	 *   errors: string[],
	 *   warnings: string[],
	 *   targetMatches: boolean,
	 *   missingComponents: string[],
	 *   unknownComponents: string[]
	 * }}
	 */
	validateManualLayout(document, { checkTarget = true } = {}) {
		const errors = [];
		const warnings = [];
		const target = this.getLayoutTarget();
		const labels = document?.labels;
		const isVector = (value) =>
			Array.isArray(value) && value.length === 3 && value.every((component) => Number.isFinite(component));

		if (!document || typeof document !== 'object' || Array.isArray(document)) {
			errors.push('Manual layout must be a JSON object.');
		}
		if (document?.schema !== CONTROLLER_LABEL_LAYOUT_SCHEMA) {
			errors.push(`Unsupported manual layout schema: ${document?.schema ?? 'missing'}.`);
		}
		if (document?.version !== CONTROLLER_LABEL_LAYOUT_VERSION) {
			errors.push(`Unsupported manual layout version: ${document?.version ?? 'missing'}.`);
		}
		if (!document?.target?.profileId || !document?.target?.handedness) {
			errors.push('Manual layout target must include profileId and handedness.');
		} else if (!['left', 'right'].includes(document.target.handedness)) {
			errors.push(`Unsupported manual layout handedness: ${document.target.handedness}.`);
		}
		if (document?.coordinateSpace !== 'controller-grip-local-offset-from-anchor') {
			errors.push(`Unsupported coordinate space: ${document?.coordinateSpace ?? 'missing'}.`);
		}
		if (!labels || typeof labels !== 'object' || Array.isArray(labels)) {
			errors.push('Manual layout labels must be an object keyed by component id.');
		} else {
			for (const [componentId, entry] of Object.entries(labels)) {
				if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
					errors.push(`Label "${componentId}" must be an object.`);
					continue;
				}
				if (!isVector(entry.labelOffset)) {
					errors.push(`Label "${componentId}" must define labelOffset as three finite numbers.`);
				}
				if (entry.lineOriginOffset != null && !isVector(entry.lineOriginOffset)) {
					errors.push(`Label "${componentId}" lineOriginOffset must contain three finite numbers.`);
				}
			}
		}

		const documentTarget = document?.target;
		const targetMatches =
			!checkTarget ||
			!target.profileId ||
			!target.handedness ||
			(documentTarget?.profileId === target.profileId &&
				documentTarget?.handedness === target.handedness);
		if (!targetMatches) {
			errors.push(
				`Manual layout targets ${documentTarget?.profileId ?? 'missing'}/${documentTarget?.handedness ?? 'missing'}, ` +
					`but the loaded controller is ${target.profileId}/${target.handedness}.`
			);
		}

		const currentComponents = new Set(
			this._layoutItems?.map((item) => item.componentId) ??
				Object.keys(this.controllerModel?.motionController?.components ?? {})
		);
		const documentComponents = new Set(Object.keys(labels ?? {}));
		const missingComponents = [...currentComponents].filter((componentId) => !documentComponents.has(componentId));
		const unknownComponents = [...documentComponents].filter((componentId) => !currentComponents.has(componentId));
		if (missingComponents.length) {
			warnings.push(`Components without manual positions: ${missingComponents.join(', ')}.`);
		}
		if (unknownComponents.length) {
			warnings.push(`Components not present on this controller: ${unknownComponents.join(', ')}.`);
		}

		return {
			valid: errors.length === 0,
			errors,
			warnings,
			targetMatches,
			missingComponents,
			unknownComponents,
		};
	}

	/**
	 * Sets a versioned manual layout document.
	 * @param {object} document
	 * @param {object} [options]
	 * @param {boolean} [options.rebuild=true]
	 * @param {boolean} [options.checkTarget=true]
	 * @returns {XRControllerLabelHelper}
	 */
	setManualLayout(document, { rebuild = true, checkTarget = true } = {}) {
		const validation = this.validateManualLayout(document, { checkTarget });
		if (!validation.valid) {
			const error = new Error(validation.errors.join(' '));
			error.validation = validation;
			throw error;
		}

		this.layout.manualLayout = document;
		if (rebuild && this._isReady) this.build();
		return this;
	}

	/**
	 * Captures the current visible label positions as a portable manual layout document.
	 * Label and line offsets are expressed in controller-grip local axes from each component anchor.
	 * @returns {object}
	 */
	exportManualLayout() {
		const target = this.getLayoutTarget();
		if (!target.profileId || !target.handedness) {
			throw new Error('Cannot export a manual layout before a controller profile is loaded.');
		}
		if (!this._layoutItems?.length) {
			throw new Error('Cannot export a manual layout before labels are built.');
		}

		const toArray = (vector) =>
			vector.toArray().map((value) => {
				const rounded = Number(value.toFixed(6));
				return Math.abs(rounded) < 1e-6 ? 0 : rounded;
			});
		const labels = {};
		for (const item of this._layoutItems) {
			const labelPosition = item.sprite?.position ?? item.labelPosition;
			labels[item.componentId] = {
				labelOffset: toArray(labelPosition.clone().sub(item.anchor)),
				lineOriginOffset: toArray(item.lineOrigin.clone().sub(item.anchor)),
			};
		}

		return {
			schema: CONTROLLER_LABEL_LAYOUT_SCHEMA,
			version: CONTROLLER_LABEL_LAYOUT_VERSION,
			target,
			coordinateSpace: 'controller-grip-local-offset-from-anchor',
			sourceMode: this.layout.mode,
			labels,
		};
	}

	/**
	 * Shows or hides all generated labels.
	 * @param {boolean} value
	 */
	setVisible(value) {
		this.group.visible = value;
		return this;
	}

	/**
	 * Toggles all generated labels and returns the new visibility.
	 * @param {boolean} [force]
	 * @returns {boolean}
	 */
	toggleVisible(force) {
		this.group.visible = force ?? !this.group.visible;
		return this.group.visible;
	}

	/**
	 * Waits until Three.js has attached profile data and visual response nodes.
	 * @returns {Promise<void>}
	 */
	waitForModel() {
		const startedAt = performance.now();

		return new Promise((resolve, reject) => {
			const check = () => {
				if (this._disposed) {
					resolve();
					return;
				}

				if (this.controllerModel?.motionController && this._hasUsableAnchors()) {
					this.controllerModel.updateMatrixWorld(true);
					this.controllerGrip.updateMatrixWorld(true);
					resolve();
					return;
				}

				if (performance.now() - startedAt > this.waitTimeout) {
					reject(new Error('XRControllerLabelHelper timed out waiting for controller component anchors.'));
					return;
				}

				// Window animation frames may be suspended while an immersive WebXR
				// session owns presentation. Keep model discovery independent from the
				// renderer's XR animation loop.
				setTimeout(check, 50);
			};

			check();
		});
	}

	/**
	 * Creates sprites and leader lines for all labeled anchors.
	 */
	build() {
		this.clear();

		const motionController = this.controllerModel?.motionController;
		if (!motionController) return;

		const anchors = this.getAnchors();
		const items = [];
		let labelsCount = 0;

		for (const [componentId, anchorData] of Object.entries(anchors)) {
			const component = motionController.components[componentId];
			const label = this._resolveLabel(componentId, anchorData, component);

			if (!label?.text) continue;

			const anchor = anchorData.local.clone();
			const offset = this.getOffset(componentId, label);
			const labelPosition = anchor.clone().add(offset);
			const labelStyle = { ...this.style, ...label.style };

			items.push({
				componentId,
				anchor,
				offset,
				label,
				labelPosition,
				lineOrigin: anchor.clone(),
				width: label.width ?? null,
				height: label.height ?? labelStyle.labelHeight,
			});
		}

		this._applyLabelWidths(items);
		this._applyLayout(items);

		for (const item of items) {
			const label = {
				...item.label,
				width: item.width,
				height: item.height,
			};
			const sprite = this._makeTextSprite(label.text, label);
			const line = this._makeLine(item.lineOrigin, item.labelPosition, label, sprite);
			item.sprite = sprite;
			item.line = line;

			sprite.position.copy(item.labelPosition);
			sprite.userData.componentId = item.componentId;
			line.userData.componentId = item.componentId;

			this.group.add(line);
			this.group.add(sprite);
			labelsCount++;
		}
		this._splitScreenItems = this.layout.mode === 'split' && this.layout.screenSpace !== false ? items : null;
		this._hybridScreenItems =
			this.layout.mode === 'hybrid'
				? items.map((item) => ({ ...item, preferredPosition: item.labelPosition.clone() }))
				: null;
		this._layoutItems = items;

		if (this.debug) {
			console.log('XRControllerLabelHelper labels built:', labelsCount);
		}
	}

	/**
	 * Removes generated labels and disposes their GPU resources.
	 */
	clear() {
		this._splitScreenItems = null;
		this._hybridScreenItems = null;
		this._layoutItems = null;
		while (this.group.children.length > 0) {
			const child = this.group.children[0];
			this.group.remove(child);
			this._disposeObject(child);
		}
	}

	/**
	 * Disposes labels and detaches the group from the controller grip.
	 */
	dispose() {
		this._disposed = true;
		this.clear();

		if (this.group.parent) {
			this.group.parent.remove(this.group);
		}
	}

	/**
	 * Returns local/world anchors for every component with a usable visual node.
	 * @returns {Object<string, {type: string, local: THREE.Vector3, world: THREE.Vector3}>}
	 */
	getAnchors() {
		this.controllerModel.updateMatrixWorld(true);
		this.controllerGrip.updateMatrixWorld(true);

		const motionController = this.controllerModel.motionController;
		const anchors = {};

		for (const [componentId, component] of Object.entries(motionController.components ?? {})) {
			const worldPosition = this._getComponentAnchorWorld(component);

			if (!worldPosition) continue;

			anchors[componentId] = {
				type: component.type,
				local: this.controllerGrip.worldToLocal(worldPosition.clone()),
				world: worldPosition,
			};
		}

		return anchors;
	}

	/**
	 * Returns the configured label offset for a component.
	 * @param {string} componentId
	 * @param {object} [label]
	 * @returns {THREE.Vector3}
	 */
	getOffset(componentId, label = null) {
		if (label?.offset) {
			return this._toVector3(label.offset);
		}

		const motionController = this.controllerModel.motionController;
		const profileId = motionController.id;
		const handedness = motionController.xrInputSource?.handedness;
		const profileOffset = this.profileOffsets?.[profileId]?.[handedness]?.[componentId];

		if (profileOffset) {
			return profileOffset.clone();
		}

		return this._getDefaultOffset(componentId, handedness);
	}

	/**
	 * Logs profile, handedness, and local anchors to the browser console.
	 */
	dumpAnchors() {
		const motionController = this.controllerModel?.motionController;
		const anchors = this.getAnchors();

		console.group('XR controller anchors');
		console.log('profile:', motionController?.id);
		console.log('handedness:', motionController?.xrInputSource?.handedness);

		for (const [id, data] of Object.entries(anchors)) {
			console.log(id, data.type, {
				x: data.local.x.toFixed(4),
				y: data.local.y.toFixed(4),
				z: data.local.z.toFixed(4),
			});
		}

		console.groupEnd();
	}

	_assertRequiredObjects() {
		if (!this.controllerGrip || !this.controllerModel) {
			throw new Error(
				'XRControllerLabelHelper requires controllerGrip and controllerModel, or a HandController.'
			);
		}
	}

	_resolveLabel(componentId, anchorData, component) {
		let definition = this.labels?.[componentId];

		if (typeof definition === 'function') {
			definition = definition({ componentId, anchorData, component, helper: this });
		}

		if (definition == null && this.includeUnknownLabels) {
			definition = this._defaultLabelForComponent(componentId, component);
		}

		if (definition === false || definition == null) {
			return null;
		}

		if (typeof definition === 'string') {
			return { text: definition };
		}

		return definition;
	}

	_defaultLabelForComponent(componentId, component) {
		if (componentId.includes('trigger')) return 'Trigger';
		if (componentId.includes('squeeze')) return 'Grip';
		if (componentId.includes('thumbstick')) return 'Joystick';
		if (componentId.includes('touchpad')) return 'Touchpad';
		if (componentId.includes('menu')) return 'Menu';
		if (component?.type === 'button') return componentId;
		return componentId;
	}

	_getComponentAnchorWorld(component) {
		if (component.touchPointNode) {
			return component.touchPointNode.getWorldPosition(new THREE.Vector3());
		}

		for (const visualResponse of Object.values(component.visualResponses ?? {})) {
			if (visualResponse.valueNode) {
				return (
					this._getRenderableNodeCenterWorld(visualResponse.valueNode) ??
					visualResponse.valueNode.getWorldPosition(new THREE.Vector3())
				);
			}

			if (visualResponse.minNode && visualResponse.maxNode) {
				const minPosition = visualResponse.minNode.getWorldPosition(new THREE.Vector3());
				const maxPosition = visualResponse.maxNode.getWorldPosition(new THREE.Vector3());
				return minPosition.add(maxPosition).multiplyScalar(0.5);
			}
		}

		return null;
	}

	_getRenderableNodeCenterWorld(node) {
		node.updateWorldMatrix(true, true);

		const bounds = new THREE.Box3();
		let hasGeometry = false;

		node.traverse((child) => {
			const geometry = child.geometry;
			if (!geometry?.attributes?.position) return;

			if (!geometry.boundingBox) {
				geometry.computeBoundingBox();
			}

			if (!geometry.boundingBox || geometry.boundingBox.isEmpty()) return;

			bounds.union(geometry.boundingBox.clone().applyMatrix4(child.matrixWorld));
			hasGeometry = true;
		});

		return hasGeometry ? bounds.getCenter(new THREE.Vector3()) : null;
	}

	_applyLayout(items) {
		if (this.layout.mode === 'offset') {
			return;
		}

		if (this.layout.mode === 'radial') {
			this._applyRadialLayout(items);
			return;
		}

		if (this.layout.mode === 'manual') {
			this._applyManualLayout(items);
			return;
		}

		if (this.layout.mode === 'hybrid') return;

		if (items.length <= 1) return;

		if (this.layout.mode === 'split') {
			this._applySplitLayout(items);
		}
	}

	_applyManualLayout(items) {
		const document = this.layout.manualLayout;
		const validation = this.validateManualLayout(document);
		if (!validation.valid) {
			const error = new Error(validation.errors.join(' '));
			error.validation = validation;
			throw error;
		}

		for (const item of items) {
			const entry = document.labels[item.componentId];
			if (!entry) continue;

			item.labelPosition.copy(item.anchor).add(this._toVector3(entry.labelOffset));
			item.lineOrigin
				.copy(item.anchor)
				.add(this._toVector3(entry.lineOriginOffset ?? [0, 0, 0]));
		}
	}

	_applyRadialLayout(items) {
		if (items.length === 0) return;

		const center = items
			.reduce((sum, item) => sum.add(item.anchor), new THREE.Vector3())
			.multiplyScalar(1 / items.length);
		const planarity = THREE.MathUtils.clamp(Number(this.layout.planarity) || 0, 0, 1);
		const minDistance = Math.max(0, Number(this.layout.minDistance) || 0);
		const minGap = Math.max(0, Number(this.layout.minGap) || 0);
		const angularSpacing = THREE.MathUtils.clamp(Number(this.layout.angularSpacing) || 0, 0, 1);
		const placedItems = [];
		const directions = items.map((item, index) =>
			this._getRadialDirection(item, center, index, items.length, planarity)
		);
		this._equalizeRadialAngles(directions, angularSpacing);

		items.forEach((item, index) => {
			const direction = directions[index];
			const radius = Math.hypot(item.width, item.height) * 0.5;
			let distance = minDistance;
			let adjusted;

			do {
				adjusted = false;
				item.labelPosition.copy(item.anchor).addScaledVector(direction, distance);

				for (const placed of placedItems) {
					const separation = radius + placed.layoutRadius + minGap;

					if (item.labelPosition.distanceToSquared(placed.labelPosition) >= separation * separation) {
						continue;
					}

					const anchorToPlaced = item.anchor.clone().sub(placed.labelPosition);
					const alongRay = anchorToPlaced.dot(direction);
					const discriminant = alongRay * alongRay - (anchorToPlaced.lengthSq() - separation * separation);

					if (discriminant >= 0) {
						distance = Math.max(distance, -alongRay + Math.sqrt(discriminant) + LAYOUT_EPSILON);
						adjusted = true;
						break;
					}
				}
			} while (adjusted);

			item.layoutDirection = direction;
			item.layoutDistance = distance;
			item.layoutRadius = radius;
			placedItems.push(item);
		});
	}

	_equalizeRadialAngles(directions, strength) {
		if (directions.length <= 1 || strength <= 0) return;

		const entries = directions
			.map((direction, index) => ({ index, angle: Math.atan2(direction.z, direction.x) }))
			.sort((a, b) => a.angle - b.angle);
		let largestGap = -1;
		let startIndex = 0;

		for (let i = 0; i < entries.length; i++) {
			const nextAngle = i === entries.length - 1 ? entries[0].angle + Math.PI * 2 : entries[i + 1].angle;
			const gap = nextAngle - entries[i].angle;
			if (gap > largestGap) {
				largestGap = gap;
				startIndex = (i + 1) % entries.length;
			}
		}

		const ordered = entries.slice(startIndex).concat(entries.slice(0, startIndex));
		for (let i = 1; i < ordered.length; i++) {
			while (ordered[i].angle < ordered[i - 1].angle) ordered[i].angle += Math.PI * 2;
		}
		const sector = (Math.PI * 2) / ordered.length;
		const origin = ordered.reduce((sum, entry, index) => sum + entry.angle - index * sector, 0) / ordered.length;
		const up = new THREE.Vector3(0, 1, 0);

		ordered.forEach((entry, index) => {
			const target = origin + index * sector;
			const delta = THREE.MathUtils.euclideanModulo(target - entry.angle + Math.PI, Math.PI * 2) - Math.PI;
			// A positive Three.js Y rotation decreases atan2(z, x).
			directions[entry.index].applyAxisAngle(up, -delta * strength).normalize();
		});
	}

	_getRadialDirection(item, center, index, itemCount, planarity) {
		let original = item.anchor.clone().sub(center);

		if (original.lengthSq() <= LAYOUT_EPSILON * LAYOUT_EPSILON) {
			original = item.offset.clone();
		}

		if (original.lengthSq() <= LAYOUT_EPSILON * LAYOUT_EPSILON) {
			original = this._getStableRadialFallback(index, itemCount);
		}

		original.normalize();

		let planar = new THREE.Vector3(original.x, 0, original.z);
		if (planar.lengthSq() <= LAYOUT_EPSILON * LAYOUT_EPSILON) {
			planar.set(item.offset.x, 0, item.offset.z);
		}
		if (planar.lengthSq() <= LAYOUT_EPSILON * LAYOUT_EPSILON) {
			planar = this._getStableRadialFallback(index, itemCount);
		}
		planar.normalize();

		const direction = original.lerp(planar, planarity);
		return direction.lengthSq() > LAYOUT_EPSILON * LAYOUT_EPSILON ? direction.normalize() : planar;
	}

	_getStableRadialFallback(index, itemCount) {
		const angle = (index / Math.max(1, itemCount)) * Math.PI * 2;
		return new THREE.Vector3(Math.cos(angle), 0, Math.sin(angle));
	}

	_applySplitLayout(items) {
		const leftItems = [];
		const rightItems = [];

		for (const item of items) {
			const side = this._getItemLayoutSide(item);

			if (side === 'left') {
				leftItems.push(item);
			} else {
				rightItems.push(item);
			}
		}

		if (leftItems.length === 0 || rightItems.length === 0) {
			this._rebalanceSplitItems(leftItems, rightItems);
		}

		this._applyStackLayoutToSide(leftItems, -1);
		this._applyStackLayoutToSide(rightItems, 1);
		leftItems.forEach((item) => {
			item.layoutSide = -1;
		});
		rightItems.forEach((item) => {
			item.layoutSide = 1;
		});
	}

	_updateSplitScreenLayout(renderer, camera) {
		if (this._hybridScreenItems?.length) {
			this._updateHybridScreenLayout(renderer, camera);
			return;
		}
		if (!this._splitScreenItems?.length || !camera) return;
		const frame = renderer?.info?.render?.frame;
		if (frame != null && frame === this._splitScreenFrame) return;
		this._splitScreenFrame = frame ?? this._splitScreenFrame + 1;
		this.group.updateWorldMatrix(true, true);

		const cameraRight = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0).normalize();
		const cameraUp = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 1).normalize();
		const centerWorld = this.group.localToWorld(new THREE.Vector3());
		const centerNdc = centerWorld.clone().project(camera);
		const sidePointNdc = centerWorld
			.clone()
			.addScaledVector(cameraRight, this.layout.sideDistance ?? 0.095)
			.project(camera);
		const columnOffset = Math.abs(sidePointNdc.x - centerNdc.x);
		const minHorizontalMargin = Math.max(0, Number(this.layout.minHorizontalMargin) || 0);
		let controllerMinX = centerNdc.x;
		let controllerMaxX = centerNdc.x;
		if (minHorizontalMargin > 0 && this.controllerModel) {
			const bounds = new THREE.Box3().setFromObject(this.controllerModel);
			if (!bounds.isEmpty()) {
				controllerMinX = Infinity;
				controllerMaxX = -Infinity;
				for (const x of [bounds.min.x, bounds.max.x])
					for (const y of [bounds.min.y, bounds.max.y])
						for (const z of [bounds.min.z, bounds.max.z]) {
							const projectedX = new THREE.Vector3(x, y, z).project(camera).x;
							controllerMinX = Math.min(controllerMinX, projectedX);
							controllerMaxX = Math.max(controllerMaxX, projectedX);
						}
			}
		}

		for (const sideSign of [-1, 1]) {
			const rows = this._splitScreenItems
				.filter((item) => item.layoutSide === sideSign && item.sprite)
				.map((item) => {
					const anchorWorld = this.group.localToWorld(item.anchor.clone());
					const anchorNdc = anchorWorld.clone().project(camera);
					const worldScale = item.sprite.getWorldScale(new THREE.Vector3());
					const planeNdc = new THREE.Vector3(centerNdc.x, anchorNdc.y, centerNdc.z);
					const planeWorld = planeNdc.clone().unproject(camera);
					const sizeNdc = planeWorld
						.clone()
						.addScaledVector(cameraUp, Math.abs(worldScale.y) * 0.5)
						.project(camera);
					const widthNdc = planeWorld
						.clone()
						.addScaledVector(cameraRight, Math.abs(worldScale.x) * 0.5)
						.project(camera);
					const gapNdc = planeWorld
						.clone()
						.addScaledVector(cameraUp, Math.max(0, Number(this.layout.minGap) || 0))
						.project(camera);
					return {
						item,
						anchorY: anchorNdc.y,
						halfHeight: Math.abs(sizeNdc.y - planeNdc.y),
						halfWidth: Math.abs(widthNdc.x - planeNdc.x),
						gap: Math.abs(gapNdc.y - planeNdc.y),
					};
				})
				.sort((a, b) => b.anchorY - a.anchorY);
			if (!rows.length) continue;

			rows[0].y = rows[0].anchorY;
			for (let i = 1; i < rows.length; i++) {
				const separation = rows[i - 1].halfHeight + rows[i].halfHeight + Math.max(rows[i - 1].gap, rows[i].gap);
				rows[i].y = Math.min(rows[i].anchorY, rows[i - 1].y - separation);
			}
			const shift = rows.reduce((sum, row) => sum + row.anchorY - row.y, 0) / rows.length;
			let x = centerNdc.x + sideSign * columnOffset;
			if (minHorizontalMargin > 0) {
				const planeWorld = new THREE.Vector3(centerNdc.x, centerNdc.y, centerNdc.z).unproject(camera);
				const marginNdc = planeWorld.clone().addScaledVector(cameraRight, minHorizontalMargin).project(camera);
				const margin = Math.abs(marginNdc.x - centerNdc.x);
				const halfWidth = Math.max(...rows.map((row) => row.halfWidth));
				x =
					sideSign < 0
						? Math.min(x, controllerMinX - margin - halfWidth)
						: Math.max(x, controllerMaxX + margin + halfWidth);
			}
			for (const row of rows) {
				const local = new THREE.Vector3(x, row.y + shift, centerNdc.z).unproject(camera);
				this.group.worldToLocal(local);
				row.item.labelPosition.copy(local);
				row.item.sprite.position.copy(local);
			}
		}
	}

	_updateHybridScreenLayout(renderer, camera) {
		const frame = renderer?.info?.render?.frame;
		if (frame != null && frame === this._splitScreenFrame) return;
		this._splitScreenFrame = frame ?? this._splitScreenFrame + 1;
		this.group.updateWorldMatrix(true, true);
		const cameraRight = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0).normalize();
		const cameraUp = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 1).normalize();
		const rows = this._hybridScreenItems
			.map((item) => {
				const world = this.group.localToWorld(item.preferredPosition.clone());
				const ndc = world.clone().project(camera);
				const scale = item.sprite.getWorldScale(new THREE.Vector3());
				const width = world
					.clone()
					.addScaledVector(cameraRight, Math.abs(scale.x) * 0.5)
					.project(camera);
				const height = world
					.clone()
					.addScaledVector(cameraUp, Math.abs(scale.y) * 0.5)
					.project(camera);
				const gap = world
					.clone()
					.addScaledVector(cameraUp, Math.max(0, Number(this.layout.minGap) || 0))
					.project(camera);
				return {
					item,
					x: ndc.x,
					y: ndc.y,
					z: ndc.z,
					halfWidth: Math.abs(width.x - ndc.x),
					halfHeight: Math.abs(height.y - ndc.y),
					gap: Math.abs(gap.y - ndc.y),
				};
			})
			.sort((a, b) => b.y - a.y);
		for (let i = 1; i < rows.length; i++) {
			for (let j = 0; j < i; j++) {
				const upper = rows[j];
				if (Math.abs(rows[i].x - upper.x) >= rows[i].halfWidth + upper.halfWidth) continue;
				const separation = rows[i].halfHeight + upper.halfHeight + Math.max(rows[i].gap, upper.gap);
				rows[i].y = Math.min(rows[i].y, upper.y - separation);
			}
		}
		for (const row of rows) {
			const local = new THREE.Vector3(row.x, row.y, row.z).unproject(camera);
			this.group.worldToLocal(local);
			row.item.labelPosition.copy(local);
			row.item.sprite.position.copy(local);
		}
	}

	_applyStackLayoutToSide(items, sideSign) {
		if (items.length === 0) {
			return;
		}

		const axis = this.layout.axis ?? 'y';
		const sideAxis = 'x';
		const depthAxis = 'z';
		const minGap = this.layout.minGap ?? 0.008;
		const sortedItems = [...items].sort((a, b) => b.anchor[axis] - a.anchor[axis]);
		const totalSize = sortedItems.reduce((sum, item) => sum + item.height, 0) + minGap * (sortedItems.length - 1);
		const center = sortedItems.reduce((sum, item) => sum + item.anchor[axis], 0) / sortedItems.length;
		const lockedSide = sideSign * (this.layout.sideDistance ?? 0.095);
		const lockedDepth =
			sortedItems.reduce((sum, item) => sum + item.labelPosition[depthAxis], 0) / sortedItems.length;
		let cursor = center + totalSize * 0.5;

		for (const item of sortedItems) {
			cursor -= item.height * 0.5;
			item.labelPosition[axis] = cursor;

			if (this.layout.lockSideAxis !== false) {
				item.labelPosition[sideAxis] = lockedSide;
			}

			if (this.layout.lockDepthAxis === true) {
				item.labelPosition[depthAxis] = lockedDepth;
			}

			cursor -= item.height * 0.5 + minGap;
		}
	}

	_getItemLayoutSide(item) {
		const sideByComponent = {
			...DEFAULT_LAYOUT_SIDE_BY_COMPONENT,
			...(this.layout.sideByComponent ?? {}),
		};
		const side = item.label.side ?? sideByComponent[item.componentId];

		if (side === 'left' || side === 'right') {
			return side;
		}

		return item.anchor.x < 0 ? 'left' : 'right';
	}

	_rebalanceSplitItems(leftItems, rightItems) {
		const sourceItems = leftItems.length > 0 ? leftItems : rightItems;
		const targetItems = leftItems.length > 0 ? rightItems : leftItems;
		const sortedItems = [...sourceItems].sort((a, b) => b.anchor.y - a.anchor.y);
		const itemsToMove = Math.floor(sourceItems.length / 2);

		for (let i = 0; i < itemsToMove; i++) {
			const item = sortedItems[i * 2 + 1] ?? sortedItems[sortedItems.length - 1 - i];
			const sourceIndex = sourceItems.indexOf(item);

			if (sourceIndex >= 0) {
				sourceItems.splice(sourceIndex, 1);
				targetItems.push(item);
			}
		}
	}

	_hasUsableAnchors() {
		const components = this.controllerModel?.motionController?.components;
		if (!components) return false;

		for (const component of Object.values(components)) {
			if (component.touchPointNode) {
				return true;
			}

			for (const visualResponse of Object.values(component.visualResponses ?? {})) {
				if (visualResponse.valueNode || (visualResponse.minNode && visualResponse.maxNode)) {
					return true;
				}
			}
		}

		return false;
	}

	_getDefaultOffset(componentId, handedness) {
		const side = handedness === 'left' ? -1 : 1;

		switch (componentId) {
			case 'xr-standard-trigger':
				return new THREE.Vector3(side * 0.035, -0.025, -0.02);
			case 'xr-standard-squeeze':
				return new THREE.Vector3(side * 0.045, -0.015, 0.02);
			case 'xr-standard-thumbstick':
				return new THREE.Vector3(side * 0.05, 0.035, 0);
			case 'a-button':
			case 'b-button':
			case 'x-button':
			case 'y-button':
				return new THREE.Vector3(side * 0.055, 0.04, -0.015);
			case 'menu':
				return new THREE.Vector3(side * 0.055, 0.025, -0.005);
			default:
				return new THREE.Vector3(side * 0.05, 0.03, 0);
		}
	}

	_applyLabelWidths(items) {
		if (!items.length) return;
		const measured = items.map((item) => {
			const style = { ...this.style, ...item.label.style };
			const canvas = document.createElement('canvas');
			const context = canvas.getContext('2d');
			context.font = `${style.fontSize}px ${style.fontFamily}`;
			const textWidth = Math.max(
				...String(item.label.text)
					.split('\n')
					.map((line) => context.measureText(line).width)
			);
			const pixelScale = item.height / Math.max(1, style.canvasHeight);
			const padding = Math.max(0, Number(style.labelHorizontalPadding) || 0);
			return Math.max(item.height, textWidth * pixelScale + padding * 2, Number(item.width) || 0);
		});
		const mode = this.style.labelWidthMode === 'content' ? 'content' : 'uniform';
		const uniformWidth = Math.max(...measured);
		items.forEach((item, index) => {
			item.width = mode === 'content' ? measured[index] : uniformWidth;
		});
	}

	_makeTextSprite(text, label) {
		const style = { ...this.style, ...label.style };
		const canvas = document.createElement('canvas');
		canvas.width = Math.max(
			1,
			Math.round((style.canvasHeight * (label.width ?? style.labelWidth)) / (label.height ?? style.labelHeight))
		);
		canvas.height = style.canvasHeight;
		style.canvasWidth = canvas.width;

		const context = canvas.getContext('2d');
		const width = canvas.width;
		const height = canvas.height;

		context.clearRect(0, 0, width, height);
		this._drawRoundRect(
			context,
			style.padding * 0.5,
			style.padding * 0.5,
			width - style.padding,
			height - style.padding,
			style.cornerRadius
		);

		context.fillStyle = style.backgroundColor;
		context.fill();
		context.strokeStyle = style.borderColor;
		context.lineWidth = 3;
		context.stroke();

		const lines = String(text).split('\n');
		const fontSize = this._fitFontSize(context, lines, style);
		const lineHeight = fontSize * 1.15;
		const startY = height * 0.5 - ((lines.length - 1) * lineHeight) / 2;

		context.fillStyle = style.textColor;
		context.font = `${fontSize}px ${style.fontFamily}`;
		context.textAlign = 'center';
		context.textBaseline = 'middle';

		lines.forEach((line, index) => {
			context.fillText(line, width * 0.5, startY + index * lineHeight);
		});

		const texture = new THREE.CanvasTexture(canvas);
		texture.needsUpdate = true;

		const material = new THREE.SpriteMaterial({
			map: texture,
			transparent: false,
			opacity: label.opacity ?? style.labelOpacity,
			alphaTest: label.alphaTest ?? style.labelAlphaTest,
			depthTest: label.labelDepthTest ?? style.labelDepthTest,
			depthWrite: label.labelDepthWrite ?? style.labelDepthWrite,
		});

		const sprite = new THREE.Sprite(material);
		sprite.scale.set(label.width ?? style.labelWidth, label.height ?? style.labelHeight, 1);

		return sprite;
	}

	_makeLine(anchor, labelPosition, label, sprite) {
		const style = { ...this.style, ...label.style };
		const opacity = label.lineOpacity ?? style.lineOpacity;
		const geometry = new THREE.BufferGeometry().setFromPoints([anchor, labelPosition]);
		const material = new THREE.LineBasicMaterial({
			color: label.lineColor ?? style.lineColor,
			transparent: opacity < 1,
			opacity,
			depthTest: label.lineDepthTest ?? style.lineDepthTest,
			depthWrite: label.lineDepthWrite ?? style.lineDepthWrite,
		});

		const line = new THREE.Line(geometry, material);
		const anchorWorld = new THREE.Vector3();
		const labelWorld = new THREE.Vector3();
		const worldScale = new THREE.Vector3();
		const cameraRight = new THREE.Vector3();
		const cameraUp = new THREE.Vector3();
		const anchorNdc = new THREE.Vector3();
		const labelNdc = new THREE.Vector3();
		const sizePoint = new THREE.Vector3();
		const sizeNdc = new THREE.Vector3();
		const anchorClip = new THREE.Vector4();
		const labelClip = new THREE.Vector4();
		const edgeLocal = new THREE.Vector3();

		line.frustumCulled = false;
		line.onBeforeRender = (_renderer, _scene, camera) => {
			this._updateSplitScreenLayout(_renderer, camera);
			this.group.localToWorld(anchorWorld.copy(anchor));
			sprite.getWorldPosition(labelWorld);
			sprite.getWorldScale(worldScale);

			cameraRight.setFromMatrixColumn(camera.matrixWorld, 0).normalize();
			cameraUp.setFromMatrixColumn(camera.matrixWorld, 1).normalize();
			const halfWidth = Math.abs(worldScale.x) * 0.5;
			const halfHeight = Math.abs(worldScale.y) * 0.5;

			anchorNdc.copy(anchorWorld).project(camera);
			labelNdc.copy(labelWorld).project(camera);
			sizePoint.copy(labelWorld).addScaledVector(cameraRight, halfWidth);
			sizeNdc.copy(sizePoint).project(camera);
			const halfWidthNdc = Math.abs(sizeNdc.x - labelNdc.x);
			sizePoint.copy(labelWorld).addScaledVector(cameraUp, halfHeight);
			sizeNdc.copy(sizePoint).project(camera);
			const halfHeightNdc = Math.abs(sizeNdc.y - labelNdc.y);
			const horizontal = anchorNdc.x - labelNdc.x;
			const vertical = anchorNdc.y - labelNdc.y;
			const edgeRatio = Math.max(
				halfWidthNdc > LAYOUT_EPSILON ? Math.abs(horizontal) / halfWidthNdc : 0,
				halfHeightNdc > LAYOUT_EPSILON ? Math.abs(vertical) / halfHeightNdc : 0
			);

			let segmentRatio = 0;
			if (edgeRatio > LAYOUT_EPSILON) {
				const useHorizontal = Math.abs(horizontal) >= Math.abs(vertical);
				const targetNdc = useHorizontal
					? labelNdc.x + horizontal / edgeRatio
					: labelNdc.y + vertical / edgeRatio;

				anchorClip
					.set(anchorWorld.x, anchorWorld.y, anchorWorld.z, 1)
					.applyMatrix4(camera.matrixWorldInverse)
					.applyMatrix4(camera.projectionMatrix);
				labelClip
					.set(labelWorld.x, labelWorld.y, labelWorld.z, 1)
					.applyMatrix4(camera.matrixWorldInverse)
					.applyMatrix4(camera.projectionMatrix);

				const anchorAxis = useHorizontal ? anchorClip.x : anchorClip.y;
				const labelAxis = useHorizontal ? labelClip.x : labelClip.y;
				const axisDelta = anchorAxis - labelAxis;
				const wDelta = anchorClip.w - labelClip.w;
				const denominator = axisDelta - targetNdc * wDelta;

				if (Math.abs(denominator) > LAYOUT_EPSILON) {
					segmentRatio = THREE.MathUtils.clamp((targetNdc * labelClip.w - labelAxis) / denominator, 0, 1);
				}
			}

			edgeLocal.copy(labelPosition).lerp(anchor, segmentRatio);

			const position = geometry.getAttribute('position');
			position.setXYZ(1, edgeLocal.x, edgeLocal.y, edgeLocal.z);
			position.needsUpdate = true;
		};

		return line;
	}

	_fitFontSize(context, lines, style) {
		const maxWidth = style.canvasWidth - style.padding * 2;
		let fontSize = style.fontSize;

		while (fontSize > style.minFontSize) {
			context.font = `${fontSize}px ${style.fontFamily}`;
			const widestLine = Math.max(...lines.map((line) => context.measureText(line).width));

			if (widestLine <= maxWidth) {
				return fontSize;
			}

			fontSize -= 2;
		}

		return style.minFontSize;
	}

	_drawRoundRect(context, x, y, width, height, radius) {
		if (context.roundRect) {
			context.beginPath();
			context.roundRect(x, y, width, height, radius);
			return;
		}

		const right = x + width;
		const bottom = y + height;
		context.beginPath();
		context.moveTo(x + radius, y);
		context.lineTo(right - radius, y);
		context.quadraticCurveTo(right, y, right, y + radius);
		context.lineTo(right, bottom - radius);
		context.quadraticCurveTo(right, bottom, right - radius, bottom);
		context.lineTo(x + radius, bottom);
		context.quadraticCurveTo(x, bottom, x, bottom - radius);
		context.lineTo(x, y + radius);
		context.quadraticCurveTo(x, y, x + radius, y);
	}

	_toVector3(value) {
		if (value instanceof THREE.Vector3) {
			return value.clone();
		}

		if (Array.isArray(value)) {
			return new THREE.Vector3(value[0] ?? 0, value[1] ?? 0, value[2] ?? 0);
		}

		return new THREE.Vector3(value.x ?? 0, value.y ?? 0, value.z ?? 0);
	}

	_disposeObject(object) {
		object.geometry?.dispose?.();

		if (Array.isArray(object.material)) {
			object.material.forEach((material) => this._disposeMaterial(material));
		} else if (object.material) {
			this._disposeMaterial(object.material);
		}
	}

	_disposeMaterial(material) {
		material.map?.dispose?.();
		material.dispose?.();
	}
}
