import {
	CanvasTexture,
	LinearFilter,
	Mesh,
	MeshBasicMaterial,
	PlaneGeometry,
	SRGBColorSpace,
	Color,
	NearestFilter,
} from 'three';
import { simulateMouseEventWithin } from './simulateMouseEvents';
import * as htmlToImage from 'html-to-image';
import { createMouseProxy } from './createMouseProxy.js';

import { merge } from 'lodash';
let addedCanvas;

let counter = 0;

const defaultOptions = {
	OUTPUT_SCALE: 1,
};

/**
 * CanvasTexture that rasterizes an HTML element with html-to-image and forwards
 * normalized mouse events back into that element.
 *
 * This is the bridge used by HtmlMenuVR: DOM is captured into a GPU texture,
 * while VR ray hits are converted back into DOM mouse input.
 *
 * @extends CanvasTexture
 */
export class HTMLTexture extends CanvasTexture {
	/**
	 * Creates an HTMLTexture from a DOM element, sets up a MutationObserver to auto-update,
	 * and initializes Three.js texture properties.
	 * @param {HTMLElement} domElement - DOM element to rasterize.
	 * @param {object} [options] - Raster options.
	 * @param {number} [options.OUTPUT_SCALE] - Raster output scale.
	 */
	constructor(domElement, options) {
		// Create an empty placeholder canvas because the real canvas is not available yet.
		// The source is an HTML element, not a canvas.
		const placeholderCanvas = document.createElement('canvas');
		placeholderCanvas.width = domElement.offsetWidth;
		placeholderCanvas.height = domElement.offsetHeight;
		super(placeholderCanvas);

		this.options = merge({}, defaultOptions, options);
		this._domElement = domElement;
		this._canvas = placeholderCanvas;

		this._listeners = {};
		this._updatePromise = null;

		this.anisotropy = 16;
		this.colorSpace = SRGBColorSpace;
		this.minFilter = LinearFilter;
		this.magFilter = LinearFilter;
		this.generateMipmaps = false;

		this.mouseProxy = createMouseProxy(this._domElement, {
			/*occluders: [threeCanvas],*/
			adaptNativeRange: true, // enable the adapter
		});

		console.log(
			'HTMLTexture: OUTPUT_SCALE',
			this.options.OUTPUT_SCALE,
			'w, h:',
			this._domElement.offsetWidth,
			this._domElement.offsetHeight
		);
		this.updateImage();
	}

	/**
	 * Updates the texture by rendering the DOM to a canvas and uploading it to the GPU.
	 * Emits an 'updated' event after the update is complete.
	 */
	updateImage() {
		if (this._updatePromise) return this._updatePromise;

		// Capture the full DOM element.

		const computedStyle = window.getComputedStyle(this._domElement);
		const zoomFactor = computedStyle.zoom || 1;

		const w = this._domElement.offsetWidth * zoomFactor;
		const h = this._domElement.offsetHeight * zoomFactor;
		const cw = Math.floor(w * this.options.OUTPUT_SCALE);
		const ch = Math.floor(h * this.options.OUTPUT_SCALE);

		const options = {
			/* 
			Define how many pixels are captured from the DOM element.
			If the DOM element is 500x500 and CSS zoom is 50%,
			the DOM element size does not change, but it occupies 250x250 on screen.
			width and height define which DOM element area is captured.
			*/
			width: w,
			height: h,

			// Define the output canvas width and height.
			canvasWidth: cw,
			canvasHeight: ch,
		};
		const t0 = performance.now();
		this._updatePromise = htmlToImage.toCanvas(this._domElement, options).then((canvas) => {
			console.log('HTMLTexture: updateImage() canvas w,h:', canvas.width, canvas.height);
			const t1 = performance.now();
			console.log('HTMLTexture: updateImage() duration:', t1 - t0, 'ms');

			if (canvas.width === 0 || canvas.height === 0) {
				console.warn('HTMLTexture: ignoring update, canvas has zero width or height');
				return;
			}
			if (this._canvas.width !== canvas.width) this._canvas.width = canvas.width;
			if (this._canvas.height !== canvas.height) this._canvas.height = canvas.height;

			const ctx = this._canvas.getContext('2d');
			ctx.clearRect(0, 0, this._canvas.width, this._canvas.height);
			ctx.drawImage(canvas, 0, 0);
			this._canvas.title = 'c' + counter;
			/*
			if (addedCanvas) {
				document.getElementById('debug').removeChild(addedCanvas);
			}
			*/
			//document.getElementById('debug').appendChild(canvas);
			//addedCanvas = canvas;
			this.image = this._canvas;
			this.needsUpdate = true;
			//console.log(canvas.title);

			this._dispatchEvent('updated', { texture: this });
			counter++;
			return this._canvas;
		}).finally(() => {
			this._updatePromise = null;
		});
		return this._updatePromise;
	}

	/**
	 * Dispatches a DOM event (e.g., mouse/touch) to the underlying DOM element.
	 * @param {object} event - Normalized event from a VR panel.
	 * @param {string} event.type
	 * @param {object} [event.data]
	 * @param {number} event.data.x
	 * @param {number} event.data.y
	 */
	dispatchDOMEvent(event) {
		if (!this.mouseProxy) return;
		if (isNaN(event?.data?.x) || isNaN(event?.data?.y)) {
			console.error('Invalid mouse event.data.xy:', event.data.x, event.data.y);
			return;
		}

		if (event.data) {
			//console.log('HTMLTexture: dispatchDOMEvent', event);
			//simulateMouseEventWithin(this._domElement, event.data.type, event.data.x, event.data.y);
			switch (event.type) {
				case 'mousedown':
					this.mouseProxy.down(event.data.x, event.data.y);
					break;
				case 'mousemove':
					this.mouseProxy.move(event.data.x, event.data.y);
					break;
				case 'mouseup':
					this.mouseProxy.up(event.data.x, event.data.y);
					break;
			}
		}
	}

	/**
	 * Registers a callback for a custom event type (e.g., 'updated').
	 * @param {string} type - Event type.
	 * @param {Function} callback - Listener callback.
	 */
	addEventListener(type, callback) {
		if (!this._listeners[type]) this._listeners[type] = [];
		this._listeners[type].push(callback);
	}

	/**
	 * Removes a previously registered callback for a custom event type.
	 * @param {string} type - Event type.
	 * @param {Function} callback - Listener callback to remove.
	 */
	removeEventListener(type, callback) {
		if (!this._listeners[type]) return;
		this._listeners[type] = this._listeners[type].filter((cb) => cb !== callback);
	}

	/**
	 * Calls all registered listeners for a given event type.
	 * @param {string} type - Event type.
	 * @param {object} event - Event payload.
	 */
	_dispatchEvent(type, event) {
		if (!this._listeners[type]) return;
		this._listeners[type].forEach((cb) => cb(event));
	}

	/**
	 * Cleans up the MutationObserver and any scheduled updates, then disposes the texture.
	 */
	dispose() {
		/*
		if (this.observer) {
			this.observer.disconnect();
		}
		this.scheduleUpdate = clearTimeout(this.scheduleUpdate);
		*/
		if (this.mouseProxy && typeof this.mouseProxy.dispose === 'function') this.mouseProxy.dispose();
		super.dispose();
	}
}
