import * as THREE from 'three';
import { VRInteractivePanel } from './VRInteractivePanel.js';
import { GrabbableVRObject } from './GrabbableVRObject.js';
import { subscribeToConsole } from './VRConsoleInterceptor.js';
import { VRConsoleRenderer } from './VRConsoleRenderer.js';

export const defaultOptions = {
	width: 800,
	height: 500,
	maxEntries: 500,
	captureRuntimeErrors: true,
	autoFollow: true,
	grabbable: true,
};

/**
 * @typedef {object} VRConsoleOptions
 * @property {number} [width=800] Canvas width in pixels.
 * @property {number} [height=500] Canvas height in pixels.
 * @property {number} [maxEntries=500] Maximum retained console calls.
 * @property {boolean} [captureRuntimeErrors=true] Capture uncaught errors and unhandled rejections.
 * @property {boolean} [autoFollow=true] Keep the viewport pinned to new output until manually scrolled.
 * @property {boolean|object} [grabbable=true] Enables direct grip movement of the panel; pass options to customize the grab behavior.
 */

/**
 * Interactive, canvas-backed browser-console mirror for WebXR debugging.
 * Call {@link createMap} after construction and add {@link mesh} to the scene.
 *
 * @extends VRInteractivePanel
 */
export class VRConsole extends VRInteractivePanel {
	/**
	 * @param {HTMLElement|null} domElement Retained for compatibility; canvas rendering does not attach to it.
	 * @param {THREE.Group} worldContainer Scene node associated with the interactive panel.
	 * @param {ControllersManager} controllersManager Shared XR controller manager.
	 * @param {VRConsoleOptions} [options]
	 */
	constructor(domElement, worldContainer, controllersManager, options = {}) {
		super(worldContainer, controllersManager, options);
		this.options = { ...defaultOptions, ...this.options, ...options };
		this.domElement = domElement;
		this.consoleDiv = null; // Kept for source compatibility; rendering is canvas-backed now.
		this._disposed = false;
		this._mesh.userData = { class: 'VRConsole' };

		this._renderer = new VRConsoleRenderer(this.options);
		this.grabbable = this.options.grabbable ? new GrabbableVRObject(this.mesh, worldContainer, {
			contactGrabbing: {
				enabled: true,
				distanceThreshold: 0.1,
				boundsObject: this._mesh,
			},
			remoteGrabbing: { enabled: false },
			follow: {
				mode: 'manual',
				preserveGrabOffset: true,
				translationSmoothing: 18,
				keepWorldUp: false,
				snapDegrees: 0,
				snapRelativeToGrab: false,
			},
			placement: { mode: 'free' },
			...(this.options.grabbable === true ? {} : this.options.grabbable),
		}) : null;
		this._renderer.onRender = () => {
			if (this._map) this._map.needsUpdate = true;
		};

		this._consoleSubscriber = {
			captureRuntimeErrors: this.options.captureRuntimeErrors,
			capture: (type, args, source, metadata) => this._renderer.add(type, args, source, metadata),
		};
		this._unsubscribeConsole = subscribeToConsole(this._consoleSubscriber);
	}

	/** Creates the CanvasTexture used by the panel. Idempotent. */
	createMap() {
		if (this._disposed) throw new Error('VRConsole.createMap: instance is disposed');
		if (this._map) return this._map;

		this._map = new THREE.CanvasTexture(this._renderer.canvas);
		this._map.colorSpace = THREE.SRGBColorSpace;
		this._map.minFilter = THREE.LinearFilter;
		this._map.magFilter = THREE.LinearFilter;
		this._map.generateMipmaps = false;
		this._frontMaterial.map = this._map;
		this._frontMaterial.toneMapped = false;
		this._frontMaterial.needsUpdate = true;
		this._mesh.material = [this._backMaterial, this._frontMaterial];
		this._updateAspectRatio(this.options.width, this.options.height, this.options.width, this.options.height);
		this._renderer.render(this._renderer.autoFollow);
		return this._map;
	}

	/** Removes every retained entry from the VR console. */
	clear() {
		this._renderer.clear();
	}

	/**
	 * Shows or hides one severity without deleting its entries.
	 * @param {'log'|'info'|'warn'|'error'|'debug'|'trace'} level
	 * @param {boolean} visible
	 * @returns {VRConsole}
	 */
	setLevelVisible(level, visible) {
		this._renderer.setLevelVisible(level, visible);
		return this;
	}

	/** Enables or disables automatic scrolling to newly captured output. */
	setAutoFollow(enabled) {
		this._renderer.setAutoFollow(enabled);
		return this;
	}

	/** Moves the viewport to the newest visible output. */
	scrollToBottom() {
		this._renderer.scrollToBottom();
		return this;
	}

	_onPointerEvent = (event) => {
		if (!event.data) {
			if (event.type === 'pointerupoutside') this._renderer.pointerCancel();
			return;
		}
		const x = event.data.x * this.options.width;
		const y = (1 - event.data.y) * this.options.height;
		if (event.type === 'pointerdown') this._renderer.pointerDown(x, y);
		else if (event.type === 'pointermove') this._renderer.pointerMove(x, y);
		else if (event.type === 'pointerup') this._renderer.pointerUp(x, y);
		else if (event.type === 'pointerupoutside') this._renderer.pointerCancel();
	};

	/** Releases console interception, controller listeners, texture, and materials. */
	dispose() {
		if (this._disposed) return;
		this._disposed = true;
		this.grabbable?.dispose();
		this.grabbable = null;
		if (this._unsubscribeConsole) this._unsubscribeConsole();
		this._unsubscribeConsole = null;
		this._renderer.dispose();
		if (this._map) this._map.dispose();
		this._map = null;
		if (this._frontMaterial) this._frontMaterial.dispose();
		if (this._backMaterial) this._backMaterial.dispose();
		if (this._mesh) this._mesh.material = null;
		super.dispose();
	}

	get canvas() {
		return this._renderer.canvas;
	}

	get renderer() {
		return this._renderer;
	}
}
