/**
 * @module DynamicMenuVR
 * @description
 * Renders a DynamicMenu instance directly to a canvas texture for fast,
 * frequently-updated VR menus.
 */
import * as THREE from 'three';
import { VRMenu } from './VRMenu.js';
import { CanvasRenderer } from '../vendor/dynamicMenu_CanvasRenderer.js';
import { merge } from 'lodash';
import { defaultOptions as parentDefaultOptions } from './VRMenu.js';
import { EventTypes as CMEventTypes } from './ControllersManager.js';

export const defaultOptions = merge({}, parentDefaultOptions, {
	rendererScale: 2,
	rendererMode: 'commitOnly',
	thumbstickNavigation: false,
	thumbstickAdjustment: {
		minSpeed: 0.02,
		maxSpeed: 0.4,
		exponent: 1.7,
	},
});

/**
 * A VR menu panel that renders a {@link createMenu DynamicMenu} directly to a
 * Three.js `CanvasTexture` via `CanvasRenderer`, without going through
 * html-to-image. This makes it significantly faster than {@link HtmlMenuVR} for
 * dynamic, frequently-updated menus.
 *
 * The panel subscribes to menu state changes and updates the texture automatically.
 * VR ray pointer events are forwarded to the renderer so buttons and inputs work
 * inside VR.
 *
 * Supports `rendererScale` to control canvas resolution, `rendererMode`
 * (`'commitOnly'` | `'live'`) to control when the renderer redraws, and optional
 * discrete focus navigation and continuous focused-slider adjustment from the left XR thumbstick.
 *
 * @extends VRMenu
 *
 * @example
 * const menu = createMenu(document.getElementById('menu-root'));
 * const vrMenu = new DynamicMenuVR(menu, scene, controllersManager, {
 *   mode: 'panel',
 *   rendererScale: 2,
 * });
 */
export class DynamicMenuVR extends VRMenu {
	/**
	 * @param {object} menu - DynamicMenu instance returned by {@link createMenu}.
	 * @param {THREE.Group} worldContainer - Scene node the menu panel is attached to.
	 * @param {ControllersManager} controllersManager - The shared ControllersManager instance.
	 * @param {object} [options] - Options merged with VRMenu defaults.
	 *   Additional properties: `rendererScale` (default `2`), `rendererMode`
	 *   (default `'commitOnly'`), `thumbstickNavigation` (default `false`), and
	 *   `thumbstickAdjustment` speed-curve settings.
	 */
	constructor(menu, worldContainer, controllersManager, options) {
		super(worldContainer, controllersManager, options);

		this._mesh.userData = { class: 'DynamicMenuVR' };
		this.options = merge({}, defaultOptions, options);
		this._menu = menu;

		// 1. Offscreen canvas — CanvasRenderer will resize it via setState()
		this._canvas = document.createElement('canvas');
		this._canvas.width = 4; // placeholder to avoid zero-size texture
		this._canvas.height = 4;

		// 2. THREE.CanvasTexture wrapping that canvas
		this._map = new THREE.CanvasTexture(this._canvas);
		this._map.minFilter = THREE.LinearFilter;
		this._map.magFilter = THREE.LinearFilter;
		this._map.colorSpace = THREE.SRGBColorSpace;
		this._map.generateMipmaps = false;

		// 3. Front material using the canvas texture
		this._frontMaterial = new THREE.MeshBasicMaterial({
			map: this._map,
			color: new THREE.Color(0xffffff),
		});
		this._mesh.material = [this._backMaterial, this._frontMaterial];

		// 4. CanvasRenderer draws the menu into this._canvas
		this._renderer = new CanvasRenderer({
			canvas: this._canvas,
			scale: this.options.rendererScale,
			mode: this.options.rendererMode,
			debug: true,
		});
		this._renderer.onRender = () => {
			if (this._map) this._map.needsUpdate = true;
		};

		// 5. Canvas resize → recreate CanvasTexture (needsUpdate=true is not enough
		//    when canvas dimensions change — the GPU texture must be rebuilt).
		//    Registered BEFORE setState so it also fires on the initial render.
		this._renderer.onResize = () => {
			const oldMap = this._map;
			this._map = new THREE.CanvasTexture(this._canvas);
			this._map.minFilter = THREE.LinearFilter;
			this._map.magFilter = THREE.LinearFilter;
			this._map.colorSpace = THREE.SRGBColorSpace;
			this._map.generateMipmaps = false;
			this._frontMaterial.map = this._map;
			this._frontMaterial.needsUpdate = true;
			oldMap.dispose();
			this._updateTextureAspect();
		};

		// 6. Commands from renderer → DynamicMenu state
		this._renderer.onCommand = (cmd) => this._menu.executeCommand(cmd);

		// 7. DynamicMenu state changes → renderer + texture
		//
		// Eager init: subscribe() does NOT re-fire for late subscribers (React is
		// already mounted by the time VR session starts). Call getMenuState()
		// immediately to bootstrap the renderer, then use subscribe for deltas.
		let initialized = false;
		const initialState = menu.getMenuState();
		if (initialState) {
			initialized = true;
			this._renderer.setState(initialState);
			this._updateTextureAspect();
			this._map.needsUpdate = true;
		}

		this._unsubscribeFn = menu.subscribe((evt) => {
			if (!initialized) {
				// Fallback: fired before React mounted (should be rare here)
				initialized = true;
				const state = menu.getMenuState();
				this._renderer.setState(state);
				this._updateTextureAspect();
				this._map.needsUpdate = true;
				// log map dimensions to console for debugging (should be >0 if aspect ratio is working)
				console.log(
					'DynamicMenuVR: initial menu state received via subscribe() fallback',
					'canvas:',
					this._canvas.width + 'x' + this._canvas.height,
					'map:',
					this._map.image.width + 'x' + this._map.image.height
				);
				return;
			}
			this._renderer.applyEvent(evt);
			if (evt.type === 'structureChange') this._updateTextureAspect();
			this._map.needsUpdate = true;
		});

		console.log('DynamicMenuVR: init() debugLevel:' + this.options.debugLevel);
		this._setupThumbstickNavigation();
	}

	_setupThumbstickNavigation() {
		if (!this.options.thumbstickNavigation) return;
		if (!this._menu?.isFocusNavEnabled?.()) {
			console.warn(
				'DynamicMenuVR: thumbstickNavigation requires the DynamicMenu to be created with focusNavigation: true'
			);
			return;
		}

		const actions = [
			[CMEventTypes.ON_AXIS_FORWARD_CLICK, 'moveUp'],
			[CMEventTypes.ON_AXIS_BACKWARD_CLICK, 'moveDown'],
			[CMEventTypes.ON_AXIS_LEFT_CLICK, 'moveLeft'],
			[CMEventTypes.ON_AXIS_RIGHT_CLICK, 'moveRight'],
		];
		this._thumbstickNavigationListeners = actions.map(([type, method]) => {
			const handler = (event) => {
				if (!this._canHandleThumbstickNavigation(event)) return;
				this._menu[method]?.();
			};
			this._controllersManager.addEventListener(type, handler);
			return { type, handler };
		});

		const buttonHandler = (event) => {
			if (!this._canHandleThumbstickNavigation(event) || event.button !== 'Joystick') return;
			this._menu.activate?.();
		};
		this._controllersManager.addEventListener(CMEventTypes.ON_BUTTON_DOWN, buttonHandler);
		this._thumbstickNavigationListeners.push({ type: CMEventTypes.ON_BUTTON_DOWN, handler: buttonHandler });

		const adjustmentStartHandler = (event) => {
			if (!this._canHandleThumbstickNavigation(event)) return;
			this._thumbstickAdjustmentActive = this._menu.beginFocusedValueAdjustment?.() === true;
		};
		const adjustmentUpdateHandler = (event) => {
			if (!this._canHandleThumbstickNavigation(event)) {
				this._endThumbstickAdjustment();
				return;
			}
			if (!this._thumbstickAdjustmentActive) return;
			const value = Number(event.normalizedValue);
			const frameDelta = Number(event.frameDelta);
			if (!Number.isFinite(value) || !Number.isFinite(frameDelta) || frameDelta <= 0) return;

			const options = this.options.thumbstickAdjustment;
			const magnitude = Math.min(1, Math.abs(value));
			const speed = options.minSpeed + (options.maxSpeed - options.minSpeed) * magnitude ** options.exponent;
			this._menu.adjustFocusedValue?.(Math.sign(value) * speed * frameDelta);
		};
		const adjustmentEndHandler = (event) => {
			if (event?.handedness !== 'left') return;
			this._endThumbstickAdjustment();
		};
		for (const [type, handler] of [
			[CMEventTypes.ON_AXIS_X_CONTINUOUS_START, adjustmentStartHandler],
			[CMEventTypes.ON_AXIS_X_CONTINUOUS_UPDATE, adjustmentUpdateHandler],
			[CMEventTypes.ON_AXIS_X_CONTINUOUS_END, adjustmentEndHandler],
		]) {
			this._controllersManager.addEventListener(type, handler);
			this._thumbstickNavigationListeners.push({ type, handler });
		}
	}

	_canHandleThumbstickNavigation(event) {
		return event?.handedness === 'left' && this.shouldTestRayEvents();
	}

	_disposeThumbstickNavigation() {
		this._endThumbstickAdjustment();
		for (const { type, handler } of this._thumbstickNavigationListeners || []) {
			this._controllersManager.removeEventListener(type, handler);
		}
		this._thumbstickNavigationListeners = null;
	}

	_endThumbstickAdjustment() {
		if (!this._thumbstickAdjustmentActive) return;
		this._thumbstickAdjustmentActive = false;
		this._menu?.endFocusedValueAdjustment?.();
	}

	setVisible(visible) {
		super.setVisible(visible);
		if (!visible) this._endThumbstickAdjustment();
	}

	/**
	 * Reads the complete backing-canvas dimensions and updates the mesh aspect ratio
	 * so the panel fits the menu exactly without blank space or distortion.
	 */
	_updateTextureAspect() {
		const logicalWidth = this._renderer.logicalWidth;
		const logicalHeight = this._renderer.logicalHeight;
		if (logicalWidth <= 0 || logicalHeight <= 0) return;

		// CanvasRenderer owns the complete image. Passing the same logical dimensions
		// for canvas and content maps the full texture and delegates mesh layout/pivot
		// handling to VRMenu/VRInteractivePanel.
		this._updateAspectRatio(logicalWidth, logicalHeight, logicalWidth, logicalHeight);
	}

	/**
	 * Forwards VR ray pointer events to CanvasRenderer.
	 * Y-axis is flipped: Three.js UV has V=0 at bottom; canvas has y=0 at top.
	 */
	_onPointerEvent = (e) => {
		if (!e.data) return;
		const u = e.data.x;
		const v = 1 - e.data.y; // Y-axis flip
		switch (e.type) {
			case 'pointerdown':
				this._renderer.pointerDown(u, v);
				break;
			case 'pointermove':
				this._renderer.pointerMove(u, v);
				this._map.needsUpdate = true; // live drag feedback
				break;
			case 'pointerup':
			case 'pointerupoutside':
				this._renderer.pointerUp(u, v);
				this._map.needsUpdate = true;
				break;
		}
	};

	/**
	 * Unsubscribes from menu state updates, destroys the renderer, and disposes
	 * of all Three.js textures and materials. Call when removing the menu from the scene.
	 */
	dispose() {
		this._disposeThumbstickNavigation();
		if (this._unsubscribeFn) this._unsubscribeFn();
		if (this._renderer) this._renderer.destroy();
		if (this._map) this._map.dispose();
		if (this._frontMaterial) this._frontMaterial.dispose();
		if (this._backMaterial) this._backMaterial.dispose();
		if (this._mesh?.material) this._mesh.material = null;
		if (super.dispose) super.dispose();
	}

	/**
	 * The offscreen canvas that the renderer draws into.
	 * @type {HTMLCanvasElement}
	 */
	get canvas() {
		return this._canvas;
	}
	/**
	 * The CanvasRenderer responsible for drawing menu state onto the canvas.
	 * @type {CanvasRenderer}
	 */
	get renderer() {
		return this._renderer;
	}
}
