/**
 * @module InfoSignPanel
 * @description
 * Shared "sign" style info panel used across examples: a canvas-textured plane with a
 * consistent dark background, accent border, and title/body typography. Content can be
 * static, updated dynamically (`setContent`), or localized (`setLocalizedContent` /
 * `setLanguage`). Optionally wraps itself in a {@link GrabbableVRObject}.
 */
import * as THREE from 'three';
import { GrabbableVRObject } from './GrabbableVRObject.js';

const CANVAS_WIDTH = 1024;
const CANVAS_HEIGHT = 512;
const CORNER_RADIUS = 24;

/**
 * @typedef {object} InfoSignPanelOptions
 * @property {string|{en:string,es:string}} [title=''] - Title text, or a localized map when `localized` is true.
 * @property {Array<string|string[]|{en:string,es:string}>} [lines=[]] - Body rows. Nested arrays render a row in multiple columns; localized maps are resolved when `localized` is true.
 * @property {number} [width=0.58] - Panel width in meters.
 * @property {number} [height=0.28] - Panel height in meters.
 * @property {string} [accentColor='#f97316'] - Border/accent color.
 * @property {string} [background='rgba(8, 13, 24, 0.92)'] - Canvas background fill.
 * @property {boolean} [withBacker=false] - Adds a solid box behind the panel for depth (useful for grabbable panels held in the air).
 * @property {boolean} [localized=false] - When true, `title`/`lines` entries are `{en, es}` maps resolved against `language`.
 * @property {string} [language='en'] - Initial language used when `localized` is true.
 * @property {object|boolean} [grabbable] - When set, wraps the panel in a {@link GrabbableVRObject}. `true` uses grab defaults; an object is passed through as `GrabbableVRObject` options. Requires `scene`.
 * @property {THREE.Scene} [scene] - Required when `grabbable` is set.
 */
const defaultOptions = {
	title: '',
	lines: [],
	width: 0.58,
	height: 0.28,
	accentColor: '#f97316',
	background: 'rgba(8, 13, 24, 0.92)',
	withBacker: false,
	localized: false,
	language: 'en',
	grabbable: null,
	scene: null,
};

/**
 * A canvas-textured info sign with a unified visual style, optional dynamic content
 * updates, optional EN/ES localization, and optional grabbability.
 *
 * @example
 * const panel = new InfoSignPanel({
 *   title: 'AR Surface Lab',
 *   lines: ['Mira una superficie y apreta el gatillo'],
 *   withBacker: true,
 *   grabbable: { contactGrabbing: { enabled: true }, follow: { mode: 'manual', keepWorldUp: true } },
 *   scene,
 * });
 * scene.add(panel.object3D);
 */
export class InfoSignPanel {
	/** @type {InfoSignPanelOptions} */
	_options;
	_canvas;
	_ctx;
	_texture;
	_group;
	_panelMesh;
	_backer = null;

	/** @type {GrabbableVRObject|null} */
	grabbable = null;

	/**
	 * @param {InfoSignPanelOptions} [options]
	 */
	constructor(options) {
		this._options = { ...defaultOptions, ...options };

		this._canvas = document.createElement('canvas');
		this._canvas.width = CANVAS_WIDTH;
		this._canvas.height = CANVAS_HEIGHT;
		this._ctx = this._canvas.getContext('2d');

		this._texture = new THREE.CanvasTexture(this._canvas);
		this._texture.colorSpace = THREE.SRGBColorSpace;

		const material = new THREE.MeshBasicMaterial({
			map: this._texture,
			transparent: true,
			depthWrite: false,
			side: THREE.DoubleSide,
		});
		this._panelMesh = new THREE.Mesh(new THREE.PlaneGeometry(this._options.width, this._options.height), material);

		this._group = new THREE.Group();

		if (this._options.withBacker) {
			this._backer = new THREE.Mesh(
				new THREE.BoxGeometry(this._options.width + 0.04, this._options.height + 0.04, 0.018),
				new THREE.MeshStandardMaterial({
					color: 0x111827,
					roughness: 0.58,
					metalness: 0.04,
					transparent: true,
					opacity: 0.88,
					depthWrite: false,
				})
			);
			this._panelMesh.position.z = 0.012;
			this._panelMesh.renderOrder = 40;
			this._backer.renderOrder = 39;
			this._group.add(this._backer, this._panelMesh);
		} else {
			this._group.add(this._panelMesh);
		}

		this._redraw();

		if (this._options.grabbable) {
			if (!this._options.scene) {
				throw new Error('InfoSignPanel: `scene` is required when `grabbable` is set.');
			}
			const grabOptions = this._options.grabbable === true ? {} : this._options.grabbable;
			this.grabbable = new GrabbableVRObject(this._group, this._options.scene, {
				...grabOptions,
				contactGrabbing: {
					boundsObject: this._backer || this._panelMesh,
					...grabOptions.contactGrabbing,
				},
			});
		}
	}

	/**
	 * The group to add to the scene (contains the panel plane and optional backer box).
	 * @type {THREE.Group}
	 */
	get object3D() {
		return this._group;
	}

	/**
	 * The backer box mesh, when `withBacker` is enabled. Useful as an attachment point
	 * for extra decoration (e.g. a feedback outline) or as the grab `boundsObject`.
	 * @type {THREE.Mesh|null}
	 */
	get backerObject3D() {
		return this._backer;
	}

	/**
	 * Replaces the plain-text content and redraws immediately.
	 * @param {string} title
	 * @param {Array<string|string[]>} [lines=[]]
	 */
	setContent(title, lines = []) {
		this._options.localized = false;
		this._options.title = title;
		this._options.lines = lines;
		this._redraw();
	}

	/**
	 * Replaces the localized content ({en, es} maps) and redraws immediately using the current language.
	 * @param {{en:string,es:string}} title
	 * @param {Array<{en:string,es:string}>} [lines=[]]
	 */
	setLocalizedContent(title, lines = []) {
		this._options.localized = true;
		this._options.title = title;
		this._options.lines = lines;
		this._redraw();
	}

	/**
	 * Sets the active language for localized content and redraws.
	 * @param {string} language
	 */
	setLanguage(language) {
		this._options.language = language;
		this._redraw();
	}

	/**
	 * Changes the accent/border color and redraws. Useful for state-driven feedback
	 * (e.g. a status sign that turns teal once a task completes).
	 * @param {string} accentColor
	 */
	setAccentColor(accentColor) {
		this._options.accentColor = accentColor;
		this._redraw();
	}

	_redraw() {
		const ctx = this._ctx;
		const { width: cw, height: ch } = this._canvas;
		const { accentColor, background, localized, language } = this._options;
		const title = localized ? resolveLocalized(this._options.title, language) : this._options.title;
		const lines = (this._options.lines || []).map((line) => {
			if (Array.isArray(line)) {
				return line.map((cell) => (localized ? resolveLocalized(cell, language) : cell));
			}
			return localized ? resolveLocalized(line, language) : line;
		});

		ctx.clearRect(0, 0, cw, ch);

		ctx.fillStyle = background;
		roundRect(ctx, 0, 0, cw, ch, CORNER_RADIUS);
		ctx.fill();

		ctx.strokeStyle = accentColor;
		ctx.lineWidth = 10;
		roundRect(ctx, 12, 12, cw - 24, ch - 24, CORNER_RADIUS);
		ctx.stroke();

		ctx.textAlign = 'center';
		ctx.fillStyle = '#ffffff';
		ctx.font = 'bold 58px system-ui, sans-serif';
		ctx.fillText(title, cw / 2, 104);

		const bodyColors = ['#dbeafe', '#fed7aa', '#cbd5e1'];
		const hasColumns = lines.some(Array.isArray);
		const rowSpacing = hasColumns ? Math.min(100, 200 / Math.max(1, lines.length - 1)) : 64;
		lines.forEach((line, i) => {
			const rowY = 190 + i * rowSpacing;
			if (!Array.isArray(line)) {
				ctx.fillStyle = bodyColors[Math.min(i, bodyColors.length - 1)];
				setFittedFont(ctx, line, cw - 120);
				ctx.fillText(line, cw / 2, rowY);
				return;
			}

			const horizontalPadding = 54;
			const columnWidth = (cw - horizontalPadding * 2) / line.length;
			line.forEach((cell, columnIndex) => {
				const colorIndex = i * line.length + columnIndex;
				ctx.fillStyle = bodyColors[Math.min(colorIndex, bodyColors.length - 1)];
				setFittedFont(ctx, cell, columnWidth - 30);
				ctx.fillText(cell, horizontalPadding + columnWidth * (columnIndex + 0.5), rowY);
			});
		});

		ctx.textAlign = 'left';
		this._texture.needsUpdate = true;
	}

	/**
	 * Disposes the grabbable wiring, texture, and materials.
	 */
	dispose() {
		this.grabbable?.dispose();
		this._texture.dispose();
		this._panelMesh.material.dispose();
		if (this._backer) this._backer.material.dispose();
	}
}

function setFittedFont(ctx, text, maxWidth, initialSize = 34, minimumSize = 24) {
	let fontSize = initialSize;
	ctx.font = `${fontSize}px system-ui, sans-serif`;
	while (fontSize > minimumSize && ctx.measureText(String(text)).width > maxWidth) {
		fontSize -= 1;
		ctx.font = `${fontSize}px system-ui, sans-serif`;
	}
}

function roundRect(ctx, x, y, w, h, r) {
	ctx.beginPath();
	ctx.moveTo(x + r, y);
	ctx.arcTo(x + w, y, x + w, y + h, r);
	ctx.arcTo(x + w, y + h, x, y + h, r);
	ctx.arcTo(x, y + h, x, y, r);
	ctx.arcTo(x, y, x + w, y, r);
	ctx.closePath();
}

function resolveLocalized(value, language) {
	if (value == null) return '';
	if (typeof value !== 'object') return value;
	return value[language] ?? value.en ?? value.es ?? value.default ?? '';
}
