import * as THREE from 'three';
import { ControllersManager } from './ControllersManager.js';

export function resolveControllersManager(controllersManager) {
	const manager = controllersManager || ControllersManager.instance;
	if (!manager) {
		throw new Error('VR controls require a ControllersManager instance');
	}
	return manager;
}

export function assertObject3D(object, label) {
	if (!(object instanceof THREE.Object3D)) {
		throw new Error(`${label} must be an instance of THREE.Object3D`);
	}
}

export function getGripWorldPosition(controller, target = new THREE.Vector3()) {
	const grip = controller?.getGrip?.();
	if (!grip) return null;
	grip.updateMatrixWorld(true);
	return grip.getWorldPosition(target);
}

export function getGripWorldQuaternion(controller, target = new THREE.Quaternion()) {
	const grip = controller?.getGrip?.();
	if (!grip) return null;
	grip.updateMatrixWorld(true);
	return grip.getWorldQuaternion(target);
}

export function getObjectWorldPosition(object, target = new THREE.Vector3()) {
	if (!object) return null;
	object.updateMatrixWorld(true);
	return object.getWorldPosition(target);
}

export function getObjectWorldBox(object, target = new THREE.Box3()) {
	object.updateMatrixWorld(true);
	return target.setFromObject(object, true);
}

export function pointDistanceToObject(point, object, box = new THREE.Box3()) {
	getObjectWorldBox(object, box);
	if (box.isEmpty()) return Infinity;
	return box.distanceToPoint(point);
}

export function getControllerFromEvent(event, controllersManager) {
	return event.controller || controllersManager.getController(event.handedness);
}

export function getButtonInteractionSources(controllersManager) {
	const sources = [];

	for (const handedness of ['left', 'right']) {
		const controller = controllersManager.getController(handedness);
		if (!controller?.connected) continue;
		const gripPoint = getGripWorldPosition(controller);
		if (gripPoint) {
			sources.push({
				key: `controller:${handedness}:grip`,
				type: 'controller-grip',
				source: 'controller',
				handedness,
				controller,
				point: gripPoint,
			});
		}

		const rayPoint = getObjectWorldPosition(controller.controller);
		if (!rayPoint || gripPoint?.distanceTo(rayPoint) < 0.01) continue;
		sources.push({
			key: `controller:${handedness}:ray`,
			type: 'controller-ray',
			source: 'controller',
			handedness,
			controller,
			point: rayPoint,
		});
	}

	const handTracking = controllersManager.handTrackingManager;
	if (!handTracking) return sources;

	for (const hand of handTracking.hands) {
		if (!hand?.connected) continue;
		const point = hand.getJointWorldPosition?.('index-finger-tip') || getGripWorldPosition(hand);
		if (!point) continue;
		sources.push({
			key: `hand:${hand.handedness}`,
			type: 'hand',
			source: 'hand-tracking',
			handedness: hand.handedness,
			controller: hand,
			hand,
			point,
		});
	}

	return sources;
}

export function getAxisInRestParentSpace(axis, restQuaternion) {
	return axis.clone().normalize().applyQuaternion(restQuaternion).normalize();
}

export function clamp(value, min, max) {
	return Math.min(Math.max(value, min), max);
}
