/**
 * @module XRTeleportMoveControl
 * @description
 * Handles headset locomotion for WebXR scenes: controller teleportation,
 * snap rotation, and optional thumbstick-driven continuous movement.
 */
import * as THREE from 'three';
import { ControllersManager, EventTypes as CMEventTypes } from './ControllersManager.js';
import { computeBoundsTree, disposeBoundsTree, acceleratedRaycast, MeshBVHHelper } from 'three-mesh-bvh';
import { BoxAxesHelper } from './../utils/BoxAxesHelper';
import { merge } from 'lodash';

const STICK_ARROW_THRESHOLD = 0.5; // modulus of stick position has to be larger than this value to show arrow on gizmo

const TORUS_RADIUS = 0.3;
const TORUS_TUBE = 0.02;
const ARROW_UPDATE_THRESHOLD = 1500; // msec
const TELEPORT_ARROW_ANGLE_INCREMENT = Math.PI / 12; //

const ROTATION_INCREMENT = 15; //degrees
const FORWARD_SPEED = 10; // meters/second
const MAX_TELEPORT_SURFACE_SLOPE = (75 * Math.PI) / 180;
const VERTICALITY_THRESHOLD = Math.cos(MAX_TELEPORT_SURFACE_SLOPE);

/**
 * Default configuration for {@link XRTeleportMoveControl}.
 * @typedef {object} XRTeleportMoveControlOptions
 * @property {boolean} [showHelpers=false] - Render debug axes helpers for the reference and world spaces.
 * @property {boolean} [enableContinousMotion=true] - Enable smooth stick-driven translation in the ray direction.
 * @property {boolean} [enableControllerTeleport=true] - Enable select/ray teleport from controller-style inputs.
 * @property {boolean} [restrictVerticalMovement=false] - When `true`, continuous motion is constrained to the XZ plane.
 * @property {'left'|'right'|'both'} [enabledHands='right'] - Which hand(s) can trigger teleport, rotation, and continuous motion.
 * @property {boolean} [showTeleportArc=true] - Render a curved ribbon from the controller ray origin to the teleport target.
 * @property {number} [teleportArcWidth=0.06] - Width of the teleport preview ribbon in meters.
 * @property {number} [teleportArcHeight=1.25] - Height added to the midpoint of the teleport preview curve in meters.
 * @property {number} [teleportArcSegments=24] - Number of segments used to approximate the teleport preview curve.
 * @property {number} [teleportArcStartForwardOffset=0.1] - Distance in meters from the target-ray origin to the visible ribbon start.
 * @property {number} [teleportArcStartHorizontalOffset=0.02] - Mirrored horizontal correction in meters used to center the ribbon on controller models.
 */
export const defaultOptions = {
	showHelpers: false,
	enableContinousMotion: true, // enables translation using the stick, in the direction of the ray
	enableControllerTeleport: true,
	restrictVerticalMovement: false,
	enabledHands: 'right', // which hands are enabled for teleporting, flying or rotating ( can beleft, right or both)
	showTeleportArc: true,
	teleportArcWidth: 0.06,
	teleportArcHeight: 1.25,
	teleportArcSegments: 24,
	teleportArcStartForwardOffset: 0.07,
	teleportArcStartHorizontalOffset: 0.02,
};

const enabledHandsOptions = ['left', 'right', 'both'];

/**
 * Handles VR locomotion: teleportation, snap rotation, and optional
 * continuous (stick-driven) movement.
 *
 * Set walkable floor geometry with {@link setTeleportSurfaces} and call
 * {@link update} every animation frame to keep the reference-space transform
 * in sync when continuous motion is enabled.
 *
 * @example
 * const move = new XRTeleportMoveControl(renderer.xr, controllersManager, scene, {
 *   enabledHands: 'both',
 *   enableContinousMotion: true,
 * });
 * move.setTeleportSurfaces(floorGeometry);
 *
 * // in the render loop:
 * move.update(deltaTime);
 */
export class XRTeleportMoveControl {
	/** @type {XRTeleportMoveControlOptions} */
	options;
	/** @type {ControllersManager} */
	controllersManager;
	/** @type {THREE.Scene} */
	scene;
	/** @type {THREE.WebXRManager} */
	xrManager;

	raycaster;
	testSurface;
	teleportGizmo;
	gizmoArrow;
	teleportArc;
	teleportArcGeometry;
	teleportArcSegmentCount;
	teleportPreviewMaterial;
	vrIsPresenting;

	xrRigidTransform;
	baseReferenceSpace;

	referenceSpaceHelper;
	worldSpaceHelper;

	vrCamera; // is an array camera, its coordinates are in the world space (not in the xrReferenceSpace)

	worldOffset = new THREE.Vector3(0, 0, 0);
	worldYRotation = (0 * Math.PI) / 2; // 0 means looking to the negative z axis

	userHeight = undefined;
	userHeightHasBeenMeasured = false;

	testRay;
	arrowHelper;

	enabledHands = [];

	_teleportGestureIsActive = false;
	/*
  
  Geometry and reference spaces in WebXR
  https://developer.mozilla.org/en-US/docs/Web/API/WebXR_Device_API/Geometry

  */
	/**
	 * @param {THREE.WebXRManager} xrManager - The WebXR manager from `renderer.xr`.
	 * @param {ControllersManager} controllersManager - The shared ControllersManager instance.
	 * @param {THREE.Scene} scene - The Three.js scene (used to add the teleport gizmo).
	 * @param {XRTeleportMoveControlOptions} [options={}] - Optional configuration merged with {@link defaultOptions}.
	 */
	constructor(xrManager, controllersManager, scene, options = {}) {
		this.options = merge({}, defaultOptions, options);
		this.xrManager = xrManager;
		this.controllersManager = controllersManager;
		this.scene = scene;
		this.raycaster = new THREE.Raycaster();
		this.raycaster.firstHitOnly = true;

		this.testRay = new THREE.Ray(new THREE.Vector3(0, 15, 0), new THREE.Vector3(0, -1, 0));

		if (this.options.showHelpers) {
			this.referenceSpaceHelper = new BoxAxesHelper(1.5, 0.02, 0);
			let sprite = this._createSpriteLabel('Reference Space', 1);
			sprite.position.set(0, 1, 0);
			sprite.frustumCulled = false;
			this.referenceSpaceHelper.add(sprite);
			this.scene.add(this.referenceSpaceHelper);

			this.worldSpaceHelper = new BoxAxesHelper(0.75, 0.04, 1);
			sprite = this._createSpriteLabel('World Space', 1);
			sprite.frustumCulled = false;
			sprite.position.set(0, 0.5, 0);
			this.worldSpaceHelper.add(sprite);
			this.scene.add(this.worldSpaceHelper);
		}

		if (this.options.enabledHands == 'both') {
			this.enabledHands = ['left', 'right'];
		} else {
			this.enabledHands = [this.options.enabledHands]; // ["left", "right"] or ["left"] or ["right"]
		}
		this._setupListeners();
		this._buildGizmo();
	}

	/**
	 * Registers XR session lifecycle, teleport, rotation, and continuous-motion listeners.
	 */
	_setupListeners() {
		// When the session starts
		this.xrManager.addEventListener('sessionstart', (e) => {
			this.userHeightHasBeenMeasured = false;
			this.vrIsPresenting = true;

			this.baseReferenceSpace = this.xrManager.getReferenceSpace();
			this.vrCamera = this.xrManager.getCamera();

			this._applyCurrentTransform();
		});

		// When the session ends
		this.xrManager.addEventListener('sessionend', (e) => {
			this.vrIsPresenting = false;
			this.baseReferenceSpace = null;
		});

		// Teleportation events

		this.controllersManager.addEventListener(
			CMEventTypes.ON_RAY_STARTED,
			(e) => {
				if (!this.options.enableControllerTeleport) return;
				if (!this._teleportSurfaces || !this.enabledHands.includes(e.handedness)) return;

				const intersection = this._getTeleportIntersectionFromRay(e.ray);
				if (intersection) {
					this._teleportGestureIsActive = true;
					return false;
				}
				return true;
			},
			-999
		);

		this.controllersManager.addEventListener(
			CMEventTypes.ON_RAY_UPDATED,
			(e) => {
				if (
					!this.options.enableControllerTeleport ||
					!this._teleportSurfaces ||
					!this.enabledHands.includes(e.handedness) ||
					!this._teleportGestureIsActive
				)
					return;

				const intersection = this._getTeleportIntersectionFromRay(e.ray);
				if (intersection) {
					const point = intersection.point;
					this._updateTeleportGizmo(
						new THREE.Vector3(point.x, point.y, point.z),
						e.stickPosition,
						e.ray,
						intersection.face.normal,
						e.handedness
					);
					return false; // stop event propagation to other listeners
				}
				this._hideTeleportPreviewVisuals();
				return true;
			},
			-999
		);

		this.controllersManager.addEventListener(
			CMEventTypes.ON_RAY_ENDED,
			(e) => {
				if (
					!this.options.enableControllerTeleport ||
					!this._teleportSurfaces ||
					!this._teleportGestureIsActive ||
					!this.enabledHands.includes(e.handedness)
				)
					return;

				const intersection = this._getTeleportIntersectionFromRay(e.ray);
				if (intersection) {
					const point = intersection.point;
					this._teleport(new THREE.Vector3(point.x, point.y, point.z), e.stickPosition, e.ray);
					this.clearTeleportPreview();
					return false;
				}

				this.clearTeleportPreview();
				return true;
			},
			-999
		);

		this._updateArrow = (ray) => {
			if (this.arrowHelper) {
				this.scene.remove(this.arrowHelper);
			}
			this.arrowHelper = new THREE.ArrowHelper(ray.direction, ray.origin, 20, 0xff9900);
			this.scene.add(this.arrowHelper);
		};

		// Rotation events
		this.controllersManager.addEventListener(
			CMEventTypes.ON_ROTATE_LEFT,
			(e) => {
				if (this._teleportGestureIsActive || !this.enabledHands.includes(e.handedness)) return;
				this._rotate(-ROTATION_INCREMENT);
			},
			-999
		);

		this.controllersManager.addEventListener(
			CMEventTypes.ON_ROTATE_RIGHT,
			(e) => {
				if (this._teleportGestureIsActive || !this.enabledHands.includes(e.handedness)) return;
				this._rotate(ROTATION_INCREMENT);
			},
			-999
		);

		if (this.options.enableContinousMotion) {
			// Listen to stick events, moving in the Y axis
			this.controllersManager.addEventListener(
				CMEventTypes.ON_AXIS_Y_NOT_ZERO,
				(e) => {
					if (this._teleportGestureIsActive || !this.enabledHands.includes(e.handedness)) return;
					this._moveInDirection(e.ray, e.stickPosition.y, e.deltaTime);
				},
				-999
			);
		}
	}

	/**
	 * Returns whether a hit face normal is close enough to world-up to be walkable.
	 * @param {THREE.Vector3} normal - Face normal in the teleport surface's local space.
	 * @returns {boolean}
	 */
	_isHorizontalSurface(normal) {
		const normalWorld = this._getSurfaceNormalWorld(normal);

		// Check whether the surface normal points upward.
		const isVertical = normalWorld.y > VERTICALITY_THRESHOLD; // Tune the threshold to match the desired floor steepness.
		return isVertical;
	}

	_getSurfaceNormalWorld(normal) {
		return new THREE.Vector3().copy(normal).transformDirection(this._teleportSurfaces.matrixWorld).normalize();
	}

	/**
	 * Computes the orientation for the teleport landing arrow from stick direction and ray heading.
	 * @param {THREE.Vector2} stickPos - Current thumbstick position.
	 * @param {THREE.Ray} ray - Controller ray in world space.
	 * @returns {number} Arrow angle in radians.
	 */
	_getTeleportGizmoAngle(stickPos, ray) {
		let projDir = ray.direction.clone();
		projDir.y = 0;
		projDir.normalize();

		let forwardAngle = Math.atan2(projDir.z, projDir.x);
		let ang = Math.atan2(stickPos.y, -stickPos.x);

		ang = Math.round(ang / TELEPORT_ARROW_ANGLE_INCREMENT) * TELEPORT_ARROW_ANGLE_INCREMENT;

		return Math.PI / 2 + ang - forwardAngle;
	}

	/**
	 * Creates a text sprite used by reference/world-space debug helpers.
	 * @param {string} [text=''] - Label text.
	 * @param {number} [size=1] - Sprite scale in scene units.
	 * @returns {THREE.Sprite}
	 */
	_createSpriteLabel(text = '', size = 1) {
		const canvas = document.createElement('canvas');
		const context = canvas.getContext('2d');

		// Set canvas size
		canvas.width = 256;
		canvas.height = 256;

		// Set text style
		context.font = '24px Arial	';
		context.fillStyle = 'white';
		context.textAlign = 'center';
		context.textBaseline = 'middle';

		// Write text on canvas
		context.fillText(text, canvas.width / 2, canvas.height / 2);

		// Create texture from canvas
		const texture = new THREE.CanvasTexture(canvas);

		// Create sprite using the texture
		const spriteMaterial = new THREE.SpriteMaterial({ map: texture, depthWrite: false });
		const sprite = new THREE.Sprite(spriteMaterial);
		// When sizeAttenutation is false, the size of the sprite is indepent of the camera distance,
		// but is affected by the camera FOV

		sprite.scale.set(size, size, size);

		return sprite;
	}

	/**
	 * Applies snap rotation around the viewer's current XZ position.
	 * @param {number} degrees - Rotation delta in degrees.
	 */
	_rotate(degrees) {
		if (!this.vrIsPresenting || !this.baseReferenceSpace) return;

		let rotationDelta = (degrees * Math.PI) / 180;

		this.worldYRotation += rotationDelta;

		let currentSceneOffset = this.worldOffset.clone();

		let vrCamPosInRefSpace = this.vrCamera.position.clone();
		let m = new THREE.Matrix4().fromArray(this.xrRigidTransform.matrix);

		vrCamPosInRefSpace.applyMatrix4(m);

		// We rotate the scene around the vrCamera position in Reference Space
		let m1 = new THREE.Matrix4().makeTranslation(vrCamPosInRefSpace.x, 0, vrCamPosInRefSpace.z);
		let m2 = new THREE.Matrix4().makeRotationY(rotationDelta);
		let m3 = new THREE.Matrix4().makeTranslation(-vrCamPosInRefSpace.x, 0, -vrCamPosInRefSpace.z);

		let mRot = new THREE.Matrix4();
		mRot.multiply(m1);
		mRot.multiply(m2);
		mRot.multiply(m3);

		currentSceneOffset.applyMatrix4(mRot);
		this.worldOffset.copy(currentSceneOffset);

		this._applyCurrentTransform();

		this.teleportGizmo.visible = false;
	}

	/**
	 * Builds the teleport target ring and orientation arrow.
	 */
	_buildGizmo() {
		const gizmoMat = new THREE.MeshPhongMaterial({ color: 0x00ffff, emissive: 0x555555, shininess: 32 });

		const xrayMaterial = new THREE.ShaderMaterial({
			uniforms: {
				cameraPosition: { value: new THREE.Vector3(1, 1, 1) },
			},
			vertexShader: `
					precision mediump float;

	
					
					varying vec3 vNormal;
					varying vec3 vPosition;

					void main() {
						vNormal = normalize(normalMatrix*vec4(normal,1.0).xyz);
						vPosition = (modelViewMatrix*vec4(position,1.0)).xyz;
						gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
					}
				`,
			fragmentShader: `
					
					varying vec3 vNormal;
					varying vec3 vPosition;

					void main() {
													
						float xrayOpacity = 0.8 - 0.6*abs(dot( vNormal, vec3(0.0,0.0,1.0) ));
						gl_FragColor = vec4(0.0, 0.8, 1.0, xrayOpacity );
						//gl_FragColor = vec4(vNormal, 1.0 );
					}
				`,
			transparent: true,
			side: THREE.DoubleSide,
			depthWrite: false,
		});
		this.teleportPreviewMaterial = xrayMaterial;

		// this.gizmoArrow
		const arrowGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.05, 3);
		arrowGeo.rotateY(Math.PI / 2);
		arrowGeo.translate(0.65, -0.025, 0);

		this.gizmoArrow = new THREE.Mesh(arrowGeo, xrayMaterial);
		this.gizmoArrow.visible = false;

		// Torus
		const torusGeo = new THREE.TorusGeometry(TORUS_RADIUS, TORUS_TUBE, 16, 100);
		torusGeo.rotateX(Math.PI / 2);

		this.teleportGizmo = new THREE.Mesh(torusGeo, xrayMaterial);
		this.teleportGizmo.add(this.gizmoArrow);

		this.scene.add(this.teleportGizmo);
		this.teleportGizmo.visible = false;

		this._buildTeleportArc();
	}

	/**
	 * Builds the dynamic ribbon used to preview the teleport arc.
	 */
	_buildTeleportArc() {
		const configuredSegments = Math.floor(Number(this.options.teleportArcSegments));
		const segmentCount = Number.isFinite(configuredSegments) ? Math.max(1, configuredSegments) : 24;
		this.teleportArcSegmentCount = segmentCount;
		const vertexCount = (segmentCount + 1) * 2;
		const positions = new Float32Array(vertexCount * 3);
		const normals = new Float32Array(vertexCount * 3);
		const indices = [];

		for (let i = 0; i < segmentCount; i++) {
			const base = i * 2;
			indices.push(base, base + 1, base + 2, base + 1, base + 3, base + 2);
		}

		this.teleportArcGeometry = new THREE.BufferGeometry();
		this.teleportArcGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
		this.teleportArcGeometry.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
		this.teleportArcGeometry.setIndex(indices);
		this.teleportArcGeometry.setDrawRange(0, indices.length);

		this.teleportArc = new THREE.Mesh(this.teleportArcGeometry, this.teleportPreviewMaterial);
		this.teleportArc.frustumCulled = false;
		this.teleportArc.visible = false;
		this.scene.add(this.teleportArc);
	}

	/**
	 * Positions and orients the teleport gizmo at the current valid target point.
	 * @param {THREE.Vector3} pos - World-space destination point.
	 * @param {THREE.Vector2} stickPosition - Current thumbstick position.
	 * @param {THREE.Ray} ray - Controller ray in world space.
	 * @param {THREE.Vector3} [surfaceNormal] - Hit face normal in teleport-surface local space.
	 * @param {'left'|'right'} [handedness] - Controller hand used to mirror the visual start correction.
	 */
	_updateTeleportGizmo(pos, stickPosition, ray, surfaceNormal = null, handedness = null) {
		const normalWorld = surfaceNormal ? this._getSurfaceNormalWorld(surfaceNormal) : new THREE.Vector3(0, 1, 0);
		const offset = normalWorld.clone().multiplyScalar(TORUS_TUBE / 2);

		this.teleportGizmo.visible = true;
		this.teleportGizmo.position.copy(pos).add(offset);
		this.teleportGizmo.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), normalWorld);
		this._updateTeleportArc(ray, pos.clone().add(offset), handedness);

		if (stickPosition.length() > STICK_ARROW_THRESHOLD) {
			this.gizmoArrow.visible = true;
			this.gizmoArrow.rotation.y = this._getTeleportGizmoAngle(stickPosition, ray);
			this.gizmoArrow.userData.lastUpdate = Date.now();
		} else {
			this.gizmoArrow.visible = false;
		}
	}

	/**
	 * Updates the dynamic teleport preview arc from the controller ray origin to the target.
	 * @param {THREE.Ray} ray - Controller ray in world space.
	 * @param {THREE.Vector3} targetPos - World-space destination point, including any surface offset.
	 * @param {'left'|'right'} [handedness] - Controller hand used to mirror the visual start correction.
	 */
	_updateTeleportArc(ray, targetPos, handedness = null) {
		if (!this.options.showTeleportArc || !this.teleportArc || !this.teleportArcGeometry || !ray?.origin) {
			if (this.teleportArc) this.teleportArc.visible = false;
			return;
		}

		const segmentCount = this.teleportArcSegmentCount;
		const width = Math.max(0, this.options.teleportArcWidth) / 2;
		const height = Math.max(0, this.options.teleportArcHeight);
		const start = this._getTeleportArcStart(ray, handedness);
		const end = targetPos;
		const control = new THREE.Vector3().addVectors(start, end).multiplyScalar(0.5);
		control.y += height;

		const positionAttribute = this.teleportArcGeometry.getAttribute('position');
		const normalAttribute = this.teleportArcGeometry.getAttribute('normal');
		const worldUp = new THREE.Vector3(0, 1, 0);
		const fallbackSide = new THREE.Vector3(1, 0, 0);

		for (let i = 0; i <= segmentCount; i++) {
			const t = i / segmentCount;
			const oneMinusT = 1 - t;
			const point = start
				.clone()
				.multiplyScalar(oneMinusT * oneMinusT)
				.add(control.clone().multiplyScalar(2 * oneMinusT * t))
				.add(end.clone().multiplyScalar(t * t));
			const tangent = control
				.clone()
				.sub(start)
				.multiplyScalar(2 * oneMinusT)
				.add(
					end
						.clone()
						.sub(control)
						.multiplyScalar(2 * t)
				)
				.normalize();
			const side = new THREE.Vector3().crossVectors(tangent, worldUp);

			if (side.lengthSq() < 0.000001) side.copy(fallbackSide);
			side.normalize().multiplyScalar(width);

			const normal = new THREE.Vector3().crossVectors(side, tangent).normalize();
			const left = point.clone().sub(side);
			const right = point.clone().add(side);
			const vertexIndex = i * 2;

			positionAttribute.setXYZ(vertexIndex, left.x, left.y, left.z);
			positionAttribute.setXYZ(vertexIndex + 1, right.x, right.y, right.z);
			normalAttribute.setXYZ(vertexIndex, normal.x, normal.y, normal.z);
			normalAttribute.setXYZ(vertexIndex + 1, normal.x, normal.y, normal.z);
		}

		positionAttribute.needsUpdate = true;
		normalAttribute.needsUpdate = true;
		this.teleportArcGeometry.computeBoundingSphere();
		this.teleportArc.visible = true;
	}

	_getTeleportArcStart(ray, handedness) {
		const forwardOffset = Math.max(0, Number(this.options.teleportArcStartForwardOffset) || 0);
		const horizontalOffset = Math.max(0, Number(this.options.teleportArcStartHorizontalOffset) || 0);
		const start = ray.origin.clone().addScaledVector(ray.direction, forwardOffset);

		if (!handedness || horizontalOffset === 0) return start;

		const handController = this.controllersManager.getController(handedness)?.controller;
		const horizontalAxis = handController
			? new THREE.Vector3(1, 0, 0).transformDirection(handController.matrixWorld)
			: new THREE.Vector3().crossVectors(ray.direction, new THREE.Vector3(0, 1, 0)).normalize();
		const horizontalSign = handedness === 'left' ? -1 : 1;

		return start.addScaledVector(horizontalAxis, horizontalOffset * horizontalSign);
	}

	/**
	 * Shows the teleport target gizmo for an arbitrary world-space ray.
	 * Useful for non-controller gestures such as hand-tracking aim poses.
	 * @param {THREE.Ray} ray - World-space ray to test against teleport surfaces.
	 * @returns {boolean} Whether a valid teleport target was found.
	 */
	previewTeleportFromRay(ray) {
		const intersection = this._getTeleportIntersectionFromRay(ray);
		if (!intersection) {
			this.clearTeleportPreview();
			return false;
		}

		this._updateTeleportGizmo(intersection.point, new THREE.Vector2(), ray, intersection.face.normal);
		return true;
	}

	/**
	 * Commits a teleport to the current hit point for an arbitrary world-space ray.
	 * @param {THREE.Ray} ray - World-space ray to test against teleport surfaces.
	 * @returns {boolean} Whether teleportation was executed.
	 */
	commitTeleportFromRay(ray) {
		const intersection = this._getTeleportIntersectionFromRay(ray);
		if (!intersection) {
			this.clearTeleportPreview();
			return false;
		}

		this._teleport(intersection.point);
		return true;
	}

	/**
	 * Hides the teleport target preview.
	 */
	clearTeleportPreview() {
		this._teleportGestureIsActive = false;
		this._hideTeleportPreviewVisuals();
	}

	/**
	 * Hides teleport preview meshes without changing gesture state.
	 */
	_hideTeleportPreviewVisuals() {
		if (this.teleportGizmo) this.teleportGizmo.visible = false;
		if (this.gizmoArrow) this.gizmoArrow.visible = false;
		if (this.teleportArc) this.teleportArc.visible = false;
	}

	_getTeleportIntersectionFromRay(ray) {
		if (!this._teleportSurfaces || !ray) return null;

		this.raycaster.ray.copy(ray);
		const intersection = this.raycaster.intersectObject(this._teleportSurfaces);
		if (
			intersection &&
			intersection[0]?.point &&
			intersection[0]?.face &&
			this._isHorizontalSurface(intersection[0].face.normal)
		) {
			return intersection[0];
		}

		return null;
	}

	/**
	 * Measures the user's current headset height once after entering XR.
	 */
	_measureUserHeight() {
		if (this.userHeightHasBeenMeasured || !this.vrIsPresenting) return;

		let pos = this.vrCamera.position.clone();
		// position has not been set yet from XR headser
		if (pos.length() === 0) return;

		let m = new THREE.Matrix4().fromArray(this.xrRigidTransform.matrix);
		pos.applyMatrix4(m);

		this.userHeight = pos.y;
		this.userHeightHasBeenMeasured = true;
	}

	/**
	 * Applies the world offset/rotation needed to move the viewer to a destination.
	 * @param {THREE.Vector3} destinationPos - Destination in world-space coordinates.
	 * @param {THREE.Vector2} [stickPosition] - Optional thumbstick direction for landing orientation.
	 * @param {THREE.Ray} [ray] - Optional controller ray used for landing orientation.
	 */
	_teleport(destinationPos, stickPosition, ray) {
		/*
		destinationPos: the position where the user wants to teleport in world space origin, not to the xrReferenceSpace
		
		Teleport references:  
		https://threejs.org/examples/webxr_vr_teleport.html
		https://github.com/smarthug/teleport
		https://discourse.threejs.org/t/teleport-functionality-in-webxrmanager-webxrcontroller/18605/2
		https://medium.com/@darktears/adding-support-for-vr-inputs-with-webxr-and-three-js-235b40beb6f0
  

    */
		if (!this.vrIsPresenting || !this.baseReferenceSpace) return;

		const arrowUpdateElpasedTime = this.gizmoArrow.userData.lastUpdate
			? Date.now() - this.gizmoArrow.userData.lastUpdate
			: Infinity;

		if (stickPosition && ray && arrowUpdateElpasedTime < ARROW_UPDATE_THRESHOLD) {
			// get head direction vector in world space
			let headDir = this.vrCamera.getWorldDirection(new THREE.Vector3(0, 0, -1));
			headDir.y = 0;
			headDir.normalize();
			let headAngle = Math.atan2(headDir.z, headDir.x);

			/*
			// get the direction of ray in the XZ plane
			let rayDir = ray.direction.clone();
			rayDir.y = 0;
			rayDir.normalize();
			let rayAngle = Math.atan2(rayDir.z, rayDir.x);
			*/
			// get the angle of the ray in the XZ plane

			// get the angle of the arrow in the XZ plane
			let arrowAngle = this.gizmoArrow.rotation.y;

			// arrowAngle is 0 in +x and 90 in +z
			// rayAngle,headAngle are 0 in +x and 90 in -z
			// that's why they are added instead of subtracted

			let deltaRotation = -(arrowAngle + headAngle);
			this.worldYRotation += deltaRotation;
		}

		this.gizmoArrow.visible = false;

		let targetPos = destinationPos.clone().negate();

		let mRot = new THREE.Matrix4().makeRotationY(this.worldYRotation);
		targetPos.applyMatrix4(mRot);

		//this.vrCamera.position() is the position in xrReferenceSpace
		//apply offset between the vrCamera and the xrReferenceSpace

		let vrCamPosInWorldSpace = this.vrCamera.position.clone();
		let m = new THREE.Matrix4().fromArray(this.xrRigidTransform.matrix);
		vrCamPosInWorldSpace.applyMatrix4(m);

		targetPos.x += vrCamPosInWorldSpace.x;
		targetPos.z += vrCamPosInWorldSpace.z;

		this.worldOffset.set(targetPos.x, targetPos.y, targetPos.z);

		this._applyCurrentTransform();
		this._hideTeleportPreviewVisuals();
	}

	/**
	 * Accumulates continuous movement in the controller ray direction.
	 * @param {THREE.Ray} ray - Controller ray in world space.
	 * @param {number} stickPositionY - Dead-zone-adjusted Y axis value.
	 * @param {number} deltaTime - Time in seconds since the last frame.
	 */
	_moveInDirection(ray, stickPositionY, deltaTime) {
		// deltaTime is in seconds
		let rayDir = ray.direction.clone();
		rayDir.normalize();

		if (this.options.restrictVerticalMovement) {
			rayDir.y = 0;
			rayDir.normalize();
		}

		rayDir.multiplyScalar(stickPositionY * FORWARD_SPEED * deltaTime);

		let mRot = new THREE.Matrix4().makeRotationY(this.worldYRotation);
		rayDir.applyMatrix4(mRot);

		this.worldOffset.add(rayDir);

		//this._applyCurrentTransform();
	}

	/**
	 * Accumulates continuous movement from an arbitrary world-space ray.
	 * Useful for hand-tracking gestures that do not have thumbstick axes.
	 * @param {THREE.Ray} ray - World-space movement ray.
	 * @param {number} amount - Signed movement amount, usually normalized from -1 to 1.
	 * @param {number} deltaTime - Time in seconds since the last frame.
	 */
	moveInDirectionFromRay(ray, amount, deltaTime) {
		if (!ray || !Number.isFinite(amount) || !Number.isFinite(deltaTime)) return;
		this._moveInDirection(ray, amount, deltaTime);
	}

	/**
	 * Applies the current world offset and yaw rotation to the XR reference space.
	 */
	_applyCurrentTransform() {
		if (!this.baseReferenceSpace) return;

		let offsetPosition = this.worldOffset.clone();

		// calculation: offsetPosition = [yRotation] * this.worldOffset
		//const mRot = new THREE.Matrix4().makeRotationY(this.worldYRotation);
		//offsetPosition.applyMatrix4(mRot);

		// execute transform
		let offsetRotation = new THREE.Quaternion();
		offsetRotation.setFromAxisAngle(new THREE.Vector3(0, 1, 0), this.worldYRotation);

		this.xrRigidTransform = new XRRigidTransform(
			new THREE.Vector3(offsetPosition.x, offsetPosition.y, offsetPosition.z),
			offsetRotation
		);

		const spaceOffset = this.baseReferenceSpace.getOffsetReferenceSpace(this.xrRigidTransform);

		this.xrManager.setReferenceSpace(spaceOffset);

		// xrRigidTransform is the transform from WorldSpace (scene) to ReferenceSpace.
		let mat = new THREE.Matrix4().fromArray(this.xrRigidTransform.matrix);
		// Its inverse gives the transform from ReferenceSpace to WorldSpace (scene).
		mat.invert();

		let pos = new THREE.Vector3();
		pos.applyMatrix4(mat);

		if (this.options.showHelpers) {
			this.referenceSpaceHelper.position.copy(pos);
			this.referenceSpaceHelper.rotation.setFromRotationMatrix(mat);
		}
	}

	/**
	 * Returns the current world-to-reference-space transform as a `THREE.Matrix4`.
	 * Useful for converting world-space positions into XR reference space.
	 * @returns {THREE.Matrix4}
	 */
	getXRRigidTransform() {
		return new THREE.Matrix4().fromArray(this.xrRigidTransform.matrix);
	}

	/**
	 * Must be called every animation frame when continuous motion is enabled.
	 * Re-applies the current world offset/rotation to the XR reference space.
	 * @param {number} deltaTime - Time in seconds since the last frame.
	 */
	update(deltaTime = null) {
		if (deltaTime == null) {
			console.warn('XRTeleportMoveControl: update() should be called with deltaTime (in seconds)');
			return;
		}
		if (this.vrIsPresenting) {
			this._applyCurrentTransform();
			//this._measureUserHeight();
		}
	}

	/**
	 * Registers the walkable floor geometry for teleportation hit-testing.
	 * Uses `three-mesh-bvh` for accelerated raycasting.
	 * Call this once after the floor mesh geometry is ready.
	 * @param {THREE.BufferGeometry} geometry - The floor or walkable surface geometry.
	 */
	setTeleportSurfaces(geometry) {
		// BVHMesh  https://github.com/gkjohnson/three-mesh-bvh
		geometry.computeBoundsTree = computeBoundsTree.bind(geometry);
		geometry.disposeBoundsTree = disposeBoundsTree.bind(geometry);
		geometry.computeBoundsTree();

		this._teleportSurfaces = new THREE.Mesh(
			geometry,
			new THREE.MeshBasicMaterial({
				side: THREE.DoubleSide,
			})
		);
		this._teleportSurfaces.raycast = acceleratedRaycast.bind(this._teleportSurfaces);
		this._teleportSurfaces.updateMatrixWorld();

		if (this.options.showHelpers) {
			let bvhHelper = new MeshBVHHelper(this._teleportSurfaces, 0xff0000);
			bvhHelper.displayEdges = true;
			this.scene.add(bvhHelper);
		}
	}

	/**
	 * Debug helper that casts a vertical test ray against the teleport surface.
	 */
	_testRayCaster() {
		this.testRay.origin.set(0, 20, 0);
		this.testRay.direction.set(0, -1, 0);
		this.raycaster.ray = this.testRay;
		this._updateArrow(this.testRay);
		const intersection = this.raycaster.intersectObject(this._teleportSurfaces);
		console.log('intersection', intersection);
	}
}
