import * as THREE from 'three';
import { VRInteractivePanel } from './VRInteractivePanel.js';
import { GrabbableVRObject } from './GrabbableVRObject.js';
import { VRVarsWatcherRenderer, defaultWatcherRendererOptions } from './VRVarsWatcherRenderer.js';

export const defaultOptions = {
	...defaultWatcherRendererOptions,
	grabbable: true,
};

/**
 * @typedef {object} VRVarsWatcherOptions
 * @property {number} [width=600] Canvas width in pixels.
 * @property {number} [height=360] Canvas height in pixels.
 * @property {number} [precision=2] Default numeric precision.
 * @property {number} [refreshIntervalMs=0] Minimum sampling interval; zero samples on every update.
 * @property {number} [maxDepth=4] Maximum generic-object snapshot depth.
 * @property {number} [maxProperties=50] Maximum properties captured per object.
 * @property {number} [maxStringLength=2000] Maximum captured string length.
 * @property {number} [changeHighlightMs=350] Duration of the changed-value highlight.
 * @property {number} [historyLength=120] Default maximum numeric history samples.
 * @property {'normal'|'compact'} [density='normal'] Initial row density.
 * @property {1|2} [columns=1] Number of value columns.
 * @property {boolean|object} [grabbable=true] Enables direct grip movement of the panel; pass options to customize the grab behavior.
 */

/**
 * @typedef {object} VRVarsWatcherEntryOptions
 * @property {string} [tab='General'] Group shown in the tab bar.
 * @property {number} [precision] Decimal places used for numeric values.
 * @property {string} [unit] Unit appended to the formatted value.
 * @property {(value: any) => string} [formatter] Custom read-only formatter.
 * @property {string} [color] Canvas text color.
 * @property {boolean} [expandable=true] Allow generic objects to expand.
 * @property {boolean} [history=false] Retain a bounded numeric sparkline.
 * @property {number} [historyLength] Per-watch history capacity.
 * @property {boolean} [pinned=false] Also show the value in the Pinned tab.
 * @property {number} [warnAbove] Highlight as warning above this value.
 * @property {number} [warnBelow] Highlight as warning below this value.
 * @property {number} [criticalAbove] Highlight as critical above this value.
 * @property {number} [criticalBelow] Highlight as critical below this value.
 * @property {(value:any) => ('warn'|'critical'|null)} [threshold] Custom status classifier.
 */

/**
 * Canvas-backed live value and object inspector for WebXR development.
 * Each watched entry represents its current value rather than a retained event log.
 *
 * @extends VRInteractivePanel
 */
export class VRVarsWatcher extends VRInteractivePanel {
	/**
	 * @param {THREE.Group} worldContainer Scene node associated with the panel.
	 * @param {ControllersManager} controllersManager Shared controller manager.
	 * @param {VRVarsWatcherOptions} [options] Renderer and panel options.
	 */
	constructor(worldContainer, controllersManager, options = {}) {
		super(worldContainer, controllersManager, options);
		this.options = { ...defaultOptions, ...this.options, ...options };
		if (!Number.isFinite(this.options.width) || this.options.width <= 0 ||
			!Number.isFinite(this.options.height) || this.options.height <= 0) {
			throw new RangeError('VRVarsWatcher: width and height must be greater than zero');
		}
		if (!Number.isFinite(this.options.refreshIntervalMs) || this.options.refreshIntervalMs < 0) {
			throw new RangeError('VRVarsWatcher: refreshIntervalMs must be zero or greater');
		}
		if (!['normal', 'compact'].includes(this.options.density)) {
			throw new RangeError("VRVarsWatcher: density must be 'normal' or 'compact'");
		}
		if (this.options.columns !== 1 && this.options.columns !== 2) {
			throw new RangeError('VRVarsWatcher: columns must be 1 or 2');
		}

		this._variables = new Map();
		this._nextVariableId = 1;
		this._disposed = false;
		this._mesh.userData = { class: 'VRVarsWatcher' };
		this._renderer = new VRVarsWatcherRenderer(this.options);
		this.grabbable = this.options.grabbable ? new GrabbableVRObject(this.mesh, worldContainer, {
			contactGrabbing: {
				enabled: true,
				distanceThreshold: 0.1,
				boundsObject: this._mesh,
			},
			remoteGrabbing: { enabled: false },
			follow: {
				mode: 'manual',
				preserveGrabOffset: true,
				translationSmoothing: 18,
				keepWorldUp: false,
				snapDegrees: 0,
				snapRelativeToGrab: false,
			},
			placement: { mode: 'free' },
			...(this.options.grabbable === true ? {} : this.options.grabbable),
		}) : null;
		this._renderer.onRender = () => {
			if (this._map) this._map.needsUpdate = true;
		};
	}

	/**
	 * Adds a watched value. Existing two-argument calls remain supported.
	 * @param {string} name Label displayed in the panel.
	 * @param {any|Function} valueOrGetter Static value or function returning the current value.
	 * @param {VRVarsWatcherEntryOptions} [options]
	 * @returns {{id: number, name: string, getter: Function, tab: string, options: object}}
	 */
	add(name, valueOrGetter, options = {}) {
		if (this._disposed) throw new Error('VRVarsWatcher.add: instance is disposed');
		const label = String(name);
		const getter = typeof valueOrGetter === 'function' ? valueOrGetter : () => valueOrGetter;
		const tab = options.tab === undefined ? 'General' : String(options.tab).trim();
		if (!tab) throw new RangeError('VRVarsWatcher.add: tab must not be empty');
		if (tab === 'Pinned') throw new RangeError("VRVarsWatcher.add: 'Pinned' is a reserved tab name");
		const ref = {
			id: this._nextVariableId++,
			name: label,
			getter,
			tab,
			options: { ...options, tab },
			pinned: Boolean(options.pinned),
			model: null,
		};
		this._variables.set(ref.id, ref);
		this._renderer.add(ref);
		if (!this._renderer.paused && (tab === this._renderer.activeTab || (ref.pinned && this._renderer.activeTab === 'Pinned'))) {
			this._renderer.evaluate(undefined, true);
		}
		return ref;
	}

	/** Removes exactly the reference returned by add(), even when labels repeat. */
	remove(ref) {
		if (!ref || !Number.isInteger(ref.id) || this._variables.get(ref.id) !== ref) return false;
		this._variables.delete(ref.id);
		return this._renderer.remove(ref.id);
	}

	/** Removes all watches, or all watches belonging to one tab. */
	clear(tab) {
		const removedIds = this._renderer.clear(tab);
		for (const id of removedIds) this._variables.delete(id);
		return this;
	}

	/** Selects an existing tab and immediately samples its values. */
	setActiveTab(tab) {
		this._renderer.setActiveTab(String(tab));
		return this;
	}

	/** Pauses or resumes live sampling while retaining the visible snapshot. */
	setPaused(paused) {
		this._renderer.setPaused(paused);
		return this;
	}

	/** Filters the active tab by label; pass an empty string to clear. */
	setFilter(filter) {
		this._renderer.setFilter(filter);
		if (!this._renderer.paused) this._renderer.evaluate(undefined, true);
		return this;
	}

	/** Changes row density between `normal` and `compact`. */
	setDensity(density) {
		this._renderer.setDensity(density);
		return this;
	}

	/** Changes the layout between one and two columns. */
	setColumns(columns) {
		this._renderer.setColumns(columns);
		return this;
	}

	/** Adds or removes one watch from the virtual Pinned tab. */
	setPinned(ref, pinned = true) {
		if (!ref || this._variables.get(ref.id) !== ref) return this;
		this._renderer.setPinned(ref.id, pinned);
		return this;
	}

	/**
	 * Adds a reusable group of watch definitions to one tab.
	 * @param {string} tab
	 * @param {Array<{name:string, value?:any, getter?:Function, options?:object}>|object} definitions
	 * @returns {Array<object>} References suitable for remove().
	 */
	addPreset(tab, definitions) {
		const refs = [];
		if (Array.isArray(definitions)) {
			for (const definition of definitions) {
				const source = definition.getter || definition.value;
				refs.push(this.add(definition.name, source, { ...definition.options, tab }));
			}
		} else if (definitions && typeof definitions === 'object') {
			for (const [name, source] of Object.entries(definitions)) refs.push(this.add(name, source, { tab }));
		} else throw new TypeError('VRVarsWatcher.addPreset: definitions must be an array or object');
		return refs;
	}

	/** Samples the visible tab; call from the application render loop. */
	update(time, deltaTime) { // eslint-disable-line no-unused-vars
		if (this._disposed) return false;
		return this._renderer.evaluate(Number.isFinite(time) ? time : undefined);
	}

	/** Creates the fixed-size CanvasTexture. Idempotent. */
	createMap() {
		if (this._disposed) throw new Error('VRVarsWatcher.createMap: instance is disposed');
		if (this._map) return this._map;
		this._map = new THREE.CanvasTexture(this._renderer.canvas);
		this._map.colorSpace = THREE.SRGBColorSpace;
		this._map.minFilter = THREE.LinearFilter;
		this._map.magFilter = THREE.LinearFilter;
		this._map.generateMipmaps = false;
		this._frontMaterial.map = this._map;
		this._frontMaterial.toneMapped = false;
		this._frontMaterial.needsUpdate = true;
		this._mesh.material = [this._backMaterial, this._frontMaterial];
		this._updateAspectRatio(this.options.width, this.options.height, this.options.width, this.options.height);
		this._renderer.render();
		return this._map;
	}

	_onPointerEvent = (event) => {
		if (!event.data) {
			if (event.type === 'pointerupoutside') this._renderer.pointerCancel();
			return;
		}
		const x = event.data.x * this.options.width;
		const y = (1 - event.data.y) * this.options.height;
		if (event.type === 'pointerdown') this._renderer.pointerDown(x, y);
		else if (event.type === 'pointermove') this._renderer.pointerMove(x, y);
		else if (event.type === 'pointerup') this._renderer.pointerUp(x, y);
		else if (event.type === 'pointerupoutside') this._renderer.pointerCancel();
	};

	/** Releases controller listeners and every owned rendering resource. */
	dispose() {
		if (this._disposed) return;
		this._disposed = true;
		this.grabbable?.dispose();
		this.grabbable = null;
		this._variables.clear();
		this._renderer.dispose();
		if (this._map) this._map.dispose();
		this._map = null;
		if (this._frontMaterial) this._frontMaterial.dispose();
		if (this._backMaterial) this._backMaterial.dispose();
		if (this._mesh?.geometry) this._mesh.geometry.dispose();
		if (this._mesh) this._mesh.material = null;
		super.dispose();
	}

	get canvas() {
		return this._renderer.canvas;
	}

	get renderer() {
		return this._renderer;
	}

	get metrics() {
		return { ...this._renderer.metrics };
	}
}
