import { EventsDispatcher } from '../utils/EventsDispatcher.js';

/**
 * @module XRSessionModeButton
 * @description
 * Provides a small DOM button that starts and ends WebXR immersive VR or AR
 * sessions using a Three.js renderer.
 */

const STYLE_ID = 'xr-session-mode-button-style';

/**
 * Event type constants dispatched by {@link XRSessionModeButton}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired after checking browser/device support for the configured session mode. */
	SUPPORT_CHANGE: 'supportchange',
	/** Fired after a WebXR session starts and is attached to the renderer. */
	SESSION_START: 'sessionstart',
	/** Fired after the active WebXR session ends. */
	SESSION_END: 'sessionend',
	/** Fired when `navigator.xr.requestSession` rejects. */
	ERROR: 'error',
};

/**
 * Default DOM button and session options.
 * @type {object}
 * @property {'immersive-vr'|'immersive-ar'} mode - WebXR session mode.
 * @property {string|null} label - Button text before a session starts.
 * @property {string|null} activeLabel - Button text while a session is active.
 * @property {string|null} unsupportedLabel - Button text when the mode is unsupported.
 * @property {Array<string>} requiredFeatures - Required WebXR session features.
 * @property {Array<string>} optionalFeatures - Optional WebXR session features.
 * @property {object} sessionInit - Extra options merged into `navigator.xr.requestSession`.
 * @property {string} className - CSS class applied to the button.
 */
export const defaultOptions = {
	mode: 'immersive-vr',
	label: null,
	activeLabel: null,
	unsupportedLabel: null,
	requiredFeatures: [],
	optionalFeatures: [],
	sessionInit: {},
	className: 'xr-session-mode-button',
};

function ensureStyles() {
	if (document.getElementById(STYLE_ID)) return;

	const style = document.createElement('style');
	style.id = STYLE_ID;
	style.textContent = `
		.xr-session-mode-button {
			position: fixed;
			right: 18px;
			bottom: 18px;
			z-index: 10000;
			min-width: 112px;
			min-height: 42px;
			padding: 10px 16px;
			border: 1px solid rgba(255, 255, 255, 0.36);
			border-radius: 8px;
			background: rgba(12, 18, 32, 0.88);
			color: #ffffff;
			font: 700 14px/1.2 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
			box-shadow: 0 12px 34px rgba(0, 0, 0, 0.34);
			cursor: pointer;
			backdrop-filter: blur(8px);
		}

		.xr-session-mode-button:hover,
		.xr-session-mode-button:focus-visible {
			background: rgba(45, 96, 212, 0.94);
			outline: 2px solid rgba(255, 255, 255, 0.82);
			outline-offset: 2px;
		}

		.xr-session-mode-button:disabled {
			cursor: not-allowed;
			opacity: 0.72;
			background: rgba(35, 39, 48, 0.88);
		}
	`;
	document.head.appendChild(style);
}

function uniqueList(values) {
	return [...new Set((values || []).filter(Boolean))];
}

function hasDomOverlayFeature(options) {
	return [...(options.requiredFeatures || []), ...(options.optionalFeatures || [])].includes('dom-overlay');
}

/**
 * DOM button for starting and ending an immersive WebXR session.
 *
 * The button is created but not appended automatically. Append `button.button`
 * wherever your application keeps its session controls.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const xrButton = new XRSessionModeButton(renderer, {
 *   mode: 'immersive-ar',
 *   requiredFeatures: ['hit-test'],
 *   optionalFeatures: ['dom-overlay'],
 * });
 * document.body.appendChild(xrButton.button);
 */
export class XRSessionModeButton extends EventsDispatcher {
	/**
	 * @param {THREE.WebGLRenderer} renderer - Renderer whose `renderer.xr` will receive the started session.
	 * @param {object} [options] - Button and session options.
	 * @param {'immersive-vr'|'immersive-ar'} [options.mode='immersive-vr'] - Session mode requested from WebXR.
	 * @param {string|null} [options.label=null] - Button text before a session starts.
	 * @param {string|null} [options.activeLabel=null] - Button text while a session is active.
	 * @param {string|null} [options.unsupportedLabel=null] - Button text when the mode is unsupported.
	 * @param {Array<string>} [options.requiredFeatures] - Required WebXR session features.
	 * @param {Array<string>} [options.optionalFeatures] - Optional WebXR session features.
	 * @param {object} [options.sessionInit] - Extra options merged into `navigator.xr.requestSession`.
	 * @param {string} [options.className='xr-session-mode-button'] - CSS class applied to the button.
	 */
	constructor(renderer, options = {}) {
		super();
		if (!renderer?.xr) throw new Error('XRSessionModeButton: renderer with WebXR enabled is required');

		this.renderer = renderer;
		this.options = {
			...defaultOptions,
			...options,
			requiredFeatures: uniqueList(options.requiredFeatures || defaultOptions.requiredFeatures),
			optionalFeatures: uniqueList(options.optionalFeatures || defaultOptions.optionalFeatures),
			sessionInit: {
				...(defaultOptions.sessionInit || {}),
				...(options.sessionInit || {}),
			},
		};
		this.mode = this.options.mode;
		this.currentSession = null;

		ensureStyles();
		this.button = document.createElement('button');
		this.button.type = 'button';
		this.button.className = this.options.className;
		this.button.textContent = this.options.label || this._defaultLabel();
		this.button.addEventListener('click', () => this._onClick());

		queueMicrotask(() => this._checkSupport());
	}

	_defaultLabel() {
		return this.mode === 'immersive-ar' ? 'Enter AR' : 'Enter VR';
	}

	_defaultActiveLabel() {
		return this.mode === 'immersive-ar' ? 'Exit AR' : 'Exit VR';
	}

	_defaultUnsupportedLabel() {
		return this.mode === 'immersive-ar' ? 'AR unsupported' : 'VR unsupported';
	}

	async _checkSupport() {
		if (!navigator.xr?.isSessionSupported) {
			this._setUnsupported('WebXR is not available in this browser.');
			return;
		}

		try {
			const supported = await navigator.xr.isSessionSupported(this.mode);
			if (!supported) {
				this._setUnsupported(`${this.mode} is not supported on this device.`);
				return;
			}
			this.button.disabled = false;
			this.button.textContent = this.options.label || this._defaultLabel();
			this.button.title = '';
			this.dispatchEvent({ type: EventTypes.SUPPORT_CHANGE, supported: true, mode: this.mode });
		} catch (error) {
			this._setUnsupported(error.message || String(error));
		}
	}

	_setUnsupported(reason) {
		this.button.disabled = true;
		this.button.textContent = this.options.unsupportedLabel || this._defaultUnsupportedLabel();
		this.button.title = reason;
		this.dispatchEvent({ type: EventTypes.SUPPORT_CHANGE, supported: false, mode: this.mode, reason });
	}

	_buildSessionInit() {
		const sessionInit = {
			...this.options.sessionInit,
			requiredFeatures: uniqueList([
				...(this.options.sessionInit.requiredFeatures || []),
				...this.options.requiredFeatures,
			]),
			optionalFeatures: uniqueList([
				...(this.options.sessionInit.optionalFeatures || []),
				...this.options.optionalFeatures,
			]),
		};

		if (hasDomOverlayFeature(sessionInit) && !sessionInit.domOverlay && document.body) {
			sessionInit.domOverlay = { root: document.body };
		}

		if (!sessionInit.requiredFeatures.length) delete sessionInit.requiredFeatures;
		if (!sessionInit.optionalFeatures.length) delete sessionInit.optionalFeatures;
		return sessionInit;
	}

	async _onClick() {
		if (this.currentSession) {
			this.currentSession.end();
			return;
		}

		try {
			const session = await navigator.xr.requestSession(this.mode, this._buildSessionInit());
			session.addEventListener('end', () => this._onSessionEnd(session), { once: true });
			await this.renderer.xr.setSession(session);
			this.currentSession = session;
			this.button.textContent = this.options.activeLabel || this._defaultActiveLabel();
			this.dispatchEvent({ type: EventTypes.SESSION_START, mode: this.mode, session });
		} catch (error) {
			this.dispatchEvent({ type: EventTypes.ERROR, mode: this.mode, error });
		}
	}

	_onSessionEnd(session) {
		if (this.currentSession !== session) return;
		this.currentSession = null;
		this.button.textContent = this.options.label || this._defaultLabel();
		this.dispatchEvent({ type: EventTypes.SESSION_END, mode: this.mode, session });
	}
}
