/**
 * @module HtmlMenuVR
 * @description
 * Renders an existing HTML element into a VR menu panel by rasterizing the DOM
 * into a Three.js texture.
 */
import * as THREE from 'three';
import { VRMenu } from './VRMenu.js';
import { ControllersManager, EventTypes as CMEventTypes } from './ControllersManager.js';
import { HTMLMesh } from 'three/addons/interactive/HTMLMesh.js';

import { defaultOptions as parentDefaultOptions } from './VRMenu.js';
import { HTMLTexture } from './HtmlTexture.js';
import { merge } from 'lodash';

export const defaultOptions = merge({}, parentDefaultOptions, {
	canvasOutputScale: 1,
	textureBackend: 'html-to-image',
});

/**
 * A VR menu panel that renders a live HTML DOM element as a Three.js texture.
 *
 * Uses {@link HTMLTexture} (html-to-image under the hood) to rasterise the DOM
 * element and map it onto a quad in world space. Call {@link update} whenever
 * the DOM content changes to refresh the texture.
 *
 * @extends VRMenu
 *
 * @example
 * const menu = new HtmlMenuVR(document.getElementById('my-menu'), scene, controllersManager, {
 *   mode: 'panel',
 * });
 */
export class HtmlMenuVR extends VRMenu {
	//mapNeedsUpdate = false;
	/**
	 * @param {HTMLElement} domElement - The DOM element to render as the menu surface.
	 * @param {THREE.Group} worldContainer - Scene node the menu panel is attached to.
	 * @param {ControllersManager} controllersManager - The shared ControllersManager instance.
	 * @param {object} [options] - Options merged with VRMenu defaults. Supports `canvasOutputScale` (default `1`).
	 */
	constructor(domElement, worldContainer, controllersManager, options) {
		super(worldContainer, controllersManager, options);

		this._mesh.userData = { class: 'HtmlMenuVR' };

		this.options = merge({}, defaultOptions, options);

		this.randomValue = Math.floor(Math.random() * 10000);

		this._domElement = domElement;
		this._htmlMeshTextureSource = null;
		this._map = this._createTextureMap();
		this._updateInFlight = false;
		this._updateQueued = false;

		this._frontMaterial = new THREE.MeshBasicMaterial({
			map: this._map,
			color: new THREE.Color(0xffffff),
		});

		this._mesh.material = [this._backMaterial, this._frontMaterial];

		window.htmlMenuVR = this;

		this._onTextureUpdatedBound = this._onTextureUpdated.bind(this);
		this._map.addEventListener('updated', this._onTextureUpdatedBound);
		this._onTextureUpdated({ texture: this._map });
		console.log('HtmlMenuVR: init() debugLevel:' + this.options.debugLevel);
	}

	_createTextureMap() {
		if (this.options.textureBackend === 'html-mesh') {
			this._htmlMeshTextureSource = new HTMLMesh(this._domElement);
			return this._htmlMeshTextureSource.material.map;
		}

		return new HTMLTexture(this._domElement, { OUTPUT_SCALE: this.options.canvasOutputScale });
	}

	_updateTextureMapImage() {
		if (typeof this._map.updateImage === 'function') return this._map.updateImage();
		if (typeof this._map.update === 'function') {
			this._map.update();
			this._onTextureUpdated({ texture: this._map });
			return this._map;
		}
		return null;
	}

	_disposeTextureMap() {
		if (this._map) {
			this._map.removeEventListener('updated', this._onTextureUpdatedBound);
		}

		if (this._htmlMeshTextureSource) {
			this._htmlMeshTextureSource.dispose();
			this._htmlMeshTextureSource = null;
		} else if (this._map && typeof this._map.dispose === 'function') {
			this._map.dispose();
		}

		this._map = null;
	}


	/**
	 * Refreshes the menu texture from the current DOM element state.
	 * Call this whenever the HTML content changes and the VR panel should reflect it.
	 */
	update() {
		if (this._updateInFlight) {
			this._updateQueued = true;
			return;
		}
		this._updateInFlight = true;

		//if (!this.mapNeedsUpdate) return;
		console.log('HtmlMenuVR: update() id:' + this.randomValue);
		const computedStyle = window.getComputedStyle(this._domElement);
		const zoomFactor = Number(computedStyle.zoom) || 1;
		const expectedWidth = Math.floor(this._domElement.offsetWidth * zoomFactor * this.options.canvasOutputScale);
		const expectedHeight = Math.floor(this._domElement.offsetHeight * zoomFactor * this.options.canvasOutputScale);

		//check if this._domElement dimensions match this._map dimensions
		if (
			expectedWidth !== this._map.image.width ||
			expectedHeight !== this._map.image.height
		) {
			this._disposeTextureMap();

			this._map = this._createTextureMap();
			this._map.addEventListener('updated', this._onTextureUpdatedBound);

			this._frontMaterial.map = this._map;
			this._frontMaterial.needsUpdate = true;
			this._finishUpdateWhenSettled(this._updateTextureMapImage());
		} else {
			this._finishUpdateWhenSettled(this._updateTextureMapImage());
		}
		//this.mapNeedsUpdate = false;
	}

	_finishUpdateWhenSettled(pending) {
		Promise.resolve(pending)
			.catch((error) => {
				console.error('HtmlMenuVR: update failed', error);
			})
			.finally(() => {
				this._updateInFlight = false;
				if (this._updateQueued) {
					this._updateQueued = false;
					this.update();
				}
			});
	}

	_onTextureUpdated(event) {
		const computedStyle = window.getComputedStyle(this._domElement);
		const zoomFactor = computedStyle.zoom || 1;

		let tx = event.texture;
		let h = tx.image.height;
		let w = tx.image.width;
		this._updateAspectRatio(w, h, this._domElement.offsetWidth, this._domElement.offsetHeight);
		tx.needsUpdate = true;
		//console.log('onTextureUpdated:' + tx.image.title);
	}

	// son invocados por la clase padre VRInteractivePanel

	_onPointerEvent = (e) => {
		// e.type: pointerdown,pointerup,pointermove
		// e.data: x,y in [0,1] range

		switch (e.type) {
			case 'pointerdown':
				// We need to convert the type to mousedown
				e.type = 'mousedown';
				// IMPORTANT: The y axis is inverted in the DOM events
				e.data.y = 1 - e.data.y;
				this._map.dispatchDOMEvent(e);
				break;
			case 'pointermove':
				e.type = 'mousemove';
				// IMPORTANT: The y axis is inverted in the DOM events
				e.data.y = 1 - e.data.y;
				this._map.dispatchDOMEvent(e);
				break;
			case 'pointerup':
				e.type = 'mouseup';
				// IMPORTANT: The y axis is inverted in the DOM events
				e.data.y = 1 - e.data.y;
				this._map.dispatchDOMEvent(e);
				break;
			case 'pointerupoutside':
				break;
		}
	};

	/**
	 * Disposes of resources used by HtmlMenuVR, including the HTMLTexture and materials.
	 */
	dispose() {
		this._disposeTextureMap();
		if (this._frontMaterial) {
			this._frontMaterial.dispose();
		}
		if (this._backMaterial) {
			this._backMaterial.dispose();
		}
		if (this._mesh && this._mesh.material) {
			this._mesh.material = null;
		}
		if (super.dispose) super.dispose();
	}

	/**
	 * The HTML element being rendered as the menu surface.
	 * @type {HTMLElement}
	 */
	get domElement() {
		return this._domElement;
	}
	/**
	 * The HTMLTexture wrapping the DOM element.
	 * @type {HTMLTexture}
	 */
	get map() {
		return this._map;
	}
}
