/**
 * @module GrabbableVRObject
 * @description
 * Makes application-owned Three.js objects grabbable in VR, with contact grab,
 * remote grab, snap targets, return behavior, and release intent events.
 */
import * as THREE from 'three';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';
import { ControllersManager, EventTypes as CMEvents } from './ControllersManager.js';

const VALID_PLACEMENT_MODES = new Set(['free', 'snap', 'return', 'snap-or-return']);

/**
 * Default options for {@link GrabbableVRObject}.
 * @typedef {object} GrabbableVRObjectOptions
 * @property {object} [contactGrabbing]
 *   Contact-grab settings. When `enabled`, squeezing while the controller grip is
 *   within `distanceThreshold` metres of the object's local oriented bounds will grab it.
 *   `boundsObject` can point to a child mesh or group when only part of the target object
 *   should define the contact volume.
 * @property {boolean} [contactGrabbing.enabled=true]
 * @property {number} [contactGrabbing.distanceThreshold=0.03]
 * @property {THREE.Object3D|null} [contactGrabbing.boundsObject=null]
 * @property {{ enabled: boolean }} [remoteGrabbing]
 *   Remote-grab settings. When `enabled`, squeezing while the controller ray
 *   intersects the object's bounding box will fly the object to the grip.
 * @property {boolean} [showHelpers=true] - Show bounding-box debug helpers.
 * @property {boolean} [restrictRotationX=false] - Lock object X rotation to its value at grab time.
 * @property {boolean} [restrictRotationY=false] - Lock object Y rotation to its value at grab time.
 * @property {boolean} [restrictRotationZ=false] - Lock object Z rotation to its value at grab time.
 * @property {object} [follow]
 *   Follow behavior used after a contact or remote grab reaches the controller.
 *   `mode: 'manual'` keeps the object in world space and applies controller deltas without reparenting.
 *   `keepWorldUp` removes roll while still allowing yaw and pitch, so the held object's local up axis
 *   remains aligned with world-up as closely as possible.
 *   `snapDegrees` quantizes manual-follow rotation; `snapRelativeToGrab` makes those snap steps relative
 *   to the object's orientation at grab start.
 */
export const defaultOptions = {
	enabled: true,
	contactGrabbing: {
		enabled: true,
		distanceThreshold: 0.03,
		boundsObject: null,
	},
	remoteGrabbing: {
		enabled: true,
	},
	showHelpers: true,
	restrictRotationX: false,
	restrictRotationY: false,
	restrictRotationZ: false,
	follow: {
		mode: 'attach',
		preserveGrabOffset: true,
		translationSmoothing: 0,
		keepWorldUp: false,
		snapDegrees: 0,
		snapRelativeToGrab: false,
	},
	releaseGesture: {
		enabled: false,
		trigger: 'grip-end-or-gesture',
		mode: 'event-and-auto-release',
		sampleWindow: 0.18,
		minSpeed: 1.2,
		minStopAcceleration: 8.0,
		cooldown: 0.35,
	},
	placement: {
		mode: 'free',
		targets: [],
		snapDistance: 0.15,
		snapRotation: true,
		snapScale: false,
		animationDuration: 0.25,
	},
	placeholders: {
		enabled: false,
		createPlaceholder: null,
		opacityRange: [0.15, 0.65],
		showOnlyNearest: true,
		maxVisibleDistance: 0.4,
	},
};

/**
 * Event type constants dispatched by {@link GrabbableVRObject}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when the object is grabbed. Event carries `{controller, object}`. */
	ON_GRAB_START: 'onGrabStart',
	/** Fired every frame while the object is grabbed. */
	ON_GRAB_UPDATE: 'onGrabUpdate',
	/** Fired when the object is released. Event carries `{controller, object}`. */
	ON_GRAB_END: 'onGrabEnd',
	/** Fired when manual-follow rotation crosses a configured snap step. */
	ON_ROTATION_SNAP: 'onRotationSnap',
	/** Fired when a violent release gesture is detected while grabbing. */
	ON_RELEASE_GESTURE: 'onReleaseGesture',
	/** Fired whenever a release is resolved, with velocity and acceleration data. */
	ON_RELEASE_INTENT: 'onReleaseIntent',
	/** Fired when the held object enters a snap target range. */
	ON_SNAP_TARGET_ENTER: 'onSnapTargetEnter',
	/** Fired when the closest snap target changes. */
	ON_SNAP_TARGET_CHANGE: 'onSnapTargetChange',
	/** Fired when the held object leaves a snap target range. */
	ON_SNAP_TARGET_EXIT: 'onSnapTargetExit',
	/** Fired when a snap placement is committed. */
	ON_SNAP_COMMIT: 'onSnapCommit',
	/** Fired when a return-to-origin animation starts. */
	ON_RETURN_START: 'onReturnStart',
	/** Fired when a return-to-origin animation completes. */
	ON_RETURN_END: 'onReturnEnd',
};

/**
 * Makes a Three.js object grabbable in a WebXR scene.
 *
 * Supports contact grabbing, remote grabbing, optional rotation constraints,
 * snap targets, placement previews, return-to-origin, and gesture-based release.
 * It intentionally does not simulate physics; consumers receive release data and
 * can apply application-specific motion, gravity, or collisions outside this class.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const cube = new THREE.Mesh(geometry, material);
 * scene.add(cube);
 *
 * const grabbable = new GrabbableVRObject(cube, scene, {
 *   contactGrabbing: { enabled: true, distanceThreshold: 0.04 },
 *   remoteGrabbing: { enabled: true },
 *   follow: { mode: 'manual', keepWorldUp: true },
 * });
 *
 * grabbable.addEventListener(EventTypes.ON_GRAB_START, ({ controller }) => {
 *   console.log('grabbed by', controller.handedness);
 * });
 */
export class GrabbableVRObject extends EventsDispatcher {
	_options;
	_controllersManager;

	_targetObject;
	_grabbingController;
	_boundingBox;
	_bboxHelper;

	_targetState;
	_scene;
	_enabled = true;

	_snapTargets = [];
	_nearestSnapTarget = null;
	_lastSnapTargetInRange = null;
	_placeholders = new Map();

	_originTransform = null;
	_motionSamples = [];
	_grabElapsed = 0;
	_lastGestureReleaseAt = -Infinity;
	_gestureBlockedHands = {
		left: false,
		right: false,
	};

	_animation = null;

	_constrainedFollow = false;
	_originalQuat = new THREE.Quaternion();
	_manualFollowOffsetMatrix = new THREE.Matrix4();
	_manualFollowBaseAngles = null;
	_lastRotationSnapKey = null;
	_eulerOrder = 'YXZ';
	_tmp = {
		eulerCtrl: new THREE.Euler(0, 0, 0, 'YXZ'),
		eulerOrig: new THREE.Euler(0, 0, 0, 'YXZ'),
		eulerOut: new THREE.Euler(0, 0, 0, 'YXZ'),
		v3: new THREE.Vector3(),
		v3b: new THREE.Vector3(),
		v3c: new THREE.Vector3(),
		v3d: new THREE.Vector3(),
		v3e: new THREE.Vector3(),
		v3f: new THREE.Vector3(),
		quat: new THREE.Quaternion(),
		quatB: new THREE.Quaternion(),
		matrix: new THREE.Matrix4(),
		matrixB: new THREE.Matrix4(),
		box: new THREE.Box3(),
		boxB: new THREE.Box3(),
	};

	/**
	 * @param {THREE.Object3D} targetObject - The scene object to make grabbable.
	 * @param {THREE.Scene} scene - The Three.js scene.
	 * @param {GrabbableVRObjectOptions} [options] - Configuration merged with {@link defaultOptions}.
	 * @throws {Error} If `targetObject` is not a `THREE.Object3D` instance.
	 */
	constructor(targetObject, scene, options) {
		super();
		this._scene = scene;
		this._options = mergeOptions(defaultOptions, options);
		this._enabled = this._options.enabled !== false;
		this._controllersManager = ControllersManager.instance;
		this._targetObject = targetObject;
		this._snapTargets = this._options.placement.targets.slice();

		if (!(targetObject instanceof THREE.Object3D)) {
			throw new Error('GrabbableVRObject: targetObject must be an instance of THREE.Object3D');
		}

		this._constrainedFollow = !!(
			this._options.restrictRotationX ||
			this._options.restrictRotationY ||
			this._options.restrictRotationZ
		);

		if (this._options.contactGrabbing.enabled || this._options.remoteGrabbing.enabled) {
			this._controllersManager.addEventListener(CMEvents.ON_SQUEEZE_START, this._onSqueezeStart);
			this._controllersManager.addEventListener(CMEvents.ON_SQUEEZE_END, this._onSqueezeEnd);
			this._controllersManager.addEventListener(CMEvents.ON_UPDATE, this._onUpdate);
		}
	}

	/**
	 * Replaces all snap targets.
	 * @param {Array<object|THREE.Object3D>} targets
	 */
	setSnapTargets(targets) {
		this._snapTargets = Array.isArray(targets) ? targets.slice() : [];
		this._nearestSnapTarget = null;
		this._setActiveSnapTarget(null);
		this._syncPlaceholders();
	}

	/**
	 * Adds one snap target.
	 * @param {object|THREE.Object3D} target
	 */
	addSnapTarget(target) {
		this._snapTargets.push(target);
	}

	/**
	 * Clears all snap targets and visible placeholders.
	 */
	clearSnapTargets() {
		this._snapTargets = [];
		this._nearestSnapTarget = null;
		this._setActiveSnapTarget(null);
		this._clearPlaceholders();
	}

	/**
	 * Returns the current nearest snap target descriptor, or computes one on demand.
	 * @returns {{ target: object|THREE.Object3D, id: string|number, distance: number, inRange: boolean, transform: object }|null}
	 */
	getNearestSnapTarget() {
		this._nearestSnapTarget = this._findNearestSnapTarget();
		return this._nearestSnapTarget;
	}

	/**
	 * Sets placement mode.
	 * @param {'free'|'snap'|'return'|'snap-or-return'} mode
	 */
	setPlacementMode(mode) {
		if (!VALID_PLACEMENT_MODES.has(mode)) {
			throw new Error(`GrabbableVRObject: invalid placement mode "${mode}"`);
		}
		this._options.placement.mode = mode;
	}

	/**
	 * Releases the object if it is currently grabbed.
	 * @param {string} [reason='manual']
	 * @param {object|null} [releaseData=null]
	 * @returns {boolean} Whether a grabbed object was released.
	 */
	release(reason = 'manual', releaseData = null) {
		if (!this._grabbingController) return false;

		const controller = this._grabbingController;
		const object = this._targetObject;
		const placement = this._resolvePlacementDecision();
		const intent = releaseData || this._getReleaseData(reason);

		if (this._targetState === 'grabbed') {
			this._grabbingController.detachObject();
		}

		this.dispatchEvent({
			type: EventTypes.ON_RELEASE_INTENT,
			controller,
			object,
			...intent,
			reason,
			placement,
		});

		this.dispatchEvent({
			type: EventTypes.ON_GRAB_END,
			controller,
			object,
			...intent,
			reason,
			placement,
		});

		this._setActiveSnapTarget(null);
		this._clearPlaceholders();
		if (this._grabbingController?.grabbedObject === object) {
			this._grabbingController.grabbedObject = null;
		}
		this._grabbingController = null;
		this._targetState = null;
		this._motionSamples.length = 0;
		this._grabElapsed = 0;
		this._applyPlacementDecision(placement, controller, reason);
		return true;
	}

	/**
	 * Cancels the active grab without applying placement rules.
	 * @param {object} [options]
	 * @param {boolean} [options.restore=false]
	 * @returns {boolean} Whether a grabbed object was cancelled.
	 */
	cancelGrab({ restore = false } = {}) {
		if (!this._grabbingController) return false;

		const controller = this._grabbingController;
		const object = this._targetObject;

		if (this._targetState === 'grabbed') {
			this._grabbingController.detachObject();
		}

		this._setActiveSnapTarget(null);
		this._clearPlaceholders();
		if (this._grabbingController?.grabbedObject === object) {
			this._grabbingController.grabbedObject = null;
		}
		this._grabbingController = null;
		this._targetState = null;
		this._motionSamples.length = 0;
		this._grabElapsed = 0;

		if (restore && this._originTransform) {
			this._startTransformAnimation(this._originTransform, 'return', null, controller, 'cancel');
		}

		this.dispatchEvent({
			type: EventTypes.ON_GRAB_END,
			controller,
			object,
			reason: restore ? 'cancel-restore' : 'cancel',
		});
		return true;
	}

	/**
	 * Enables or disables this grabbable object.
	 * @param {boolean} enabled
	 */
	setEnabled(enabled) {
		this._enabled = !!enabled;
		if (!this._enabled) {
			this.cancelGrab();
		}
	}

	/**
	 * Updates animations, fly-to-grip, constrained follow, snap preview, and gesture detection.
	 * @param {{ time: number, deltaTime: number }} e
	 */
	_onUpdate = (e) => {
		this._updateAnimation(e.deltaTime || 0);

		if (!this._grabbingController) return;

		if (this._targetState == 'flyToGrip') {
			this._updateFlyToGrip();
			return;
		}

		if (this._targetState === 'grabbed_constrained') {
			this._updateConstrainedFollow();
		}

		if (this._targetState === 'grabbed_manual') {
			this._updateManualFollow(e.deltaTime || 0);
		}

		this._grabElapsed += e.deltaTime || 0;
		this._recordMotionSample(e.deltaTime || 0);
		this._updateSnapState();

		const releaseData = this._getReleaseData('update');
		this.dispatchEvent({
			type: EventTypes.ON_GRAB_UPDATE,
			controller: this._grabbingController,
			object: this._targetObject,
			snapTarget: this._nearestSnapTarget,
			...releaseData,
		});

		this._maybeTriggerReleaseGesture(releaseData);
	};

	_updateFlyToGrip() {
		const grip = this._grabbingController.getGrip();
		const gripPos = grip.getWorldPosition(new THREE.Vector3());
		const pos = this._targetObject.position;

		const incrementVector = new THREE.Vector3();
		incrementVector.subVectors(gripPos, pos).multiplyScalar(0.5);
		this._targetObject.position.add(incrementVector);

		const distanceToGrip = this._targetObject.position.distanceTo(gripPos);
		if (distanceToGrip < 0.15) {
			if (this._isManualFollow()) {
				this._targetState = 'grabbed_manual';
				this._initManualFollowOffset(this._grabbingController);
			} else if (this._constrainedFollow) {
				this._targetState = 'grabbed_constrained';
				this._originalQuat.copy(this._targetObject.quaternion);
				this._targetObject.position.copy(gripPos);
			} else {
				this._grabbingController.attachObject(this._targetObject);
				this._targetState = 'grabbed';
			}
		}
	}

	_updateConstrainedFollow() {
		const grip = this._grabbingController.getGrip();
		const gripPos = grip.getWorldPosition(this._tmp.v3);
		this._targetObject.position.copy(gripPos);

		const ctrlQuat = grip.getWorldQuaternion(this._tmp.quat);
		this._tmp.eulerCtrl.setFromQuaternion(ctrlQuat, this._eulerOrder);
		this._tmp.eulerOrig.setFromQuaternion(this._originalQuat, this._eulerOrder);

		const useX = !this._options.restrictRotationX;
		const useY = !this._options.restrictRotationY;
		const useZ = !this._options.restrictRotationZ;

		this._tmp.eulerOut.set(
			useX ? this._tmp.eulerCtrl.x : this._tmp.eulerOrig.x,
			useY ? this._tmp.eulerCtrl.y : this._tmp.eulerOrig.y,
			useZ ? this._tmp.eulerCtrl.z : this._tmp.eulerOrig.z,
			this._eulerOrder
		);

		this._targetObject.quaternion.setFromEuler(this._tmp.eulerOut);
	}

	_isManualFollow() {
		return this._options.follow?.mode === 'manual';
	}

	_initManualFollowOffset(controller) {
		const grip = controller?.getGrip?.();
		if (!grip) return;

		grip.updateMatrixWorld(true);
		this._targetObject.updateMatrixWorld(true);
		this._initManualFollowRotationSnapState();

		if (this._options.follow.preserveGrabOffset === false) {
			this._manualFollowOffsetMatrix.identity();
			return;
		}

		this._manualFollowOffsetMatrix.copy(grip.matrixWorld).invert().multiply(this._targetObject.matrixWorld);
	}

	_updateManualFollow(deltaTime) {
		const grip = this._grabbingController?.getGrip?.();
		if (!grip) return;

		grip.updateMatrixWorld(true);
		this._tmp.matrix.copy(grip.matrixWorld).multiply(this._manualFollowOffsetMatrix);
		this._tmp.matrix.decompose(this._tmp.v3, this._tmp.quat, this._tmp.v3c);

		this._applyManualFollowRotationConstraints(this._tmp.quat);
		this._applyManualFollowTranslationSmoothing(this._tmp.v3, deltaTime);

		this._applyWorldTransform({
			position: this._tmp.v3,
			quaternion: this._tmp.quat,
			scale: this._tmp.v3c,
		});
	}

	_applyManualFollowTranslationSmoothing(targetPosition, deltaTime) {
		const smoothing = this._options.follow.translationSmoothing || 0;
		if (smoothing <= 0 || deltaTime <= 0) return;

		const alpha = 1 - Math.exp(-smoothing * deltaTime);
		const currentPosition = this._targetObject.getWorldPosition(this._tmp.v3b);
		targetPosition.lerpVectors(currentPosition, targetPosition, THREE.MathUtils.clamp(alpha, 0, 1));
	}

	_applyManualFollowRotationConstraints(quaternion) {
		const snapRadians = THREE.MathUtils.degToRad(Math.max(0, this._options.follow.snapDegrees || 0));

		if (this._options.follow.keepWorldUp) {
			this._applyWorldUpManualFollowRotation(quaternion, snapRadians);
			return;
		}

		if (snapRadians <= 0) return;
		this._tmp.eulerOut.setFromQuaternion(quaternion, this._eulerOrder);
		this._tmp.eulerOut.x = Math.round(this._tmp.eulerOut.x / snapRadians) * snapRadians;
		this._tmp.eulerOut.y = Math.round(this._tmp.eulerOut.y / snapRadians) * snapRadians;
		this._tmp.eulerOut.z = Math.round(this._tmp.eulerOut.z / snapRadians) * snapRadians;
		quaternion.setFromEuler(this._tmp.eulerOut);
	}

	_initManualFollowRotationSnapState() {
		const snapRadians = THREE.MathUtils.degToRad(Math.max(0, this._options.follow.snapDegrees || 0));
		if (!this._options.follow.keepWorldUp || snapRadians <= 0) {
			this._manualFollowBaseAngles = null;
			this._lastRotationSnapKey = null;
			return;
		}

		const baseQuaternion = this._targetObject.getWorldQuaternion(this._tmp.quatB);
		this._manualFollowBaseAngles = this._getWorldUpYawPitch(baseQuaternion);
		if (this._options.follow.snapRelativeToGrab) {
			this._lastRotationSnapKey = this._getRotationSnapKey(0, 0);
		} else {
			this._lastRotationSnapKey = this._getRotationSnapKey(
				Math.round(this._manualFollowBaseAngles.yaw / snapRadians),
				Math.round(this._manualFollowBaseAngles.pitch / snapRadians)
			);
		}
	}

	_applyWorldUpManualFollowRotation(quaternion, snapRadians) {
		const angles = this._getWorldUpYawPitch(quaternion);
		let yaw = angles.yaw;
		let pitch = angles.pitch;
		let yawIndex = null;
		let pitchIndex = null;

		if (snapRadians > 0) {
			const base = this._options.follow.snapRelativeToGrab
				? this._manualFollowBaseAngles || { yaw: 0, pitch: 0 }
				: { yaw: 0, pitch: 0 };
			yawIndex = Math.round(wrapAngle(yaw - base.yaw) / snapRadians);
			pitchIndex = Math.round((pitch - base.pitch) / snapRadians);
			yaw = base.yaw + yawIndex * snapRadians;
			pitch = base.pitch + pitchIndex * snapRadians;
			this._dispatchRotationSnapIfNeeded(yawIndex, pitchIndex, yaw, pitch);
		}

		const maxPitch = Math.PI / 2 - 0.0001;
		pitch = THREE.MathUtils.clamp(pitch, -maxPitch, maxPitch);

		const forward = this._tmp.v3b;
		const cosPitch = Math.cos(pitch);
		forward.set(Math.sin(yaw) * cosPitch, Math.sin(pitch), Math.cos(yaw) * cosPitch).normalize();

		const worldUp = this._tmp.v3f.set(0, 1, 0);
		const right = this._tmp.v3d.crossVectors(worldUp, forward);
		if (right.lengthSq() < 0.000001) {
			right.set(1, 0, 0);
		} else {
			right.normalize();
		}

		const up = this._tmp.v3e.crossVectors(forward, right).normalize();
		this._tmp.matrix.makeBasis(right, up, forward);
		quaternion.setFromRotationMatrix(this._tmp.matrix);
	}

	_getWorldUpYawPitch(quaternion) {
		const forward = this._tmp.v3b.set(0, 0, 1).applyQuaternion(quaternion).normalize();
		return {
			yaw: Math.atan2(forward.x, forward.z),
			pitch: Math.asin(THREE.MathUtils.clamp(forward.y, -1, 1)),
		};
	}

	_dispatchRotationSnapIfNeeded(yawIndex, pitchIndex, yaw, pitch) {
		const snapKey = this._getRotationSnapKey(yawIndex, pitchIndex);
		if (this._lastRotationSnapKey === snapKey) return;

		const previousSnapKey = this._lastRotationSnapKey;
		this._lastRotationSnapKey = snapKey;

		this.dispatchEvent({
			type: EventTypes.ON_ROTATION_SNAP,
			controller: this._grabbingController,
			object: this._targetObject,
			previousSnapKey,
			snapKey,
			yawIndex,
			pitchIndex,
			yaw,
			pitch,
			snapDegrees: this._options.follow.snapDegrees,
		});
	}

	_getRotationSnapKey(yawIndex, pitchIndex) {
		return `${yawIndex}:${pitchIndex}`;
	}

	/**
	 * Computes the distance from a controller grip to the configured contact bounds.
	 * @param {'left'|'right'} which - Controller hand.
	 * @returns {number|null}
	 */
	_getControllerDistanceToBBox(which) {
		return this.getControllerDistanceToContactBounds(which);
	}

	/**
	 * Computes the world-space distance from a controller grip to the local oriented
	 * bounds used for contact grabbing.
	 *
	 * The contact bounds are aligned with `contactGrabbing.boundsObject` local axes,
	 * or with the target object's local axes when no bounds object is configured.
	 * This avoids the inflated contact area produced by a world-axis-aligned AABB
	 * when the object is rotated.
	 *
	 * @param {'left'|'right'} which - Controller hand.
	 * @returns {number|null}
	 */
	getControllerDistanceToContactBounds(which) {
		const controller = this._controllersManager.getController(which);
		if (!controller?.connected) return null;

		const grip = controller.getGrip?.();
		if (!grip) return null;

		const gripWorldPos = grip.getWorldPosition(this._tmp.v3);
		return this._getDistanceToContactBounds(gripWorldPos);
	}

	_getDistanceToContactBounds(worldPoint) {
		const boundsObject = this._options.contactGrabbing.boundsObject || this._targetObject;
		if (!(boundsObject instanceof THREE.Object3D)) return null;

		const bounds = this._computeLocalContactBounds(boundsObject, this._tmp.box);
		if (!bounds) return null;

		const localPoint = this._tmp.v3b.copy(worldPoint);
		boundsObject.worldToLocal(localPoint);

		const closestLocal = this._tmp.v3c.copy(localPoint).clamp(bounds.min, bounds.max);
		const closestWorld = boundsObject.localToWorld(this._tmp.v3d.copy(closestLocal));
		return closestWorld.distanceTo(worldPoint);
	}

	_computeLocalContactBounds(boundsObject, targetBox) {
		targetBox.makeEmpty();
		boundsObject.updateMatrixWorld(true);

		const inverseBoundsMatrix = this._tmp.matrix.copy(boundsObject.matrixWorld).invert();
		let hasBounds = false;

		boundsObject.traverse((child) => {
			const geometry = child.geometry;
			if (!geometry) return;
			if (!geometry.boundingBox) geometry.computeBoundingBox();
			if (!geometry.boundingBox) return;

			this._tmp.matrixB.multiplyMatrices(inverseBoundsMatrix, child.matrixWorld);
			this._tmp.boxB.copy(geometry.boundingBox).applyMatrix4(this._tmp.matrixB);
			targetBox.union(this._tmp.boxB);
			hasBounds = true;
		});

		return hasBounds ? targetBox : null;
	}

	/**
	 * Distance in metres from the right controller grip to the nearest point on
	 * the object's contact bounds. Returns `null` if the right controller is not connected.
	 * @type {number|null}
	 */
	get distanceToRightController() {
		return this._getControllerDistanceToBBox('right');
	}

	/**
	 * Starts contact or remote grabbing when a squeeze begins near or over the object.
	 * @param {object} e - ControllersManager squeeze event.
	 * @returns {false|undefined} `false` stops event propagation when a grab starts.
	 */
	_onSqueezeStart = (e) => {
		if (!this._enabled) return;
		if (this._grabbingController) return;
		if (this._gestureBlockedHands[e.handedness]) return;

		const controller = e.controller || this._controllersManager.getController(e.handedness);
		if (!controller) return;

		if (this._options.contactGrabbing.enabled) {
			const grip = controller.getGrip?.();
			const gripWorldPos = grip?.getWorldPosition(this._tmp.v3);
			const distance = gripWorldPos ? this._getDistanceToContactBounds(gripWorldPos) : null;

			if (distance !== null && distance < this._options.contactGrabbing.distanceThreshold) {
				this._startGrab(controller, gripWorldPos, false);
				return false;
			}
		}

		if (this._options.remoteGrabbing.enabled) {
			this._targetObject.updateMatrixWorld();
			this._boundingBox = new THREE.Box3().setFromObject(this._targetObject, true);
			const res = e.ray.intersectBox(this._boundingBox, new THREE.Vector3());
			if (res) {
				this._startGrab(controller, null, true);
				return false;
			}
		}
	};

	_startGrab(controller, gripWorldPos, remote) {
		this._animation = null;
		this._originTransform = this._captureWorldTransform(this._targetObject);
		this._grabbingController = controller;
		this._grabbingController.grabbedObject = this._targetObject;
		this._motionSamples.length = 0;
		this._grabElapsed = 0;
		this._nearestSnapTarget = null;
		this._lastSnapTargetInRange = null;

		if (remote) {
			this._moveObjectToScenePreservingWorldTransform();
			this._targetState = 'flyToGrip';
		} else if (this._isManualFollow()) {
			this._targetState = 'grabbed_manual';
			this._initManualFollowOffset(controller);
		} else if (this._constrainedFollow) {
			this._targetState = 'grabbed_constrained';
			this._originalQuat.copy(this._targetObject.quaternion);
			if (gripWorldPos) this._targetObject.position.copy(gripWorldPos);
		} else {
			this._grabbingController.attachObject(this._targetObject);
			this._targetState = 'grabbed';
		}

		this._recordMotionSample(0);
		this.dispatchEvent({
			type: EventTypes.ON_GRAB_START,
			controller: this._grabbingController,
			object: this._targetObject,
			originTransform: this._cloneTransform(this._originTransform),
		});
	}

	/**
	 * Releases the object when the active grabbing controller stops squeezing.
	 * @param {object} e - ControllersManager squeeze event.
	 */
	_onSqueezeEnd = (e) => {
		this._gestureBlockedHands[e.handedness] = false;
		if (!this._grabbingController || this._grabbingController.handedness !== e.handedness) return;

		if (this._options.releaseGesture.enabled && this._options.releaseGesture.trigger === 'gesture-only') {
			return;
		}

		this.release('grip-end');
	};

	_updateSnapState() {
		this._nearestSnapTarget = this._findNearestSnapTarget();
		const active = this._nearestSnapTarget?.inRange ? this._nearestSnapTarget : null;
		this._setActiveSnapTarget(active);
		this._syncPlaceholders();
	}

	_setActiveSnapTarget(next) {
		const previous = this._lastSnapTargetInRange;
		if (sameSnapTarget(previous, next)) return;

		if (previous) {
			this.dispatchEvent({
				type: EventTypes.ON_SNAP_TARGET_EXIT,
				controller: this._grabbingController,
				object: this._targetObject,
				snapTarget: previous,
			});
		}

		if (next && previous) {
			this.dispatchEvent({
				type: EventTypes.ON_SNAP_TARGET_CHANGE,
				controller: this._grabbingController,
				object: this._targetObject,
				previousSnapTarget: previous,
				snapTarget: next,
			});
		}

		if (next) {
			this.dispatchEvent({
				type: EventTypes.ON_SNAP_TARGET_ENTER,
				controller: this._grabbingController,
				object: this._targetObject,
				snapTarget: next,
			});
		}

		this._lastSnapTargetInRange = next;
	}

	_findNearestSnapTarget() {
		if (!this._snapTargets.length) return null;

		const objectPos = this._targetObject.getWorldPosition(this._tmp.v3);
		let nearest = null;

		for (let i = 0; i < this._snapTargets.length; i++) {
			const target = this._snapTargets[i];
			const transform = this._getTargetWorldTransform(target);
			if (!transform?.position) continue;

			const distance = objectPos.distanceTo(transform.position);
			if (!nearest || distance < nearest.distance) {
				nearest = {
					target,
					id: getSnapTargetId(target, i),
					distance,
					inRange: distance <= this._options.placement.snapDistance,
					transform,
				};
			}
		}

		return nearest;
	}

	_resolvePlacementDecision() {
		const mode = this._options.placement.mode;
		const snapTarget = this._nearestSnapTarget?.inRange ? this._nearestSnapTarget : null;

		if (mode === 'return') {
			return { action: 'return', snapTarget: null, transform: this._cloneTransform(this._originTransform) };
		}

		if ((mode === 'snap' || mode === 'snap-or-return') && snapTarget) {
			const transform = this._buildSnapTransform(snapTarget.transform);
			return { action: 'snap', snapTarget, transform };
		}

		if (mode === 'snap-or-return') {
			return { action: 'return', snapTarget: null, transform: this._cloneTransform(this._originTransform) };
		}

		return { action: 'free', snapTarget: null, transform: null };
	}

	_applyPlacementDecision(placement, controller, reason) {
		if (!placement || placement.action === 'free') return;

		if (placement.action === 'snap') {
			this._startTransformAnimation(placement.transform, 'snap', placement.snapTarget, controller, reason);
			return;
		}

		if (placement.action === 'return') {
			this.dispatchEvent({
				type: EventTypes.ON_RETURN_START,
				controller,
				object: this._targetObject,
				reason,
			});
			this._startTransformAnimation(placement.transform, 'return', null, controller, reason);
		}
	}

	_startTransformAnimation(toTransform, type, snapTarget, controller, reason) {
		if (!toTransform) return;

		const fromTransform = this._captureWorldTransform(this._targetObject);
		const duration = Math.max(0, this._options.placement.animationDuration || 0);

		this._animation = {
			type,
			snapTarget,
			controller,
			reason,
			from: fromTransform,
			to: this._cloneTransform(toTransform),
			duration,
			elapsed: 0,
		};

		if (duration === 0) {
			this._updateAnimation(0);
		}
	}

	_updateAnimation(deltaTime) {
		if (!this._animation) return;

		const animation = this._animation;
		animation.elapsed += deltaTime || animation.duration;
		const t = animation.duration <= 0 ? 1 : Math.min(animation.elapsed / animation.duration, 1);
		const position = animation.from.position.clone().lerp(animation.to.position, t);
		const quaternion = animation.from.quaternion.clone().slerp(animation.to.quaternion, t);
		const scale = animation.from.scale.clone().lerp(animation.to.scale, t);

		this._applyWorldTransform({ position, quaternion, scale });

		if (t < 1) return;

		if (animation.to.parent && this._targetObject.parent !== animation.to.parent) {
			animation.to.parent.attach(this._targetObject);
			this._applyWorldTransform(animation.to);
		}

		if (animation.type === 'snap') {
			this.dispatchEvent({
				type: EventTypes.ON_SNAP_COMMIT,
				controller: animation.controller,
				object: this._targetObject,
				reason: animation.reason,
				snapTarget: animation.snapTarget,
			});
		} else if (animation.type === 'return') {
			this.dispatchEvent({
				type: EventTypes.ON_RETURN_END,
				controller: animation.controller,
				object: this._targetObject,
				reason: animation.reason,
			});
		}

		this._animation = null;
	}

	_recordMotionSample(deltaTime) {
		if (!this._grabbingController) return;

		const grip = this._grabbingController.getGrip();
		const position = grip.getWorldPosition(new THREE.Vector3());
		const quaternion = grip.getWorldQuaternion(new THREE.Quaternion());
		const previous = this._motionSamples[this._motionSamples.length - 1];
		const dt = Math.max(deltaTime || 0, previous ? this._grabElapsed - previous.time : 0);

		let velocity = new THREE.Vector3();
		let angularVelocity = new THREE.Vector3();
		let speed = 0;

		if (previous && dt > 0.0001) {
			velocity = position.clone().sub(previous.position).divideScalar(dt);
			angularVelocity = computeAngularVelocity(previous.quaternion, quaternion, dt);
			speed = velocity.length();
		}

		const sample = {
			time: this._grabElapsed,
			position,
			quaternion,
			velocity,
			angularVelocity,
			speed,
		};

		this._motionSamples.push(sample);

		const minTime = this._grabElapsed - this._options.releaseGesture.sampleWindow;
		while (this._motionSamples.length > 1 && this._motionSamples[0].time < minTime) {
			this._motionSamples.shift();
		}
	}

	_getReleaseData(reason) {
		const last = this._motionSamples[this._motionSamples.length - 1];
		const previous = this._motionSamples[this._motionSamples.length - 2];
		const peak = this._getPeakMotionSample();
		const dt = last && previous ? Math.max(last.time - previous.time, 0.0001) : 0;
		const acceleration =
			last && previous ? last.velocity.clone().sub(previous.velocity).divideScalar(dt) : new THREE.Vector3();
		const stopAcceleration = this._getMaxStopAcceleration();
		const linearVelocity = peak?.velocity?.clone() || last?.velocity?.clone() || new THREE.Vector3();
		const angularVelocity = peak?.angularVelocity?.clone() || last?.angularVelocity?.clone() || new THREE.Vector3();
		const direction = linearVelocity.lengthSq() > 0 ? linearVelocity.clone().normalize() : new THREE.Vector3();

		return {
			reason,
			linearVelocity,
			angularVelocity,
			acceleration,
			direction,
			speed: linearVelocity.length(),
			stopAcceleration,
		};
	}

	_getPeakMotionSample() {
		let peak = null;
		for (const sample of this._motionSamples) {
			if (!peak || sample.speed > peak.speed) peak = sample;
		}
		return peak;
	}

	_getMaxStopAcceleration() {
		let maxStopAcceleration = 0;
		for (let i = 1; i < this._motionSamples.length; i++) {
			const previous = this._motionSamples[i - 1];
			const current = this._motionSamples[i];
			const dt = Math.max(current.time - previous.time, 0.0001);
			const stopAcceleration = Math.max((previous.speed - current.speed) / dt, 0);
			if (stopAcceleration > maxStopAcceleration) {
				maxStopAcceleration = stopAcceleration;
			}
		}
		return maxStopAcceleration;
	}

	_maybeTriggerReleaseGesture(releaseData) {
		const options = this._options.releaseGesture;
		if (!options.enabled) return;
		if (options.trigger === 'grip-end') return;
		if (this._grabElapsed - this._lastGestureReleaseAt < options.cooldown) return;
		if (releaseData.speed < options.minSpeed) return;
		if (releaseData.stopAcceleration < options.minStopAcceleration) return;

		this._lastGestureReleaseAt = this._grabElapsed;
		const hand = this._grabbingController?.handedness;
		const event = {
			type: EventTypes.ON_RELEASE_GESTURE,
			object: this._targetObject,
			controller: this._grabbingController,
			...releaseData,
			reason: 'gesture',
			cancelable: options.mode === 'event-and-auto-release',
		};

		if (options.mode === 'event-only') {
			this.dispatchEvent(event);
			return;
		}

		let shouldRelease = true;
		if (options.mode === 'event-and-auto-release') {
			shouldRelease = this._dispatchCancelableEvent(event);
		} else {
			this.dispatchEvent(event);
		}

		if (!shouldRelease || !this._grabbingController) return;

		if (hand) this._gestureBlockedHands[hand] = true;
		this.release('gesture', releaseData);
	}

	_dispatchCancelableEvent(event) {
		if (!this._listeners || !(event.type in this._listeners)) return true;

		const handlers = this._listeners[event.type].slice();
		for (let i = 0; i < handlers.length; i++) {
			if (handlers[i].handler.call(this, event) === false) {
				return false;
			}
		}
		return true;
	}

	_syncPlaceholders() {
		const options = this._options.placeholders;
		if (!options.enabled || !this._grabbingController) {
			this._clearPlaceholders();
			return;
		}

		const visibleTargets = this._getVisiblePlaceholderTargets();
		const visibleIds = new Set(visibleTargets.map((entry) => entry.id));

		for (const [id, placeholder] of this._placeholders) {
			if (!visibleIds.has(id)) {
				this._removePlaceholder(id, placeholder);
			}
		}

		for (const entry of visibleTargets) {
			let placeholder = this._placeholders.get(entry.id);
			if (!placeholder) {
				placeholder = this._createPlaceholder(entry);
				if (!placeholder) continue;
				this._placeholders.set(entry.id, placeholder);
			}

			this._applyWorldTransformToObject(placeholder, entry.transform);
			this._setPlaceholderOpacity(placeholder, this._getPlaceholderOpacity(entry.distance));
			placeholder.visible = true;
		}
	}

	_getVisiblePlaceholderTargets() {
		const options = this._options.placeholders;
		const maxDistance = options.maxVisibleDistance;

		if (options.showOnlyNearest) {
			const nearest = this._nearestSnapTarget || this._findNearestSnapTarget();
			return nearest && nearest.distance <= maxDistance ? [nearest] : [];
		}

		const entries = [];
		for (let i = 0; i < this._snapTargets.length; i++) {
			const target = this._snapTargets[i];
			const transform = this._getTargetWorldTransform(target);
			if (!transform?.position) continue;
			const distance = this._targetObject.getWorldPosition(this._tmp.v3).distanceTo(transform.position);
			if (distance <= maxDistance) {
				entries.push({
					target,
					id: getSnapTargetId(target, i),
					distance,
					inRange: distance <= this._options.placement.snapDistance,
					transform,
				});
			}
		}
		return entries;
	}

	_createPlaceholder(entry) {
		const factory = this._options.placeholders.createPlaceholder;
		const placeholder =
			typeof factory === 'function'
				? factory(this._targetObject, entry.target, entry)
				: this._createDefaultPlaceholder();

		if (!(placeholder instanceof THREE.Object3D)) return null;
		this._scene.add(placeholder);
		return placeholder;
	}

	_createDefaultPlaceholder() {
		const clone = this._targetObject.clone(true);
		clone.traverse((child) => {
			if (!child.material) return;
			if (Array.isArray(child.material)) {
				child.material = child.material.map((material) => this._clonePlaceholderMaterial(material));
			} else {
				child.material = this._clonePlaceholderMaterial(child.material);
			}
		});
		return clone;
	}

	_clonePlaceholderMaterial(material) {
		const placeholderMaterial = this._options.placeholders.material
			? this._options.placeholders.material.clone()
			: material.clone();
		placeholderMaterial.transparent = true;
		placeholderMaterial.opacity = this._options.placeholders.opacityRange[0];
		placeholderMaterial.depthWrite = false;
		return placeholderMaterial;
	}

	_getPlaceholderOpacity(distance) {
		const [minOpacity, maxOpacity] = this._options.placeholders.opacityRange;
		const maxDistance = Math.max(this._options.placeholders.maxVisibleDistance, 0.0001);
		const t = THREE.MathUtils.clamp(1 - distance / maxDistance, 0, 1);
		return THREE.MathUtils.lerp(minOpacity, maxOpacity, t);
	}

	_setPlaceholderOpacity(object, opacity) {
		object.traverse((child) => {
			if (!child.material) return;
			const materials = Array.isArray(child.material) ? child.material : [child.material];
			for (const material of materials) {
				material.transparent = true;
				material.opacity = opacity;
				material.needsUpdate = true;
			}
		});
	}

	_clearPlaceholders() {
		for (const [id, placeholder] of this._placeholders) {
			this._removePlaceholder(id, placeholder);
		}
	}

	_removePlaceholder(id, placeholder) {
		this._placeholders.delete(id);
		if (placeholder.parent) placeholder.parent.remove(placeholder);
		placeholder.traverse((child) => {
			if (!child.material) return;
			const materials = Array.isArray(child.material) ? child.material : [child.material];
			for (const material of materials) {
				material.dispose?.();
			}
		});
	}

	_getTargetWorldTransform(target) {
		if (target instanceof THREE.Object3D) {
			return this._captureWorldTransform(target);
		}

		if (target?.object instanceof THREE.Object3D) {
			return this._captureWorldTransform(target.object);
		}

		if (!target?.position) return null;

		const position = target.position.clone ? target.position.clone() : new THREE.Vector3().fromArray(target.position);
		const quaternion = target.quaternion
			? target.quaternion.clone()
			: target.rotation
				? new THREE.Quaternion().setFromEuler(target.rotation)
				: new THREE.Quaternion();
		const scale = target.scale
			? target.scale.clone
				? target.scale.clone()
				: new THREE.Vector3().fromArray(target.scale)
			: new THREE.Vector3(1, 1, 1);

		return {
			parent: target.parent || null,
			position,
			quaternion,
			scale,
		};
	}

	_buildSnapTransform(targetTransform) {
		const current = this._captureWorldTransform(this._targetObject);
		return {
			parent: targetTransform.parent || current.parent,
			position: targetTransform.position.clone(),
			quaternion: this._options.placement.snapRotation ? targetTransform.quaternion.clone() : current.quaternion,
			scale: this._options.placement.snapScale ? targetTransform.scale.clone() : current.scale,
		};
	}

	_captureWorldTransform(object) {
		object.updateMatrixWorld(true);
		return {
			parent: object.parent || null,
			position: object.getWorldPosition(new THREE.Vector3()),
			quaternion: object.getWorldQuaternion(new THREE.Quaternion()),
			scale: object.getWorldScale(new THREE.Vector3()),
		};
	}

	_cloneTransform(transform) {
		if (!transform) return null;
		return {
			parent: transform.parent || null,
			position: transform.position.clone(),
			quaternion: transform.quaternion.clone(),
			scale: transform.scale.clone(),
		};
	}

	_applyWorldTransform(transform) {
		this._applyWorldTransformToObject(this._targetObject, transform);
	}

	_applyWorldTransformToObject(object, transform) {
		if (!transform) return;

		const worldMatrix = new THREE.Matrix4().compose(transform.position, transform.quaternion, transform.scale);
		const parent = object.parent;

		if (parent) {
			parent.updateMatrixWorld(true);
			const localMatrix = new THREE.Matrix4().copy(parent.matrixWorld).invert().multiply(worldMatrix);
			localMatrix.decompose(object.position, object.quaternion, object.scale);
		} else {
			object.position.copy(transform.position);
			object.quaternion.copy(transform.quaternion);
			object.scale.copy(transform.scale);
		}

		object.updateMatrixWorld(true);
	}

	_moveObjectToScenePreservingWorldTransform() {
		const world = this._captureWorldTransform(this._targetObject);
		const parent = this._targetObject.parent;
		if (parent) parent.remove(this._targetObject);
		this._scene.add(this._targetObject);
		this._targetObject.position.copy(world.position);
		this._targetObject.quaternion.copy(world.quaternion);
		this._targetObject.scale.copy(world.scale);
	}

	/**
	 * Removes all internal event listeners from the ControllersManager.
	 * Call this when the grabbable object is removed from the scene.
	 */
	dispose() {
		this.cancelGrab();
		this._clearPlaceholders();
		this._animation = null;

		if (this._options.contactGrabbing.enabled || this._options.remoteGrabbing.enabled) {
			this._controllersManager.removeEventListener(CMEvents.ON_SQUEEZE_START, this._onSqueezeStart);
			this._controllersManager.removeEventListener(CMEvents.ON_SQUEEZE_END, this._onSqueezeEnd);
			this._controllersManager.removeEventListener(CMEvents.ON_UPDATE, this._onUpdate);
		}
	}
}

function mergeOptions(defaults, options = {}) {
	const result = { ...defaults, ...options };
	result.contactGrabbing = { ...defaults.contactGrabbing, ...options.contactGrabbing };
	result.remoteGrabbing = { ...defaults.remoteGrabbing, ...options.remoteGrabbing };
	result.follow = { ...defaults.follow, ...options.follow };
	result.releaseGesture = { ...defaults.releaseGesture, ...options.releaseGesture };
	result.placement = { ...defaults.placement, ...options.placement };
	result.placement.targets = Array.isArray(result.placement.targets) ? result.placement.targets.slice() : [];
	result.placeholders = { ...defaults.placeholders, ...options.placeholders };
	result.placeholders.opacityRange = Array.isArray(result.placeholders.opacityRange)
		? result.placeholders.opacityRange.slice()
		: defaults.placeholders.opacityRange.slice();
	return result;
}

function sameSnapTarget(a, b) {
	return (!a && !b) || (a && b && a.id === b.id);
}

function getSnapTargetId(target, index) {
	if (target instanceof THREE.Object3D) return target.uuid;
	if (target?.id !== undefined) return target.id;
	if (target?.object instanceof THREE.Object3D) return target.object.uuid;
	return index;
}

function wrapAngle(angle) {
	return Math.atan2(Math.sin(angle), Math.cos(angle));
}

function computeAngularVelocity(previousQuaternion, currentQuaternion, dt) {
	const delta = currentQuaternion.clone().multiply(previousQuaternion.clone().invert());
	if (delta.w > 1) delta.normalize();

	const angle = 2 * Math.acos(THREE.MathUtils.clamp(delta.w, -1, 1));
	const s = Math.sqrt(1 - delta.w * delta.w);
	if (s < 0.0001 || angle === 0) return new THREE.Vector3();

	return new THREE.Vector3(delta.x / s, delta.y / s, delta.z / s).multiplyScalar(angle / dt);
}
