﻿import * as THREE from 'three';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';
import { InteractiveVRObject } from './InteractiveVRObject.js';
import { ControllersManager } from './ControllersManager.js';

/**
 * @module VRInteractiveSurface
 * @description
 * Provides geometry-agnostic controller ray interaction for app-owned
 * UV-mapped meshes.
 */

/**
 * Pointer event types dispatched by {@link VRInteractiveSurface}.
 * The string values mirror the DOM-like names already used across the panel family.
 * @enum {string}
 */
export const EventTypes = {
	/** Trigger pressed while the ray hits the surface (approx. mousedown). */
	POINTER_DOWN: 'pointerdown',
	/** Ray moved while the trigger is held over the surface (approx. mousemove during drag). */
	POINTER_MOVE: 'pointermove',
	/** Trigger released while the ray hits the surface (approx. mouseup). */
	POINTER_UP: 'pointerup',
	/** Trigger released while the ray is NOT over the surface (approx. mouseup outside / cancel). */
	POINTER_UP_OUTSIDE: 'pointerupoutside',
};

/**
 * Default options for {@link VRInteractiveSurface}.
 * @typedef {object} VRInteractiveSurfaceOptions
 * @property {number} [debugLevel=0] - Forwarded to {@link InteractiveVRObject} (hit markers).
 * @property {boolean} [useBVH=false] - Forwarded to {@link InteractiveVRObject}: build a BVH and
 *   use accelerated raycasting. Recommended for dense / high-poly / curved surfaces.
 */
export const defaultOptions = {
	debugLevel: 0,
	useBVH: false,
};

/**
 * Geometry-agnostic interactive surface: attaches VR controller ray interaction to **any**
 * app-owned mesh and emits mouse-like pointer events carrying the **normalized UV coordinate**
 * (0..1) of the hit, so whatever renders the mesh texture (a 2D canvas, a curved screen,
 * an exotic shape) knows exactly where it was touched.
 *
 * It does NOT create geometry, textures, materials, visibility containers, or add anything to
 * the scene: the caller owns the mesh. It only needs a mesh whose geometry has a `uv` attribute.
 * For both faces to be hittable, the material should use `side: THREE.DoubleSide` (the raycaster
 * ignores back-faces otherwise).
 *
 * Use this class directly when the interactive surface is supplied by the application: curved
 * screens, domes, control consoles, mesh-mounted canvases, or any custom UV-mapped object.
 * Use {@link VRInteractivePanel} when the component should own a standard flat rectangular
 * panel, its materials, aspect-ratio fitting, and panel visibility semantics.
 *
 * Consume events either via {@link EventsDispatcher} listeners (the common case for new code) or
 * by subclassing and overriding {@link _onPointerEvent} (used internally by {@link VRInteractivePanel}).
 *
 * @example
 * const surface = new VRInteractiveSurface(myMesh, scene, controllersManager, { useBVH: true });
 * surface.addEventListener(EventTypes.POINTER_DOWN, (e) => {
 *   // e.uv: THREE.Vector2 in [0,1]; e.point: world-space hit; e.handedness: 'left' | 'right'
 *   drawCursor(e.uv.x * canvas.width, (1 - e.uv.y) * canvas.height);
 * });
 *
 * @extends EventsDispatcher
 */
export class VRInteractiveSurface extends EventsDispatcher {
	/**
	 * The mesh used for ray hit-testing, provided by the caller.
	 * @type {THREE.Mesh}
	 */
	_mesh;
	/** @type {InteractiveVRObject} */
	_interactive;
	/**
	 * Whether ray events are currently tested against this surface.
	 * @type {boolean}
	 */
	_enabled = true;

	/**
	 * @param {THREE.Mesh} mesh - Any mesh with a `uv` attribute to make interactive.
	 * @param {THREE.Group} worldContainer - Scene node used to host optional debug hit markers.
	 * @param {ControllersManager} controllersManager - Shared ControllersManager instance.
	 * @param {VRInteractiveSurfaceOptions} [options] - Options merged with {@link defaultOptions}.
	 */
	constructor(mesh, worldContainer, controllersManager, options = {}) {
		super();
		if (mesh === undefined || worldContainer === undefined || controllersManager === undefined) {
			throw Error('VRInteractiveSurface: Missing parameters');
		}
		this.options = { ...defaultOptions, ...options };
		this._mesh = mesh;

		this._interactive = new InteractiveVRObject(this, worldContainer, controllersManager, {
			debugLevel: this.options.debugLevel || 0,
			useBVH: this.options.useBVH || false,
		});
	}

	// --- InteractiveVRObject target contract ---

	/**
	 * @returns {THREE.Mesh} The mesh InteractiveVRObject raycasts against.
	 */
	getIntersectionMesh() {
		return this._mesh;
	}

	/**
	 * @returns {boolean} Whether controller rays should currently be tested against this surface.
	 */
	shouldTestRayEvents() {
		return this._enabled && this._mesh.visible;
	}

	/**
	 * @param {THREE.Intersection} intersection
	 * @param {'left'|'right'} [handedness]
	 */
	onRayStarted(intersection, handedness) {
		this._emitPointer(EventTypes.POINTER_DOWN, intersection, handedness);
	}

	/**
	 * @param {THREE.Intersection} intersection
	 * @param {'left'|'right'} [handedness]
	 */
	onRayUpdated(intersection, handedness) {
		this._emitPointer(EventTypes.POINTER_MOVE, intersection, handedness);
	}

	/**
	 * @param {THREE.Intersection|null} intersection
	 * @param {'left'|'right'} [handedness]
	 */
	onRayEnded(intersection, handedness) {
		if (intersection) {
			this._emitPointer(EventTypes.POINTER_UP, intersection, handedness);
		} else {
			this._emitPointer(EventTypes.POINTER_UP_OUTSIDE, null, handedness);
		}
	}

	// --- pointer event emission ---

	/**
	 * Builds a normalized pointer event and delivers it both to the {@link _onPointerEvent}
	 * template method (for subclass backends) and to {@link EventsDispatcher} listeners.
	 * @param {string} type - One of {@link EventTypes}.
	 * @param {THREE.Intersection|null} intersection
	 * @param {'left'|'right'} [handedness]
	 */
	_emitPointer(type, intersection, handedness) {
		const uv = this._buildPointerUV(intersection);
		const e = {
			type,
			uv, // THREE.Vector2 in [0,1], or undefined when there is no hit
			data: uv, // legacy alias consumed by VRInteractivePanel subclasses
			point: intersection ? intersection.point : null,
			handedness,
		};
		this._onPointerEvent(e);
		this.dispatchEvent(e);
	}

	/**
	 * Hook to transform the raw intersection UV before it is emitted. Default: the raw UV.
	 * {@link VRInteractivePanel} overrides it to apply its aspect-ratio remap.
	 * @param {THREE.Intersection|null} intersection
	 * @returns {THREE.Vector2|undefined}
	 */
	_buildPointerUV(intersection) {
		return intersection && intersection.uv ? intersection.uv.clone() : undefined;
	}

	/**
	 * Template method for subclasses that drive a UI backend (e.g. dispatching to a DOM element).
	 * Default is a no-op: external consumers should use `addEventListener(EventTypes.*)`.
	 * @param {object} e
	 * @param {string} e.type
	 * @param {THREE.Vector2} [e.uv]
	 * @param {THREE.Vector2} [e.data]
	 * @param {THREE.Vector3|null} e.point
	 * @param {string} [e.handedness]
	 */
	_onPointerEvent = (e) => {
		// no-op by default
	};

	// --- public API ---

	/**
	 * Enables or disables ray testing without changing mesh visibility.
	 * @param {boolean} enabled
	 */
	setEnabled(enabled) {
		this._enabled = enabled;
	}

	/**
	 * The interactive mesh.
	 * @type {THREE.Mesh}
	 */
	get mesh() {
		return this._mesh;
	}

	/**
	 * Refits the BVH after the geometry was deformed in place (same topology). No-op without BVH.
	 */
	refitBoundsTree() {
		this._interactive.refitBoundsTree();
	}

	/**
	 * Rebuilds the BVH from scratch (topology changed). No-op without BVH.
	 */
	rebuildBoundsTree() {
		this._interactive.rebuildBoundsTree();
	}

	/**
	 * Removes controller listeners and releases interaction resources.
	 */
	dispose() {
		this._interactive.dispose();
	}
}
