/**
 * @module HandController
 * @description
 * Low-level wrapper around one WebXR hand controller. Most applications should
 * use {@link ControllersManager}, which creates and coordinates two
 * `HandController` instances.
 */
import * as THREE from 'three';
import { XRControllerModelFactory } from 'three/addons/webxr/XRControllerModelFactory.js';

import { XRGamepadMonitor, EventTypes as MonitorEvents } from './XRGamepadMonitor.js';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';

// Moves only the visible line forward so it starts outside the controller shell.
// Increase this value if a controller model still covers the beginning of the line.
const CONTROLLER_RAY_VISUAL_START_OFFSET = 0.05;
// Quest target-ray poses point slightly inward relative to the visible controller shell.
// This mirrored offset recenters the beginning of the line on the controller face.
const CONTROLLER_RAY_VISUAL_START_HORIZONTAL_OFFSET = 0.02;

/**
 * Event type constants dispatched by {@link HandController}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when the controller is physically connected. */
	ON_CONNECTED: 'onConnected',
	/** Fired when the controller is physically disconnected. */
	ON_DISCONNECTED: 'onDisconnected',

	/** Fired when the trigger is pressed (select start). */
	ON_SELECT_START: 'onSelectStart',
	/** Fired when the trigger is released (select end). */
	ON_SELECT_END: 'onSelectEnd',

	/** Fired when the grip button is pressed. */
	ON_SQUEEZE_START: 'onSqueezeStart',
	/** Fired when the grip button is released. */
	ON_SQUEEZE_END: 'onSqueezeEnd',

	/** Fired when the trigger is pressed and a ray is cast. Event carries `{handedness, ray, stickPosition}`. */
	ON_RAY_STARTED: 'onRayStarted',
	/** Fired every frame while the trigger is held. Event carries `{handedness, ray, stickPosition}`. */
	ON_RAY_UPDATED: 'onRayUpdated',
	/** Fired when the trigger is released. Event carries `{handedness, ray, stickPosition}`. */
	ON_RAY_ENDED: 'onRayEnded',

	/** Fired when the thumbstick is flicked to the left (snap-rotate). */
	ON_ROTATE_LEFT: 'onRotateLeft',
	/** Fired when the thumbstick is flicked to the right (snap-rotate). */
	ON_ROTATE_RIGHT: 'onRotateRight',

	/** Fired when a mapped button is pressed. */
	ON_BUTTON_UP: 'onButtonUp',
	/** Fired when a mapped button is released. */
	ON_BUTTON_DOWN: 'onButtonDown',

	/** Fired when the thumbstick Y axis crosses the forward threshold (down). */
	ON_AXIS_FORWARD_DOWN: 'onAxisForwardDown',
	/** Fired when the thumbstick Y axis crosses the forward threshold (up). */
	ON_AXIS_FORWARD_UP: 'onAxisForwardUp',

	/** Fired every frame while the thumbstick Y axis is non-zero. Event carries `{handedness, ray, stickPosition, deltaTime}`. */
	ON_AXIS_Y_NOT_ZERO: 'onAxisYNotZero',

	/** Fired when the thumbstick is pushed forward past the click threshold. */
	ON_AXIS_FORWARD_CLICK: 'onAxisFowardClick',
	/** Fired when the thumbstick is pushed backward past the click threshold. */
	ON_AXIS_BACKWARD_CLICK: 'onAxisBackwardClick',

	/** Fired when the thumbstick is pushed left past the click threshold. */
	ON_AXIS_LEFT_CLICK: 'onAxisLeftClick',
	/** Fired when the thumbstick is pushed right past the click threshold. */
	ON_AXIS_RIGHT_CLICK: 'onAxisRightClick',
	ON_AXIS_X_CONTINUOUS_START: 'onAxisXContinuousStart',
	ON_AXIS_X_CONTINUOUS_UPDATE: 'onAxisXContinuousUpdate',
	ON_AXIS_X_CONTINUOUS_END: 'onAxisXContinuousEnd',
};

/**
 * Represents a single VR hand controller. Wraps the underlying
 * `THREE.XRTargetRaySpace` and `XRGamepadMonitor` to expose a unified event
 * API and helper methods for attachment, haptics, and ray casting.
 *
 * Instances are created internally by {@link ControllersManager} — do not
 * instantiate directly.
 *
 * @extends EventsDispatcher
 *
 * @example
 * // Usually created by ControllersManager:
 * const controllers = new ControllersManager(renderer.xr, scene);
 * const rightHand = controllers.right;
 *
 * rightHand?.addEventListener(EventTypes.ON_RAY_STARTED, ({ ray }) => {
 *   console.log(ray.origin, ray.direction);
 * });
 */
export class HandController extends EventsDispatcher {
	/** Which hand this controller is assigned to once connected. @type {'left'|'right'|undefined} */
	handedness;
	/** Index used by `renderer.xr.getController(index)` — either `0` or `1`. @type {number} */
	index;
	/** `true` once the controller has fired a `connected` event. @type {boolean} */
	connected;
	/** `true` when this controller is the dominant (skilled) hand. @type {boolean} */
	skilled = false;

	/** @type {THREE.WebXRManager} */
	xr;
	/** @type {THREE.Group} */
	parentContainer;
	/** Gamepad input monitor — available after the controller connects. @type {XRGamepadMonitor} */
	monitor;

	/** The underlying Three.js target-ray space object. @type {THREE.XRTargetRaySpace} */
	controller;
	/** Raw XR gamepad object — available after the controller connects. @type {Gamepad} */
	gamepad;
	/** Raw XR input source — available after the controller connects. @type {XRInputSource} */
	inputSource;

	triggerIsDown = false;
	time = 0;

	holdingPoint = new THREE.Object3D();
	/** The grip group that carries the controller model. @type {THREE.Group} */
	grip;
	/** Controller model returned by XRControllerModelFactory. @type {THREE.Object3D} */
	controllerModel;
	/** Current ray cast from the controller muzzle in world space. @type {THREE.Ray} */
	controllerRay;
	lastControllerRay;

	vrMenuMesh;

	clock = new THREE.Clock();
	raycaster;
	/** `true` while the grip button is held. @type {boolean} */
	isSqueezing = false;

	attachedObject = null;
	attachedObjectParent = null;

	/**
	 * @param {THREE.WebXRManager} xr - The WebXR manager from `renderer.xr`.
	 * @param {THREE.Group} parentContainer - Scene node that this controller is added to.
	 * @private
	 */
	constructor(xr, parentContainer) {
		super();
		this.xr = xr;
		this.parentContainer = parentContainer;
		this.clock.start();
		this.raycaster = new THREE.Raycaster();
	}

	/**
	 * A clone of the current controller ray in world space.
	 * @type {THREE.Ray}
	 */
	get ray() {
		return this.controllerRay.clone();
	}

	set vrMenuMesh(m) {
		this.vrMenuMesh = m;
	}

	get isSqueeing() {
		return this.isSqueezing;
	}

	// public methods

	/**
	 * Initialises the controller at the given index. Called automatically by
	 * {@link ControllersManager} — you do not need to call this manually.
	 * @param {number} index - Controller index (`0` or `1`).
	 */
	setup(index) {
		this.index = index;
		this.controller = this.xr.getController(index);

		// handle internal events
		this.controller.addEventListener('connected', this._onConnected.bind(this));
		this.controller.addEventListener('disconnected', this._onDisconnected.bind(this));

		this.controller.addEventListener('selectstart', this._onSelectStart.bind(this));
		this.controller.addEventListener('selectend', this._onSelectEnd.bind(this));

		this.controller.addEventListener('squeezestart', this._onSqueezeStart.bind(this));
		this.controller.addEventListener('squeezeend', this._onSqueezeEnd.bind(this));

		this.parentContainer.add(this.controller);

		// export basic events
		this._exportEvent(this.controller, EventTypes.ON_CONNECTED, 'connected');
		this._exportEvent(this.controller, EventTypes.ON_DISCONNECTED, 'disconnected');

		this._exportEvent(this.controller, EventTypes.ON_SELECT_START, 'selectstart');
		this._exportEvent(this.controller, EventTypes.ON_SELECT_END, 'selectend');

		this._exportEvent(this.controller, EventTypes.ON_SQUEEZE_START, 'squeezestart');
		this._exportEvent(this.controller, EventTypes.ON_SQUEEZE_END, 'squeezeend');

		// The XRControllerModelFactory will automatically fetch controller models that match what the user is holding as closely as possible
		const controllerModelFactory = new XRControllerModelFactory();
		this.grip = this.xr.getControllerGrip(index);
		this.grip.name = `grip${index}`;
		this.controllerModel = controllerModelFactory.createControllerModel(this.grip);
		this.grip.add(this.controllerModel);
		this.grip.add(this.holdingPoint);

		this.parentContainer.add(this.grip);
	}

	/**
	 * Returns the grip group that the controller model is attached to.
	 * You can use this to attach scene objects to the controller's hand.
	 * @returns {THREE.Group}
	 */
	getGrip() {
		return this.grip;
	}

	/**
	 * Returns the controller model created by Three.js.
	 * @returns {THREE.Object3D}
	 */
	getControllerModel() {
		return this.controllerModel;
	}

	/**
	 * Returns `true` if the given button is currently pressed.
	 * Delegates to the underlying {@link XRGamepadMonitor}.
	 * @param {string} button - Button identifier as defined in XRGamepadMonitor.
	 * @returns {boolean}
	 */
	isDown(button) {
		return this.monitor.isDown(button);
	}

	/**
	 * Returns the analog value (0–1) of the given button.
	 * Delegates to the underlying {@link XRGamepadMonitor}.
	 * @param {string} button - Button identifier as defined in XRGamepadMonitor.
	 * @returns {number}
	 */
	getButtonValue(button) {
		return this.monitor.getButtonValue(button);
	}

	/**
	 * Must be called every animation frame. Updates the controller ray,
	 * polls the gamepad monitor, and dispatches axis/ray events.
	 * @param {number} time - Elapsed time in seconds since session start.
	 * @param {number} [deltaTime=0] - Time in seconds since the last frame.
	 */
	update(time, deltaTime = 0) {
		this.time += deltaTime;
		if (!this.monitor) return;

		this._updateControllerRay();
		let stickPosition = this.monitor.getStickPosition();
		this.monitor.update(deltaTime);

		if (this.triggerIsDown) {
			this.dispatchEvent({
				type: EventTypes.ON_RAY_UPDATED,
				handedness: this.handedness,
				ray: this.controllerRay.clone(),
				stickPosition: stickPosition.clone(),
			});
		}

		this._checkAndDispatchAxisYNonZeroEvent(deltaTime);
	}

	/**
	 * Attaches a scene object to the controller's holding point so it follows
	 * the hand during movement.
	 * @param {THREE.Object3D} object - The object to attach.
	 */
	attachObject(object) {
		this.attachedObject = object;
		this.attachedObjectParent = object.parent;
		this.holdingPoint.attach(object);
	}

	/**
	 * Detaches the currently held object and restores it to its original parent.
	 */
	detachObject() {
		// restore the object to its original parent
		if (this.attachedObject && this.attachedObjectParent) this.attachedObjectParent.attach(this.attachedObject);
		this.attachedObject = null;
	}

	/**
	 * Triggers haptic vibration on this controller.
	 * @param {number} intensity - Vibration strength from `0` (off) to `1` (maximum).
	 * @param {number} millis - Duration of the vibration in milliseconds.
	 */
	pulse(intensity, millis) {
		this.gamepad.hapticActuators?.[0].pulse(intensity, millis);
	}

	// private methods
	_exportEvent(origin, externalType, internalType) {
		this._updateControllerRay();
		origin.addEventListener(internalType, (xrEvent) => {
			const e = { ...xrEvent };
			e.internalType = e.type;
			e.type = externalType;
			e.handedness = this.handedness;
			e.ray = this.controllerRay.clone();
			this.dispatchEvent(e);
		});
	}

	_onSqueezeStart(event) {
		this.isSqueezing = true;
	}

	_onSqueezeEnd(event) {
		this.isSqueezing = false;
	}

	_onSelectStart(event) {
		if (this.triggerIsDown) return;
		this.triggerIsDown = true;
		let stickPosition = this.monitor.getStickPosition();

		this._updateControllerRay();

		this.dispatchEvent({
			type: EventTypes.ON_RAY_STARTED,
			handedness: this.handedness,
			ray: this.controllerRay.clone(),
			stickPosition: stickPosition.clone(),
		});

		this.monitor.restartHoldingTimer();
	}

	_onSelectEnd(event) {
		if (!this.triggerIsDown) return;
		this.triggerIsDown = false;

		let stickPosition = this.monitor.getStickPosition();

		this._updateControllerRay();

		this.dispatchEvent({
			type: EventTypes.ON_RAY_ENDED,
			handedness: this.handedness,
			ray: this.controllerRay.clone(),
			stickPosition: stickPosition.clone(),
		});

		this.monitor.restartHoldingTimer();
	}

	_onConnected(event) {
		this.connected = true;
		this.inputSource = event.data;
		this.handedness = event.data.handedness;
		this.gamepad = event.data.gamepad;

		this.monitor = new XRGamepadMonitor(this.xr, this.handedness);

		this._exportEvent(this.monitor, EventTypes.ON_BUTTON_DOWN, MonitorEvents.ON_BUTTON_DOWN);
		this._exportEvent(this.monitor, EventTypes.ON_BUTTON_UP, MonitorEvents.ON_BUTTON_UP);

		this._exportEvent(this.monitor, EventTypes.ON_BUTTON_UP, MonitorEvents.ON_AXIS_FORWARD_DOWN);
		this._exportEvent(this.monitor, EventTypes.ON_BUTTON_UP, MonitorEvents.ON_AXIS_FORWARD_UP);

		this._exportEvent(this.monitor, EventTypes.ON_AXIS_FORWARD_CLICK, MonitorEvents.ON_AXIS_FORWARD_CLICK);
		this._exportEvent(this.monitor, EventTypes.ON_AXIS_BACKWARD_CLICK, MonitorEvents.ON_AXIS_BACKWARD_CLICK);
		this._exportEvent(this.monitor, EventTypes.ON_AXIS_LEFT_CLICK, MonitorEvents.ON_AXIS_LEFT_CLICK);
		this._exportEvent(this.monitor, EventTypes.ON_AXIS_RIGHT_CLICK, MonitorEvents.ON_AXIS_RIGHT_CLICK);
		this._exportEvent(
			this.monitor,
			EventTypes.ON_AXIS_X_CONTINUOUS_START,
			MonitorEvents.ON_AXIS_X_CONTINUOUS_START
		);
		this._exportEvent(
			this.monitor,
			EventTypes.ON_AXIS_X_CONTINUOUS_UPDATE,
			MonitorEvents.ON_AXIS_X_CONTINUOUS_UPDATE
		);
		this._exportEvent(this.monitor, EventTypes.ON_AXIS_X_CONTINUOUS_END, MonitorEvents.ON_AXIS_X_CONTINUOUS_END);

		this.monitor.addEventListener(MonitorEvents.ON_AXIS_X_HOLDED, (event) => {
			if (event.value > 0) {
				this.dispatchEvent({
					type: EventTypes.ON_ROTATE_RIGHT,
					handedness: this.handedness,
				});
			} else {
				this.dispatchEvent({
					type: EventTypes.ON_ROTATE_LEFT,
					handedness: this.handedness,
				});
			}
		});

		this.controller.add(this._buildController(event.data));
	}

	_onDisconnected(event) {
		this.controller.remove(this.controller.children[0]);
		this.connected = false;
		this.inputSource = null;
		this.gamepad = null;
		this.monitor = null;
	}

	_updateControllerRay() {
		const mat = new THREE.Matrix4();

		this.lastControllerRay = this.controllerRay?.clone();

		mat.identity().extractRotation(this.controller.matrixWorld);

		const origin = new THREE.Vector3().setFromMatrixPosition(this.controller.matrixWorld);
		const direction = new THREE.Vector3().set(0, 0, -1).applyMatrix4(mat);

		this.controllerRay = new THREE.Ray(origin, direction);
	}

	_buildController(data) {
		let geometry, material;

		// See WebXR > Concepts > Targeting categories
		// https://immersive-web.github.io/webxr/input-explainer.html#concepts
		switch (data.targetRayMode) {
			// Pointers can be tracked separately from the viewer (e.g. Cculus touch controllers)
			case 'tracked-pointer': {
				const horizontalStartOffset =
					this.handedness === 'left'
						? -CONTROLLER_RAY_VISUAL_START_HORIZONTAL_OFFSET
						: CONTROLLER_RAY_VISUAL_START_HORIZONTAL_OFFSET;

				geometry = new THREE.BufferGeometry();
				geometry.setAttribute(
					'position',
					new THREE.Float32BufferAttribute(
						[horizontalStartOffset, 0, -CONTROLLER_RAY_VISUAL_START_OFFSET, 0, 0, -1],
						3
					)
				);
				geometry.setAttribute('color', new THREE.Float32BufferAttribute([0.5, 0.5, 0.5, 0, 0, 0], 3));

				material = new THREE.LineBasicMaterial({
					vertexColors: true,
					blending: THREE.AdditiveBlending,
					depthWrite: false,
					transparent: true,
				});

				return new THREE.Line(geometry, material);
			}

			// Gaze-based input sources do not have their own tracking mechanism and instead use the viewer's head position for targeting.
			case 'gaze':
				geometry = new THREE.RingGeometry(0.02, 0.04, 32).translate(0, 0, -1);
				material = new THREE.MeshBasicMaterial({
					opacity: 0.5,
					transparent: true,
					depthWrite: false,
				});
				return new THREE.Mesh(geometry, material);
		}
	}

	_checkAndDispatchAxisYNonZeroEvent(deltaTime) {
		if (!this.monitor) return;
		let pos = this.monitor.getStickPosition();
		if (Math.abs(pos.y) > 0 && !this.monitor.xIsAboveHoldThreshold()) {
			// this is used to translate the user on every frame
			this.dispatchEvent({
				type: EventTypes.ON_AXIS_Y_NOT_ZERO,
				handedness: this.handedness,
				ray: this.controllerRay.clone(),
				stickPosition: pos,
				deltaTime: deltaTime,
			});
		}
	}
}
