import * as THREE from 'three';
import { ControllersManager, EventTypes as CMEventTypes } from './ControllersManager.js';
import { computeBoundsTree, disposeBoundsTree, acceleratedRaycast } from 'three-mesh-bvh';

/**
 * Default options for {@link InteractiveVRObject}.
 * @typedef {object} InteractiveVRObjectOptions
 * @property {number} [debugLevel=0] - When greater than zero, render hit markers for each hand.
 * @property {boolean} [useBVH=false] - When true, build a BVH (three-mesh-bvh) over the hit-test
 *   mesh geometry and use accelerated raycasting with `firstHitOnly`. Recommended for dense or
 *   high-poly interactive surfaces. When false, the standard `THREE.Raycaster` is used.
 */
export const defaultOptions = {
	debugLevel: 0,
	useBVH: false,
};

/**
 * This class connects a 3D object to VR controller ray events, enabling interactive behaviors
 * such as hover, click, and drag in a WebXR environment. It listens for ray events from a
 * ControllersManager, performs hit testing using a raycaster, and calls the target object's
 * interaction methods (onRayStarted, onRayUpdated, onRayEnded) when appropriate. Optional
 * debug markers visualize intersection points for each controller hand.
 */

export class InteractiveVRObject {
	_raycaster; // raycaster used for hit testing
	_hitTestMesh; // mesh used for hit testing
	_lastRayStartedOnHand; // hand that started the ray
	_options; // options
	_leftHitMarker; // left hit marker
	_rightHitMarker; // right hit marker
	_targetObject; // target object
	_debugMarkersEnabled; // cached: whether debug hit markers are rendered
	_ownsBoundsTree; // whether this instance built the BVH on the hit-test geometry

	/**
	 * @param {object} targetObject - Object implementing `onRayStarted`, `onRayEnded`, `getIntersectionMesh`, and `shouldTestRayEvents`.
	 * @param {THREE.Group} worldContainer - Scene node used to host optional debug hit markers.
	 * @param {ControllersManager} controllersManager - Shared ControllersManager instance.
	 * @param {InteractiveVRObjectOptions} [options] - Optional behavior flags.
	 */
	constructor(targetObject, worldContainer, controllersManager, options) {
		this.options = { ...defaultOptions, ...options };
		if (worldContainer === undefined || controllersManager === undefined || targetObject === undefined) {
			throw Error('InteractiveVRObject: Missing parameters');
		}

		// if targetObject does not implement the required methods, throw an error
		if (typeof targetObject.onRayStarted !== 'function' || typeof targetObject.onRayEnded !== 'function') {
			throw Error('InteractiveVRObject: targetObject does not implement the required methods');
		}

		if (targetObject?.getIntersectionMesh() != undefined) {
			this._hitTestMesh = targetObject.getIntersectionMesh();
		} else {
			throw Error('InteractiveVRObject: targetObject does not implement the getIntersectionMesh method');
		}

		this._targetObject = targetObject;
		this._controllersManager = controllersManager;
		this._worldContainer = worldContainer;
		this._controllersManager = controllersManager;
		this._raycaster = new THREE.Raycaster();

		this._debugMarkersEnabled = this.options.debugLevel > 0;

		// Optionally accelerate raycasting with a BVH (three-mesh-bvh). The tree lives in the
		// geometry's local space, so it stays valid while the mesh moves/rotates/scales rigidly;
		// only deforming geometry needs refitBoundsTree()/rebuildBoundsTree().
		this._ownsBoundsTree = false;
		if (this.options.useBVH) {
			this._enableBVH();
		}

		// create hit markers
		if (this.options.debugLevel > 0) {
			const markerGeo = new THREE.SphereGeometry(0.01, 16, 8);
			this._leftHitMarker = new THREE.Mesh(markerGeo, new THREE.MeshBasicMaterial({ color: 0xff0000 }));
			this._rightHitMarker = new THREE.Mesh(markerGeo, new THREE.MeshBasicMaterial({ color: 0x00ff00 }));
			//this._leftHitMarker.visible = false;
			//this._rightHitMarker.visible = false;

			this._worldContainer.add(this._leftHitMarker);
			this._worldContainer.add(this._rightHitMarker);
		}

		this._setupEventListeners();
	}

	/**
	 * Registers controller ray listeners and binds them to this wrapper instance.
	 */
	_setupEventListeners() {
		const events = [
			{ type: CMEventTypes.ON_RAY_STARTED, handler: '_onRayStarted' },
			{ type: CMEventTypes.ON_RAY_UPDATED, handler: '_onRayUpdated' },
			{ type: CMEventTypes.ON_RAY_ENDED, handler: '_onRayEnded' },
		];

		this.boundedHandlers = {};
		events.forEach((event) => {
			this.boundedHandlers[event.handler] = this[event.handler].bind(this);
			this._controllersManager.addEventListener(
				event.type,
				this.boundedHandlers[event.handler]
				//this._targetObject[event.handler].bind(this._targetObject)
			);
		});
	}

	/**
	 * Handles a controller ray start event and forwards it to the target when
	 * the ray intersects the target mesh.
	 * @param {object} e - Controller ray event.
	 * @returns {boolean} Whether other listeners should continue receiving the event.
	 */
	_onRayStarted(e) {
		if (!this._targetObject.shouldTestRayEvents()) return true;

		let allowEventPropagation = true;
		let intersection = this._getRayIntersection(e.ray);
		if (intersection && !this._lastRayStartedOnHand) {
			// store the hand that started the ray or the "mouse down"
			this._lastRayStartedOnHand = e.handedness;
			allowEventPropagation = false;
			if (this._targetObject.onRayStarted) this._targetObject.onRayStarted(intersection, e.handedness);
		}
		return allowEventPropagation;
	}

	/**
	 * Handles a controller ray move/update event while a ray interaction is active.
	 * @param {object} e - Controller ray event.
	 * @returns {boolean} Whether other listeners should continue receiving the event.
	 */
	_onRayUpdated(e) {
		if (!this._targetObject.shouldTestRayEvents()) return true;

		// ON_RAY_UPDATED is broadcast to every InteractiveVRObject while any trigger is held.
		// Only the object that owns the active gesture (or debug markers) needs a raycast, so
		// skip the per-frame hit test for everyone else.
		const isActiveHand = this._lastRayStartedOnHand === e.handedness;
		if (!isActiveHand && !this._debugMarkersEnabled) return true;

		let allowEventPropagation = true;

		let intersection = this._getRayIntersection(e.ray);
		if (intersection && isActiveHand) {
			// the ray hand is the same that started the ray (the "mouse down"),
			// so update the mouse position
			allowEventPropagation = false;
			if (this._targetObject.onRayUpdated) this._targetObject.onRayUpdated(intersection, e.handedness);
		}

		this._updateMarkers(e, intersection);
		return allowEventPropagation;
	}

	/**
	 * Updates optional debug markers for the active hand and intersection point.
	 * @param {object} e - Controller ray event.
	 * @param {THREE.Intersection|null} intersection - Current hit result, if any.
	 */
	_updateMarkers(e, intersection) {
		if (!this._leftHitMarker || !this._rightHitMarker) return;

		let marker = e.handedness == 'left' ? this._leftHitMarker : this._rightHitMarker;
		if (intersection) {
			// update marker position and visibility, corresponding to the hand
			let d = e.ray.origin.distanceTo(intersection.point);
			let s = 1 + d * 0.5;

			marker.position.copy(intersection.point);
			marker.scale.set(s, s, s);
			marker.visible = true;
		} else {
			marker.visible = false;
		}
	}

	/**
	 * Handles a controller ray end event and forwards pointer-up semantics to the target.
	 * @param {object} e - Controller ray event.
	 * @returns {boolean} Whether other listeners should continue receiving the event.
	 */
	_onRayEnded(e) {
		if (!this._targetObject.shouldTestRayEvents()) return true;

		// The "mouse up" only matters to the hand that started the gesture; other objects can
		// skip the hit test (debug markers still need it to be hidden/updated).
		const isActiveHand = this._lastRayStartedOnHand === e.handedness;
		if (!isActiveHand && !this._debugMarkersEnabled) return true;

		let allowEventPropagation = true;

		let intersection = this._getRayIntersection(e.ray);
		// Only trigger mouse up if the hand that started the ray is the same that ended it
		if (isActiveHand) {
			// only trigger mouse up if the ray is over the menu

			if (this._targetObject.onRayEnded) this._targetObject.onRayEnded(intersection, e.handedness);

			// clear the last ray started hand
			this._lastRayStartedOnHand = null;
			allowEventPropagation = false;
		}

		this._updateMarkers(e, intersection);

		return allowEventPropagation;
	}

	/**
	 * Raycasts against the target object's intersection mesh.
	 * @param {THREE.Ray} ray - Controller ray in world space.
	 * @returns {THREE.Intersection|null}
	 */
	_getRayIntersection(ray) {
		if (this._hitTestMesh && ray) {
			this._raycaster.ray = ray;
			const intersection = this._raycaster.intersectObject(this._hitTestMesh, false)?.[0];
			if (intersection) {
				return intersection;
			}
		}
		return null;
	}

	/**
	 * Builds a BVH on the hit-test geometry and switches the mesh to accelerated raycasting.
	 * Idempotent: if the geometry already has a `boundsTree` (e.g. the caller built it), it is
	 * reused and not rebuilt.
	 */
	_enableBVH() {
		const geometry = this._hitTestMesh?.geometry;
		if (!geometry) return;

		if (!geometry.boundsTree) {
			geometry.computeBoundsTree = computeBoundsTree.bind(geometry);
			geometry.disposeBoundsTree = disposeBoundsTree.bind(geometry);
			geometry.computeBoundsTree();
			this._ownsBoundsTree = true;
		}

		this._hitTestMesh.raycast = acceleratedRaycast.bind(this._hitTestMesh);
		this._raycaster.firstHitOnly = true;
	}

	/**
	 * Refits the BVH after the hit-test geometry has been deformed in place (same topology).
	 * Cheap relative to a full rebuild. No-op when BVH is not in use.
	 */
	refitBoundsTree() {
		this._hitTestMesh?.geometry?.boundsTree?.refit();
	}

	/**
	 * Rebuilds the BVH from scratch. Use when the geometry topology changed (vertex/index count).
	 * No-op when BVH is not in use.
	 */
	rebuildBoundsTree() {
		const geometry = this._hitTestMesh?.geometry;
		if (!geometry?.computeBoundsTree) return;
		geometry.disposeBoundsTree?.();
		geometry.computeBoundsTree();
	}

	/**
	 * Removes controller event listeners and disposes optional debug markers.
	 */
	dispose() {
		// Remove event listeners
		const events = [
			{ type: CMEventTypes.ON_RAY_STARTED, handler: '_onRayStarted' },
			{ type: CMEventTypes.ON_RAY_UPDATED, handler: '_onRayUpdated' },
			{ type: CMEventTypes.ON_RAY_ENDED, handler: '_onRayEnded' },
		];
		events.forEach((event) => {
			this._controllersManager.removeEventListener(event.type, this.boundedHandlers[event.handler]);
		});

		// Dispose the BVH only if this instance built it (do not touch a caller-owned tree)
		if (this._ownsBoundsTree) {
			this._hitTestMesh?.geometry?.disposeBoundsTree?.();
			this._ownsBoundsTree = false;
		}

		// Remove and dispose hit markers
		[this._leftHitMarker, this._rightHitMarker].forEach((marker) => {
			if (marker) {
				this._worldContainer.remove(marker);
				if (marker.geometry) marker.geometry.dispose();
				if (marker.material) marker.material.dispose();
			}
		});
	}
}
