import { SNAPSHOT_LIMITS, snapshotDebugValue, snapshotDebugValues } from './DebugValueSnapshot.js';

export { SNAPSHOT_LIMITS } from './DebugValueSnapshot.js';

const LEVELS = ['log', 'info', 'warn', 'error', 'debug', 'trace'];

const COLORS = {
	log: '#202124',
	info: '#174ea6',
	warn: '#7a4d00',
	error: '#b3261e',
	debug: '#5f6368',
	trace: '#6f5685',
};

const SAFE_STYLE_PROPERTIES = new Set([
	'color',
	'background-color',
	'font-weight',
	'font-style',
	'text-decoration',
]);

/** Creates a detached, getter-safe snapshot of a console argument. */
export function snapshotConsoleValue(value, limits = {}) {
	return snapshotDebugValue(value, limits);
}

function snapshotArguments(args, limits) {
	return snapshotDebugValues(args, limits);
}

function parseSafeStyle(cssText) {
	const style = {};
	if (typeof cssText !== 'string') return style;
	for (const declaration of cssText.split(';')) {
		const colon = declaration.indexOf(':');
		if (colon < 0) continue;
		const property = declaration.slice(0, colon).trim().toLowerCase();
		const value = declaration.slice(colon + 1).trim();
		if (!SAFE_STYLE_PROPERTIES.has(property) || !value) continue;
		if (property === 'color') style.color = value;
		else if (property === 'background-color') style.backgroundColor = value;
		else if (property === 'font-weight') style.fontWeight = value;
		else if (property === 'font-style') style.fontStyle = value;
		else if (property === 'text-decoration') style.textDecoration = value;
	}
	return style;
}

function previewText(node) {
	if (node.properties) {
		const braces = node.type === 'array' || node.type === 'typedarray' || node.type === 'set' ? '[]' : '{}';
		return `${node.label || node.type} ${braces}`;
	}
	const text = nodeText(node, node.type === 'string');
	return text.length > 48 ? `${text.slice(0, 47)}…` : text;
}

function nodeText(node, quoteStrings = false) {
	if (node.type === 'string') return quoteStrings ? JSON.stringify(node.text) : node.text;
	if (node.type === 'date' || node.type === 'regexp') return node.label;
	if (node.properties) {
		const shown = node.properties.slice(0, 3).map((property) => {
			if (node.type === 'array' || node.type === 'set') return previewText(property.value);
			return `${property.key}: ${previewText(property.value)}`;
		});
		const more = node.truncated || node.properties.length > shown.length ? '…' : '';
		const content = [...shown, ...(more ? [more] : [])].join(', ');
		const braces = node.type === 'array' || node.type === 'typedarray' || node.type === 'set' ? ['[', ']'] : ['{', '}'];
		return `${node.label || node.type} ${braces[0]}${content}${braces[1]}`;
	}
	return node.text ?? node.label ?? '';
}

function numericDirective(node, integer) {
	const value = Number(node.type === 'string' ? node.text : node.text);
	if (integer) return String(Number.isNaN(value) ? NaN : Math.trunc(value));
	return String(value);
}

/** Formats snapshots using the common browser-console substitution directives. */
export function formatConsoleArguments(args, limits = {}) {
	const nodes = snapshotArguments(args, limits);
	const runs = [];
	let argIndex = 0;
	let activeStyle = {};

	if (typeof args[0] === 'string') {
		const format = args[0];
		argIndex = 1;
		let buffer = '';
		const flush = () => {
			if (buffer) runs.push({ text: buffer, style: { ...activeStyle } });
			buffer = '';
		};

		for (let i = 0; i < format.length; i++) {
			if (format[i] !== '%' || i + 1 >= format.length) {
				buffer += format[i];
				continue;
			}
			const directive = format[i + 1];
			if (directive === '%') {
				buffer += '%';
				i++;
				continue;
			}
			if (!'sdifoOc'.includes(directive) || argIndex >= nodes.length) {
				buffer += format[i];
				continue;
			}
			flush();
			const node = nodes[argIndex];
			const raw = args[argIndex++];
			if (directive === 'c') activeStyle = parseSafeStyle(typeof raw === 'string' ? raw : '');
			else if (directive === 'o' || directive === 'O') runs.push({ node, style: { ...activeStyle } });
			else if (directive === 'd' || directive === 'f') runs.push({ text: numericDirective(node, false), style: { ...activeStyle } });
			else if (directive === 'i') runs.push({ text: numericDirective(node, true), style: { ...activeStyle } });
			else runs.push({ text: nodeText(node), style: { ...activeStyle } });
			i++;
		}
		flush();
	}

	for (; argIndex < nodes.length; argIndex++) {
		if (runs.length) runs.push({ text: ' ', style: {} });
		const node = nodes[argIndex];
		if (node.properties) runs.push({ node, style: {} });
		else runs.push({ text: nodeText(node), style: {} });
	}
	return { runs, nodes };
}

function fontForStyle(style, baseFont) {
	const fontStyle = style?.fontStyle === 'italic' ? 'italic ' : '';
	const fontWeight = style?.fontWeight === 'bold' || Number(style?.fontWeight) >= 600 ? 'bold ' : '';
	return `${fontStyle}${fontWeight}${baseFont}`;
}

function splitTextToFit(ctx, text, maxWidth, style, baseFont) {
	ctx.font = fontForStyle(style, baseFont);
	const parts = String(text).split(/(\n|\s+)/);
	const chunks = [];
	for (const part of parts) {
		if (part === '') continue;
		if (part === '\n') {
			chunks.push({ text: '', newline: true });
			continue;
		}
		if (ctx.measureText(part).width <= maxWidth) {
			chunks.push({ text: part });
			continue;
		}
		let current = '';
		for (const char of part) {
			if (current && ctx.measureText(current + char).width > maxWidth) {
				chunks.push({ text: current });
				current = char;
			} else current += char;
		}
		if (current) chunks.push({ text: current });
	}
	return chunks;
}

/** Canvas renderer and interaction model used by VRConsole. */
export class VRConsoleRenderer {
	constructor(options = {}) {
		this.options = options;
		this.width = options.width || 800;
		this.height = options.height || 500;
		this.maxEntries = Math.max(1, options.maxEntries || 500);
		this.canvas = options.canvas || document.createElement('canvas');
		this.canvas.width = this.width;
		this.canvas.height = this.height;
		this.context = this.canvas.getContext('2d');
		this.entries = [];
		this.levelVisibility = Object.fromEntries(LEVELS.map((level) => [level, true]));
		this.autoFollow = options.autoFollow !== false;
		this.scrollTop = 0;
		this.expanded = new Set();
		this.hitZones = [];
		this.nextEntryId = 1;
		this.contentHeight = 0;
		this.onRender = null;
		this.pointer = null;
		this.font = '13px monospace';
		this.lineHeight = 18;
		this.toolbarHeight = 38;
		this.render();
	}

	add(type, args, source = 'console', metadata = {}) {
		if (type === 'clear') {
			this.clear();
			return;
		}
		const formatted = formatConsoleArguments(args, SNAPSHOT_LIMITS);
		if (type === 'trace') {
			const stack = metadata.stack?.split('\n').slice(2).join('\n');
			if (stack) formatted.runs.push({ text: `${formatted.runs.length ? '\n' : ''}${stack}`, style: {} });
		}
		this.entries.push({ id: this.nextEntryId++, type, source, runs: formatted.runs });
		if (this.entries.length > this.maxEntries) {
			const removed = this.entries.splice(0, this.entries.length - this.maxEntries);
			for (const entry of removed) {
				for (const key of [...this.expanded]) if (key.startsWith(`${entry.id}:`)) this.expanded.delete(key);
			}
		}
		this.render(this.autoFollow);
	}

	clear() {
		this.entries.length = 0;
		this.expanded.clear();
		this.scrollTop = 0;
		this.render();
	}

	setLevelVisible(level, visible) {
		if (!LEVELS.includes(level)) throw new RangeError(`Unknown VRConsole level: ${level}`);
		this.levelVisibility[level] = Boolean(visible);
		this.render();
	}

	setAutoFollow(enabled) {
		this.autoFollow = Boolean(enabled);
		this.render(this.autoFollow);
	}

	scrollToBottom() {
		this.scrollTop = this.maxScroll;
		this.render();
	}

	get viewportHeight() {
		return this.height - this.toolbarHeight;
	}

	get maxScroll() {
		return Math.max(0, this.contentHeight - this.viewportHeight);
	}

	_nodeKey(entry, node) {
		return `${entry.id}:${node.id}`;
	}

	_nodeRun(entry, node, style = {}) {
		const expandable = Boolean(node.properties?.length || node.truncated);
		const key = node.id ? this._nodeKey(entry, node) : null;
		const marker = expandable ? (this.expanded.has(key) ? '▼ ' : '▶ ') : '';
		return { text: marker + nodeText(node, true), style, nodeKey: expandable ? key : null };
	}

	_addNodeChildren(logicalRows, entry, node, depth) {
		const key = node.id ? this._nodeKey(entry, node) : null;
		if (!key || !this.expanded.has(key)) return;
		for (const property of node.properties || []) {
			const runs = [{ text: `${property.key}: `, style: { color: '#5f6368' } }];
			if (property.value.properties) runs.push(this._nodeRun(entry, property.value));
			else runs.push({ text: nodeText(property.value, property.value.type === 'string'), style: {} });
			logicalRows.push({ entry, depth, runs, nodeKey: property.value.properties ? this._nodeKey(entry, property.value) : null });
			this._addNodeChildren(logicalRows, entry, property.value, depth + 1);
		}
		if (node.truncated) logicalRows.push({ entry, depth, runs: [{ text: '… truncated', style: { color: '#777' } }] });
	}

	_buildLogicalRows() {
		const rows = [];
		for (const entry of this.entries) {
			if (!this.levelVisibility[entry.type]) continue;
			const runs = [{ text: `${entry.type.toUpperCase()} `, style: { color: COLORS[entry.type], fontWeight: 'bold' } }];
			for (const run of entry.runs) runs.push(run.node ? this._nodeRun(entry, run.node, run.style) : run);
			rows.push({ entry, depth: 0, runs });
			for (const run of entry.runs) if (run.node) this._addNodeChildren(rows, entry, run.node, 1);
		}
		return rows;
	}

	_wrapRows(logicalRows) {
		const ctx = this.context;
		const wrapped = [];
		for (const logical of logicalRows) {
			const indent = logical.depth * 16;
			const available = Math.max(20, this.width - 24 - indent);
			let line = { ...logical, segments: [], indent, nodeKey: logical.nodeKey || null };
			let used = 0;
			for (const run of logical.runs) {
				const chunks = splitTextToFit(ctx, run.text, available, run.style, this.font);
				for (const chunk of chunks) {
					if (chunk.newline) {
						wrapped.push(line);
						line = { ...logical, segments: [], indent, nodeKey: logical.nodeKey || null };
						used = 0;
						continue;
					}
					ctx.font = fontForStyle(run.style, this.font);
					const width = ctx.measureText(chunk.text).width;
					if (used > 0 && used + width > available) {
						wrapped.push(line);
						line = { ...logical, segments: [], indent, nodeKey: logical.nodeKey || null };
						used = 0;
					}
					line.segments.push({ ...run, text: chunk.text, width });
					used += width;
				}
			}
			wrapped.push(line);
		}
		return wrapped;
	}

	_renderToolbar(ctx) {
		ctx.textBaseline = 'middle';
		ctx.fillStyle = '#e8eaed';
		ctx.fillRect(0, 0, this.width, this.toolbarHeight);
		ctx.strokeStyle = '#9aa0a6';
		ctx.beginPath(); ctx.moveTo(0, this.toolbarHeight - 0.5); ctx.lineTo(this.width, this.toolbarHeight - 0.5); ctx.stroke();

		ctx.font = 'bold 14px monospace';
		ctx.fillStyle = '#202124';
		ctx.fillText('VRConsole', 10, 19);
		ctx.strokeStyle = '#bdc1c6';
		ctx.beginPath(); ctx.moveTo(91.5, 7); ctx.lineTo(91.5, 31); ctx.stroke();

		let x = 100;
		const button = (label, width, action, active = true, color = '#202124') => {
			ctx.fillStyle = active ? '#ffffff' : '#d4d7db';
			ctx.fillRect(x, 7, width, 24);
			ctx.strokeStyle = active ? '#7b8085' : '#aeb2b7';
			ctx.strokeRect(x + 0.5, 7.5, width - 1, 23);
			ctx.font = 'bold 11px monospace';
			ctx.fillStyle = active ? color : '#777';
			ctx.fillText(label, x + 6, 19);
			this.hitZones.push({ x, y: 7, w: width, h: 24, action });
			x += width + 5;
		};

		button('CLEAR', 50, { type: 'clear' });
		for (const level of LEVELS) {
			const width = level === 'error' || level === 'debug' || level === 'trace' ? 48 : 42;
			button(level.toUpperCase(), width, { type: 'level', level }, this.levelVisibility[level], COLORS[level]);
		}
		button('FOLLOW', 58, { type: 'follow' }, this.autoFollow, '#174ea6');
	}

	_renderScrollbar(ctx) {
		if (this.contentHeight <= this.viewportHeight) return;
		const x = this.width - 11;
		const y = this.toolbarHeight + 2;
		const height = this.viewportHeight - 4;
		const thumbHeight = Math.max(24, height * (this.viewportHeight / this.contentHeight));
		const travel = height - thumbHeight;
		const thumbY = y + (this.maxScroll ? (this.scrollTop / this.maxScroll) * travel : 0);
		ctx.fillStyle = '#e1e3e6'; ctx.fillRect(x, y, 8, height);
		ctx.fillStyle = '#7b8085'; ctx.fillRect(x, thumbY, 8, thumbHeight);
		this.hitZones.push({ x, y, w: 8, h: height, action: { type: 'scrollTrack', thumbY, thumbHeight, trackY: y, trackHeight: height } });
	}

	render(forceBottom = false) {
		const ctx = this.context;
		this.hitZones = [];
		const rows = this._wrapRows(this._buildLogicalRows());
		this.contentHeight = rows.length * this.lineHeight + 8;
		if (forceBottom) this.scrollTop = this.maxScroll;
		this.scrollTop = Math.max(0, Math.min(this.scrollTop, this.maxScroll));

		ctx.clearRect(0, 0, this.width, this.height);
		ctx.fillStyle = '#f8f9fa'; ctx.fillRect(0, 0, this.width, this.height);
		this._renderToolbar(ctx);
		ctx.textBaseline = 'top';
		ctx.save();
		ctx.beginPath(); ctx.rect(0, this.toolbarHeight, this.width, this.viewportHeight); ctx.clip();
		for (let index = 0; index < rows.length; index++) {
			const row = rows[index];
			const y = this.toolbarHeight + 5 + index * this.lineHeight - this.scrollTop;
			if (y + this.lineHeight < this.toolbarHeight || y > this.height) continue;
			if (row.entry.type === 'warn') { ctx.fillStyle = '#fff4ce'; ctx.fillRect(0, y - 3, this.width - 12, this.lineHeight); }
			if (row.entry.type === 'error') { ctx.fillStyle = '#fce8e6'; ctx.fillRect(0, y - 3, this.width - 12, this.lineHeight); }
			let x = 7 + row.indent;
			for (const segment of row.segments) {
				ctx.font = fontForStyle(segment.style, this.font);
				if (segment.style?.backgroundColor) { ctx.fillStyle = segment.style.backgroundColor; ctx.fillRect(x, y - 2, segment.width, this.lineHeight - 2); }
				ctx.fillStyle = segment.style?.color || COLORS[row.entry.type] || '#202124';
				ctx.fillText(segment.text, x, y);
				if (segment.style?.textDecoration?.includes('underline')) { ctx.fillRect(x, y + 14, segment.width, 1); }
				if (segment.nodeKey) this.hitZones.push({ x, y: y - 3, w: segment.width, h: this.lineHeight, action: { type: 'toggle', key: segment.nodeKey } });
				x += segment.width;
			}
			if (row.nodeKey) this.hitZones.push({ x: 0, y: y - 3, w: this.width - 12, h: this.lineHeight, action: { type: 'toggle', key: row.nodeKey } });
		}
		ctx.restore();
		this._renderScrollbar(ctx);
		if (this.onRender) this.onRender(this.canvas);
	}

	_hitTest(x, y) {
		for (let i = this.hitZones.length - 1; i >= 0; i--) {
			const zone = this.hitZones[i];
			if (x >= zone.x && x <= zone.x + zone.w && y >= zone.y && y <= zone.y + zone.h) return zone;
		}
		return null;
	}

	_actionId(action) {
		if (!action) return null;
		if (action.type === 'level') return `${action.type}:${action.level}`;
		if (action.type === 'toggle') return `${action.type}:${action.key}`;
		return action.type;
	}

	pointerDown(x, y) {
		const zone = this._hitTest(x, y);
		this.pointer = {
			x,
			y,
			lastY: y,
			startScroll: this.scrollTop,
			zone,
			actionId: this._actionId(zone?.action),
			moved: false,
		};
	}

	pointerMove(x, y) {
		if (!this.pointer) return;
		if (Math.hypot(x - this.pointer.x, y - this.pointer.y) > 4) this.pointer.moved = true;
		if (!this.pointer.moved) return;
		const action = this.pointer.zone?.action;
		let scrolled = false;
		if (action?.type === 'scrollTrack') {
			const travel = action.trackHeight - action.thumbHeight;
			if (travel > 0) {
				this.scrollTop = this.pointer.startScroll + ((y - this.pointer.y) / travel) * this.maxScroll;
				scrolled = true;
			}
		} else if (this.pointer.y >= this.toolbarHeight) {
			this.scrollTop = this.pointer.startScroll - (y - this.pointer.y);
			scrolled = this.maxScroll > 0;
		}
		if (scrolled) {
			this.autoFollow = false;
			this.render();
		}
		this.pointer.lastY = y;
	}

	pointerUp(x, y) {
		if (!this.pointer) return;
		const pointer = this.pointer;
		this.pointer = null;
		if (pointer.moved) return;
		const zone = this._hitTest(x, y);
		if (!zone || this._actionId(zone.action) !== pointer.actionId) return;
		const action = zone.action;
		if (action.type === 'clear') this.clear();
		else if (action.type === 'level') this.setLevelVisible(action.level, !this.levelVisibility[action.level]);
		else if (action.type === 'follow') this.setAutoFollow(!this.autoFollow);
		else if (action.type === 'toggle') {
			const wasAtBottom = this.scrollTop >= this.maxScroll - 1;
			if (this.expanded.has(action.key)) this.expanded.delete(action.key);
			else this.expanded.add(action.key);
			this.render(this.autoFollow && wasAtBottom);
		} else if (action.type === 'scrollTrack') {
			const position = (y - action.trackY - action.thumbHeight / 2) / (action.trackHeight - action.thumbHeight);
			this.scrollTop = Math.max(0, Math.min(1, position)) * this.maxScroll;
			this.autoFollow = false;
			this.render();
		}
	}

	pointerCancel() {
		this.pointer = null;
	}

	dispose() {
		this.pointer = null;
		this.onRender = null;
		this.hitZones.length = 0;
		this.entries.length = 0;
		this.expanded.clear();
	}
}
