import * as THREE from 'three';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';

/**
 * @module ARRealWorldHitTestManager
 * @description
 * Provides an event-driven wrapper around WebXR real-world hit testing. Use it
 * in immersive AR sessions to convert raw `XRHitTestResult` objects into
 * normalized Three.js-friendly placement data.
 */

/**
 * Event type constants dispatched by {@link ARRealWorldHitTestManager}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired after the WebXR hit-test source is created. */
	SOURCE_READY: 'sourceReady',
	/** Fired every frame while a valid hit is available after the first hit. */
	HIT_UPDATE: 'hitUpdate',
	/** Fired when hit testing transitions from no hit to a valid hit. */
	HIT_FOUND: 'hitFound',
	/** Fired when hit testing loses a previously valid hit. */
	HIT_LOST: 'hitLost',
	/** Fired when the current browser/session cannot provide hit testing. */
	UNAVAILABLE: 'unavailable',
	/** Fired when WebXR rejects source creation or pose normalization fails. */
	ERROR: 'error',
};

/**
 * Default hit-test source options.
 * @type {object}
 * @property {Array<string>|null} entityTypes - Optional WebXR entity types such as `['plane']`.
 * @property {string|null} transientInputProfile - Optional profile for transient input hit testing.
 * @property {boolean} autoStart - Whether to start and stop with renderer XR session events.
 */
export const defaultOptions = {
	entityTypes: null,
	transientInputProfile: null,
	autoStart: true,
};

const _matrix = new THREE.Matrix4();
const _position = new THREE.Vector3();
const _quaternion = new THREE.Quaternion();
const _scale = new THREE.Vector3();

function getSessionFromXR(xr) {
	return typeof xr?.getSession === 'function' ? xr.getSession() : null;
}

function getReferenceSpaceFromXR(xr) {
	try {
		return typeof xr?.getReferenceSpace === 'function' ? xr.getReferenceSpace() : null;
	} catch {
		return null;
	}
}

/**
 * Manages WebXR AR hit-test sources and exposes normalized hit data.
 *
 * The manager accepts either a `THREE.WebGLRenderer` or a `THREE.WebXRManager`.
 * Call {@link ARRealWorldHitTestManager#update} from the XR animation loop with
 * the current `XRFrame`. Events include a normalized `hit` object with
 * `matrix`, `position`, `quaternion`, `normal`, and `alignment` fields.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const hitTest = new ARRealWorldHitTestManager(renderer, {
 *   entityTypes: ['plane'],
 * });
 *
 * hitTest.addEventListener(EventTypes.HIT_UPDATE, ({ hit }) => {
 *   reticle.updateFromHit(hit);
 * });
 *
 * renderer.setAnimationLoop((time, frame) => {
 *   hitTest.update(frame);
 *   renderer.render(scene, camera);
 * });
 */
export class ARRealWorldHitTestManager extends EventsDispatcher {
	/**
	 * @param {THREE.WebGLRenderer|THREE.WebXRManager} rendererOrXRManager - Renderer or XR manager used to access the active XR session.
	 * @param {object} [options] - Hit-test source options.
	 * @param {Array<string>|null} [options.entityTypes] - Optional WebXR entity types requested from the runtime.
	 * @param {string|null} [options.transientInputProfile] - Optional profile passed to transient input hit testing.
	 * @param {boolean} [options.autoStart=true] - Automatically start and stop with XR session events.
	 */
	constructor(rendererOrXRManager, options = {}) {
		super();
		this.xr = rendererOrXRManager?.xr || rendererOrXRManager;
		this.options = { ...defaultOptions, ...options };
		this.session = null;
		this.viewerSpace = null;
		this.hitTestSource = null;
		this.transientHitTestSource = null;
		this.currentHit = null;
		this.available = false;
		this._hadHit = false;

		if (this.options.autoStart && this.xr?.addEventListener) {
			this.xr.addEventListener('sessionstart', () => this.start(getSessionFromXR(this.xr)));
			this.xr.addEventListener('sessionend', () => this.stop());
		}
	}

	/**
	 * Creates the WebXR hit-test source for the active AR session.
	 * @param {XRSession} [session] - Session to use; defaults to the current renderer XR session.
	 * @returns {Promise<boolean>} `true` when hit testing was started.
	 */
	async start(session = getSessionFromXR(this.xr)) {
		this.stop();
		this.session = session;

		if (!session?.requestReferenceSpace || !session?.requestHitTestSource) {
			this.available = false;
			this.dispatchEvent({
				type: EventTypes.UNAVAILABLE,
				reason: 'WebXR hit-test is not available for this session.',
			});
			return false;
		}

		try {
			this.viewerSpace = await session.requestReferenceSpace('viewer');
			this.hitTestSource = await this._requestHitTestSource(session, this.viewerSpace);

			if (this.options.transientInputProfile && session.requestHitTestSourceForTransientInput) {
				this.transientHitTestSource = await this._requestTransientHitTestSource(session);
			}

			this.available = true;
			this.dispatchEvent({ type: EventTypes.SOURCE_READY, session, manager: this });
			return true;
		} catch (error) {
			this.available = false;
			this.dispatchEvent({ type: EventTypes.ERROR, error, manager: this });
			return false;
		}
	}

	/**
	 * Cancels active hit-test sources and clears current hit state.
	 * @returns {void}
	 */
	stop() {
		if (this.hitTestSource?.cancel) this.hitTestSource.cancel();
		if (this.transientHitTestSource?.cancel) this.transientHitTestSource.cancel();
		this.viewerSpace = null;
		this.hitTestSource = null;
		this.transientHitTestSource = null;
		this.currentHit = null;
		this.available = false;
		this._hadHit = false;
	}

	/**
	 * Updates hit testing for the current XR frame.
	 * @param {XRFrame} frame - Current XR frame from `renderer.setAnimationLoop`.
	 * @param {XRReferenceSpace} [referenceSpace] - Reference space used to resolve hit poses.
	 * @returns {object|null} Normalized hit information, or `null` when no hit is available.
	 */
	update(frame, referenceSpace = getReferenceSpaceFromXR(this.xr)) {
		if (!frame || !referenceSpace || !this.hitTestSource) return null;

		const results = frame.getHitTestResults(this.hitTestSource);
		const hit = results?.[0] ? this._normalizeHit(results[0], frame, referenceSpace, false) : null;
		this.currentHit = hit;

		if (hit) {
			const type = this._hadHit ? EventTypes.HIT_UPDATE : EventTypes.HIT_FOUND;
			this._hadHit = true;
			this.dispatchEvent({ type, hit, manager: this });
		} else if (this._hadHit) {
			this._hadHit = false;
			this.dispatchEvent({ type: EventTypes.HIT_LOST, manager: this });
		}

		return hit;
	}

	/**
	 * Updates transient input hit testing, usually for touch-screen or pointer based AR input.
	 * @param {XRFrame} frame - Current XR frame.
	 * @param {XRReferenceSpace} [referenceSpace] - Reference space used to resolve hit poses.
	 * @returns {Array<object>} Normalized transient hits.
	 */
	updateTransient(frame, referenceSpace = getReferenceSpaceFromXR(this.xr)) {
		if (!frame || !referenceSpace || !this.transientHitTestSource) return [];
		const groups = frame.getHitTestResultsForTransientInput(this.transientHitTestSource) || [];
		return groups.flatMap((group) =>
			group.results.map((result) => this._normalizeHit(result, frame, referenceSpace, true, group.inputSource))
		);
	}

	async _requestHitTestSource(session, space) {
		const init = { space };
		if (this.options.entityTypes) init.entityTypes = this.options.entityTypes;

		try {
			return await session.requestHitTestSource(init);
		} catch (error) {
			if (!this.options.entityTypes) throw error;
			return session.requestHitTestSource({ space });
		}
	}

	async _requestTransientHitTestSource(session) {
		const init = { profile: this.options.transientInputProfile };
		if (this.options.entityTypes) init.entityTypes = this.options.entityTypes;

		try {
			return await session.requestHitTestSourceForTransientInput(init);
		} catch (error) {
			if (!this.options.entityTypes) throw error;
			return session.requestHitTestSourceForTransientInput({ profile: this.options.transientInputProfile });
		}
	}

	_normalizeHit(rawHit, frame, referenceSpace, transient, inputSource = null) {
		const pose = rawHit.getPose(referenceSpace);
		if (!pose) return null;

		_matrix.fromArray(pose.transform.matrix);
		_matrix.decompose(_position, _quaternion, _scale);
		const normal = new THREE.Vector3(0, 1, 0).applyQuaternion(_quaternion).normalize();

		return {
			rawHit,
			frame,
			referenceSpace,
			inputSource,
			transient,
			pose,
			matrix: _matrix.clone(),
			matrixArray: Array.from(pose.transform.matrix),
			position: _position.clone(),
			quaternion: _quaternion.clone(),
			scale: _scale.clone(),
			normal,
			alignment: Math.abs(normal.y) > 0.72 ? 'horizontal' : 'vertical-or-sloped',
			entityType: rawHit.entityType || null,
		};
	}
}
