import * as THREE from 'three';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';
import { VRInteractiveSurface, EventTypes as SurfaceEventTypes } from './VRInteractiveSurface.js';

/**
 * @module CanvasInteractiveSurface
 * @description
 * Maps controller ray hits on a UV-mapped mesh into canvas pixel coordinates and
 * optional command hit zones.
 */

/**
 * Event type constants dispatched by {@link CanvasInteractiveSurface}.
 * @enum {string}
 */
export const EventTypes = {
	/** Forwarded when the controller pointer presses the surface. */
	POINTER_DOWN: SurfaceEventTypes.POINTER_DOWN,
	/** Forwarded while the controller pointer moves over the surface. */
	POINTER_MOVE: SurfaceEventTypes.POINTER_MOVE,
	/** Forwarded when the controller pointer releases over the surface. */
	POINTER_UP: SurfaceEventTypes.POINTER_UP,
	/** Forwarded when the pointer releases after leaving the surface. */
	POINTER_UP_OUTSIDE: SurfaceEventTypes.POINTER_UP_OUTSIDE,
	/** Fired when a configured hit zone receives a pointer command. */
	COMMAND: 'command',
};

/**
 * Default canvas surface options.
 * @type {object}
 */
export const defaultOptions = {
	width: 1024,
	height: 512,
	canvas: null,
	context: null,
	contextAttributes: undefined,
	useBVH: false,
	debugLevel: 0,
	flipU: false,
	textureOptions: {
		colorSpace: THREE.SRGBColorSpace,
		minFilter: THREE.LinearFilter,
		magFilter: THREE.LinearFilter,
		generateMipmaps: false,
	},
	materialIndex: null,
	hitZones: [],
};

/**
 * Converts normalized UV coordinates into canvas pixel coordinates.
 * @param {THREE.Vector2} uv - Mesh UV coordinate.
 * @param {number} width - Canvas width in pixels.
 * @param {number} height - Canvas height in pixels.
 * @param {object} [options] - Conversion options.
 * @param {boolean} [options.flipU=false] - Whether to mirror the U coordinate.
 * @returns {{x: number, y: number}}
 */
export function uvToCanvasPoint(uv, width, height, options = {}) {
	const ux = options.flipU ? 1 - uv.x : uv.x;
	return {
		x: ux * width,
		y: (1 - uv.y) * height,
	};
}

/**
 * Converts a hit-zone rectangle to pixel coordinates.
 * @param {object} zone - Hit-zone descriptor.
 * @param {Array<number>|object} [zone.rect] - Normalized rect as `[x,y,w,h]` or object.
 * @param {Array<number>|object} [zone.pixelRect] - Pixel rect as `[x,y,w,h]` or object.
 * @param {number} width - Canvas width in pixels.
 * @param {number} height - Canvas height in pixels.
 * @returns {{x: number, y: number, w: number, h: number}|null}
 */
export function normalizeHitZoneRect(zone, width, height) {
	const rect = zone?.rect || zone?.pixelRect;
	if (!rect) return null;

	const source = Array.isArray(rect)
		? {
			x: rect[0],
			y: rect[1],
			w: rect[2],
			h: rect[3],
		}
		: rect;

	if (zone.pixelRect) {
		return {
			x: source.x,
			y: source.y,
			w: source.w,
			h: source.h,
		};
	}

	return {
		x: source.x * width,
		y: source.y * height,
		w: source.w * width,
		h: source.h * height,
	};
}

/**
 * Finds the top-most active hit zone containing a canvas point.
 * @param {Array<object>} hitZones - Hit-zone descriptors.
 * @param {{x: number, y: number}|null} point - Canvas point.
 * @param {number} width - Canvas width in pixels.
 * @param {number} height - Canvas height in pixels.
 * @returns {object|null}
 */
export function hitTestZones(hitZones, point, width, height) {
	if (!point || !Array.isArray(hitZones)) return null;

	for (let i = hitZones.length - 1; i >= 0; i--) {
		const zone = hitZones[i];
		if (zone?.disabled) continue;
		const rect = normalizeHitZoneRect(zone, width, height);
		if (!rect) continue;
		if (point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h) {
			return zone;
		}
	}
	return null;
}

/**
 * Canvas-backed adapter for an application-owned UV-mapped mesh.
 *
 * The class owns only the canvas texture and pointer/hit-zone translation. The
 * caller still owns the mesh shape, placement, material choice, and drawing.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const surface = new CanvasInteractiveSurface(panelMesh, scene, controllersManager, {
 *   width: 512,
 *   height: 256,
 *   hitZones: [
 *     { id: 'ok', command: 'confirm', rect: { x: 0.7, y: 0.75, w: 0.25, h: 0.18 } },
 *   ],
 * });
 *
 * surface.context.fillText('Confirm', 360, 210);
 * surface.updateTexture();
 * surface.addEventListener(EventTypes.COMMAND, ({ command }) => runCommand(command));
 */
export class CanvasInteractiveSurface extends EventsDispatcher {
	/**
	 * @param {THREE.Mesh} mesh - UV-mapped mesh that receives the canvas texture and pointer hits.
	 * @param {THREE.Group|THREE.Scene} worldContainer - Scene node used by the underlying interactive surface.
	 * @param {ControllersManager} controllersManager - Controller manager used for ray input.
	 * @param {object} [options] - Canvas surface options.
	 * @param {number} [options.width=1024] - Canvas width in pixels.
	 * @param {number} [options.height=512] - Canvas height in pixels.
	 * @param {HTMLCanvasElement|null} [options.canvas=null] - Existing canvas to use instead of creating one.
	 * @param {CanvasRenderingContext2D|null} [options.context=null] - Existing 2D context.
	 * @param {Array<object>} [options.hitZones] - Command zones in normalized or pixel coordinates.
	 */
	constructor(mesh, worldContainer, controllersManager, options = {}) {
		super();
		if (mesh === undefined || worldContainer === undefined || controllersManager === undefined) {
			throw Error('CanvasInteractiveSurface: Missing parameters');
		}

		this.options = {
			...defaultOptions,
			...options,
			textureOptions: {
				...defaultOptions.textureOptions,
				...(options.textureOptions || {}),
			},
		};
		this._mesh = mesh;
		this._canvas = this.options.canvas || document.createElement('canvas');
		this._canvas.width = this.options.width;
		this._canvas.height = this.options.height;
		this._ctx = this.options.context || this._canvas.getContext('2d', this.options.contextAttributes);
		this._hitZones = [...(this.options.hitZones || [])];
		this._activeZone = null;

		this._texture = this._createTexture(this._canvas);
		this._applyTexture();

		this._surface = new VRInteractiveSurface(mesh, worldContainer, controllersManager, {
			useBVH: this.options.useBVH,
			debugLevel: this.options.debugLevel,
		});

		this._bound = {
			down: (e) => this._onPointer(e),
			move: (e) => this._onPointer(e),
			up: (e) => this._onPointer(e),
			upOutside: (e) => this._onPointer(e),
		};
		this._surface.addEventListener(SurfaceEventTypes.POINTER_DOWN, this._bound.down);
		this._surface.addEventListener(SurfaceEventTypes.POINTER_MOVE, this._bound.move);
		this._surface.addEventListener(SurfaceEventTypes.POINTER_UP, this._bound.up);
		this._surface.addEventListener(SurfaceEventTypes.POINTER_UP_OUTSIDE, this._bound.upOutside);
	}

	_createTexture(canvas) {
		const texture = new THREE.CanvasTexture(canvas);
		const textureOptions = this.options.textureOptions;
		texture.colorSpace = textureOptions.colorSpace;
		texture.minFilter = textureOptions.minFilter;
		texture.magFilter = textureOptions.magFilter;
		texture.generateMipmaps = textureOptions.generateMipmaps;
		if (this.options.flipU) {
			texture.wrapS = THREE.RepeatWrapping;
			texture.repeat.x = -1;
			texture.offset.x = 1;
		}
		return texture;
	}

	_applyTexture() {
		const materials = Array.isArray(this._mesh.material) ? this._mesh.material : [this._mesh.material];
		const targets = this.options.materialIndex == null ? materials : [materials[this.options.materialIndex]];
		for (const material of targets) {
			if (!material) continue;
			material.map = this._texture;
			material.needsUpdate = true;
		}
	}

	_onPointer(e) {
		const point = e.uv ? uvToCanvasPoint(e.uv, this._canvas.width, this._canvas.height, this.options) : null;
		const hitZone = hitTestZones(this._hitZones, point, this._canvas.width, this._canvas.height);
		const event = {
			...e,
			pointPx: point,
			canvas: this._canvas,
			context: this._ctx,
			hitZone,
			surface: this,
		};

		if (e.type === SurfaceEventTypes.POINTER_DOWN) {
			this._activeZone = hitZone;
			if (hitZone?.trigger === 'down') this._dispatchCommand(hitZone, event);
		} else if (e.type === SurfaceEventTypes.POINTER_UP) {
			if (hitZone && hitZone === this._activeZone && hitZone.trigger !== 'down') {
				this._dispatchCommand(hitZone, event);
			}
			this._activeZone = null;
		} else if (e.type === SurfaceEventTypes.POINTER_UP_OUTSIDE) {
			this._activeZone = null;
		}

		this.dispatchEvent(event);
	}

	_dispatchCommand(hitZone, pointerEvent) {
		const command = hitZone.command || hitZone.id;
		if (!command) return;
		this.dispatchEvent({
			type: EventTypes.COMMAND,
			command,
			hitZone,
			pointerEvent,
			surface: this,
		});
	}

	get canvas() {
		return this._canvas;
	}

	get context() {
		return this._ctx;
	}

	get texture() {
		return this._texture;
	}

	get surface() {
		return this._surface;
	}

	get hitZones() {
		return this._hitZones;
	}

	setHitZones(hitZones = []) {
		this._hitZones = [...hitZones];
	}

	addHitZone(hitZone) {
		this._hitZones.push(hitZone);
		return hitZone;
	}

	uvToCanvasPoint(uv) {
		return uvToCanvasPoint(uv, this._canvas.width, this._canvas.height, this.options);
	}

	hitTest(point) {
		return hitTestZones(this._hitZones, point, this._canvas.width, this._canvas.height);
	}

	invalidate() {
		this._texture.needsUpdate = true;
	}

	dispose() {
		this._surface.removeEventListener(SurfaceEventTypes.POINTER_DOWN, this._bound.down);
		this._surface.removeEventListener(SurfaceEventTypes.POINTER_MOVE, this._bound.move);
		this._surface.removeEventListener(SurfaceEventTypes.POINTER_UP, this._bound.up);
		this._surface.removeEventListener(SurfaceEventTypes.POINTER_UP_OUTSIDE, this._bound.upOutside);
		this._surface.dispose();
		this._texture.dispose();
	}
}
