import * as THREE from 'three';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';

/**
 * @module XRInteractionModeAdapter
 * @description
 * Detects whether the current XR session is using world-space controllers,
 * screen-space input, or pointer fallback input, then exposes consistent select
 * events and ray helpers.
 */

/**
 * Supported high-level interaction modes.
 * @enum {string}
 */
export const InteractionModes = {
	/** Touchscreen or screen-targeted AR input. */
	SCREEN_SPACE: 'screen-space',
	/** Tracked controller or hand-pointer input. */
	WORLD_SPACE: 'world-space',
	/** Non-XR pointer fallback mode. */
	POINTER_FALLBACK: 'pointer-fallback',
};

/**
 * Event type constants dispatched by {@link XRInteractionModeAdapter}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when the detected interaction mode changes. */
	MODE_CHANGE: 'modeChange',
	/** Fired when the active XR session emits a `select` event. */
	SELECT: 'select',
};

const _matrix = new THREE.Matrix4();

/**
 * Normalizes AR/VR input mode detection and select events.
 *
 * Use this when the same placement or interaction feature should work with
 * Quest controllers, AR screen taps, and regular pointer fallback input.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const modes = new XRInteractionModeAdapter(renderer);
 * modes.addEventListener(EventTypes.SELECT, (event) => {
 *   const ray = modes.getRayFromSelectEvent(event.originalEvent, renderer.xr.getReferenceSpace());
 * });
 */
export class XRInteractionModeAdapter extends EventsDispatcher {
	/**
	 * @param {THREE.WebGLRenderer|THREE.WebXRManager} rendererOrXRManager - Renderer or XR manager that owns the session.
	 * @param {object} [options] - Adapter options.
	 * @param {string} [options.mode] - Optional forced mode from {@link InteractionModes}.
	 */
	constructor(rendererOrXRManager, options = {}) {
		super();
		this.xr = rendererOrXRManager?.xr || rendererOrXRManager;
		this.mode = options.mode || InteractionModes.POINTER_FALLBACK;
		this.modeOverride = options.mode || null;
		this._session = null;
		this._boundSelect = (event) => this._onSelect(event);

		if (this.xr?.addEventListener) {
			this.xr.addEventListener('sessionstart', () => this.connectSession(this.xr.getSession?.()));
			this.xr.addEventListener('sessionend', () => this.disconnectSession());
		}
	}

	/**
	 * Connects the adapter to an XR session and subscribes to select events.
	 * @param {XRSession|null} session - Session to observe.
	 * @returns {void}
	 */
	connectSession(session) {
		this.disconnectSession();
		this._session = session;
		if (session) {
			session.addEventListener('select', this._boundSelect);
			session.addEventListener('inputsourceschange', () => this.update(session));
		}
		this.update(session);
	}

	/**
	 * Removes listeners from the current XR session.
	 * @returns {void}
	 */
	disconnectSession() {
		if (this._session) this._session.removeEventListener('select', this._boundSelect);
		this._session = null;
		this.update(null);
	}

	/**
	 * Re-detects the current interaction mode.
	 * @param {XRSession|null} [session] - Session to inspect.
	 * @returns {string} Current value from {@link InteractionModes}.
	 */
	update(session = this._session) {
		const nextMode = this.modeOverride || this._detectMode(session);
		if (nextMode === this.mode) return this.mode;
		const previousMode = this.mode;
		this.mode = nextMode;
		this.dispatchEvent({ type: EventTypes.MODE_CHANGE, mode: this.mode, previousMode });
		return this.mode;
	}

	_detectMode(session) {
		if (!session) return InteractionModes.POINTER_FALLBACK;
		const sources = Array.from(session.inputSources || []);
		if (sources.some((source) => source.targetRayMode === 'tracked-pointer')) return InteractionModes.WORLD_SPACE;
		if (sources.some((source) => source.targetRayMode === 'screen')) return InteractionModes.SCREEN_SPACE;
		return InteractionModes.SCREEN_SPACE;
	}

	_onSelect(event) {
		this.update(event.currentTarget || this._session);
		this.dispatchEvent({
			type: EventTypes.SELECT,
			mode: this.mode,
			originalEvent: event,
			inputSource: event.inputSource || null,
		});
	}

	/**
	 * Returns the current interaction mode.
	 * @returns {string}
	 */
	getMode() {
		return this.mode;
	}

	/**
	 * Builds a Three.js ray from an XR `select` event.
	 * @param {XRInputSourceEvent} event - Original WebXR select event.
	 * @param {XRReferenceSpace} referenceSpace - Reference space used to resolve the target ray pose.
	 * @returns {THREE.Ray|null}
	 */
	getRayFromSelectEvent(event, referenceSpace) {
		const inputSource = event?.inputSource;
		const frame = event?.frame;
		if (!inputSource?.targetRaySpace || !frame || !referenceSpace) return null;

		const pose = frame.getPose(inputSource.targetRaySpace, referenceSpace);
		if (!pose) return null;

		_matrix.fromArray(pose.transform.matrix);
		const origin = new THREE.Vector3().setFromMatrixPosition(_matrix);
		const direction = new THREE.Vector3(0, 0, -1).transformDirection(_matrix);
		return new THREE.Ray(origin, direction);
	}

	/**
	 * Builds a forward ray from a camera for non-XR or pointer fallback selection.
	 * @param {THREE.Camera} camera - Camera used as ray origin and direction source.
	 * @returns {THREE.Ray}
	 */
	getViewerRay(camera) {
		const origin = new THREE.Vector3();
		const direction = new THREE.Vector3(0, 0, -1);
		camera.getWorldPosition(origin);
		camera.getWorldDirection(direction);
		return new THREE.Ray(origin, direction.normalize());
	}
}
