/**
 * @module VRRotaryControl
 * @description
 * Adds constrained rotary/knob behavior to app-owned Three.js objects.
 */
import * as THREE from 'three';

import { EventsDispatcher } from '../utils/EventsDispatcher.js';
import {
	assertObject3D,
	clamp,
	getAxisInRestParentSpace,
	getControllerFromEvent,
	getGripWorldQuaternion,
	getGripWorldPosition,
	pointDistanceToObject,
	resolveControllersManager,
} from './VRControlInput.js';

export const EventTypes = {
	/** Fired when a controller begins dragging the rotary control. */
	ON_DRAG_START: 'onDragStart',
	/** Fired while the active drag updates the angle. */
	ON_DRAG_UPDATE: 'onDragUpdate',
	/** Fired when dragging ends. */
	ON_DRAG_END: 'onDragEnd',
	/** Fired whenever the angle/value changes. */
	ON_VALUE_CHANGE: 'onValueChange',
};

export const defaultOptions = {
	enabled: true,
	interactionObject: null,
	controllersManager: null,
	axis: new THREE.Vector3(0, 0, 1),
	minAngle: 0,
	maxAngle: Math.PI * 2,
	initialAngle: 0,
	grabDistance: 0.075,
	translationInput: {
		enabled: true,
		multiplier: 1,
	},
	twistInput: {
		enabled: true,
		multiplier: 1,
		referenceVector: new THREE.Vector3(0, 0, -1),
	},
	haptics: {
		enabled: true,
		stepAngle: THREE.MathUtils.degToRad(7.5),
		intensity: 0.25,
		duration: 18,
		minInterval: 0.035,
	},
};

/**
 * Adds constrained rotary behavior to an app-owned Object3D. The object must
 * provide its own visual shape and pivot; this class only computes angle,
 * clamps limits, applies rotation, and emits interaction events.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const knob = new VRRotaryControl(knobMesh, {
 *   controllersManager,
 *   axis: new THREE.Vector3(0, 0, 1),
 *   minAngle: 0,
 *   maxAngle: Math.PI,
 * });
 *
 * knob.addEventListener(EventTypes.ON_VALUE_CHANGE, ({ value, angle }) => {
 *   console.log(value, angle);
 * });
 */
export class VRRotaryControl extends EventsDispatcher {
	/**
	 * @param {THREE.Object3D} movingObject - Object rotated by the control.
	 * @param {object} [options] - Rotary interaction options.
	 * @param {boolean} [options.enabled=true] - Whether the control reacts to squeeze/drag input.
	 * @param {THREE.Object3D|null} [options.interactionObject=null] - Object used for grab-distance testing.
	 * @param {ControllersManager|null} [options.controllersManager=null] - Controller source; resolved automatically when possible.
	 * @param {THREE.Vector3} [options.axis] - Local rotation axis.
	 * @param {number} [options.minAngle=0] - Minimum rotation angle in radians.
	 * @param {number} [options.maxAngle=Math.PI*2] - Maximum rotation angle in radians.
	 * @param {number} [options.initialAngle=0] - Initial angle in radians.
	 * @param {number} [options.grabDistance=0.075] - Distance threshold for starting a drag.
	 * @param {object} [options.translationInput] - Translation-based drag contribution options.
	 * @param {object} [options.twistInput] - Controller-twist contribution options.
	 * @param {object} [options.haptics] - Haptic detent feedback options.
	 */
	constructor(movingObject, options = {}) {
		super();
		assertObject3D(movingObject, 'VRRotaryControl movingObject');

		this.movingObject = movingObject;
		this.options = { ...defaultOptions, ...options };
		this.options.axis = (options.axis || defaultOptions.axis).clone().normalize();
		this.options.translationInput = { ...defaultOptions.translationInput, ...options.translationInput };
		this.options.twistInput = { ...defaultOptions.twistInput, ...options.twistInput };
		this.options.twistInput.referenceVector = (
			options.twistInput?.referenceVector || defaultOptions.twistInput.referenceVector
		)
			.clone()
			.normalize();
		this.options.haptics = { ...defaultOptions.haptics, ...options.haptics };
		this.interactionObject = this.options.interactionObject || movingObject;
		assertObject3D(this.interactionObject, 'VRRotaryControl interactionObject');

		this.controllersManager = resolveControllersManager(this.options.controllersManager);
		this.enabled = this.options.enabled !== false;
		this._restQuaternion = movingObject.quaternion.clone();
		this._restPosition = movingObject.position.clone();
		this._axisLocal = this.options.axis.clone().normalize();
		this._axisParent = getAxisInRestParentSpace(this._axisLocal, this._restQuaternion);
		this._pivotLocal = this._restPosition.clone();
		this._box = new THREE.Box3();
		this._angle = clamp(this.options.initialAngle || 0, this.options.minAngle, this.options.maxAngle);
		this._activeDrag = null;
		this._time = 0;
		this._lastHapticAt = -Infinity;
		this._lastDetentIndex = this._getDetentIndex(this._angle);
		this._tmp = {
			v1: new THREE.Vector3(),
			v2: new THREE.Vector3(),
			v3: new THREE.Vector3(),
			q: new THREE.Quaternion(),
			m: new THREE.Matrix4(),
		};

		this._applyAngle();
		this._boundSqueezeStart = this._onSqueezeStart.bind(this);
		this._boundSqueezeEnd = this._onSqueezeEnd.bind(this);
		this._boundUpdate = this._onUpdate.bind(this);
		this.controllersManager.addEventListener('onSqueezeStart', this._boundSqueezeStart);
		this.controllersManager.addEventListener('onSqueezeEnd', this._boundSqueezeEnd);
		this.controllersManager.addEventListener('onUpdate', this._boundUpdate);
	}

	/**
	 * Current angle in radians.
	 * @type {number}
	 */
	get angle() {
		return this._angle;
	}

	/**
	 * Current normalized value from 0 to 1 across the configured angle range.
	 * @type {number}
	 */
	get value() {
		const range = this.options.maxAngle - this.options.minAngle;
		if (range === 0) return 0;
		return (this._angle - this.options.minAngle) / range;
	}

	/**
	 * Whether a controller is currently dragging the control.
	 * @type {boolean}
	 */
	get dragging() {
		return !!this._activeDrag;
	}

	/**
	 * Enables or disables drag handling.
	 * @param {boolean} enabled
	 * @returns {void}
	 */
	setEnabled(enabled) {
		this.enabled = !!enabled;
		if (!this.enabled) this._endDrag('disabled');
	}

	/**
	 * Sets the control angle directly.
	 * @param {number} angle - Target angle in radians.
	 * @param {boolean} [dispatch=true] - Whether to emit `ON_VALUE_CHANGE`.
	 * @returns {void}
	 */
	setAngle(angle, dispatch = true) {
		const next = clamp(angle, this.options.minAngle, this.options.maxAngle);
		if (Math.abs(next - this._angle) < 0.0001) return;
		const previous = this._angle;
		this._angle = next;
		this._applyAngle();
		this._updateHapticFeedback(previous, next);
		if (dispatch) this._dispatchValueChange(this._activeDrag?.controller || null);
	}

	/**
	 * Removes event listeners registered on the controller manager.
	 * @returns {void}
	 */
	dispose() {
		this.controllersManager.removeEventListener('onSqueezeStart', this._boundSqueezeStart);
		this.controllersManager.removeEventListener('onSqueezeEnd', this._boundSqueezeEnd);
		this.controllersManager.removeEventListener('onUpdate', this._boundUpdate);
	}

	_onSqueezeStart(event) {
		if (!this.enabled || this._activeDrag) return;

		const controller = getControllerFromEvent(event, this.controllersManager);
		const point = getGripWorldPosition(controller);
		if (!controller || !point) return;

		const distance = pointDistanceToObject(point, this.interactionObject, this._box);
		if (distance > this.options.grabDistance) return;

		const startPositionVector = this.options.translationInput.enabled ? this._getProjectedPointerVector(point) : null;
		const startTwistVector = this.options.twistInput.enabled ? this._getProjectedGripVector(controller) : null;
		if (!startPositionVector && !startTwistVector) return;

		this._activeDrag = {
			controller,
			handedness: event.handedness,
			source: controller.source || 'controller',
			startPositionVector,
			startTwistVector,
			startAngle: this._angle,
		};
		this._lastDetentIndex = this._getDetentIndex(this._angle);

		this.dispatchEvent(this._buildDragEvent(EventTypes.ON_DRAG_START, controller));
		controller.pulse?.(0.35, 45);
		return false;
	}

	_onSqueezeEnd(event) {
		if (!this._activeDrag || this._activeDrag.handedness !== event.handedness) return;
		this._endDrag('squeeze-end');
	}

	_onUpdate(event) {
		this._time += event?.deltaTime || 0;
		if (!this.enabled || !this._activeDrag) return;

		const controller = this._activeDrag.controller;
		const point = getGripWorldPosition(controller);
		if (!point) {
			this._endDrag('lost-input');
			return;
		}

		const currentPositionVector = this.options.translationInput.enabled ? this._getProjectedPointerVector(point) : null;
		const currentTwistVector = this.options.twistInput.enabled ? this._getProjectedGripVector(controller) : null;

		let delta = 0;
		if (this._activeDrag.startPositionVector && currentPositionVector) {
			delta +=
				signedAngleAroundAxis(this._activeDrag.startPositionVector, currentPositionVector, this._axisParent) *
				this.options.translationInput.multiplier;
		}
		if (this._activeDrag.startTwistVector && currentTwistVector) {
			delta +=
				signedAngleAroundAxis(this._activeDrag.startTwistVector, currentTwistVector, this._axisParent) *
				this.options.twistInput.multiplier;
		}

		this.setAngle(this._activeDrag.startAngle + delta, true);
		this.dispatchEvent(this._buildDragEvent(EventTypes.ON_DRAG_UPDATE, controller));
	}

	_endDrag(reason) {
		if (!this._activeDrag) return;
		const controller = this._activeDrag.controller;
		this.dispatchEvent(this._buildDragEvent(EventTypes.ON_DRAG_END, controller, { reason }));
		this._activeDrag = null;
	}

	_getProjectedPointerVector(worldPoint) {
		const localPoint = this._worldToParentLocal(worldPoint, this._tmp.v1);
		const vector = this._tmp.v2.copy(localPoint).sub(this._pivotLocal);
		vector.addScaledVector(this._axisParent, -vector.dot(this._axisParent));
		if (vector.lengthSq() < 0.000001) return null;
		return vector.clone().normalize();
	}

	_getProjectedGripVector(controller) {
		const quaternion = getGripWorldQuaternion(controller, this._tmp.q);
		if (!quaternion) return null;

		const worldVector = this._tmp.v3.copy(this.options.twistInput.referenceVector).applyQuaternion(quaternion);
		const parentVector = this._worldDirectionToParentLocal(worldVector, this._tmp.v1);
		parentVector.addScaledVector(this._axisParent, -parentVector.dot(this._axisParent));
		if (parentVector.lengthSq() < 0.000001) return null;
		return parentVector.clone().normalize();
	}

	_worldToParentLocal(worldPoint, target) {
		target.copy(worldPoint);
		if (this.movingObject.parent) this.movingObject.parent.worldToLocal(target);
		return target;
	}

	_worldDirectionToParentLocal(worldDirection, target) {
		target.copy(worldDirection);
		if (this.movingObject.parent) {
			this.movingObject.parent.updateMatrixWorld(true);
			this._tmp.m.identity().extractRotation(this.movingObject.parent.matrixWorld).invert();
			target.applyMatrix4(this._tmp.m);
		}
		return target.normalize();
	}

	_applyAngle() {
		this._tmp.q.setFromAxisAngle(this._axisLocal, this._angle);
		this.movingObject.quaternion.copy(this._restQuaternion).multiply(this._tmp.q);
		this.movingObject.updateMatrixWorld(true);
	}

	_updateHapticFeedback(previousAngle, nextAngle) {
		const haptics = this.options.haptics;
		const previousIndex = this._lastDetentIndex ?? this._getDetentIndex(previousAngle);
		const nextIndex = this._getDetentIndex(nextAngle);
		if (!this._activeDrag) {
			this._lastDetentIndex = nextIndex;
			return;
		}
		if (previousIndex === nextIndex) return;
		this._lastDetentIndex = nextIndex;
		if (!haptics.enabled || !this._activeDrag.controller?.pulse) return;
		if (haptics.stepAngle <= 0 || haptics.intensity <= 0 || haptics.duration <= 0) return;

		if (this._time - this._lastHapticAt < haptics.minInterval) return;
		this._lastHapticAt = this._time;

		const crossed = Math.max(1, Math.abs(nextIndex - previousIndex));
		const intensity = clamp(haptics.intensity * Math.min(crossed, 3), 0, 1);
		this._activeDrag.controller.pulse(intensity, haptics.duration);
	}

	_getDetentIndex(angle) {
		const step = this.options.haptics.stepAngle;
		if (!step || step <= 0) return 0;
		return Math.round((angle - this.options.minAngle) / step);
	}

	_dispatchValueChange(controller) {
		this.dispatchEvent({
			type: EventTypes.ON_VALUE_CHANGE,
			control: this,
			controller,
			angle: this._angle,
			value: this.value,
		});
	}

	_buildDragEvent(type, controller, extra = {}) {
		return {
			type,
			control: this,
			controller,
			angle: this._angle,
			value: this.value,
			...extra,
		};
	}
}

function signedAngleAroundAxis(from, to, axis) {
	const cross = new THREE.Vector3().crossVectors(from, to);
	return Math.atan2(axis.dot(cross), clamp(from.dot(to), -1, 1));
}
