import * as THREE from 'three';

/**
 * @module ARPlacementReticle
 * @description
 * Exports a lightweight Three.js reticle for previewing where AR content will
 * be placed on a real-world hit-test result.
 */

/**
 * Default visual options for {@link ARPlacementReticle}.
 * @type {object}
 * @property {number} radius - Reticle radius in meters.
 * @property {number} color - Hex color used for valid placement hits.
 * @property {number} invalidColor - Hex color used when placement is invalid.
 * @property {number} opacity - Material opacity.
 * @property {THREE.Object3D|null} previewObject - Optional object cloned into the reticle.
 */
export const defaultOptions = {
	radius: 0.18,
	color: 0x32d583,
	invalidColor: 0xffb020,
	opacity: 0.9,
	previewObject: null,
};

/**
 * Visual marker that follows an AR hit-test pose.
 *
 * Add it to the scene once, then call {@link ARPlacementReticle#updateFromHit}
 * with hits returned by {@link ARRealWorldHitTestManager}. The reticle hides
 * itself when no hit is available.
 *
 * @extends THREE.Group
 *
 * @example
 * const reticle = new ARPlacementReticle({ radius: 0.2 });
 * scene.add(reticle);
 *
 * hitTest.addEventListener(HitTestEventTypes.HIT_UPDATE, ({ hit }) => {
 *   reticle.updateFromHit(hit);
 * });
 */
export class ARPlacementReticle extends THREE.Group {
	/**
	 * @param {object} [options] - Visual reticle options.
	 * @param {number} [options.radius=0.18] - Reticle radius in meters.
	 * @param {number} [options.color=0x32d583] - Valid placement color.
	 * @param {number} [options.invalidColor=0xffb020] - Invalid placement color.
	 * @param {number} [options.opacity=0.9] - Reticle opacity.
	 * @param {THREE.Object3D|null} [options.previewObject=null] - Optional preview object cloned into the reticle.
	 */
	constructor(options = {}) {
		super();
		this.options = { ...defaultOptions, ...options };
		this.matrixAutoUpdate = false;
		this.visible = false;
		this.valid = false;

		this._validMaterial = new THREE.MeshBasicMaterial({
			color: this.options.color,
			transparent: true,
			opacity: this.options.opacity,
			side: THREE.DoubleSide,
			depthWrite: false,
		});
		this._invalidMaterial = new THREE.MeshBasicMaterial({
			color: this.options.invalidColor,
			transparent: true,
			opacity: this.options.opacity * 0.85,
			side: THREE.DoubleSide,
			depthWrite: false,
		});

		const ring = new THREE.Mesh(
			new THREE.RingGeometry(this.options.radius * 0.72, this.options.radius, 48),
			this._validMaterial
		);
		ring.rotation.x = -Math.PI / 2;
		this.add(ring);
		this.ring = ring;

		const lineMaterial = new THREE.LineBasicMaterial({ color: this.options.color, transparent: true, opacity: 0.8 });
		const points = [
			new THREE.Vector3(-this.options.radius, 0.002, 0),
			new THREE.Vector3(this.options.radius, 0.002, 0),
			new THREE.Vector3(0, 0.002, -this.options.radius),
			new THREE.Vector3(0, 0.002, this.options.radius),
		];
		const geometry = new THREE.BufferGeometry().setFromPoints(points);
		this.cross = new THREE.LineSegments(geometry, lineMaterial);
		this.add(this.cross);

		if (this.options.previewObject) {
			this.previewObject = this.options.previewObject.clone();
			this.previewObject.position.y = 0.05;
			this.add(this.previewObject);
		}
	}

	/**
	 * Switches the reticle between valid and invalid visual states.
	 * @param {boolean} valid - Whether the current placement is valid.
	 * @returns {void}
	 */
	setValid(valid) {
		this.valid = Boolean(valid);
		this.ring.material = this.valid ? this._validMaterial : this._invalidMaterial;
		this.cross.material.color.setHex(this.valid ? this.options.color : this.options.invalidColor);
	}

	/**
	 * Copies a normalized AR hit matrix into the reticle and toggles visibility.
	 * @param {object|null} hit - Normalized hit returned by {@link ARRealWorldHitTestManager#update}.
	 * @returns {void}
	 */
	updateFromHit(hit) {
		if (!hit?.matrix) {
			this.visible = false;
			this.setValid(false);
			return;
		}

		this.matrix.copy(hit.matrix);
		this.visible = true;
		this.setValid(true);
	}

	/**
	 * Disposes geometries and materials owned by the reticle.
	 * @returns {void}
	 */
	dispose() {
		this.ring.geometry.dispose();
		this._validMaterial.dispose();
		this._invalidMaterial.dispose();
		this.cross.geometry.dispose();
		this.cross.material.dispose();
	}
}
