import * as THREE from 'three';
import { merge } from 'lodash';
import { VRMenu, defaultOptions as menuDefaultOptions } from './VRMenu.js';
import {
	EventTypes as CanvasSurfaceEventTypes,
	hitTestZones,
	uvToCanvasPoint,
} from './CanvasInteractiveSurface.js';

/**
 * @module VRGuidePanel
 * @description
 * Provides a canvas-rendered tutorial/wizard panel for XR scenes, with step
 * navigation, command hit zones, audio, language changes, and completion flow.
 */

/**
 * Event type constants dispatched by {@link VRGuidePanel}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when a step becomes active. */
	STEP_ENTER: 'stepenter',
	/** Fired before leaving the previous step. */
	STEP_EXIT: 'stepexit',
	/** Fired when a step hit zone emits a command. */
	COMMAND: 'command',
	/** Fired after the guide language changes. */
	LANGUAGE_CHANGE: 'languagechange',
	/** Fired when the guide reaches completion. */
	COMPLETE: 'complete',
	/** Fired when the guide is dismissed by a command or API call. */
	DISMISS: 'dismiss',
};

export const defaultOptions = merge({}, menuDefaultOptions, {
	width: 1024,
	height: 576,
	steps: [],
	language: 'en',
	autoplayAudio: true,
	audioVolume: 1,
	closeOnComplete: false,
});

function normalizeConstructorArgs(stepsOrWorldContainer, worldOrControllers, controllersOrOptions, maybeOptions) {
	if (Array.isArray(stepsOrWorldContainer)) {
		return {
			steps: stepsOrWorldContainer,
			worldContainer: worldOrControllers,
			controllersManager: controllersOrOptions,
			options: maybeOptions || {},
		};
	}

	const options = controllersOrOptions || {};
	return {
		steps: options.steps || [],
		worldContainer: stepsOrWorldContainer,
		controllersManager: worldOrControllers,
		options,
	};
}

/**
 * Floating tutorial/wizard panel for XR applications.
 *
 * Steps provide their own canvas renderer and optional validation event. The
 * guide only owns flow, hit-zone commands, audio, and lifecycle events.
 *
 * @extends VRMenu
 *
 * @example
 * const guide = new VRGuidePanel(scene, controllersManager, {
 *   steps: [
 *     {
 *       id: 'welcome',
 *       render(ctx, guide) {
 *         ctx.fillText('Welcome', 64, 96);
 *       },
 *       hitZones: [{ command: 'next', rect: { x: 0.72, y: 0.78, w: 0.2, h: 0.12 } }],
 *     },
 *   ],
 * });
 * guide.addEventListener(EventTypes.COMPLETE, () => guide.setVisible(false));
 */
export class VRGuidePanel extends VRMenu {
	/**
	 * Creates a guide panel. Supports either `(steps, worldContainer, controllersManager, options)`
	 * or `(worldContainer, controllersManager, optionsWithSteps)`.
	 * @param {Array<object>|THREE.Group} stepsOrWorldContainer - Steps array or world container.
	 * @param {THREE.Group|ControllersManager} worldOrControllers - World container or controllers manager.
	 * @param {ControllersManager|object} controllersOrOptions - Controllers manager or options object.
	 * @param {object} [maybeOptions] - Options when the first argument is a steps array.
	 */
	constructor(stepsOrWorldContainer, worldOrControllers, controllersOrOptions, maybeOptions) {
		const args = normalizeConstructorArgs(
			stepsOrWorldContainer,
			worldOrControllers,
			controllersOrOptions,
			maybeOptions
		);
		const options = merge({}, defaultOptions, args.options, { steps: args.steps });
		super(args.worldContainer, args.controllersManager, options);

		this.options = options;
		this._steps = [...(options.steps || [])];
		this._stepIndex = -1;
		this._stepById = new Map(this._steps.map((step, index) => [step.id, index]));
		this._activeZone = null;
		this._audio = null;
		this._completeWhen = null;
		this._language = options.language || 'en';

		this._canvas = document.createElement('canvas');
		this._canvas.width = options.width;
		this._canvas.height = options.height;
		this._ctx = this._canvas.getContext('2d');

		this._map = new THREE.CanvasTexture(this._canvas);
		this._map.colorSpace = THREE.SRGBColorSpace;
		this._map.minFilter = THREE.LinearFilter;
		this._map.magFilter = THREE.LinearFilter;
		this._map.generateMipmaps = false;
		this._frontMaterial.map = this._map;
		this._frontMaterial.needsUpdate = true;
		this._mesh.userData = { class: 'VRGuidePanel' };
		this._updateAspectRatio(this._canvas.width, this._canvas.height, this._canvas.width, this._canvas.height);

		if (this._steps.length) this.goTo(0);
	}

	get canvas() {
		return this._canvas;
	}

	get context() {
		return this._ctx;
	}

	get steps() {
		return this._steps;
	}

	get currentStep() {
		return this._steps[this._stepIndex] || null;
	}

	get stepIndex() {
		return this._stepIndex;
	}

	get language() {
		return this._language;
	}

	setLanguage(language) {
		if (!language || language === this._language) return false;
		const previousLanguage = this._language;
		this._language = language;
		this.options.language = language;
		this.render();
		this._playStepAudio();
		this.dispatchEvent({
			type: EventTypes.LANGUAGE_CHANGE,
			language,
			previousLanguage,
			step: this.currentStep,
			index: this._stepIndex,
			guide: this,
		});
		return true;
	}

	resolveContent(step = this.currentStep, language = this._language) {
		if (!step) return null;
		return {
			title: this._resolveLocalizedValue(step.title, language),
			body: this._resolveLocalizedValue(step.body, language),
			image: this._resolveLocalizedValue(step.image, language),
			audio: this._resolveLocalizedValue(step.audio, language),
		};
	}

	setSteps(steps = []) {
		this._teardownStepValidation();
		this._steps = [...steps];
		this._stepById = new Map(this._steps.map((step, index) => [step.id, index]));
		this._stepIndex = -1;
		if (this._steps.length) this.goTo(0);
		else this.render();
	}

	goTo(target) {
		const nextIndex = typeof target === 'number' ? target : this._stepById.get(target);
		if (nextIndex == null || nextIndex < 0 || nextIndex >= this._steps.length) return false;
		if (nextIndex === this._stepIndex) {
			this.render();
			return true;
		}

		const previous = this.currentStep;
		if (previous) {
			this.dispatchEvent({
				type: EventTypes.STEP_EXIT,
				step: previous,
				index: this._stepIndex,
				guide: this,
			});
		}

		this._teardownStepValidation();
		this._stepIndex = nextIndex;
		this._setupStepValidation();
		this.render();
		this._playStepAudio();

		this.dispatchEvent({
			type: EventTypes.STEP_ENTER,
			step: this.currentStep,
			index: this._stepIndex,
			guide: this,
		});
		return true;
	}

	next() {
		const step = this.currentStep;
		if (!step) return false;
		const target = step.next ?? this._stepIndex + 1;
		if (target == null || target === false || this._stepIndex >= this._steps.length - 1) {
			this.complete();
			return true;
		}
		return this.goTo(target);
	}

	previous() {
		const step = this.currentStep;
		const target = step?.previous ?? this._stepIndex - 1;
		if (target == null || target === false) return false;
		return this.goTo(target);
	}

	close() {
		this.setVisible(false);
		this.dispatchEvent({
			type: EventTypes.DISMISS,
			step: this.currentStep,
			index: this._stepIndex,
			guide: this,
		});
	}

	complete() {
		this.dispatchEvent({
			type: EventTypes.COMPLETE,
			step: this.currentStep,
			index: this._stepIndex,
			guide: this,
		});
		if (this.options.closeOnComplete) this.close();
	}

	replayAudio() {
		this._playStepAudio(true);
	}

	executeCommand(command, event = {}) {
		this.dispatchEvent({
			type: EventTypes.COMMAND,
			command,
			step: this.currentStep,
			index: this._stepIndex,
			guide: this,
			...event,
		});

		switch (command) {
			case 'next':
				return this.next();
			case 'previous':
			case 'prev':
				return this.previous();
			case 'close':
			case 'dismiss':
				this.close();
				return true;
			case 'replayAudio':
			case 'audio':
				this.replayAudio();
				return true;
			default:
				if (typeof command === 'string' && command.startsWith('language:')) {
					return this.setLanguage(command.slice('language:'.length));
				}
				return false;
		}
	}

	render() {
		const step = this.currentStep;
		const ctx = this._ctx;
		const content = this.resolveContent(step);
		ctx.clearRect(0, 0, this._canvas.width, this._canvas.height);

		if (typeof step?.render === 'function') {
			step.render({
				ctx,
				canvas: this._canvas,
				step,
				content,
				guide: this,
				language: this._language,
				index: this._stepIndex,
				total: this._steps.length,
			});
		} else {
			this._renderFallbackStep(ctx, step, content);
		}

		this._map.needsUpdate = true;
	}

	invalidate() {
		this.render();
	}

	_onPointerEvent = (e) => {
		const point = e.uv ? uvToCanvasPoint(e.uv, this._canvas.width, this._canvas.height) : null;
		const step = this.currentStep;
		const hitZone = hitTestZones(step?.hitZones || [], point, this._canvas.width, this._canvas.height);
		const pointerEvent = {
			...e,
			pointPx: point,
			hitZone,
			step,
			guide: this,
		};

		if (e.type === CanvasSurfaceEventTypes.POINTER_DOWN) {
			this._activeZone = hitZone;
			if (hitZone?.trigger === 'down') this.executeCommand(hitZone.command || hitZone.id, { hitZone, pointerEvent });
		} else if (e.type === CanvasSurfaceEventTypes.POINTER_UP) {
			if (hitZone && hitZone === this._activeZone && hitZone.trigger !== 'down') {
				this.executeCommand(hitZone.command || hitZone.id, { hitZone, pointerEvent });
			}
			this._activeZone = null;
		} else if (e.type === CanvasSurfaceEventTypes.POINTER_UP_OUTSIDE) {
			this._activeZone = null;
		}
	};

	_renderFallbackStep(ctx, step, content = this.resolveContent(step)) {
		const W = this._canvas.width;
		const H = this._canvas.height;
		ctx.fillStyle = '#121820';
		ctx.fillRect(0, 0, W, H);
		ctx.fillStyle = '#4ecdc4';
		ctx.fillRect(0, 0, W, 18);
		ctx.fillStyle = '#ffffff';
		ctx.font = 'bold 52px Arial, sans-serif';
		ctx.fillText(content?.title || 'Guide', 48, 100);
		ctx.font = '32px Arial, sans-serif';
		ctx.fillStyle = '#dce6f0';
		const lines = Array.isArray(content?.body) ? content.body : [content?.body || 'No render function provided.'];
		lines.forEach((line, i) => ctx.fillText(line, 52, 170 + i * 46));
	}

	_resolveLocalizedValue(value, language = this._language) {
		if (value == null || Array.isArray(value)) return value;
		if (typeof value !== 'object') return value;
		if (Object.prototype.hasOwnProperty.call(value, language)) return value[language];
		if (Object.prototype.hasOwnProperty.call(value, 'default')) return value.default;
		if (Object.prototype.hasOwnProperty.call(value, 'en')) return value.en;
		const firstKey = Object.keys(value)[0];
		return firstKey ? value[firstKey] : undefined;
	}

	_setupStepValidation() {
		const step = this.currentStep;
		const completeWhen = step?.completeWhen;
		if (!completeWhen?.eventSource || !completeWhen.type) return;

		const handler = (event) => {
			if (typeof completeWhen.match === 'function' && !completeWhen.match(event)) return;
			if (completeWhen.command) this.executeCommand(completeWhen.command, { validationEvent: event });
			else this.next();
		};

		completeWhen.eventSource.addEventListener(completeWhen.type, handler);
		this._completeWhen = {
			eventSource: completeWhen.eventSource,
			type: completeWhen.type,
			handler,
		};
	}

	_teardownStepValidation() {
		if (!this._completeWhen) return;
		this._completeWhen.eventSource.removeEventListener(this._completeWhen.type, this._completeWhen.handler);
		this._completeWhen = null;
	}

	_playStepAudio(force = false) {
		const audioSrc = this.resolveContent(this.currentStep)?.audio;
		if (this._audio) {
			this._audio.pause();
			this._audio = null;
		}
		if (!audioSrc) return;
		if (!force && !this.options.autoplayAudio) return;

		this._audio = new Audio(audioSrc);
		this._audio.volume = this.options.audioVolume;
		this._audio.play().catch(() => {});
	}

	dispose() {
		this._teardownStepValidation();
		if (this._audio) {
			this._audio.pause();
			this._audio = null;
		}
		if (this._map) this._map.dispose();
		super.dispose();
	}
}
