import * as THREE from 'three';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';

/**
 * @module ARDepthOcclusionManager
 * @description
 * Wraps WebXR depth-sensing access and exposes a small state/event API for AR
 * scenes that need real-world depth awareness.
 */

/**
 * Event type constants dispatched by {@link ARDepthOcclusionManager}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when depth information becomes available. */
	DEPTH_AVAILABLE: 'depthAvailable',
	/** Fired when depth information is unavailable or becomes unavailable. */
	DEPTH_UNAVAILABLE: 'depthUnavailable',
};

/**
 * Reads WebXR depth information from the active XR frame.
 *
 * This class does not implement a complete occlusion shader by itself. It
 * centralizes depth availability checks, stores the last depth-information
 * object, and provides helper material creation for simple depth-mask meshes.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const depth = new ARDepthOcclusionManager(renderer);
 * depth.addEventListener(EventTypes.DEPTH_UNAVAILABLE, ({ reason }) => {
 *   console.warn(reason);
 * });
 *
 * renderer.setAnimationLoop((time, frame) => {
 *   depth.update(frame);
 * });
 */
export class ARDepthOcclusionManager extends EventsDispatcher {
	/**
	 * @param {THREE.WebGLRenderer|null} [renderer=null] - Renderer used to access the XR camera.
	 */
	constructor(renderer = null) {
		super();
		this.renderer = renderer;
		this.depthInformation = null;
		this.available = false;
		this.unavailableReason = 'Depth information has not been observed yet.';
	}

	/**
	 * Reads depth information for the current XR frame.
	 * @param {XRFrame} frame - Current XR frame.
	 * @returns {object|null} Depth information, or `null` when unavailable.
	 */
	update(frame) {
		if (!frame?.getDepthInformation || !this.renderer?.xr?.getCamera) {
			this._setUnavailable('WebXR depth sensing is not available in this runtime.');
			return null;
		}

		const xrCamera = this.renderer.xr.getCamera();
		const viewCamera = xrCamera?.cameras?.[0];
		if (!viewCamera) {
			this._setUnavailable('No XR camera view is available for depth sensing.');
			return null;
		}

		try {
			this.depthInformation = frame.getDepthInformation(viewCamera);
			if (this.depthInformation) {
				if (!this.available) this.dispatchEvent({ type: EventTypes.DEPTH_AVAILABLE, depthInformation: this.depthInformation });
				this.available = true;
				this.unavailableReason = '';
				return this.depthInformation;
			}
		} catch (error) {
			this._setUnavailable(error.message || String(error));
			return null;
		}

		this._setUnavailable('Depth information is not active for the current frame.');
		return null;
	}

	_setUnavailable(reason) {
		this.depthInformation = null;
		if (this.available || this.unavailableReason !== reason) {
			this.dispatchEvent({ type: EventTypes.DEPTH_UNAVAILABLE, reason });
		}
		this.available = false;
		this.unavailableReason = reason;
	}

	/**
	 * Creates a material suitable for invisible depth-mask geometry.
	 * @param {object} [options] - Material options.
	 * @param {number} [options.color=0x000000] - Debug color; color writes are disabled.
	 * @param {THREE.Side} [options.side=THREE.DoubleSide] - Render side for the mask.
	 * @returns {THREE.MeshBasicMaterial}
	 */
	createDepthMaskMaterial(options = {}) {
		return new THREE.MeshBasicMaterial({
			color: options.color ?? 0x000000,
			colorWrite: false,
			depthWrite: true,
			depthTest: true,
			side: options.side ?? THREE.DoubleSide,
		});
	}

	/**
	 * Returns the latest depth availability state.
	 * @returns {{available: boolean, depthInformation: object|null, unavailableReason: string}}
	 */
	getState() {
		return {
			available: this.available,
			depthInformation: this.depthInformation,
			unavailableReason: this.unavailableReason,
		};
	}
}
