import * as THREE from 'three';
import { ControllersManager } from './ControllersManager.js';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
import { VRInteractiveSurface } from './VRInteractiveSurface.js';
import { merge } from 'lodash';

/**
 * Default options for {@link VRInteractivePanel}.
 * @typedef {object} VRInteractivePanelOptions
 * @property {'panel'|'swatch'} [mode='panel'] - Placement mode used by subclasses.
 * @property {number} [debugLevel=0] - Enables visual helpers when greater than zero.
 * @property {number} [size=0.5] - Panel width in meters; height follows the content aspect ratio.
 * @property {'top'|'center'|'bottom'} [pivot='top'] - Stable vertical anchor used when laying out the mesh.
 */
export const defaultOptions = {
	mode: 'panel', // "swatch", "panel",
	debugLevel: 0,
	size: 0.5, // meters
	pivot: 'top', // "top", "center", "bottom"
};

/**
 * Builds centered unit-sized double-sided panel geometry. Runtime layout applies size and pivot.
 * Standalone (no `this`) so it can run before `super()` in the constructor.
 * @param {VRInteractivePanelOptions} options
 * @returns {THREE.BufferGeometry}
 */
function buildPanelGeometry(options) {
	// create geometry for the menu with front and back faces
	const frontface = new THREE.PlaneGeometry(1, 1);
	const backface = new THREE.PlaneGeometry(1, 1);
	backface.rotateY(Math.PI);
	let geo = new THREE.BufferGeometry();
	geo = BufferGeometryUtils.mergeGeometries([backface, frontface]);
	let c1 = frontface.index.count;
	let c2 = backface.index.count;
	geo.addGroup(0, c1, 0);
	geo.addGroup(c1, c2, 1);
	geo.computeBoundingBox();
	geo.computeBoundingSphere();
	return geo;
}

/**
 * Base class for owned, flat interactive 2D panels rendered inside a Three.js/WebXR scene.
 *
 * Specializes {@link VRInteractiveSurface} for the common case where the component, not the
 * application, owns a flat rectangular panel. The geometry-agnostic ray wiring (raycasting,
 * pointer-event emission, gesture ownership, optional BVH) is inherited from the base; this
 * class adds the generated double-sided mesh, front/back materials, texture aspect-ratio
 * fitting, visibility toggling, and a vertical-pivot container.
 *
 * Do not use this class for arbitrary app-provided meshes such as curved dashboards or domes.
 * Wrap those meshes directly with {@link VRInteractiveSurface}; use this class for floating
 * panels, menus, debug panels, and wizard/tutorial panels that need a standard rectangular
 * surface.
 *
 * Subclasses must implement {@link createMap} and {@link _onPointerEvent}.
 *
 * @extends VRInteractiveSurface
 */
export class VRInteractivePanel extends VRInteractiveSurface {
	_container;
	_map;

	_mapYScale = 1;
	_mapYOffset = 0;
	_contentAspect = 1;

	_frontMaterial;
	_backMaterial;

	/**
	 * @param {THREE.Group} worldContainer - Scene node that owns the panel in world/panel mode.
	 * @param {ControllersManager} controllersManager - Shared ControllersManager instance.
	 * @param {VRInteractivePanelOptions} [options] - Options merged with {@link defaultOptions}.
	 */
	constructor(worldContainer, controllersManager, options) {
		if (worldContainer === undefined || controllersManager === undefined) {
			throw Error('VRInteractivePanel: Missing parameters');
		}
		const opts = merge({}, defaultOptions, options);
		if (!Number.isFinite(opts.size) || opts.size <= 0) {
			throw new RangeError('VRInteractivePanel: size must be greater than zero');
		}
		if (!['top', 'center', 'bottom'].includes(opts.pivot)) {
			throw new RangeError("VRInteractivePanel: pivot must be 'top', 'center', or 'bottom'");
		}

		// Build the mesh with locals (no `this`) so it can be passed to super().
		const frontMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
		const backMaterial = new THREE.MeshBasicMaterial({ color: 0xaaaaaa });
		const mesh = new THREE.Mesh(buildPanelGeometry(opts), [backMaterial, frontMaterial]);
		mesh.userData = { class: 'VRInteractivePanel' };

		super(mesh, worldContainer, controllersManager, opts);

		this._frontMaterial = frontMaterial;
		this._backMaterial = backMaterial;

		// The hit-test mesh lives inside a container so subclasses can apply a vertical pivot
		// and toggle visibility at the group level.
		this._container = new THREE.Group();
		this._container.add(this._mesh);
		this._applyPanelLayout();

		// axes helper
		if (opts.debugLevel > 0) this._container.add(new THREE.AxesHelper(0.25));
	}

	/**
	 * Whether controller rays should currently be tested against this panel.
	 * Panels gate on the container visibility (the mesh stays `visible` inside it).
	 * @returns {boolean}
	 */
	shouldTestRayEvents() {
		return this._enabled && this._container.visible;
	}

	/**
	 * Applies the panel's aspect-ratio remap to the raw intersection UV before emitting it,
	 * so DOM-backed subclasses receive coordinates that map the content over the whole mesh.
	 * @param {THREE.Intersection|null} intersection
	 * @returns {THREE.Vector2|undefined}
	 */
	_buildPointerUV(intersection) {
		if (!intersection || !intersection.uv) return undefined;
		const coords = intersection.uv.clone();
		coords.y = coords.y * this._mapYScale + this._mapYOffset;
		return coords;
	}

	/**
	 * Sets the panel container visibility.
	 * @param {boolean} visible
	 */
	setVisible(visible) {
		this._container.visible = visible;
	}

	/**
	 * Toggles the panel visibility.
	 */
	toggleVisibility() {
		this._container.visible = !this._container.visible;
		this.setVisible(this._container.visible);
	}

	/**
	 * Updates the panel texture mapping and mesh scale to fit content pixels.
	 * @param {number} canvasWidthPx - Source canvas width in pixels.
	 * @param {number} canvasHeightPx - Source canvas height in pixels.
	 * @param {number} contentWidthPx - Width of the meaningful content inside the canvas.
	 * @param {number} contentHeightPx - Height of the meaningful content inside the canvas.
	 */
	_updateAspectRatio(canvasWidthPx, canvasHeightPx, contentWidthPx, contentHeightPx) {
		if (![canvasWidthPx, canvasHeightPx, contentWidthPx, contentHeightPx].every(Number.isFinite)) {
			throw new TypeError('VRInteractivePanel: aspect dimensions must be finite numbers');
		}
		if (canvasWidthPx <= 0 || canvasHeightPx <= 0 || contentWidthPx <= 0 || contentHeightPx <= 0) {
			throw new RangeError('VRInteractivePanel: aspect dimensions must be greater than zero');
		}
		const aspect = contentWidthPx / contentHeightPx;
		const canvasAspect = canvasWidthPx / canvasHeightPx;

		// map 0 .. contentHeightPx to 0 .. 1, to cover the whole mesh with the UI pixels only
		// Canvas and content dimensions may use different pixel scales (for example a 2x
		// renderer canvas). Comparing their aspect ratios avoids treating resolution scale
		// as empty texture space while still cropping genuine vertical padding.
		const yScale = Math.min(1, canvasAspect / aspect); // map scaling factor
		// We center the map in the canvas, vertically
		const yOffset = 1 - yScale;

		// extend the area covered by the content, to cover the whole canvas
		this._map.offset.set(0, yOffset);
		this._map.repeat.set(1, yScale);

		this._contentAspect = aspect;
		this._applyPanelLayout();
		/*
		if (this.options.debugLevel > 0) {
			console.log('_updateUiAspectRatio()');
			console.log('canvas w,h:', canvasWidthPx, canvasHeightPx);
			console.log('contentHeightPx:', contentHeightPx);
			console.log('yOffset:', yOffset);
			console.log('yScale:', yScale);
			console.log('aspect:', aspect);
		}*/

		this._mapYOffset = yOffset;
		this._mapYScale = yScale;
	}

	_applyPanelLayout() {
		const width = this.options.size;
		const height = width / this._contentAspect;
		this._mesh.scale.set(width, height, 1);

		if (this.options.pivot === 'top') this._mesh.position.y = -height / 2;
		else if (this.options.pivot === 'bottom') this._mesh.position.y = height / 2;
		else this._mesh.position.y = 0;
	}

	setSize(widthMeters) {
		if (!Number.isFinite(widthMeters) || widthMeters <= 0) {
			throw new RangeError('VRInteractivePanel.setSize: widthMeters must be greater than zero');
		}
		this.options.size = widthMeters;
		this._applyPanelLayout();
		return this;
	}

	setPivot(pivot) {
		if (!['top', 'center', 'bottom'].includes(pivot)) {
			throw new RangeError("VRInteractivePanel.setPivot: pivot must be 'top', 'center', or 'bottom'");
		}
		this.options.pivot = pivot;
		this._applyPanelLayout();
		return this;
	}

	get panelSize() {
		return { width: this.options.size, height: this.options.size / this._contentAspect };
	}

	/**
	 * Creates the texture map used by the front material.
	 * Must be implemented by subclasses.
	 */
	createMap() {
		throw Error('Should be implemented in a subclass');
	}

	/**
	 * Handles normalized pointer events emitted from controller ray intersections.
	 * Must be implemented by subclasses.
	 * @param {object} e
	 * @param {string} e.type
	 * @param {THREE.Vector2} [e.data]
	 */
	_onPointerEvent = (e) => {
		// e.type: pointerdown,pointerup,pointermove,pointerupoutside
		// e.data: x,y in [0,1] range. e.data may be undefined
		throw Error('Should be implemented in a subclass');
	};

	/**
	 * The panel container object (add this to the scene).
	 * @type {THREE.Group}
	 */
	get mesh() {
		return this._container;
	}

	/**
	 * The front and back panel materials.
	 * @type {THREE.Material[]}
	 */
	get materials() {
		return [this._frontMaterial, this._backMaterial];
	}
}
