/** Default safety limits for detached debug-value snapshots. */
export const SNAPSHOT_LIMITS = {
	maxDepth: 6,
	maxProperties: 100,
	maxStringLength: 10_000,
};

function truncateString(value, maxLength) {
	if (value.length <= maxLength) return value;
	return `${value.slice(0, maxLength)}… <${value.length - maxLength} chars truncated>`;
}

function safeConstructorName(value) {
	try {
		const prototype = Object.getPrototypeOf(value);
		const descriptor = prototype && Object.getOwnPropertyDescriptor(prototype, 'constructor');
		return typeof descriptor?.value === 'function' ? descriptor.value.name || 'Object' : 'Object';
	} catch (_) {
		return 'Object';
	}
}

function isInstance(value, constructor) {
	try {
		return value instanceof constructor;
	} catch (_) {
		return false;
	}
}

function primitiveSnapshot(value, limits) {
	if (value === null) return { type: 'null', text: 'null' };
	if (value === undefined) return { type: 'undefined', text: 'undefined' };
	if (typeof value === 'string') return { type: 'string', text: truncateString(value, limits.maxStringLength) };
	if (typeof value === 'number') {
		const text = Object.is(value, -0) ? '-0' : String(value);
		return { type: 'number', text };
	}
	if (typeof value === 'bigint') return { type: 'bigint', text: `${value}n` };
	if (typeof value === 'boolean') return { type: 'boolean', text: String(value) };
	if (typeof value === 'symbol') return { type: 'symbol', text: String(value) };
	if (typeof value === 'function') return { type: 'function', text: `ƒ ${value.name || '(anonymous)'}()` };
	return null;
}

function makeProperty(key, value) {
	return { key: typeof key === 'symbol' ? `[${String(key)}]` : String(key), value };
}

function snapshotObject(value, state, depth) {
	const previousId = state.seen.get(value);
	if (previousId) return { type: 'reference', text: `↳ #${previousId}` };

	const id = state.nextId++;
	state.seen.set(value, id);
	const node = { type: 'object', id, label: safeConstructorName(value), properties: [], truncated: false };

	if (isInstance(value, Date)) {
		node.type = 'date';
		try {
			node.label = Number.isNaN(value.getTime()) ? 'Invalid Date' : value.toISOString();
		} catch (_) {
			node.label = 'Date <uninspectable>';
		}
		return node;
	}
	if (isInstance(value, RegExp)) {
		node.type = 'regexp';
		try { node.label = String(value); } catch (_) { node.label = 'RegExp <uninspectable>'; }
		return node;
	}
	if (isInstance(value, Error)) {
		node.type = 'error';
		node.label = `${value.name || 'Error'}${value.message ? `: ${value.message}` : ''}`;
		if (value.stack) node.properties.push(makeProperty('stack', primitiveSnapshot(String(value.stack), state.limits)));
	}

	let isArray = false;
	try { isArray = Array.isArray(value); } catch (_) { /* revoked proxy */ }
	if (isArray) {
		node.type = 'array';
		node.label = `Array(${value.length})`;
	}
	const isMap = isInstance(value, Map);
	const isSet = isInstance(value, Set);
	if (isMap) {
		node.type = 'map';
		try { node.label = `Map(${value.size})`; } catch (_) { node.label = 'Map <uninspectable>'; }
	}
	if (isSet) {
		node.type = 'set';
		try { node.label = `Set(${value.size})`; } catch (_) { node.label = 'Set <uninspectable>'; }
	}
	let isTypedArray = false;
	try { isTypedArray = ArrayBuffer.isView(value) && !isInstance(value, DataView); } catch (_) { /* revoked proxy */ }
	if (isTypedArray) {
		node.type = 'typedarray';
		node.label = `${safeConstructorName(value)}(${value.length})`;
	}

	if (depth >= state.limits.maxDepth) {
		node.truncated = true;
		return node;
	}

	if (isMap) {
		let index = 0;
		try {
			for (const [key, item] of value) {
				if (index >= state.limits.maxProperties) {
					node.truncated = true;
					break;
				}
				const pair = {
					type: 'object', id: state.nextId++, label: 'Map entry', properties: [
						makeProperty('key', snapshotAny(key, state, depth + 2)),
						makeProperty('value', snapshotAny(item, state, depth + 2)),
					], truncated: false,
				};
				node.properties.push(makeProperty(index++, pair));
			}
		} catch (_) { node.label += ' <uninspectable>'; }
		return node;
	}

	if (isSet) {
		let index = 0;
		try {
			for (const item of value) {
				if (index >= state.limits.maxProperties) {
					node.truncated = true;
					break;
				}
				node.properties.push(makeProperty(index++, snapshotAny(item, state, depth + 1)));
			}
		} catch (_) { node.label += ' <uninspectable>'; }
		return node;
	}

	let descriptors;
	try {
		descriptors = Object.getOwnPropertyDescriptors(value);
	} catch (_) {
		node.label += ' <uninspectable>';
		return node;
	}

	let keys;
	try { keys = Reflect.ownKeys(descriptors); } catch (_) { keys = []; }
	for (const key of keys) {
		if (node.type === 'error' && (key === 'stack' || key === 'message' || key === 'name')) continue;
		if (key === 'length' && (node.type === 'array' || node.type === 'typedarray')) continue;
		if (node.properties.length >= state.limits.maxProperties) {
			node.truncated = true;
			break;
		}
		const descriptor = descriptors[key];
		let child;
		if ('value' in descriptor) child = snapshotAny(descriptor.value, state, depth + 1);
		else {
			const label = descriptor.get && descriptor.set ? '(getter/setter)' : descriptor.get ? '(getter)' : '(setter)';
			child = { type: 'accessor', text: label };
		}
		node.properties.push(makeProperty(key, child));
	}
	return node;
}

function snapshotAny(value, state, depth = 0) {
	const primitive = primitiveSnapshot(value, state.limits);
	return primitive || snapshotObject(value, state, depth);
}

/** Creates a detached snapshot without invoking object accessors. */
export function snapshotDebugValue(value, limits = {}) {
	const resolvedLimits = { ...SNAPSHOT_LIMITS, ...limits };
	return snapshotAny(value, { limits: resolvedLimits, seen: new WeakMap(), nextId: 1 });
}

/** Creates multiple snapshots sharing circular-reference tracking. */
export function snapshotDebugValues(values, limits = {}) {
	const state = {
		limits: { ...SNAPSHOT_LIMITS, ...limits },
		seen: new WeakMap(),
		nextId: 1,
	};
	return values.map((value) => snapshotAny(value, state));
}
