import { EventsDispatcher } from '../utils/EventsDispatcher.js';

/**
 * @module XRAnchorManager
 * @description
 * Maintains WebXR anchors and optionally keeps attached Three.js objects aligned
 * with those anchors as tracking updates.
 */

/**
 * Event type constants dispatched by {@link XRAnchorManager}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired after an anchor is created successfully. */
	ANCHOR_CREATED: 'anchorCreated',
	/** Fired after an anchor is removed from the manager. */
	ANCHOR_REMOVED: 'anchorRemoved',
	/** Fired when the runtime does not support anchor creation for a hit. */
	ANCHOR_UNAVAILABLE: 'anchorUnavailable',
	/** Fired every frame when an anchor pose is resolved. */
	ANCHOR_UPDATE: 'anchorUpdate',
	/** Fired when anchor creation fails. */
	ERROR: 'error',
};

/**
 * Tracks WebXR anchors created from AR hit-test results.
 *
 * If an object is passed to {@link XRAnchorManager#createAnchorFromHit}, the
 * manager updates that object's transform every frame while the anchor is
 * tracked.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const anchors = new XRAnchorManager();
 * const entry = await anchors.createAnchorFromHit(hit, placedObject);
 *
 * renderer.setAnimationLoop((time, frame) => {
 *   anchors.update(frame, renderer.xr.getReferenceSpace());
 * });
 */
export class XRAnchorManager extends EventsDispatcher {
	/**
	 * Creates an empty anchor manager.
	 */
	constructor() {
		super();
		this.anchors = [];
	}

	/**
	 * Creates a WebXR anchor from a normalized AR hit-test result.
	 * @param {object} hit - Normalized hit returned by {@link ARRealWorldHitTestManager}.
	 * @param {THREE.Object3D|null} [object=null] - Optional object whose transform should follow the anchor.
	 * @returns {Promise<object|null>} Anchor entry, or `null` when unavailable or rejected.
	 */
	async createAnchorFromHit(hit, object = null) {
		if (!hit?.rawHit?.createAnchor) {
			this.dispatchEvent({
				type: EventTypes.ANCHOR_UNAVAILABLE,
				reason: 'XRHitTestResult.createAnchor is not available in this runtime.',
				object,
			});
			return null;
		}

		try {
			const anchor = await hit.rawHit.createAnchor();
			const entry = { anchor, object, lastPose: null };
			this.anchors.push(entry);
			this.dispatchEvent({ type: EventTypes.ANCHOR_CREATED, anchor, object, entry });
			return entry;
		} catch (error) {
			this.dispatchEvent({ type: EventTypes.ERROR, error, object });
			return null;
		}
	}

	/**
	 * Updates tracked anchors and attached objects for the current XR frame.
	 * @param {XRFrame} frame - Current XR frame.
	 * @param {XRReferenceSpace} referenceSpace - Reference space used to resolve anchor poses.
	 * @returns {void}
	 */
	update(frame, referenceSpace) {
		if (!frame || !referenceSpace) return;
		const trackedAnchors = frame.trackedAnchors;

		for (const entry of this.anchors) {
			if (trackedAnchors && !trackedAnchors.has(entry.anchor)) continue;
			const pose = frame.getPose(entry.anchor.anchorSpace, referenceSpace);
			if (!pose) continue;

			entry.lastPose = pose;
			if (entry.object) {
				entry.object.matrix.fromArray(pose.transform.matrix);
				entry.object.matrix.decompose(entry.object.position, entry.object.quaternion, entry.object.scale);
			}
			this.dispatchEvent({ type: EventTypes.ANCHOR_UPDATE, ...entry });
		}
	}

	/**
	 * Removes one anchor entry or raw `XRAnchor` from the manager.
	 * @param {object|XRAnchor} entryOrAnchor - Entry returned by `createAnchorFromHit`, or the raw anchor.
	 * @returns {void}
	 */
	remove(entryOrAnchor) {
		const index = this.anchors.findIndex((entry) => entry === entryOrAnchor || entry.anchor === entryOrAnchor);
		if (index < 0) return;
		const [entry] = this.anchors.splice(index, 1);
		if (entry.anchor?.delete) entry.anchor.delete();
		this.dispatchEvent({ type: EventTypes.ANCHOR_REMOVED, ...entry });
	}

	/**
	 * Removes all tracked anchors.
	 * @returns {void}
	 */
	clear() {
		[...this.anchors].forEach((entry) => this.remove(entry));
	}

	/**
	 * Whether at least one anchor is currently tracked by this manager.
	 * @type {boolean}
	 */
	get isTrackingAnchors() {
		return this.anchors.length > 0;
	}
}
