/**
 * Mouse Proxy with optional native <input type="range"> adapter.
 *
 * Overview
 * --------
 * This utility maps normalized coordinates (xNorm, yNorm in [0..1]) inside a given `root`
 * to real viewport coordinates, resolves the target using `document.elementFromPoint`,
 * and dispatches standard mouse events (`mousedown`, `mousemove`, `mouseup`) to the
 * element under that point. If `down` and `up` happen on the same "activatable" element
 * (button/link/tab/etc.), it also triggers a `click` (via `.click()` when possible).
 *
 * Why the native range adapter?
 * -----------------------------
 * Native sliders (`<input type="range">`) in browsers often ignore non-trusted synthetic
 * mouse events for moving the thumb. Even if the thumb graphic moves, frameworks like
 * React may not observe a value change unless the *native* value setter is used and
 * `input`/`change` events are dispatched.
 *
 * The optional adapter:
 *  - Tracks when a gesture starts on a native range.
 *  - Computes the candidate value from the cursor X position.
 *  - Commits the value only on `mouseup` using the native value setter, then fires
 *    `input` + `change` so React/other bindings update derived UI (e.g., a textbox).
 *
 * Notes
 * -----
 * - Works even when the UI is visually occluded (e.g., by a <canvas>) by temporarily
 *   disabling `pointer-events` on those occluders during hit-testing only.
 * - Does not rearrange DOM or styles (no layout side effects).
 * - Limitations of the web still apply: `<select>`/`<input type="file">` won’t open
 *   native popovers from non-trusted events, etc.
 */

// --- Small helpers & configuration ---

// Helper to avoid spamming events when the value did not change.
function setRangeValueIfChanged(el, newVal, { fireChange } = { fireChange: false }) {
	const s = String(newVal);
	if (el.value !== s) {
		nativeSetInputValue(el, s);
		el.dispatchEvent(new Event('input', { bubbles: true })); // live update
	}
	if (fireChange) {
		el.dispatchEvent(new Event('change', { bubbles: true })); // final commit
	}
}

/** Clamp v to [0,1]. */
const clamp01 = (v) => Math.max(0, Math.min(1, v));

/** CSS selector for elements that should be "click-activated". */
const ACTIVATABLE_SEL = [
	'button',
	'a',
	'label',
	'summary',
	'[role="button"]',
	'[role="tab"]',
	'[data-bs-toggle]',
	'.nav-link',
	'input',
	'textarea',
	'select',
].join(',');

/**
 * Returns the nearest "activatable" ancestor for `el`, or `el` itself as fallback.
 * Used to decide where a synthetic `click` should land when down/up match.
 */
function activatableAncestor(el) {
	return el.closest?.(ACTIVATABLE_SEL) || el;
}

/**
 * Builds a MouseEventInit with coherent coordinates and button state.
 * - Sets bubbles/cancelable/composed to true.
 * - Derives `view` from the root's document.
 * - Provides client/page/screen coordinates.
 * - Uses button=0 and buttons=1 for mousedown, buttons=0 otherwise (unless overridden).
 */
function buildMouseInit(root, clientX, clientY, type, buttonsOverride) {
	const view = root.ownerDocument.defaultView;
	return {
		bubbles: true,
		cancelable: true,
		composed: true,
		view,
		clientX,
		clientY,
		pageX: clientX + (view?.scrollX ?? 0),
		pageY: clientY + (view?.scrollY ?? 0),
		button: 0,
		buttons: typeof buttonsOverride === 'number' ? buttonsOverride : type === 'mousedown' ? 1 : 0,
	};
}

// --- Native <input type="range"> adapter helpers ---

/** Clamp v to [a,b]. */
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

/** Snap `raw` to the (min, step) grid; if step invalid, return raw. */
const roundToStep = (raw, min, step) => {
	if (!step || !isFinite(step) || step <= 0) return raw;
	const k = Math.round((raw - min) / step);
	return min + k * step;
};

/**
 * Compute the slider value from a given clientX, respecting min/max/step and RTL.
 * Returns a number (not string).
 */
function valueFromClientX(rangeEl, clientX) {
	const r = rangeEl.getBoundingClientRect();
	if (r.width === 0) return Number(rangeEl.value) || 0;

	const min = parseFloat(rangeEl.min || '0');
	const max = parseFloat(rangeEl.max || '100');
	const step = parseFloat(rangeEl.step || '1');

	let t = clamp((clientX - r.left) / r.width, 0, 1);
	const rtl = rangeEl.dir === 'rtl' || rangeEl.closest?.('[dir="rtl"]');
	if (rtl) t = 1 - t;

	const raw = min + (max - min) * t;
	return roundToStep(raw, min, step);
}

/**
 * Set an input's value using the native setter so React/trackers can detect it.
 * Falls back to direct assignment if no setter is found.
 */
function nativeSetInputValue(el, v) {
	const proto = Object.getPrototypeOf(el);
	const desc = Object.getOwnPropertyDescriptor(proto, 'value');
	const set = desc?.set;
	if (set) set.call(el, String(v));
	else el.value = String(v);
}

/**
 * Create a mouse proxy bound to `root`.
 *
 * @param {Element} root
 *   The root whose visual area [0..1]x[0..1] we map coordinates into.
 *
 * @param {Object} [options]
 * @param {Element[]} [options.occluders=[]]
 *   Elements (e.g. a WebGL <canvas>) that visually sit on top of the UI and would
 *   block hit-testing. The proxy temporarily sets `pointer-events:none` on them
 *   when resolving the target, then restores the original value.
 *
 * @param {boolean} [options.adaptNativeRange=true]
 *   If true, when a gesture starts on a native <input type="range">, the proxy commits
 *   the computed value on mouseup using the native setter + dispatches `input` and
 *   `change` so React/other bindings get notified.
 *
 * @param {boolean} [options.liveRangeDrag=false]
 *   If true, when dragging a native <input type="range"> the adapter updates the
 *   slider’s value on each `mousemove` (dispatching an `input` event), and then
 *   emits a single `change` on `mouseup`. If false, no updates are applied during
 *   the drag; the value is committed only on `mouseup`.
 *
 * @returns {{
 *   move: (xNorm:number, yNorm:number) => boolean,
 *   down: (xNorm:number, yNorm:number) => boolean,
 *   up:   (xNorm:number, yNorm:number) => boolean,
 *   dispose: () => void
 * }}
 *   An object with clean mouse methods. Call `dispose()` to clear internal state.
 */
export function createMouseProxy(root, { occluders = [], adaptNativeRange = true, liveRangeDrag = false } = {}) {
	// Tracks whether the pointer is down and the last down target for click synthesis.
	let isDown = false;
	let downTarget = null;

	// Tracks the element currently hovered for basic over/out semantics (optional).
	let lastOver = null;

	// Adapter state: active native range and the pending (uncommitted) value.
	let rangeActiveEl = null;
	let rangePendingValue = null;

	/**
	 * Temporarily disable pointer-events on occluders while running `fn`, then restore.
	 * Keeps layout untouched and avoids DOM movement to hit-test accurately.
	 */
	const withOccludersDisabled = (fn) => {
		const prev = occluders.map((el) => el.style.pointerEvents);
		occluders.forEach((el) => (el.style.pointerEvents = 'none'));
		try {
			return fn();
		} finally {
			occluders.forEach((el, i) => (el.style.pointerEvents = prev[i]));
		}
	};

	let lastNorm = { x: 0.5, y: 0.5 };

	/**
	 * Convert normalized coordinates (0..1) to viewport space inside `root`.
	 * Returns `{x, y}` in client (viewport) coordinates.
	 */
	const coords = (xNorm, yNorm) => {
		const r = root.getBoundingClientRect();
		return {
			x: r.left + clamp01(xNorm) * r.width,
			y: r.top + clamp01(yNorm) * r.height,
		};
	};

	const setLast = (xNorm, yNorm) => {
		lastNorm = { x: clamp01(xNorm), y: clamp01(yNorm) };
		return lastNorm;
	};

	/**
	 * Resolve the element at (x,y) using document.elementFromPoint,
	 * with occluders temporarily disabled. Falls back to `root`.
	 */
	const hit = (x, y) => withOccludersDisabled(() => document.elementFromPoint(x, y)) || root;

	/**
	 * Dispatch a standard MouseEvent on `el` with the given init.
	 * Returns `true` if not canceled, `false` otherwise.
	 */
	const dispatch = (el, type, init) => el.dispatchEvent(new MouseEvent(type, init));

	/**
	 * Move the mouse to (xNorm, yNorm).
	 * - Sends mouseover/mouseout when the hovered element changes (basic semantics).
	 * - Sends a `mousemove` with `buttons=1` while dragging, else `buttons=0`.
	 */

	const move = (xNorm, yNorm) => {
		setLast(xNorm, yNorm);
		const { x, y } = coords(lastNorm.x, lastNorm.y);
		const target = hit(x, y);

		// Optional hover handling.
		// Standard mousemove event.
		dispatch(target, 'mousemove', buildMouseInit(root, x, y, 'mousemove', isDown ? 1 : 0));

		// ⬇️ adapter: live drag
		if (adaptNativeRange && isDown && rangeActiveEl) {
			const v = valueFromClientX(rangeActiveEl, x);
			if (liveRangeDrag) {
				// Update the DOM and notify React onChange at every step via input.
				setRangeValueIfChanged(rangeActiveEl, v, { fireChange: false });
				// Keep the latest value for the mouseup commit.
				rangePendingValue = v;
			} else {
				// Only remember the candidate value for mouseup.
				rangePendingValue = v;
			}
		}
		return true;
	};

	/**
	 * Press the primary button at (xNorm, yNorm).
	 * - Focuses the target to mimic native behavior (prevents scroll).
	 * - Sends `mousedown` with `buttons=1`.
	 * - If over a native range, starts tracking it (without changing its value yet).
	 */
	const down = (xNorm, yNorm) => {
		setLast(xNorm, yNorm);
		const { x, y } = coords(lastNorm.x, lastNorm.y);

		const target = hit(x, y);
		target.focus?.({ preventScroll: true });

		isDown = true;
		downTarget = target;
		lastOver = target;

		// Standard down
		dispatch(target, 'mousedown', buildMouseInit(root, x, y, 'mousedown', 1));

		// Adapter: begin tracking native range under pointer
		if (adaptNativeRange) {
			const rangeEl =
				(target instanceof HTMLInputElement && target.type === 'range') ||
				target?.closest?.('input[type="range"]');

			rangeActiveEl = null;
			rangePendingValue = null;

			if (rangeEl) {
				// If closest(...) returned an element, use it; if boolean true (from instanceof),
				// target is already the range.
				const resolvedRange = rangeEl instanceof Element ? rangeEl : target;
				rangeActiveEl = resolvedRange;
				rangePendingValue = valueFromClientX(resolvedRange, x); // candidate only
			}
		}
		return true;
	};

	/**
	 * Release the primary button at (xNorm, yNorm).
	 * - Sends `mouseup` with `buttons=0`.
	 * - If a native range was active, commits the pending value using the native setter,
	 *   then dispatches `input` + `change` (so frameworks like React update bound UI).
	 * - If `down` and `up` happen on the same "activatable" element, also triggers a click.
	 */
	// up(): final commit
	const up = (xNorm, yNorm) => {
		// If no coordinates are provided, use the last known position.
		if (typeof xNorm !== 'number' || typeof yNorm !== 'number') {
			xNorm = lastNorm.x;
			yNorm = lastNorm.y;
		} else {
			setLast(xNorm, yNorm);
		}
		const { x, y } = coords(xNorm, yNorm);

		const target = hit(x, y);

		const res = dispatch(target, 'mouseup', buildMouseInit(root, x, y, 'mouseup', 0));

		if (adaptNativeRange && rangeActiveEl) {
			// If live updates were active, only ensure the value and dispatch the final change.
			/*
			const finalVal = liveRangeDrag
				? rangePendingValue ?? valueFromClientX(rangeActiveEl, x)
				: rangePendingValue ?? valueFromClientX(rangeActiveEl, x);
            */
			const finalVal = rangePendingValue ?? valueFromClientX(rangeActiveEl, x);
			setRangeValueIfChanged(rangeActiveEl, finalVal, { fireChange: true });

			rangeActiveEl = null;
			rangePendingValue = null;
		}

		// Synthesize a click when appropriate.

		if (downTarget) {
			const actDown = activatableAncestor(downTarget);
			const actUp = activatableAncestor(target);
			if (actDown === actUp) {
				if (typeof actUp.click === 'function') actUp.click();
				else dispatch(actUp, 'click', buildMouseInit(root, x, y, 'click', 0));
			}
		}

		isDown = false;
		downTarget = null;
		return res;
	};

	/**
	 * Clear internal state (e.g., if you abort an interaction externally).
	 * Safe to call multiple times.
	 */
	const dispose = () => {
		isDown = false;
		downTarget = null;
		lastOver = null;
		rangeActiveEl = null;
		rangePendingValue = null;
		// Keep or reset lastNorm. Reset it here for predictable future interactions.
		lastNorm = { x: 0.5, y: 0.5 };
	};

	return { move, down, up, dispose };
}
