/**
 * @module UILMenuVR
 * @description
 * Renders a UIL canvas UI into a VR menu panel and forwards VR pointer events
 * back to the UIL interaction layer.
 */
import * as THREE from 'three';
import { VRMenu } from './VRMenu.js';
import { ControllersManager, EventTypes as CMEventTypes } from './ControllersManager.js';
import * as UIL from '../vendor/uil.module.js';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';

/**
 * A VR menu panel that renders a UIL (uil.module.js) canvas as a Three.js texture.
 *
 * Automatically syncs the texture whenever the UIL library redraws its canvas via
 * the `ui.onDraw` hook, and correctly maps the canvas aspect ratio to the quad mesh
 * so there is no blank space or distortion.
 *
 * @extends VRMenu
 *
 * @example
 * const ui = new UIL.Gui({ w: 300 });
 * const menu = new UILMenuVR(ui, scene, controllersManager, { mode: 'swatch' });
 */
export class UILMenuVR extends VRMenu {
	/** Tracks canvas dimensions to detect resize and rebuild the texture. @type {{ w: number, h: number }} */
	lastCanvasSize = { w: 0, h: 0 };

	/**
	 * @param {object} ui - A UIL Gui/Panel instance that exposes `ui.canvas`, `ui.zone`, and `ui.onDraw`.
	 * @param {THREE.Group} worldContainer - Scene node the menu panel is attached to.
	 * @param {ControllersManager} controllersManager - The shared ControllersManager instance.
	 * @param {object} [options] - Options forwarded to VRMenu.
	 */
	constructor(ui, worldContainer, controllersManager, options) {
		super(worldContainer, controllersManager, options);

		this._mesh.userData = { class: 'UILMenuVR' };

		this._ui = ui;

		if (!this._ui.canvas) {
			console.error('UILMenuVR: No canvas provided on ui object');
		}

		const me = this;

		this._ui.onDraw = function () {
			// In this callback, `this` is the UIL object, so `this.canvas` is the UIL canvas.
			// `this.canvas` is the canvas owned by the UI object.

			const canvasSize = { w: this.canvas.width, h: this.canvas.height };
			const canvasSizeChanged = canvasSize.w !== me.lastCanvasSize.w || canvasSize.h !== me.lastCanvasSize.h;

			if (!me._map || canvasSizeChanged) {
				me._initMap(this.canvas);
			}
			me._map.needsUpdate = true;
			me._adjustAspect();
		};

		// we need to make a first update because onDraw is not called if no change occurs on the UI
		this._initMap(this._ui.canvas);
		this._adjustAspect();
	}

	_initMap(canvas) {
		if (!canvas) console.error('UTILVRMenu: No canvas provided');
		this.lastCanvasSize.w = canvas.width;
		this.lastCanvasSize.h = canvas.height;

		if (this._map) this._map.dispose();
		this._map = new THREE.Texture(canvas);
		this._map.wrapS = THREE.ClampToEdgeWrapping;
		this._map.wrapT = THREE.ClampToEdgeWrapping;
		this._map.minFilter = THREE.LinearFilter;
		this._map.needsUpdate = true;

		this._frontMaterial.map = this._map;
		this._frontMaterial.needsUpdate = true;
	}

	_adjustAspect() {
		const canvasWidthPx = this._ui.canvas.width;
		const canvasHeightPx = this._ui.canvas.height;

		const uiWidthPx = this._ui.zone.w;
		const uiHeightPx = this._ui.zone.h;

		this._updateAspectRatio(canvasWidthPx, canvasHeightPx, uiWidthPx, uiHeightPx);
	}

	_onPointerEvent = (e) => {
		if (e.type == 'pointerupoutside') {
			this._ui.reset(true);
			return;
		}
		// e.type: pointerdown,pointerup,pointermove
		// e.data: x,y in [0,1] range

		let u = e.data.x; // vector {x,y}
		let v = e.data.y;

		switch (e.type) {
			case 'pointerdown':
				// Important!! After setMouse, we need to triggerMouseMove
				// We need to setMouse and triggerMouseMove before triggerMouseDown
				// to capture the latest pointer position

				this._ui.setMouseUV(u, v);
				this._ui.triggerMouseMoveUV(u, v);
				this._ui.triggerMouseDownUV(u, v);
				break;
			case 'pointermove':
				this._ui.setMouseUV(u, v);
				this._ui.triggerMouseMoveUV(u, v);
				break;
			case 'pointerup':
				this._ui.setMouseUV(u, v);
				this._ui.triggerMouseUpUV(u, v);
				break;
		}
	};

	/**
	 * The underlying UIL instance.
	 * @type {object}
	 */
	get ui() {
		return this._ui;
	}

	/**
	 * Disposes of the UIL instance and calls the parent VRMenu dispose.
	 */
	dispose() {
		this._ui.dispose();
		super.dispose();
	}
}
