import { EventsDispatcher } from '../utils/EventsDispatcher.js';
import { EventTypes as HitTestEventTypes } from './ARRealWorldHitTestManager.js';

/**
 * @module ARWorldSurfaceProvider
 * @description
 * Converts AR hit-test events into a stable "current surface" object that can
 * be consumed by placement, anchoring, or UI systems.
 */

/**
 * Event type constants dispatched by {@link ARWorldSurfaceProvider}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired whenever a hit produces or updates the current world surface. */
	SURFACE_UPDATE: 'surfaceUpdate',
	/** Fired when the current surface is cleared or hit testing loses tracking. */
	SURFACE_LOST: 'surfaceLost',
};

/**
 * Tracks the most recent AR world surface from a hit-test manager.
 *
 * The provider stores a compact surface object with `id`, `entityType`,
 * `alignment`, `matrix`, `position`, `normal`, and the original `hit`.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const surfaces = new ARWorldSurfaceProvider(hitTestManager);
 * surfaces.addEventListener(EventTypes.SURFACE_UPDATE, ({ surface }) => {
 *   placementPreview.matrix.copy(surface.matrix);
 * });
 */
export class ARWorldSurfaceProvider extends EventsDispatcher {
	/**
	 * @param {ARRealWorldHitTestManager|null} [hitTestManager=null] - Optional manager to connect immediately.
	 */
	constructor(hitTestManager = null) {
		super();
		this.currentSurface = null;

		if (hitTestManager) this.connect(hitTestManager);
	}

	/**
	 * Subscribes to hit-test events and keeps this provider synchronized.
	 * @param {ARRealWorldHitTestManager} hitTestManager - Source hit-test manager.
	 * @returns {void}
	 */
	connect(hitTestManager) {
		hitTestManager.addEventListener(HitTestEventTypes.HIT_FOUND, (event) => this.updateFromHit(event.hit));
		hitTestManager.addEventListener(HitTestEventTypes.HIT_UPDATE, (event) => this.updateFromHit(event.hit));
		hitTestManager.addEventListener(HitTestEventTypes.HIT_LOST, () => this.clear());
	}

	/**
	 * Updates the current surface from a normalized AR hit.
	 * @param {object|null} hit - Normalized hit data, or `null` to clear.
	 * @returns {void}
	 */
	updateFromHit(hit) {
		this.currentSurface = hit
			? {
					id: `${hit.entityType || 'surface'}:${hit.position.x.toFixed(2)}:${hit.position.z.toFixed(2)}`,
					entityType: hit.entityType || 'unknown',
					alignment: hit.alignment,
					matrix: hit.matrix.clone(),
					position: hit.position.clone(),
					normal: hit.normal.clone(),
					hit,
				}
			: null;

		if (this.currentSurface) {
			this.dispatchEvent({ type: EventTypes.SURFACE_UPDATE, surface: this.currentSurface });
		} else {
			this.dispatchEvent({ type: EventTypes.SURFACE_LOST });
		}
	}

	/**
	 * Clears the current surface and dispatches {@link EventTypes.SURFACE_LOST}.
	 * @returns {void}
	 */
	clear() {
		this.currentSurface = null;
		this.dispatchEvent({ type: EventTypes.SURFACE_LOST });
	}

	/**
	 * Returns the last known AR surface.
	 * @returns {object|null}
	 */
	getCurrentSurface() {
		return this.currentSurface;
	}
}
