/**
 * @module ControllersManager
 * @description
 * Provides the main entry point for WebXR controller input. The module exports
 * {@link ControllersManager}, a singleton that creates the two hand controllers,
 * normalizes their low-level WebXR events, and re-emits them through a single
 * event dispatcher.
 */
import * as THREE from 'three';

import { HandController, EventTypes as HCEvents } from './HandController.js';
import { HandTrackingManager, EventTypes as HTEvents } from './HandTrackingManager.js';
import { EventsDispatcher } from '../utils/EventsDispatcher.js';

/**
 * Event type constants dispatched by {@link ControllersManager}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when the left controller connects. */
	ON_LEFT_CONTROLLER_CONNECTED: 'onLeftControllerConnected',
	/** Fired when the right controller connects. */
	ON_RIGHT_CONTROLLER_CONNECTED: 'onRightControllerConnected',

	/** Fired when the left controller disconnects. */
	ON_LEFT_CONTROLLER_DISCONNECTED: 'onLeftControllerDisconnected',
	/** Fired when the right controller disconnects. */
	ON_RIGHT_CONTROLLER_DISCONNECTED: 'onRightControllerDisconnected',

	/** Fired when a trigger-ray gesture starts (trigger pressed). */
	ON_RAY_STARTED: 'onRayStarted',
	/** Fired every frame while a trigger-ray gesture is active. */
	ON_RAY_UPDATED: 'onRayUpdated',
	/** Fired when a trigger-ray gesture ends (trigger released). */
	ON_RAY_ENDED: 'onRayEnded',

	/** Fired when the thumbstick is flicked to the left (snap-rotate). */
	ON_ROTATE_LEFT: 'onRotateLeft',
	/** Fired when the thumbstick is flicked to the right (snap-rotate). */
	ON_ROTATE_RIGHT: 'onRotateRight',

	/** Fired when any mapped button is pressed down. */
	ON_BUTTON_UP: 'onButtonUp',
	/** Fired when any mapped button is released. */
	ON_BUTTON_DOWN: 'onButtonDown',

	/** Fired when the thumbstick is pushed forward past the click threshold. */
	ON_AXIS_FORWARD_CLICK: 'onAxisFowardClick',
	/** Fired when the thumbstick is pushed backward past the click threshold. */
	ON_AXIS_BACKWARD_CLICK: 'onAxisBackwardClick',

	/** Fired when the thumbstick is pushed left past the click threshold. */
	ON_AXIS_LEFT_CLICK: 'onAxisLeftClick',
	/** Fired when the thumbstick is pushed right past the click threshold. */
	ON_AXIS_RIGHT_CLICK: 'onAxisRightClick',
	ON_AXIS_X_CONTINUOUS_START: 'onAxisXContinuousStart',
	ON_AXIS_X_CONTINUOUS_UPDATE: 'onAxisXContinuousUpdate',
	ON_AXIS_X_CONTINUOUS_END: 'onAxisXContinuousEnd',

	/** Fired every frame while the thumbstick Y axis is non-zero (continuous motion). */
	ON_AXIS_Y_NOT_ZERO: 'onAxisYNotZero',

	/** Fired when a squeeze button is pressed. */
	ON_SQUEEZE_START: 'onSqueezeStart',
	/** Fired when a squeeze button is released. */
	ON_SQUEEZE_END: 'onSqueezeEnd',

	/** Fired when both squeeze buttons are pressed simultaneously. */
	ON_DOUBLE_SQUEEZE_STARTED: 'onDoubleSqueezeStarted',
	/** Fired when the double-squeeze gesture ends. */
	ON_DOUBLE_SQUEEZE_ENDED: 'onDoubleSqueezeEnded',

	/** Fired on every animation-frame update cycle. */
	ON_UPDATE: 'onUpdate',
};

/**
 * Singleton manager that owns both VR hand controllers and aggregates their
 * events into a single, uniform event surface.
 *
 * Internally it creates two {@link HandController} instances (`controller0` /
 * `controller1`) and proxies all of their events as {@link EventTypes} values
 * so consumers only need to listen to this one object.
 *
 * Because only one headset is ever active at a time the constructor enforces a
 * singleton pattern — calling `new ControllersManager(…)` a second time returns
 * the existing instance.
 *
 * @extends EventsDispatcher
 *
 * @example
 * const cm = new ControllersManager(renderer.xr, scene, {});
 * cm.addEventListener(EventTypes.ON_RAY_STARTED, (e) => {
 *   console.log(e.handedness, e.ray);
 * });
 */
export class ControllersManager extends EventsDispatcher {
	/** @type {THREE.WebXRManager} */
	xr;
	/** @type {HandController} */
	controller0;
	/** @type {HandController} */
	controller1;
	/** @type {HandTrackingManager|null} */
	handTrackingManager = null;
	/** Dominant hand — `'right'` by default. @type {'left'|'right'} */
	userHandedness = 'right';
	/** THREE.Group that controller meshes are added to. @type {THREE.Group} */
	parentContainer;
	me = this;
	/** @type {object} */
	options;

	_doubleSqueezeGesture = {
		left: {
			isDown: false,
			initialPosition: null,
		},
		right: {
			isDown: false,
			initialPosition: null,
		},
		initialDistance: null,
		initialCenterPoint: null,
	};

	/**
	 * @param {THREE.WebXRManager} xr - The WebXR manager from `renderer.xr`.
	 * @param {THREE.Group} parentContainer - Scene node that controller meshes are attached to.
	 * @param {object} options - Optional configuration object.
	 */
	constructor(xr, parentContainer, options) {
		if (ControllersManager.instance) {
			return ControllersManager.instance;
		}
		super();

		this.options = options;
		this.xr = xr;
		this.parentContainer = parentContainer;

		this.controller0 = new HandController(this.xr, this.parentContainer);
		this.controller0.setup(0);

		this.controller1 = new HandController(this.xr, this.parentContainer);
		this.controller1.setup(1);

		this._setupEventListeners();
		ControllersManager.instance = this;
	}

	/**
	 * `true` when both controllers are physically connected.
	 * @type {boolean}
	 */
	get connected() {
		return this.controller0.connected && this.controller1.connected;
	}

	/**
	 * The controller assigned to the dominant hand (see {@link userHandedness}).
	 * @type {HandController}
	 */
	get skilledHand() {
		if (this.controller0.handedness == this.userHandedness) return this.controller0;
		else return this.controller1;
	}

	/**
	 * The controller assigned to the non-dominant hand.
	 * @type {HandController}
	 */
	get otherHand() {
		if (this.controller0.handedness != this.userHandedness) return this.controller0;
		else return this.controller1;
	}

	/**
	 * The right-hand controller, or `null` if not yet connected.
	 * @type {HandController|null}
	 */
	get right() {
		if (this.controller0 && this.controller0.handedness == 'right') return this.controller0;
		else if (this.controller1 && this.controller1.handedness === 'right') return this.controller1;
		return null;
	}

	/**
	 * The left-hand controller, or `null` if not yet connected.
	 * @type {HandController|null}
	 */
	get left() {
		if (this.controller0 && this.controller0.handedness == 'left') return this.controller0;
		else if (this.controller1 && this.controller1.handedness === 'left') return this.controller1;
		return null;
	}

	/**
	 * Returns the controller for the given hand.
	 * @param {'left'|'right'} hand
	 * @returns {HandController|undefined}
	 */
	getController(hand) {
		if (hand == 'right') return this.right;
		if (hand == 'left') return this.left;
	}

	/**
	 * Returns the world-space distance between the two controller grips,
	 * or `null` if either controller is missing.
	 * @returns {number|null}
	 */
	getDistanceBetweenHands() {
		if (!this.controller0 || !this.controller1) return null;

		let p0 = this.controller0.controller.getWorldPosition(new THREE.Vector3());
		let p1 = this.controller1.controller.getWorldPosition(new THREE.Vector3());
		return p0.distanceTo(p1);
	}

	/**
	 * Returns the world-space midpoint between the two controller grips,
	 * or `null` if either controller is missing.
	 * @returns {THREE.Vector3|null}
	 */
	getCenterPointBetweenHands() {
		if (!this.controller0 || !this.controller1) return null;
		let p0 = this.controller0.controller.getWorldPosition(new THREE.Vector3());
		let p1 = this.controller1.controller.getWorldPosition(new THREE.Vector3());
		return new THREE.Vector3().addVectors(p0, p1).multiplyScalar(0.5);
	}

	/**
	 * Must be called every animation frame. Forwards the call to both
	 * controllers and dispatches {@link EventTypes.ON_UPDATE}.
	 * @param {number} time - Elapsed time in seconds since session start.
	 * @param {number} deltaTime - Time in seconds since the last frame.
	 */
	update(time, deltaTime) {
		if (this.controller0) this.controller0.update(time, deltaTime);
		if (this.controller1) this.controller1.update(time, deltaTime);
		if (this.handTrackingManager) this.handTrackingManager.update(time, deltaTime);
		this.dispatchEvent({ type: EventTypes.ON_UPDATE, time, deltaTime });
	}

	/**
	 * Enables native WebXR hand tracking through Three.js helpers.
	 *
	 * Pinch start/end events are re-emitted as squeeze start/end events so
	 * existing GrabbableVRObject instances can work with hands without changing
	 * their construction code.
	 * @param {object} [options={}]
	 * @returns {HandTrackingManager}
	 */
	enableHandTracking(options = {}) {
		if (this.handTrackingManager) return this.handTrackingManager;

		this.handTrackingManager = new HandTrackingManager(this.xr, this.parentContainer, options);
		this._setupHandTrackingEventListeners();
		return this.handTrackingManager;
	}

	/**
	 * Switches the dominant hand. Pass `'left'` or `'right'` to set explicitly,
	 * or omit the argument to toggle from the current value.
	 * @param {'left'|'right'} [handedness]
	 */
	toggleHandedness(handedness) {
		if (handedness == undefined) handedness = this.userHandedness == 'right' ? 'left' : 'right';

		this.userHandedness = handedness;

		this.right.skilled = handedness == 'right';
		this.left.skilled = handedness == 'left';

		this.otherHand.getGrip().add(this.vrMenu);
	}

	/**
	 * Returns the headset's current position and forward direction in world space.
	 * @returns {{ position: THREE.Vector3, viewDirection: THREE.Vector3 }}
	 */
	getHeadsetTransform() {
		// Returns values in world coordinates.
		let xrCamera = this.xr.getCamera();
		let e = xrCamera.matrixWorld.elements;
		// Elements [12], [13], and [14] contain the camera position in world coordinates.
		let position = new THREE.Vector3(e[12] / e[15], e[13] / e[15], e[14] / e[15]);
		// Elements [8], [9], and [10] represent the camera Z axis in world coordinates.
		// Three.js cameras look down their local negative Z axis, so the vector is negated.
		let viewDirection = new THREE.Vector3(-e[8], -e[9], -e[10]).normalize();

		return { position, viewDirection };
	}

	/**
	 * Proxies an event from a child dispatcher while preserving the original type
	 * in `internalType`.
	 * @param {EventsDispatcher} origin - Source dispatcher to listen to.
	 * @param {string} externalType - Event type emitted by this manager.
	 * @param {string} internalType - Event type emitted by the child dispatcher.
	 */
	_exportEvent(origin, externalType, internalType) {
		origin.addEventListener(internalType, (event) => {
			const e = { ...event };
			e.internalType = e.type;
			e.type = externalType;
			this.dispatchEvent(e);
		});
	}

	/**
	 * Registers listeners on both HandController instances and re-emits their
	 * events through the ControllersManager event surface.
	 */
	_setupEventListeners() {
		[this.controller0, this.controller1].forEach((o, i) => {
			o.addEventListener(HCEvents.ON_CONNECTED, this._onControllerConnected.bind(this, o));
			o.addEventListener(HCEvents.ON_DISCONNECTED, this._onControllerDisconnected.bind(this, o));

			o.addEventListener(HCEvents.ON_SQUEEZE_START, this._onControllerSqueezeStart.bind(this, o));
			o.addEventListener(HCEvents.ON_SQUEEZE_END, this._onControllerSqueezeEnd.bind(this, o));

			this._exportEvent(o, EventTypes.ON_SQUEEZE_START, HCEvents.ON_SQUEEZE_START);
			this._exportEvent(o, EventTypes.ON_SQUEEZE_END, HCEvents.ON_SQUEEZE_END);

			this._exportEvent(o, EventTypes.ON_RAY_STARTED, HCEvents.ON_RAY_STARTED);
			this._exportEvent(o, EventTypes.ON_RAY_UPDATED, HCEvents.ON_RAY_UPDATED);
			this._exportEvent(o, EventTypes.ON_RAY_ENDED, HCEvents.ON_RAY_ENDED);

			this._exportEvent(o, EventTypes.ON_AXIS_Y_NOT_ZERO, HCEvents.ON_AXIS_Y_NOT_ZERO);

			this._exportEvent(o, EventTypes.ON_ROTATE_LEFT, HCEvents.ON_ROTATE_LEFT);
			this._exportEvent(o, EventTypes.ON_ROTATE_RIGHT, HCEvents.ON_ROTATE_RIGHT);

			this._exportEvent(o, EventTypes.ON_BUTTON_DOWN, HCEvents.ON_BUTTON_DOWN);
			this._exportEvent(o, EventTypes.ON_BUTTON_UP, HCEvents.ON_BUTTON_UP);

			this._exportEvent(o, EventTypes.ON_AXIS_FORWARD_CLICK, HCEvents.ON_AXIS_FORWARD_CLICK);
			this._exportEvent(o, EventTypes.ON_AXIS_BACKWARD_CLICK, HCEvents.ON_AXIS_BACKWARD_CLICK);

			this._exportEvent(o, EventTypes.ON_AXIS_LEFT_CLICK, HCEvents.ON_AXIS_LEFT_CLICK);
			this._exportEvent(o, EventTypes.ON_AXIS_RIGHT_CLICK, HCEvents.ON_AXIS_RIGHT_CLICK);
			this._exportEvent(o, EventTypes.ON_AXIS_X_CONTINUOUS_START, HCEvents.ON_AXIS_X_CONTINUOUS_START);
			this._exportEvent(o, EventTypes.ON_AXIS_X_CONTINUOUS_UPDATE, HCEvents.ON_AXIS_X_CONTINUOUS_UPDATE);
			this._exportEvent(o, EventTypes.ON_AXIS_X_CONTINUOUS_END, HCEvents.ON_AXIS_X_CONTINUOUS_END);
		});
	}

	_setupHandTrackingEventListeners() {
		const handTracking = this.handTrackingManager;
		if (!handTracking) return;

		handTracking.addEventListener(HTEvents.ON_PINCH_START, (event) => {
			const e = { ...event };
			e.internalType = e.type;
			e.type = EventTypes.ON_SQUEEZE_START;
			this.dispatchEvent(e);
		});

		handTracking.addEventListener(HTEvents.ON_PINCH_END, (event) => {
			const e = { ...event };
			e.internalType = e.type;
			e.type = EventTypes.ON_SQUEEZE_END;
			this.dispatchEvent(e);
		});
	}

	/**
	 * Handles a hand controller connection and dispatches a left/right specific event.
	 * @param {HandController} controller
	 * @param {object} event
	 */
	_onControllerConnected(controller, event) {
		if (this.userHandedness == controller.handedness) {
			controller.skilled = true;
		} else {
			controller.skilled = false;
		}

		this.dispatchEvent({
			type:
				controller.handedness == 'right'
					? EventTypes.ON_RIGHT_CONTROLLER_CONNECTED
					: EventTypes.ON_LEFT_CONTROLLER_CONNECTED,
			controller: controller,
		});
	}

	/**
	 * Handles a hand controller disconnection and dispatches a left/right specific event.
	 * @param {HandController} controller
	 * @param {object} event
	 */
	_onControllerDisconnected(controller, event) {
		this.dispatchEvent({
			type:
				controller.handedness == 'right'
					? EventTypes.ON_RIGHT_CONTROLLER_DISCONNECTED
					: EventTypes.ON_LEFT_CONTROLLER_DISCONNECTED,
		});
	}

	/**
	 * Tracks squeeze start and emits the double-squeeze event when both hands
	 * are squeezing simultaneously.
	 * @param {HandController} hc
	 * @param {object} event
	 */
	_onControllerSqueezeStart(hc, event) {
		let gesture = this._doubleSqueezeGesture[event.handedness];

		gesture.isDown = true;
		gesture.initialPosition = hc.controller.getWorldPosition(new THREE.Vector3());
		// if both squeezes are down, trigger the action.
		if (this._doubleSqueezeGesture['left'].isDown && this._doubleSqueezeGesture['right'].isDown) {
			this._doubleSqueezeGesture.initialDistance = this.getDistanceBetweenHands();
			this._doubleSqueezeGesture.initialCenterPoint = this.getCenterPointBetweenHands();
			this.dispatchEvent({
				type: EventTypes.ON_DOUBLE_SQUEEZE_STARTED,
				initialDistance: this._doubleSqueezeGesture.initialDistance,
				initialCenterPoint: this._doubleSqueezeGesture.initialCenterPoint,
			});
		}
	}

	/**
	 * Tracks squeeze release and emits the double-squeeze end event when the
	 * two-handed gesture is no longer active.
	 * @param {HandController} controller
	 * @param {object} event
	 */
	_onControllerSqueezeEnd(controller, event) {
		this._doubleSqueezeGesture[event.handedness].isDown = false;
		// exclusive OR
		if (this._doubleSqueezeGesture['left'].isDown != this._doubleSqueezeGesture['right'].isDown) {
			this.dispatchEvent({
				type: EventTypes.ON_DOUBLE_SQUEEZE_ENDED,
			});
		}
	}
}
