import * as THREE from 'three';
import { ControllersManager, EventTypes as CMEventTypes } from './ControllersManager.js';

import { VRInteractivePanel, defaultOptions as parentDefaultOptions } from './VRInteractivePanel.js';
import { GrabbableVRObject, EventTypes as GrabEventTypes } from './GrabbableVRObject.js';

import { merge } from 'lodash';

/**
 * @module VRMenu
 * @description
 * Base class for rectangular VR menu panels that can be shown in front of the
 * user or attached to a controller, with optional direct manipulation.
 */

/**
 * Default menu options, merged with {@link VRInteractivePanel} defaults.
 * @type {object}
 */
export const defaultOptions = merge({}, parentDefaultOptions, {
	swatch: {
		handedness: 'left',
		position: { x: 0, y: 0.25, z: -0.05 },
		rotation: { x: -20, y: 0, z: 0 },
		rotationOrder: 'YXZ',
	},
	panel: {
		inclination: 20, // degrees
		distance: 0.6, // meters
		verticalOffset: -0.4, // meters , displacement in World Y axis from headset Y position
	},
	manipulation: {
		enabled: false,
		contactGrabbing: {
			enabled: true,
			// Distance in metres from the controller grip center to the oriented panel bounds.
			distanceThreshold: 0.1,
		},
		remoteGrabbing: {
			enabled: false,
		},
		translation: {
			smoothing: 18,
		},
		rotation: {
			keepWorldUp: true,
			snapDegrees: 30,
			// Haptics are menu-specific feedback for discrete rotation snap steps.
			haptics: {
				enabled: true,
				intensity: 0.28,
				duration: 30,
				minInterval: 0.08,
			},
		},
		feedback: {
			enabled: true,
			mode: 'wireBounds',
			nearDistance: null,
			nearColor: 0x44aaff,
			contactColor: 0xffcc44,
			grabColor: 0xffffff,
			nearOpacity: 0.35,
			contactOpacity: 0.55,
			grabOpacity: 1,
		},
	},
});

/**
 * Event type constants dispatched by {@link VRMenu}.
 * @enum {string}
 */
export const EventTypes = {
	/** Fired when a controller comes within the menu's near-grab range. */
	ON_MENU_GRAB_NEAR: 'onMenuGrabNear',
	/** Fired when a controller leaves the near-grab range. */
	ON_MENU_GRAB_NEAR_END: 'onMenuGrabNearEnd',
	/** Fired when a controller reaches contact-grab range. */
	ON_MENU_GRAB_CONTACT: 'onMenuGrabContact',
	/** Fired when menu manipulation starts. */
	ON_MENU_GRAB_START: 'onMenuGrabStart',
	/** Fired while menu manipulation updates. */
	ON_MENU_GRAB_UPDATE: 'onMenuGrabUpdate',
	/** Fired when menu manipulation ends. */
	ON_MENU_GRAB_END: 'onMenuGrabEnd',
};

const startHidden = true;

/**
 * This class represents a VR menu in a 2D panel that can be attached to a controller ("swatch" mode)
 * or positioned in front of the user ("panel" mode) in a WebXR environment. It manages its
 * position, orientation, and visibility based on the selected mode and headset/controller state.
 * VRMenu extends VRInteractivePanel and handles controller connection events to attach or detach
 * the menu from the appropriate scene node.
 *
 * @extends VRInteractivePanel
 *
 * @example
 * const menu = new VRMenu(scene, controllersManager, {
 *   mode: 'panel',
 *   panel: { distance: 0.75, verticalOffset: -0.25 },
 *   manipulation: { enabled: true },
 * });
 * menu.setVisible(true);
 */
export class VRMenu extends VRInteractivePanel {
	/**
	 * @param {THREE.Group} worldContainer - Scene node the menu panel is attached to.
	 * @param {ControllersManager} controllersManager - Shared ControllersManager instance.
	 * @param {object} [options] - Options merged with VRInteractivePanel and VRMenu defaults.
	 */
	constructor(worldContainer, controllersManager, options) {
		const mergeOpts = merge({}, defaultOptions, options);
		super(worldContainer, controllersManager, mergeOpts);

		this._worldContainer = worldContainer;
		this._controllersManager = controllersManager;
		this._mesh.userData = { class: 'VRMenu' };

		if (this.options.mode == 'swatch') {
			this.setSwatchPose(this.options.swatch);
		} else {
			this._container.position.set(0, 0.5, -1);
		}

		this._container.visible = !startHidden;
		// add axes helper for debugging
		if (this.options.debugLevel > 0) {
			const axesHelper = new THREE.AxesHelper(0.1);
			this._container.add(axesHelper);
		}

		this._setupEventListeners();
		this._setupMenuManipulation();
	}

	/**
	 * Sets menu visibility and repositions panel-mode menus when becoming visible.
	 * @param {boolean} visible
	 */
	setVisible(visible) {
		this._container.visible = visible;
		if (!visible) this._cancelMenuManipulation();
		if (visible && this.options.mode == 'panel') this._repositionPanel();
	}

	/**
	 * Updates the aspect ratio and vertical mapping of the UI mesh to ensure
	 * it maps all the UI pixels without blank space and deformation.
	 *
	 * This method recalculates the scaling and offset values for the UI texture mapping and mesh transformation,
	 * based on the provided canvas and UI dimensions. It ensures that the UI content is properly scaled and centered
	 * vertically within the canvas, regardless of the canvas or UI height in pixels.
	 *
	 * @param {number} canvasWidthPx - The width of the rendering canvas in pixels.
	 * @param {number} canvasHeightPx - The height of the rendering canvas in pixels.
	 * @param {number} uiHeightPx - The height of the UI in pixels, which determines the vertical mapping range.
	 *
	 * The method performs the following steps:
	 * 1. Calculates the aspect ratio using the canvas width and the UI height, which is used to adjust the mesh's vertical scale.
	 * 2. Computes the vertical scaling factor (`yScale`) to map the UI's pixel height to the canvas height, ensuring the UI covers the intended area.
	 * 3. Determines the vertical offset (`yOffset`) to center the UI mapping within the canvas.
	 * 4. Updates the texture mapping (`offset` and `repeat`) to apply the calculated scale and offset, so the UI texture fills the mesh appropriately.
	 * 5. Adjusts the mesh's vertical scale and position to maintain the correct aspect ratio and vertical alignment.
	 * 6. Stores the computed `yOffset` and `yScale` for potential later use.
	 *
	 * This function is typically used in WebXR or VR/AR UI rendering scenarios where the UI must dynamically adapt
	 * to varying display resolutions and aspect ratios.
	 */
	_updateAspectRatio(canvasWidthPx, canvasHeightPx, uiWidthPx = null, uiHeightPx = null) {
		const contentWidth = uiWidthPx > 0 ? uiWidthPx : canvasWidthPx;
		const contentHeight = uiHeightPx > 0 ? uiHeightPx : canvasHeightPx;
		super._updateAspectRatio(canvasWidthPx, canvasHeightPx, contentWidth, contentHeight);
	}

	setSwatchPose(pose = {}) {
		const previousHandedness = this.options.swatch?.handedness;
		const next = merge({}, this.options.swatch, pose);
		if (!['left', 'right'].includes(next.handedness)) {
			throw new RangeError("VRMenu.setSwatchPose: handedness must be 'left' or 'right'");
		}
		for (const key of ['x', 'y', 'z']) {
			if (!Number.isFinite(next.position?.[key]) || !Number.isFinite(next.rotation?.[key])) {
				throw new TypeError(`VRMenu.setSwatchPose: position.${key} and rotation.${key} must be finite numbers`);
			}
		}
		if (!['XYZ', 'YZX', 'ZXY', 'XZY', 'YXZ', 'ZYX'].includes(next.rotationOrder)) {
			throw new RangeError('VRMenu.setSwatchPose: invalid rotationOrder');
		}

		if (this.options.mode === 'swatch' && previousHandedness && previousHandedness !== next.handedness) {
			const previousGrip = this._controllersManager?.[previousHandedness]?.getGrip();
			const nextGrip = this._controllersManager?.[next.handedness]?.getGrip();
			if (this._container.parent === previousGrip) {
				previousGrip.remove(this._container);
				nextGrip?.add(this._container);
				this._detachSwatchParentAxes();
				this._attachSwatchParentAxes(nextGrip);
			}
		}
		this.options.swatch = next;
		this._container.position.set(next.position.x, next.position.y, next.position.z);
		this._container.rotation.set(
			THREE.MathUtils.degToRad(next.rotation.x),
			THREE.MathUtils.degToRad(next.rotation.y),
			THREE.MathUtils.degToRad(next.rotation.z),
			next.rotationOrder
		);
		return this;
	}

	/**
	 * Repositions the menu panel in front of the user based on headset orientation.
	 */
	_repositionPanel() {
		// position and viewDirection are defined in world coordinates
		const { position, viewDirection } = this._controllersManager.getHeadsetTransform();

		viewDirection.y = 0; // we want to project direction on XZ plane
		viewDirection.normalize();
		viewDirection.multiplyScalar(this.options.panel.distance);

		position.y += this.options.panel.verticalOffset;
		position.add(viewDirection);

		this._container.position.copy(position);

		this._container.rotation.order = 'ZYX';
		this._container.rotation.y = -Math.atan2(viewDirection.z, viewDirection.x) - Math.PI / 2;
		this._container.rotation.x = -THREE.MathUtils.degToRad(this.options.panel.inclination);
	}

	_setupMenuManipulation() {
		const options = this.options.manipulation;
		if (!options?.enabled || this.options.mode !== 'panel') return;

		this._menuGrabNearHand = null;
		this._menuGrabContactHand = null;
		this._menuGrabbed = false;
		this._lastRotationSnapHapticAt = -Infinity;

		this._createMenuManipulationFeedback();

		this._menuGrabbable = new GrabbableVRObject(this._container, this._worldContainer, {
			contactGrabbing: {
				...options.contactGrabbing,
				// Only the panel mesh defines contact; helpers and feedback lines do not enlarge the grab volume.
				boundsObject: this._mesh,
			},
			remoteGrabbing: options.remoteGrabbing,
			showHelpers: false,
			follow: {
				mode: 'manual',
				preserveGrabOffset: true,
				translationSmoothing: options.translation.smoothing,
				keepWorldUp: options.rotation.keepWorldUp,
				snapDegrees: options.rotation.snapDegrees,
				snapRelativeToGrab: true,
			},
		});

		this._onMenuGrabStartBound = this._onMenuGrabStart.bind(this);
		this._onMenuGrabUpdateBound = this._onMenuGrabUpdate.bind(this);
		this._onMenuGrabEndBound = this._onMenuGrabEnd.bind(this);
		this._onMenuRotationSnapBound = this._onMenuRotationSnap.bind(this);
		this._onMenuManipulationUpdateBound = this._onMenuManipulationUpdate.bind(this);

		this._menuGrabbable.addEventListener(GrabEventTypes.ON_GRAB_START, this._onMenuGrabStartBound);
		this._menuGrabbable.addEventListener(GrabEventTypes.ON_GRAB_UPDATE, this._onMenuGrabUpdateBound);
		this._menuGrabbable.addEventListener(GrabEventTypes.ON_GRAB_END, this._onMenuGrabEndBound);
		this._menuGrabbable.addEventListener(GrabEventTypes.ON_ROTATION_SNAP, this._onMenuRotationSnapBound);
		this._controllersManager.addEventListener(CMEventTypes.ON_UPDATE, this._onMenuManipulationUpdateBound);
	}

	_createMenuManipulationFeedback() {
		const options = this.options.manipulation.feedback;
		if (!options.enabled || options.mode !== 'wireBounds') return;

		this._mesh.geometry.computeBoundingBox();
		const bounds = this._mesh.geometry.boundingBox;
		const z = 0.002;
		const points = [
			new THREE.Vector3(bounds.min.x, bounds.min.y, z),
			new THREE.Vector3(bounds.max.x, bounds.min.y, z),
			new THREE.Vector3(bounds.max.x, bounds.min.y, z),
			new THREE.Vector3(bounds.max.x, bounds.max.y, z),
			new THREE.Vector3(bounds.max.x, bounds.max.y, z),
			new THREE.Vector3(bounds.min.x, bounds.max.y, z),
			new THREE.Vector3(bounds.min.x, bounds.max.y, z),
			new THREE.Vector3(bounds.min.x, bounds.min.y, z),
		];

		const geometry = new THREE.BufferGeometry().setFromPoints(points);
		const material = new THREE.LineBasicMaterial({
			color: options.nearColor,
			transparent: true,
			opacity: options.nearOpacity,
			depthTest: false,
			depthWrite: false,
		});

		this._menuManipulationFeedback = new THREE.LineSegments(geometry, material);
		this._menuManipulationFeedback.renderOrder = 1000;
		this._menuManipulationFeedback.visible = false;
		this._mesh.add(this._menuManipulationFeedback);
	}

	_onMenuManipulationUpdate() {
		if (!this._menuGrabbable) return;

		if (!this._container.visible || this._menuGrabbed) {
			if (!this._container.visible) this._setMenuGrabNearHand(null);
			this._setMenuManipulationFeedback(this._menuGrabbed ? 'grab' : 'hidden');
			return;
		}

		const nearest = this._getNearestControllerToMenu();
		const contactDistance = this.options.manipulation.contactGrabbing.distanceThreshold;
		const nearDistance = this.options.manipulation.feedback.nearDistance || contactDistance * 3;
		const near = nearest && nearest.distance <= nearDistance ? nearest : null;
		const contact = nearest && nearest.distance <= contactDistance ? nearest : null;

		this._setMenuGrabNearHand(near);
		this._setMenuGrabContactHand(contact);
		this._setMenuManipulationFeedback(contact ? 'contact' : near ? 'near' : 'hidden');
	}

	_getNearestControllerToMenu() {
		let nearest = null;
		for (const handedness of ['left', 'right']) {
			const distance = this._getControllerDistanceToMenu(handedness);
			if (distance === null) continue;
			if (!nearest || distance < nearest.distance) {
				nearest = {
					handedness,
					controller: this._controllersManager.getController(handedness),
					distance,
				};
			}
		}
		return nearest;
	}

	_getControllerDistanceToMenu(handedness) {
		return this._menuGrabbable.getControllerDistanceToContactBounds(handedness);
	}

	_setMenuGrabNearHand(entry) {
		const next = entry?.handedness || null;
		if (this._menuGrabNearHand === next) return;

		if (this._menuGrabNearHand) {
			this.dispatchEvent({
				type: EventTypes.ON_MENU_GRAB_NEAR_END,
				menu: this,
				handedness: this._menuGrabNearHand,
			});
		}

		this._menuGrabNearHand = next;
		if (!entry) return;

		this.dispatchEvent({
			type: EventTypes.ON_MENU_GRAB_NEAR,
			menu: this,
			...entry,
		});
	}

	_setMenuGrabContactHand(entry) {
		const next = entry?.handedness || null;
		if (this._menuGrabContactHand === next) return;
		this._menuGrabContactHand = next;
		if (!entry) return;

		this.dispatchEvent({
			type: EventTypes.ON_MENU_GRAB_CONTACT,
			menu: this,
			...entry,
		});
	}

	_setMenuManipulationFeedback(state) {
		if (!this._menuManipulationFeedback) return;

		const options = this.options.manipulation.feedback;
		const material = this._menuManipulationFeedback.material;
		this._menuManipulationFeedback.visible = state !== 'hidden' && this._container.visible;

		if (state === 'grab') {
			material.color.setHex(options.grabColor);
			material.opacity = options.grabOpacity;
		} else if (state === 'contact') {
			material.color.setHex(options.contactColor);
			material.opacity = options.contactOpacity;
		} else {
			material.color.setHex(options.nearColor);
			material.opacity = options.nearOpacity;
		}
		material.needsUpdate = true;
	}

	_onMenuGrabStart(e) {
		this._menuGrabbed = true;
		this._setMenuManipulationFeedback('grab');
		this.dispatchEvent({
			...e,
			type: EventTypes.ON_MENU_GRAB_START,
			menu: this,
		});
	}

	_onMenuGrabUpdate(e) {
		this._setMenuManipulationFeedback('grab');
		this.dispatchEvent({
			...e,
			type: EventTypes.ON_MENU_GRAB_UPDATE,
			menu: this,
		});
	}

	_onMenuRotationSnap(e) {
		const haptics = this.options.manipulation.rotation.haptics;
		if (!haptics?.enabled || !e.controller?.pulse) return;
		if (haptics.intensity <= 0 || haptics.duration <= 0) return;

		const now = performance.now() / 1000;
		if (now - this._lastRotationSnapHapticAt < haptics.minInterval) return;
		this._lastRotationSnapHapticAt = now;

		e.controller.pulse(haptics.intensity, haptics.duration);
	}

	_onMenuGrabEnd(e) {
		this._menuGrabbed = false;
		this._menuGrabContactHand = null;
		this._setMenuManipulationFeedback('hidden');
		this.dispatchEvent({
			...e,
			type: EventTypes.ON_MENU_GRAB_END,
			menu: this,
		});
	}

	_cancelMenuManipulation() {
		if (!this._menuGrabbable) return;
		this._menuGrabbable.cancelGrab();
		this._menuGrabbed = false;
		this._menuGrabContactHand = null;
		this._setMenuGrabNearHand(null);
		this._setMenuManipulationFeedback('hidden');
	}

	/**
	 * Sets up controller connection/disconnection listeners used by swatch and panel modes.
	 */
	_setupEventListeners() {
		this._onLeftControllerConnectedBound = this._onLeftControllerConnected.bind(this);
		this._onLeftControllerDisconnectedBound = this._onLeftControllerDisconnected.bind(this);
		this._onRightControllerConnectedBound = this._onRightControllerConnected.bind(this);
		this._onRightControllerDisconnectedBound = this._onRightControllerDisconnected.bind(this);
		this._controllersManager.addEventListener(
			CMEventTypes.ON_LEFT_CONTROLLER_CONNECTED,
			this._onLeftControllerConnectedBound
		);

		this._controllersManager.addEventListener(
			CMEventTypes.ON_LEFT_CONTROLLER_DISCONNECTED,
			this._onLeftControllerDisconnectedBound
		);
		this._controllersManager.addEventListener(
			CMEventTypes.ON_RIGHT_CONTROLLER_CONNECTED,
			this._onRightControllerConnectedBound
		);
		this._controllersManager.addEventListener(
			CMEventTypes.ON_RIGHT_CONTROLLER_DISCONNECTED,
			this._onRightControllerDisconnectedBound
		);
	}

	/**
	 * Attaches the menu to the left controller in swatch mode, or to the world in panel mode.
	 * @param {object} e - Controller connection event.
	 */
	_onLeftControllerConnected(e) {
		if (this.options.mode == 'swatch') {
			if (this.options.swatch.handedness !== 'left') return;
			let grip = this._controllersManager?.left?.getGrip();
			if (grip) {
				grip.add(this._container);
				this._attachSwatchParentAxes(grip);
			}
		} else {
			// panel mode
			this._worldContainer.add(this._container);
		}
	}

	_onRightControllerConnected(e) {
		if (this.options.mode !== 'swatch' || this.options.swatch.handedness !== 'right') return;
		const grip = this._controllersManager?.right?.getGrip();
		if (grip) {
			grip.add(this._container);
			this._attachSwatchParentAxes(grip);
		}
	}

	_attachSwatchParentAxes(grip) {
		if (this.options.debugLevel <= 0 || !grip) return;
		if (!this._swatchParentAxes) {
			this._swatchParentAxes = new THREE.AxesHelper(0.15);
			this._swatchParentAxes.name = 'VRMenu.swatchParentAxes';
			this._swatchParentAxes.userData = { class: 'VRMenuSwatchParentAxes' };
		}
		grip.add(this._swatchParentAxes);
	}

	_detachSwatchParentAxes() {
		this._swatchParentAxes?.removeFromParent();
	}

	/**
	 * Detaches the menu when the left controller disconnects and cancels any active pointer gesture.
	 * @param {object} e - Controller disconnection event.
	 */
	_onLeftControllerDisconnected(e) {
		if (this._lastRayStartedHand == e.handedness) {
			// Cancel any active pointer gesture (emits POINTER_UP_OUTSIDE via the base).
			this.onRayEnded(null, e.handedness);

			this._lastRayStartedHand = null;
		}
		if (this.options.mode == 'swatch') {
			if (this.options.swatch.handedness !== 'left') return;
			let grip = this._controllersManager?.left?.getGrip();
			if (grip) {
				grip.remove(this._container);
			}
			this._detachSwatchParentAxes();
		} else {
			// panel mode
			this._cancelMenuManipulation();
			this._worldContainer.remove(this._container);
		}
	}

	_onRightControllerDisconnected(e) {
		if (this._lastRayStartedHand == e.handedness) {
			this.onRayEnded(null, e.handedness);
			this._lastRayStartedHand = null;
		}
		if (this.options.mode !== 'swatch' || this.options.swatch.handedness !== 'right') return;
		const grip = this._controllersManager?.right?.getGrip();
		if (grip) grip.remove(this._container);
		this._detachSwatchParentAxes();
	}

	/**
	 * Cleans up event listeners and removes the menu from the scene or controller.
	 */
	dispose() {
		this._cancelMenuManipulation();
		if (this._menuGrabbable) {
			this._menuGrabbable.removeEventListener(GrabEventTypes.ON_GRAB_START, this._onMenuGrabStartBound);
			this._menuGrabbable.removeEventListener(GrabEventTypes.ON_GRAB_UPDATE, this._onMenuGrabUpdateBound);
			this._menuGrabbable.removeEventListener(GrabEventTypes.ON_GRAB_END, this._onMenuGrabEndBound);
			this._menuGrabbable.removeEventListener(GrabEventTypes.ON_ROTATION_SNAP, this._onMenuRotationSnapBound);
			this._menuGrabbable.dispose();
			this._menuGrabbable = null;
		}
		if (this._onMenuManipulationUpdateBound) {
			this._controllersManager.removeEventListener(CMEventTypes.ON_UPDATE, this._onMenuManipulationUpdateBound);
		}
		if (this._menuManipulationFeedback) {
			this._mesh.remove(this._menuManipulationFeedback);
			this._menuManipulationFeedback.geometry.dispose();
			this._menuManipulationFeedback.material.dispose();
			this._menuManipulationFeedback = null;
		}

		// Remove event listeners
		this._controllersManager.removeEventListener(
			CMEventTypes.ON_LEFT_CONTROLLER_CONNECTED,
			this._onLeftControllerConnectedBound
		);
		this._controllersManager.removeEventListener(
			CMEventTypes.ON_LEFT_CONTROLLER_DISCONNECTED,
			this._onLeftControllerDisconnectedBound
		);
		this._controllersManager.removeEventListener(
			CMEventTypes.ON_RIGHT_CONTROLLER_CONNECTED,
			this._onRightControllerConnectedBound
		);
		this._controllersManager.removeEventListener(
			CMEventTypes.ON_RIGHT_CONTROLLER_DISCONNECTED,
			this._onRightControllerDisconnectedBound
		);

		// Remove the menu from the scene or controller
		if (this.options.mode === 'swatch') {
			let grip = this._controllersManager?.[this.options.swatch.handedness]?.getGrip();
			if (grip) {
				grip.remove(this._container);
			}
			this._detachSwatchParentAxes();
			if (this._swatchParentAxes) {
				this._swatchParentAxes.geometry.dispose();
				this._swatchParentAxes.material.dispose();
				this._swatchParentAxes = null;
			}
		} else {
			this._worldContainer.remove(this._container);
		}

		// Call parent dispose if available
		if (super.dispose) super.dispose();
	}
}
