/**
 * @module VRLeverControl
 * @description
 * Semantic one-axis lever built on top of {@link VRRotaryControl}.
 */
import * as THREE from 'three';

import { VRRotaryControl, defaultOptions as rotaryDefaults, EventTypes } from './VRRotaryControl.js';

export { EventTypes };

export const defaultOptions = {
	...rotaryDefaults,
	axis: new THREE.Vector3(1, 0, 0),
	minAngle: -Math.PI / 6,
	maxAngle: Math.PI / 6,
	initialAngle: 0,
};

/**
 * Semantic wrapper for one-axis lever behavior. Visual shape, handle length,
 * base, and pivot are supplied by the app through `movingObject`.
 *
 * @extends VRRotaryControl
 *
 * @example
 * const lever = new VRLeverControl(leverMesh, {
 *   controllersManager,
 *   minAngle: -Math.PI / 4,
 *   maxAngle: Math.PI / 4,
 * });
 */
export class VRLeverControl extends VRRotaryControl {
	/**
	 * @param {THREE.Object3D} movingObject - Object rotated by the lever.
	 * @param {object} [options] - Lever options; same shape as {@link VRRotaryControl} options.
	 */
	constructor(movingObject, options = {}) {
		super(movingObject, { ...defaultOptions, ...options });
	}
}
